// Funnel: eventos de conversión (prueba → registro → conexión → semana → pago).
// Tabla funnel_events (db.js). Sin PII: solo user_id + evento.
function track(userId, event, meta = '') {
  try {
    db.prepare('INSERT INTO funnel_events (user_id, event, meta) VALUES (?,?,?)')
      .run(userId || null, event, String(meta || '').slice(0, 200));
  } catch (e) { /* el tracking nunca bloquea */ }
}

// Analytics propio (tabla events): el frontend manda pantallas y acciones en batch.
// Sin PII en props: solo datos agregados del uso. El tracking nunca bloquea.
function evTrack(userId, name, props = null, sessionId = '') {
  try {
    if (!/^[a-z0-9_]{2,40}$/.test(name)) return;
    // (v322) ORIGEN: todo evento con usuario hereda src (canal normalizado) e
    // idioma de su cuenta si el emisor no los trae — registered/payment y el
    // resto del funnel quedan separables por canal e idioma en el tablero.
    if (userId && props == null || userId && typeof props === 'object') {
      try {
        const u = db.prepare('SELECT utm_source, lang FROM users WHERE id = ?').get(userId);
        if (u) {
          const pp = Object.assign({}, props || {});
          if (!pp.src) { const s = LA.normalizeSrc(u.utm_source); if (s) pp.src = s; }
          if (!pp.lang && u.lang) pp.lang = u.lang;
          if (pp.src || pp.lang) props = pp;
        }
      } catch (e) { /* sin usuario legible: el evento sale como nació */ }
    }
    let p = '';
    try { p = JSON.stringify(props || {}).slice(0, 2000); } catch (e) {}
    db.prepare('INSERT INTO events (user_id, session_id, name, props) VALUES (?,?,?,?)')
      .run(userId || null, String(sessionId || '').slice(0, 32), name, p);
  } catch (e) { /* el tracking nunca bloquea */ }
  // 😕 Aviso al dueño (v283): el post_failed que se emite desde server.js
  // (posteos trabados en publishing) avisa igual que los del scheduler —
  // mismo helper, mismo toggle y mismo dedupe (push.js). Nunca bloquea.
  if (name === 'post_failed' && userId) {
    try { push.notifyPostFailed(userId).catch(() => {}); } catch (e) { /* sin aviso, nunca un error */ }
  }
}

// Palabras en las que un titular JAMÁS debe terminar: se vería cortado a mitad
// de oración (ej. "Tip: Cómo organizar tu contenido de"). Se chequea sin
// puntuación ni mayúsculas.
const HEADLINE_DANGLING = new Set(['de','del','al','el','la','los','las','un','una','unos','unas','y','e','o','u','ni','que','en','con','por','para','sin','sobre','entre','hasta','desde','durante','a','ante','bajo','contra','hacia','tras','mediante','segun','según','como','cómo','pero','mas','más','si','sí','no','tu','tus','su','sus','mi','mis','nuestro','nuestra','esta','este','esto','es','son','hay','se','le','les','lo','me','te']);
// Quita palabras "colgadas" del final (preposiciones, artículos, conjunciones).
function sinColgada(words) {
  const w = words.slice();
  while (w.length > 1 && HEADLINE_DANGLING.has(String(w[w.length - 1]).toLowerCase().replace(/[.,;:!?¿¡()"“”'']/g, ''))) w.pop();
  return w;
}

// Corta un texto SIN partir palabras a la mitad (nunca "efecti") y SIN dejarlo
// terminado en preposición/artículo (nunca "...tu contenido de").
function cortar(t, max) {
  const s = String(t || '').trim();
  if (s.length <= max) return s;
  const c = s.slice(0, max);
  const i = c.lastIndexOf(' ');
  const cut = (i > max * 0.4 ? c.slice(0, i) : c).trim();
  return sinColgada(cut.split(' ').filter(Boolean)).join(' ');
}

// Titular COMPLETO para renderizar en imágenes: nunca sale cortado a mitad de
// oración. Prefiere la primera oración si entra en el límite; si no, recorta por
// palabras y retrocede hasta una palabra "firme". Tope de caracteres para que el
// brief (que corta en 80) jamás lo mutile.
// Rubro del cliente para el C1 (makeHeadline rubro-aware): null si no hay.
const rubroOf = (uid) => { try { const pr = getProfile(uid); return (pr && pr.category) || null; } catch (e) { return null; } };
// Efeméride con criterio (2026-10-16): la fecha comercial SOLO fuerza la
// idea N°1 en rubros donde regalar tiene sentido. Evidencia (prueba de
// rubros del 2026-10-15): el único posteo fuera de topic en 99 fue la
// efeméride forzada en una barbería de hombres (Día de la Madre). Para los
// demás rubros la fecha no entra: su semana habla de SU negocio.
const EPHEMERIS_GIFT_OK = /flor|gastro|helad|pastel|panad|cafeter|cafe|joya|indument|ropa|moda|belleza|estetic|estétic|spa|deco|hogar|perfum|chocolat|regal|libro|juguete|tecno|electr|peluquer/i;
function ephemerisFor(profile) {
  const eph = upcomingEphemeris(12)[0] || null;
  if (!eph) return null;
  const cat = String((profile && profile.category) || '');
  const biz = String((profile && profile.business_name) || '');
  if (/barber/i.test(cat + ' ' + biz)) return null;
  return EPHEMERIS_GIFT_OK.test(cat) ? eph : null;
}
// C1 + paquete de titulares (2026-10-16, aprobado por Valentino "arma
// todo"; paquete makeheadline-decision-v113 de Mora + spec M53 de Uma):
// (1) el rubro elige la "palabra-dinero" (qué oración gana) — familias:
// gastronomía=precio, mascotas/deco=transformación, belleza=técnica
// brandeada, moda=día/stock, fitness=hook de negación; una efeméride con
// precio o fecha gana sobre cualquier familia; (2) sentence case: solo la
// primera palabra lleva mayúscula, salvo nombres propios (mayúscula en
// TODAS sus apariciones a mitad de oración) y siglas; (3) jamás terminar
// en puntuación débil ni en palabra colgada; (4) jamás empalmar dos
// oraciones en un titular.
function headlineCase(out, raw) {
  const toks = String(raw || '').split(/\s+/).filter(Boolean);
  const stats = new Map();
  toks.forEach((t, i) => {
    const clean = t.replace(/[^\p{L}\p{N}$]/gu, '');
    if (!clean) return;
    const initial = i === 0 || /[.!?…]$/.test(toks[i - 1] || '');
    const key = clean.toLowerCase();
    const e = stats.get(key) || { capNonInitial: 0, lowNonInitial: 0 };
    if (!initial) { if (/^\p{Lu}/u.test(clean)) e.capNonInitial++; else e.lowNonInitial++; }
    stats.set(key, e);
  });
  const keep = new Set();
  for (const [k, e] of stats) {
    if (e.capNonInitial > 0 && e.lowNonInitial === 0 && !HEADLINE_DANGLING.has(k)) keep.add(k);
  }
  return String(out || '').split(' ').map((w, i) => {
    const clean = w.replace(/[^\p{L}\p{N}$]/gu, '');
    const low = clean.toLowerCase();
    if (/^\p{Lu}{2,}$/u.test(clean)) return w; // sigla (IG, MP): intacta
    if (i === 0) return w.charAt(0).toUpperCase() + (keep.has(low) ? w.slice(1) : w.slice(1).toLowerCase());
    return keep.has(low) ? w : w.toLowerCase();
  }).join(' ');
}
function makeHeadline(text, maxWords = 6, maxChars = 70, rubro = null) {
  const sRaw = String(text || '').replace(/\s+/g, ' ').trim();
  if (!sRaw) return '';
  // PRECIO-33 (2026-10-11, fallo real): el punto de miles NO es fin de oración
  // ("La docena a $12.500" salía como "La docena a $12."). Se protege el
  // dígito.punto.dígito con un marcador antes de dividir en oraciones y se
  // restaura al devolver: el precio sale ENTERO o no sale.
  const s = sRaw.replace(/(\d)\.(?=\d)/g, '$1\u0001');
  // Guard 2026-10-06 (propuesta Juli, QA captions): titulares de 1-2 palabras
  // ("Lunes.") no venden y salen del makeHeadline cuando el caption arranca con
  // una escena corta. Se toma la primera oración con >=3 palabras entre las 3
  // primeras; si ninguna califica, se usan las primeras 8 palabras del texto.
  const sentences = (s.match(/[^.!?…]+[.!?…]/g) || [s]).slice(0, 5);
  const hasWords = (c) => c.trim().split(' ').filter(Boolean).length >= 3;
  // ESTACIONAL (M53): efeméride comercial + precio o fecha → esa oración gana
  // sobre cualquier familia de rubro.
  let seed = sentences.find(c => hasWords(c) &&
    /día de la madre|día del padre|día del niño|día del amigo|navidad|año nuevo|reyes|san valentín|hot sale|cyber monday|black friday/i.test(c) &&
    (/\$\s?\d/.test(c) || /\b(hasta el|el|este)\s+\d{1,2}\b/i.test(c) || /\b(domingo|lunes|martes|miércoles|jueves|viernes|sábado)\b/i.test(c)));
  if (!seed && rubro) {
    const r = String(rubro).toLowerCase();
    // C1 (2026-10-10, Uma): prioridad a la "palabra-dinero" del rubro.
    if (/mascota|veterinar|pet\s?shop|grooming|peluquer[ií]a canina/.test(r)) {
      // Transformación (antes/desp ués) o precio.
      seed = sentences.find(c => hasWords(c) && (/\b(antes|después|despues|quedó|quedo|bañ|look nuevo|transform)/i.test(c) || /\$\s?\d/.test(c)));
    } else if (/deco|hogar|muebl|interior/.test(r)) {
      // Transformación (antes/desp ués, renovación) o precio.
      seed = sentences.find(c => hasWords(c) && (/\b(antes|después|despues|renova|quedó|quedo|transform)/i.test(c) || /\$\s?\d/.test(c)));
    } else if (/gastronom|cafeter|bar\b|parrilla|pizzer|panader|rotiser|helader|reposter|pasteler|carnicer/.test(r)) {
      // Precio explícito: "$69.900", "$10.000"
      seed = sentences.find(c => hasWords(c) && /\$\s?\d/.test(c));
    } else if (/belleza|estetica|estética|peluquer|barber/.test(r)) {
      // Técnica brandeada: entre comillas o 2+ palabras con mayúscula sostenida
      seed = sentences.find(c => hasWords(c) && (/\"[^\"]{3,}\"/.test(c) || /\b[A-ZÁÉÍÓÚÑ][a-záéíóúñ]+ [A-ZÁÉÍÓÚÑ][a-záéíóúñ]+/.test(c)));
    } else if (/moda|ropa|tienda|indumentaria/.test(r)) {
      // Día+hora o escasez cuantificada: "sábado 10hs", "1.000 piezas", "stock"
      seed = sentences.find(c => hasWords(c) && (/\b(lunes|martes|miércoles|jueves|viernes|sábado|domingo)\b/i.test(c) || /\d[\d.]*\s?(piezas|unidades|stock)/i.test(c)));
    } else if (/fitness|gimnasio|gym|entrenamiento/.test(r)) {
      // Hook de negación: "no es solo…", "≠", "dejé de…"
      seed = sentences.find(c => hasWords(c) && (/\bno es solo\b/i.test(c) || /≠/.test(c) || /\bdej[ée] de\b/i.test(c)));
    }
  }
  if (!seed) seed = sentences.slice(0, 3).find(c => c.trim().split(' ').filter(Boolean).length >= 3);
  // Sin empalmes: el fallback de últimas toma palabras SOLO de la primera oración.
  if (!seed) seed = String(s.split(/[.!?…]/)[0] || s).split(' ').filter(Boolean).slice(0, 8).join(' ');
  seed = seed.trim();
  // 1) La oración elegida: si entra en el límite de palabras, va entera.
  const fw = seed.split(' ').filter(Boolean);
  let words;
  if (fw.length <= maxWords) {
    words = sinColgada(fw);
  } else {
    // 2) Recorte por palabras + retroceso anti-colgada (sobre la oración elegida).
    words = sinColgada(seed.split(' ').filter(Boolean).slice(0, maxWords));
  }
  let out = words.join(' ');
  // 3) Tope de caracteres, cortando por palabra y re-chequeando colgadas.
  if (out.length > maxChars) {
    const c = out.slice(0, maxChars);
    const i = c.lastIndexOf(' ');
    out = sinColgada((i > maxChars * 0.4 ? c.slice(0, i) : c).trim().split(' ').filter(Boolean)).join(' ');
  }
  // 4) Jamás terminar en puntuación débil + re-chequeo de colgada tras el strip.
  out = sinColgada(out.replace(/[,;:]+$/, '').trim().split(' ').filter(Boolean)).join(' ').replace(/[,;:]+$/, '').trim();
  // 5) Sentence case con nombres propios y siglas preservados.
  out = headlineCase(out, sRaw);
  // 5b) PREGUNTA CORTADA = PUNTOS SUSPENSIVOS (regla de Valentino
  // 2026-10-19): si la oración elegida es una PREGUNTA y el recorte la
  // deja INCOMPLETA, el titular NO se cierra con "?" como si estuviera
  // entera — termina con "…". Una pregunta cerrada a la mitad parece
  // completa y queda gramaticalmente rota (defecto vivo: post 413,
  // "¿listo para que tu Instagram sea?"). Si la pregunta entra entera,
  // el cierre "?" de siempre se mantiene (paso 6). Espejo en generator.js.
  const seedIsQuestion = /^\s*¿/.test(seed) || /\?\s*$/.test(seed);
  const normWordsQ = (t) => String(t || '').replace(/\u0001/g, '.').toLowerCase().split(/\s+/).map((w) => w.replace(/[^\p{L}\p{N}$]/gu, '')).filter(Boolean);
  const seedWordsQ = normWordsQ(seed);
  const questionIsCut = () => {
    if (!seedIsQuestion || seedWordsQ.length < 3) return false;
    const ow = normWordsQ(out);
    return !(ow.length >= seedWordsQ.length && seedWordsQ.every((w, i) => ow[i] === w));
  };
  // 6) CIERRE DE SIGNOS (Mora 2026-10-18, ids reales 458/461): el recorte por
  // palabras dejaba preguntas abiertas sin su cierre (¿cuántas veces te
  // imaginaste creando contenido" sin "?"). Si el titular abre con ¿/¡, el
  // signo de cierre es obligatorio: se restaura siempre. Sin efecto en
  // titulares que no abren con signo. (v239: una pregunta CORTADA no se
  // cierra — la manda la regla 5b, no este paso.)
  if (out.startsWith('¿') && !out.endsWith('?') && !questionIsCut()) out = out.replace(/[.]+$/, '') + '?';
  if (out.startsWith('¡') && !out.endsWith('!')) out = out.replace(/[.]+$/, '') + '!';
  // 7) CAP DE PALABRAS DURO (v209, regla de pieza de Valentino
  // 2026-10-18): garantía FINAL — ningún titular sale de acá con más de
  // maxWords palabras (default 6), venga del seed que venga (rubro-aware,
  // estacional o el fallback de 8 palabras). Recorte por CLÁUSULA
  // primero (la primera completa que entra), después por palabras con
  // retroceso anti-colgada: nunca una idea cortada a la mitad si una
  // cláusula entera cumple. (Espejo en generator.js.)
  {
    const ws = out.split(' ').filter(Boolean);
    if (ws.length > maxWords) {
      const clauses = out.split(/\s*[:;—]\s*|\s+-\s+/).map((x) => x.trim()).filter(Boolean);
      let picked = '';
      for (const c of clauses) {
        const cw = c.split(' ').filter(Boolean);
        if (cw.length >= 2 && cw.length <= maxWords) { picked = c; break; }
      }
      out = picked || sinColgada(ws.slice(0, maxWords)).join(' ');
      out = out.replace(/[,;:]+$/, '').trim();
      if (out.startsWith('¿') && !out.endsWith('?') && !questionIsCut()) out = out.replace(/[.]+$/, '') + '?';
      if (out.startsWith('¡') && !out.endsWith('!')) out = out.replace(/[.]+$/, '') + '!';
    }
  }
  // 8) Cierre de la regla 5b: pregunta cortada ⇒ "…" final y sin "?".
  if (questionIsCut()) out = out.replace(/\s*[?….]+$/, '').trim() + '…';
  // 9) FRAGMENTO DECLARATIVO = PUNTOS SUSPENSIVOS (Mora 2026-10-19, ids
  // reales 482/473 — extensión de la regla 5b de Valentino a toda
  // oración cortada): el recorte por palabras + sinColgada también deja
  // DECLARATIVAS cortadas que parecen completas, porque sinColgada
  // borra la preposición final y disfraza el corte ("Halloween: tu
  // Instagram, el alma de la fiesta" → "…, el alma"; "…a medida,
  // ideales para tu comedor" → "…, ideales"). Si el titular es un
  // prefijo propio de la oración elegida (la oración sigue y el
  // titular no la contiene entera), cierra con "…" igual que la
  // pregunta cortada: nunca se presenta un fragmento como frase
  // completa. Una exclamación cortada entra en la misma regla (el "!"
  // del paso 6 se reemplaza por "…"). Espejo en generator.js.
  const declarIsCut = () => {
    if (seedIsQuestion || seedWordsQ.length < 3) return false;
    const ow = normWordsQ(out);
    if (!(ow.length < seedWordsQ.length && ow.every((w, i) => seedWordsQ[i] === w))) return false;
    // Solo cuando el corte se llevó un COMPLEMENTO que la última
    // palabra conservada exige: la primera palabra cortada es "de/del"
    // (complemento del nombre: "el alma DE la fiesta") o "para"
    // (finalidad del adjetivo/nombre: "ideales PARA tu comedor"). Un
    // adjunto opcional cortado ("hechos hoy EN el local", "$12.500
    // recién salida") deja un titular de estilo nominal completo y NO
    // lleva "…" (test-character-lock (f): no-pregunta intacta).
    return ['de', 'del', 'para'].includes(seedWordsQ[ow.length]);
  };
  if (declarIsCut()) out = out.replace(/\s*[!….]+$/, '').trim() + '…';
  return out.replace(/\u0001/g, '.');
}
const app = express();
const NODE_ENV = process.env.NODE_ENV || 'development';
const IS_PROD = NODE_ENV === 'production';
const PORT = parseInt(process.env.PORT || '3000', 10);
// Los archivos subidos (diseños, fotos, logos) van al volumen persistente (DATA_DIR),
// no al repo: Railway borra el filesystem en cada deploy y los posteos quedarían rotos.
const DATA_DIR = process.env.DATA_DIR || path.join(__dirname, 'data');
const MEDIA_DIR = process.env.MEDIA_DIR || path.join(DATA_DIR, 'media');
const IMAGE_BASE_URL = (process.env.IMAGE_BASE_URL || '').replace(/\/$/, '');
const OPENAI_API_KEY = process.env.OPENAI_API_KEY || '';

const SESSION_SECRET = process.env.SESSION_SECRET;
if (IS_PROD && !SESSION_SECRET) {
  console.error('[posta] ❌ ERROR: en producción tenés que definir SESSION_SECRET en las variables de entorno.');
  process.exit(1);
}
if (!fs.existsSync(MEDIA_DIR)) fs.mkdirSync(MEDIA_DIR, { recursive: true });

// (v285) Webhook de Stripe: la verificación de firma exige el body CRUDO, así
// que esta ruta se registra ANTES del parser JSON global. Fail-closed: sin
// STRIPE_WEBHOOK_SECRET responde 503 y no procesa nada; sin STRIPE_SECRET_KEY,
// tampoco. Los hooks espejan la activación/cancelación del flujo MercadoPago.
function stripeHooks() {
  return {
    onActivated: (uid, planId) => {
      try { stampFounder(uid); } catch (e) {}
      reactivatePausedPosts(uid);
      track(uid, 'subscribed', planId);
      evTrack(uid, 'payment_ok', { plan: planId, provider: 'stripe' });
      console.log(`[stripe] ✅ Plan ${planId} activado para el usuario ${uid}`);
    },
    onCancelled: (uid) => { console.log(`[stripe] Plan cancelado para el usuario ${uid}`); },
    onPaymentOk: (uid, planId) => { evTrack(uid, 'payment_ok', { plan: planId || '', provider: 'stripe' }); },
    // Gracia espejo MP: el fallo de cobro se registra pero NO cancela el plan;
    // Stripe reintenta y solo subscription.deleted da de baja.
    onPaymentFailed: (uid, planId) => { evTrack(uid, 'payment_failed', { plan: planId || '', provider: 'stripe' }); },
  };
}
app.post('/api/billing/stripe/webhook', express.raw({ type: 'application/json', limit: '1mb' }), async (req, res) => {
  if (!stripeBilling.webhookConfigured() || !stripeBilling.stripeConfigured()) {
    return res.status(503).json({ ok: false, error: 'stripe_no_configurado' });
  }
  const client = stripeBilling.stripeClient();
  let event;
  try {
    event = stripeBilling.constructEvent(client, req.body, req.get('stripe-signature'));
  } catch (e) {
    console.error('[stripe] webhook: firma inválida:', e.message);
    return res.status(400).json({ ok: false, error: 'firma_invalida' });
  }
  try {
    await stripeBilling.processEvent(db, client, event, stripeHooks());
    res.status(200).json({ ok: true });
  } catch (e) {
    // 500 para que Stripe REINTENTE (misma lección que el webhook de MP).
    console.error('[stripe] webhook falló:', e.message);
    res.status(500).json({ ok: false, error: 'retry' });
  }
});

app.use(express.json({ limit: '15mb', verify: (req, res, buf) => { try { req.rawBody = buf; } catch (e) {} } }));

// Mudanza de dominio: postahacetodo.com -> postyhacetodo.com (301).
// No toca /api/* (webhooks de MP, OAuth) ni /.well-known/* (assetlinks).
app.use((req, res, next) => {
  const host = (req.get('host') || '').split(':')[0].toLowerCase();
  if ((host === 'postahacetodo.com' || host === 'www.postahacetodo.com' || host === 'www.postyhacetodo.com') &&
      !req.path.startsWith('/api/') && !req.path.startsWith('/.well-known/')) {
    return res.redirect(301, 'https://postyhacetodo.com' + req.originalUrl);
  }
  next();
});

// Sesiones persistentes en SQLite: cada deploy reinicia el servidor y la memoria
// se pierde; sin este store cada deploy deslogueaba a todos los usuarios.
class SqliteSessionStore extends session.Store {
  constructor() {
    super();
    db.exec(`CREATE TABLE IF NOT EXISTS sessions (
      sid TEXT PRIMARY KEY,
      sess TEXT NOT NULL,
      expire INTEGER NOT NULL
    )`);
    const sweep = setInterval(() => {
      try { db.prepare('DELETE FROM sessions WHERE expire < ?').run(Date.now()); } catch (e) {}
    }, 3600 * 1000);
    if (sweep.unref) sweep.unref();
  }
  get(sid, cb) {
    try {
      const row = db.prepare('SELECT sess, expire FROM sessions WHERE sid = ?').get(sid);
      if (!row || row.expire <= Date.now()) return cb(null, null);
      cb(null, JSON.parse(row.sess));
    } catch (e) { cb(e); }
  }
  set(sid, sess, cb) {
    try {
      const maxAge = (sess.cookie && sess.cookie.maxAge) || 7 * 24 * 3600 * 1000;
      db.prepare('INSERT OR REPLACE INTO sessions (sid, sess, expire) VALUES (?, ?, ?)')
        .run(sid, JSON.stringify(sess), Date.now() + maxAge);
      cb(null);
    } catch (e) { cb(e); }
  }
  destroy(sid, cb) {
    try { db.prepare('DELETE FROM sessions WHERE sid = ?').run(sid); cb(null); } catch (e) { cb(e); }
  }
  touch(sid, sess, cb) { this.set(sid, sess, cb); }
}
app.use(
  session({
    store: new SqliteSessionStore(),
    secret: SESSION_SECRET || 'posta-dev-secret-cambiar-en-prod',
    resave: false,
    saveUninitialized: false,
    rolling: true, // cada request renueva la expiración: mientras uses Posta, nunca se cierra
    cookie: { sameSite: 'lax', maxAge: 365 * 24 * 3600 * 1000, httpOnly: true, secure: ['1', 'true'].includes(String(process.env.COOKIE_SECURE || '').toLowerCase())  },
  })
);
app.use('/media', express.static(MEDIA_DIR, {
  // Los nombres de archivo son únicos por generación (el contenido bajo
  // un nombre nunca cambia): caché larga e inmutable → el Schedule y las
  // vistas repintan al instante sin re-descargar las imágenes.
  maxAge: '30d', immutable: true,
}));
app.use(express.static(path.join(__dirname, 'public'), {
  setHeaders: (res, fp) => {
    // sw.js: SIEMPRE fresco — si queda cacheado, la PWA no se entera de
    // las versiones nuevas del propio service worker.
    if (/sw\.js$/.test(fp)) { res.setHeader('Cache-Control', 'no-cache'); return; }
    // JS/CSS: immutable de 30 días SOLO si la URL trae ?v= (la versión ES
    // el contenido). Sin ?v=, la caché larga dejaba código viejo pegado
    // por 30 días — multiplicador del incidente del iPhone (2026-10-21).
    if (/\.(js|css)$/.test(fp)) {
      const u = (res.req && res.req.url) || '';
      res.setHeader('Cache-Control', u.includes('?v=') ? 'public, max-age=2592000, immutable' : 'no-cache');
    }
    else if (/\.html$/.test(fp)) res.setHeader('Cache-Control', 'no-cache');
  },
}));

const requireAuth = (req, res, next) => {
  if (!req.session.userId) return res.status(401).json({ error: 'No autenticado' });
  next();
};

// Si la prueba gratis venció, no se puede generar ni programar: el paywall es "Mi plan"
function requireTrialValid(req, res, next) {
  try {
    const u = db.prepare('SELECT plan_status, trial_ends_at, trial_extended_until, created_at FROM users WHERE id = ?').get(req.session.userId);
    if (u && u.plan_status === 'trial' && trialEffectiveEnd(u) <= Date.now())
      return res.status(402).json({ error: 'trial_expired', message: 'ey! se terminó tu prueba gratis 😢 elegí tu plan y seguimos publicando juntos — posty te extraña.' });
  } catch (e) {
    // FAIL-CLOSED (2026-10-02): si la DB falla, NO dejamos pasar. Antes dejaba
    // usar la IA sin trial válido ante cualquier error transitorio.
    console.error('[requireTrialValid] DB error, bloqueando por seguridad:', e.message);
    return res.status(503).json({ error: 'tmp_unavailable', message: 'Dame un segundo 😅 Probá de nuevo.' });
  }
  next();
}
// Fin efectivo de la prueba: respeta la política vigente (TRIAL_DAYS desde la creación),
// aunque la cuenta se haya creado cuando la prueba duraba más.
function trialEffectiveEnd(u) {
  // Extensión manual de soporte: si hay una vigente, manda ella (2026-10-03 fix:
  // se chequea PRIMERO, antes el early return por trial_ends_at vacío la ignoraba).
  const ext = u.trial_extended_until || 0;
  if (ext > Date.now()) return ext;
  const tEnds = u.trial_ends_at || 0;
  if (!tEnds) return 0;
  const cMs = Date.parse(String(u.created_at || '').replace(' ', 'T') + 'Z');
  const policyEnd = cMs ? cMs + TRIAL_DAYS * 86400000 : Infinity;
  const base = Math.min(tEnds, policyEnd);
  return base;
}

// ---------- Página pública del negocio (v169): /p/<slug> ----------
// Slug desde el nombre del negocio: minúsculas, sin acentos, [a-z0-9-], máx 40.
function slugifyBiz(name) {
  let s = String(name || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-').replace(/^-+|-+$/g, '');
  s = s.slice(0, 40).replace(/-+$/g, '');
  return s;
}
// Garantiza que el usuario tenga page_slug único; lo genera desde business_name
// la primera vez que se necesita (al leer el perfil o al pedir la página).
function ensurePageSlug(userId) {
  const p = getProfile(userId);
  const cur = String(p.page_slug || '').trim();
  if (/^[a-z0-9][a-z0-9-]{1,39}$/.test(cur)) return cur;
  let base = slugifyBiz(p.business_name) || 'negocio';
  let candidate = base;
  let n = 2;
  while (db.prepare('SELECT user_id FROM profiles WHERE page_slug = ? AND user_id != ?').get(candidate, userId)) {
    const suf = '-' + n;
    candidate = base.slice(0, 40 - suf.length) + suf;
    n++;
  }
  db.prepare(`UPDATE profiles SET page_slug = ?, updated_at = datetime('now') WHERE user_id = ?`).run(candidate, userId);
  return candidate;
}

function getProfile(userId) {
  let p = db.prepare('SELECT * FROM profiles WHERE user_id = ?').get(userId);
  if (!p) {
    db.prepare('INSERT INTO profiles (user_id) VALUES (?)').run(userId);
    p = db.prepare('SELECT * FROM profiles WHERE user_id = ?').get(userId);
  }
  return p;
}
function getSettings(userId) {
  let s = db.prepare('SELECT * FROM settings WHERE user_id = ?').get(userId);
  if (!s) {
    db.prepare('INSERT INTO settings (user_id) VALUES (?)').run(userId);
    s = db.prepare('SELECT * FROM settings WHERE user_id = ?').get(userId);
  }
  return s;
}
// ADN del negocio (dna_json): lectura/escritura con merge (nunca pisar campos como series o pausas).
function readDna(userId) {
  try {
    const r = db.prepare('SELECT dna_json FROM business_dna WHERE user_id = ?').get(userId);
    if (r && r.dna_json) { const o = JSON.parse(r.dna_json); return (o && typeof o === 'object') ? o : {}; }
  } catch (e) {}
  return {};
}
function writeDna(userId, obj) {
  db.prepare(`INSERT INTO business_dna (user_id, dna_json, updated_at) VALUES (?, ?, datetime('now'))
    ON CONFLICT(user_id) DO UPDATE SET dna_json=excluded.dna_json, updated_at=datetime('now')`).run(userId, JSON.stringify(obj || {}));
}

// ---------- FUNDAMENTO (v229): digest del cliente ----------
// El digest (client-digest.js) es la foto compilada del fundamento del
// negocio: productos/servicios/promos reales, temas de su feed, paleta,
// ciudad, diferencial — con la fuente y la fecha de cada bloque. Se
// construye en la prueba, viaja en su payload, se siembra ENTERO en la
// cuenta al registrarse y se refresca con cadencia (refreshDigestsSweep).
function digestForUser(uid) {
  try { return clientDigest.getDigest(db, uid); } catch (e) { return null; }
}
function digestAnchorsFor(uid) {
  try { return clientDigest.anchorsOf(clientDigest.getDigest(db, uid)).map((a) => a.text); }
  catch (e) { return []; }
}
// Trazabilidad: cada posteo guarda el hash del digest con el que nació
// (posts.digest_hash); ':sin-ancla' si la pieza no pasó el chequeo de
// pertenencia — el loop de calidad mide % de piezas con ancla/semana.
function stampPostDigest(postId, uid, unanchored) {
  try {
    const d = digestForUser(uid);
    if (!d || !postId) return;
    const h = String(d.hash || '') + (unanchored ? ':sin-ancla' : '');
    if (h) db.prepare('UPDATE posts SET digest_hash = ? WHERE id = ?').run(h, postId);
  } catch (e) {}
}
// (v230) FOTO↔PRODUCTO en clientes: si el mapa foto→producto del digest
// cubre fotos del ÁLBUM del cliente con EL producto del que habla la
// pieza, esas fotos van como referencia de la generación (la imagen
// nace de la foto del producto exacto, no de una foto cualquiera).
// La clave del mapa es el hash del contenido: se cachea por ruta (los
// archivos de MEDIA_DIR son inmutables por nombre).
const photoKeyCache = new Map();
function photoMappedRefsFor(uid, texts) {
  try {
    const digest = digestForUser(uid);
    const entries = digest && digest.photo_map && digest.photo_map.entries;
    if (!entries || !Object.keys(entries).length) return [];
    const joined = (texts || []).filter(Boolean).join(' ');
    if (!joined) return [];
    const targets = new Set();
    const itemNames = [...(digest.productos || []), ...(digest.servicios || []), ...((digest.catalog && digest.catalog.items) || [])]
      .map((x) => (x && (x.nombre || x)) || '').filter(Boolean);
    for (const n of itemNames) {
      if (clientDigest.pieceAnchored(joined, clientDigest.anchorsFromTexts([n])).ok) targets.add(clientDigest.norm(n));
    }
    if (!targets.size) return [];
    const rows = db.prepare(`SELECT file_path FROM assets WHERE user_id = ? AND kind = 'photo' ORDER BY created_at DESC LIMIT 12`).all(uid);
    const out = [];
    for (const r of rows) {
      const abs = path.join(MEDIA_DIR, path.basename(String(r.file_path || '')));
      let ck = photoKeyCache.get(abs);
      if (ck === undefined) {
        ck = deepRead.photoContentKey(abs);
        photoKeyCache.set(abs, ck);
        if (photoKeyCache.size > 500) photoKeyCache.clear();
      }
      if (!ck) continue;
      const e = entries[ck];
      if (e && e.item && targets.has(clientDigest.norm(e.item))) out.push(r.file_path);
      if (out.length >= 2) break;
    }
    return out;
  } catch (e) { return []; }
}
// (v235) Mapa categoría-de-prueba → profiles.category, UNA sola copia
// (antes vivía duplicado en seedFromTrialDigest y applyTrialProfile).
// FIX de la auditoría: moda → 'moda' (era 'ropa', un valor que NINGÚN
// preset del catálogo declara: el pool de prompts de todo cliente de
// moda quedaba vacío). rubroMatch suma alias para las filas viejas.
const TRIAL_CAT_MAP = { moda: 'moda', gastronomia: 'gastronomia', belleza: 'belleza', fitness: 'fitness', mascotas: 'mascotas', salud: 'salud', hogar: 'hogar', inmobiliaria: 'inmobiliaria', autos: 'servicios', educacion: 'educacion', turismo: 'viajes', eventos: 'eventos', tecnologia: 'tecnologia', deco: 'hogar', joyeria: 'otro', fotografia: 'arte', profesionales: 'servicios', flores: 'otro', bar: 'gastronomia', cafeteria: 'cafeteria', barberia: 'barberia', servicios: 'servicios', viajes: 'viajes', arte: 'arte', otro: 'otro' };

/* (v235) Resolución de rubro de la PRUEBA — el orden de Valentino: la
 * pregunta va ANTES de generar. Los endpoints de estudio (prefill /
 * web-prefill) clasifican y devuelven rubro_check; el front pregunta
 * con un toque si hay duda y reenvía la confirmación como fields
 * (category + subcat + rubro_src='pregunta'). Una edición manual del
 * select llega con rubro_src='form' y también manda. Sin confirmación:
 * manda el voto multi-señal; si duda, category = rubro padre seguro y
 * subcat = '' (jamás un subrubro inventado), registrado sin_confirmar. */
function resolveTrialRubro({ fields, webData, feed, formText, catalogItems, lang }) {
  const f = fields || {};
  const src = String(f.rubro_src || '');
  const catSel = String(f.category || '').trim();
  const subSel = String(f.subcat || '').trim();
  const signals = {
    jsonldType: (webData && webData.categoryHint) || '',
    catalogText: [((webData && webData.services) || []).join(' · '), (catalogItems || []).join(' · ')].join(' '),
    webText: [(webData && webData.name) || '', (webData && webData.description) || ''].join(' '),
    bio: (feed && feed.bio) || '', fullName: (feed && feed.name) || '',
    handle: (feed && (feed.handle || feed.username)) || String(f.ig || '').replace(/^@/, ''),
    captions: (feed && feed.captions) || [],
    igCategory: (feed && feed.category) || '',
    formText: [formText || '', f.business || ''].join(' '),
  };
  const cls = rubroId.classifyBusiness(signals);
  if ((src === 'pregunta' || src === 'form') && catSel && rubroId.RUBROS.includes(catSel)) {
    return rubroId.resolveRubro({ confirmed: { rubro: catSel, subrubro: subSel, fuente: src }, cls, lang });
  }
  const res = rubroId.resolveRubro({ cls, lang });
  if (src === 'skip' && !cls.segura) {
    // Saltó la pregunta: se genera con el padre seguro y queda el
    // registro (la pregunta sigue viva en question_candidates).
    res.rubroId.fuente = 'skip';
    res.rubroCheck.needed = false;
  }
  return res;
}

/* (v235) Desempate por VISIÓN — la ÚNICA llamada paga posible de la
 * identificación, y solo cuando el voto determinístico quedó cerca
 * (rubroId.needsVisionTiebreak). Una llamada batch gpt-4o-mini sobre
 * 3-4 fotos (mismo patrón que deep-read.classifyDigestPhotos), atrás
 * del tope diario del demo y con carrera de 6 s; cualquier falla deja
 * el voto determinístico. Devuelve la clasificación re-votada con la
 * familia 'vision', o null si no hubo desempate. */
async function classifyWithVision(signals, photoUrls, lang) {
  const cls = rubroId.classifyBusiness(signals);
  try {
    if (!rubroId.needsVisionTiebreak(cls)) return cls;
    const apiKey = process.env.OPENAI_API_KEY || '';
    if (!apiKey || !costs.demoAiCapOk()) return cls;
    const options = rubroId.questionOptions(cls, lang);
    if (options.length < 2) return cls;
    const urls = (photoUrls || []).filter((u) => typeof u === 'string' && /^https:\/\//.test(u)).slice(0, 4);
    if (urls.length < 2) return cls;
    const list = options.map((o, i) => `${i + 1}. ${o.label}`).join('\n');
    const resp = await Promise.race([
      fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: 'gpt-4o-mini',
          messages: [{ role: 'user', content: [
            { type: 'text', text: lang === 'en'
              ? `These photos are from ONE business. Which of these options does it match?\n${list}\nReply ONLY with a JSON {"i": N} with the option number (1 to ${options.length}). If none fits, {"i": 0}.`
              : `Estas fotos son de UN negocio. ¿A cuál de estas opciones corresponde?\n${list}\nRespondé SOLO un JSON {"i": N} con el número de la opción (1 a ${options.length}). Si ninguna encaja, {"i": 0}.` },
            ...urls.map((u) => ({ type: 'image_url', image_url: { url: u, detail: 'low' } })),
          ] }],
          response_format: { type: 'json_object' }, max_tokens: 20, temperature: 0,
        }),
      }),
      new Promise((_, rej) => setTimeout(() => rej(new Error('vision-timeout')), 6000)),
    ]).catch(() => null);
    if (!resp || !resp.ok) return cls;
    const data = await resp.json().catch(() => null);
    try { costs.trackUsage(data && data.usage, 'rubro-vision', null); } catch (e) {}
    const txt = data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content;
    const idx = parseInt((JSON.parse(String(txt || '{}')) || {}).i, 10);
    if (!idx || !options[idx - 1]) return cls;
    const win = options[idx - 1];
    return rubroId.classifyBusiness({ ...signals, visionKey: win.rubro + (win.subrubro ? '/' + win.subrubro : '') });
  } catch (e) { return cls; }
}

// Compila el digest de la prueba desde las fuentes que la ruta ya
// recolectó (web + feed + formulario). Determinístico, USD 0. El digest
// viaja en el payload de la prueba y en trial_cache: es el fundamento
// que la conversión siembra en la cuenta.
function buildTrialDigest({ business, category, webData, feed, formText, feedPalette, registro, deep, rubro }) {
  try {
    return clientDigest.buildFromParts({
      business,
      category: rubro ? rubro.category : category,
      subcat: rubro ? (rubro.subcat || '') : undefined,
      rubroId: rubro ? rubro.rubroId : undefined,
      web: webData ? { name: webData.name, description: webData.description, services: webData.services || [], city: webData.city, palette: webData.palette || [], url: webData.url, categoryHint: webData.categoryHint } : null,
      feed: feed ? { bio: feed.bio || '', captions: feed.captions || [], name: feed.name || '', handle: feed.handle || '' } : null,
      form: formText ? { description: formText } : null,
      feedPalette: feedPalette || null,
      registro: registro || null,
      // (v230) LECTURA PROFUNDA: catálogo completo (web profunda + PDFs),
      // link de la bio seguido y mapa foto→producto de las fotos de su
      // web — los recolectan las rutas con sus carreras acotadas.
      catalog: (deep && deep.catalog) || null,
      bioLink: (deep && deep.bioLink) || null,
      photoEntries: (deep && deep.photoEntries) || null,
      webCopy: webData ? String(webData.description || '') : '',
    });
  } catch (e) { console.error('[digest] build trial:', e.message); return null; }
}
// (v230) Lectura profunda de la prueba, cacheada por URL como el
// contexto web (una web que se prueba dos veces no se re-crawlea):
// catálogo profundo y link de bio corren con carrera — si la fuente es
// lenta, la prueba sigue con el fundamento de v229 y la lectura queda
// hecha para la próxima (la promesa sigue en segundo plano).
const trialDeepPromises = new Map();
function trialDeepCatalog(webData) {
  if (!webData || !webData.url) return Promise.resolve(null);
  const key = 'cat:' + webData.url;
  let p = trialDeepPromises.get(key);
  if (!p) {
    p = deepRead.fetchDeepCatalog(webData.url).catch(() => null);
    trialDeepPromises.set(key, p);
    if (trialDeepPromises.size > 300) trialDeepPromises.clear();
    p.then(() => { const t = setTimeout(() => trialDeepPromises.delete(key), 30 * 60 * 1000); if (t.unref) t.unref(); });
  }
  return p;
}
function trialBioLink(link) {
  if (!link) return Promise.resolve(null);
  const key = 'bio:' + link;
  let p = trialDeepPromises.get(key);
  if (!p) {
    p = deepRead.fetchBioLink(link).catch(() => null);
    trialDeepPromises.set(key, p);
    if (trialDeepPromises.size > 300) trialDeepPromises.clear();
    p.then(() => { const t = setTimeout(() => trialDeepPromises.delete(key), 30 * 60 * 1000); if (t.unref) t.unref(); });
  }
  return p;
}
const raceMs = (p, ms) => Promise.race([p, new Promise((r) => setTimeout(() => r(null), ms))]).catch(() => null);
/* Mapa foto→producto de la PRUEBA: clasifica las fotos de SU web contra
 * los ítems ya conocidos (web + catálogo), bajo el MISMO tope diario del
 * demo con IA y solo si hay clave. Best-effort total: sin mapa, la
 * semana sale con el gate foto↔tema de siempre. */
async function trialPhotoEntries(webPhotos, itemNames) {
  try {
    if (!Array.isArray(webPhotos) || !webPhotos.length || !itemNames || !itemNames.length) return null;
    const apiKey = process.env.OPENAI_API_KEY || '';
    if (!apiKey || !costs.demoAiCapOk()) return null;
    const photos = webPhotos.filter((w) => w && w.url && w.path).slice(0, deepRead.VISION_MAX_PHOTOS)
      .map((w) => ({ key: w.url, path: w.path }));
    if (!photos.length) return null;
    const entries = await deepRead.classifyDigestPhotos({ photos, items: itemNames, apiKey, fetchImpl: null });
    return entries && Object.keys(entries).length ? entries : null;
  } catch (e) { return null; }
}
// Transferencia TOTAL al registrarse: la cuenta nace con el fundamento
// de la prueba sembrado (digest persistido + ADN + perfil + colores).
// Solo completa campos vacíos/genéricos: jamás pisa datos del dueño.
function seedFromTrialDigest(userId, igRaw) {
  try {
    const ig = String(igRaw || '').trim().replace(/^@/, '').toLowerCase();
    if (!ig) return false;
    const hit = db.prepare('SELECT payload FROM trial_cache WHERE ig = ?').get(ig);
    if (!hit) return false;
    let out;
    try { out = JSON.parse(hit.payload); } catch (e) { return false; }
    let digest = (out && out.digest && typeof out.digest === 'object') ? out.digest : null;
    if (!digest) {
      // Payloads cacheados sin digest (motor anterior): se compila desde
      // lo que el payload sí trae — el fundamento no se descarta.
      digest = clientDigest.buildFromParts({
        business: out.business, category: out.category,
        web: out.web_info ? { name: out.web_info.name, description: out.web_info.description, services: out.web_info.services || [], city: out.web_info.city, palette: out.web_info.palette || [], url: out.web_info.url } : null,
        feed: out.profile ? { bio: out.profile.bio, captions: out.profile.captions || [], name: out.profile.name, handle: out.profile.handle } : null,
        feedPalette: out.feed_palette || null,
        registro: out.feed_register || null,
      });
    }
    if (!digest || (!clientDigest.hasFoundation(digest) && !digest.business)) return false;
    clientDigest.saveDigest(db, userId, digest);
    // ADN: merge respetando lo ya cargado (convención del ADN).
    try {
      const cur = readDna(userId);
      const frag = clientDigest.dnaFragmentFromDigest(digest);
      const merged = { ...cur };
      for (const k of Object.keys(frag)) {
        const empty = cur[k] == null || (Array.isArray(cur[k]) && !cur[k].length) || String(cur[k] || '').trim() === '';
        if (empty) merged[k] = frag[k];
      }
      if (JSON.stringify(merged) !== JSON.stringify(cur)) writeDna(userId, merged);
    } catch (e) { console.error('[digest] seed ADN:', e.message); }
    // Perfil: categoría real si la cuenta nació en 'otro'/vacía,
    // descripción si falta, IG si el digest lo conoce.
    try {
      const prof = getProfile(userId) || {};
      // (v235) UNA sola copia del mapa: TRIAL_CAT_MAP (junto a
      // buildTrialDigest) — la comparte applyTrialProfile.
      const catMap = TRIAL_CAT_MAP;
      const sets = [];
      const vals = [];
      const mappedCat = catMap[digest.category] || '';
      if (mappedCat && mappedCat !== 'otro' && (!prof.category || prof.category === 'otro')) { sets.push('category = ?'); vals.push(mappedCat); }
      if (!prof.description || prof.description.trim().length < 20) {
        // (v343) La descripción de la cuenta es el DETALLE DEL DUEÑO,
        // con sus palabras (fuentes.form.description): antes se
        // sembraba solo el "Ofrece: …" derivado y el texto completo
        // que el dueño escribió en la prueba se perdía — si una lista
        // salía mal, la cuenta nacía presentando ese error.
        const ownerText = (digest.fuentes && digest.fuentes.form && digest.fuentes.form.description) || '';
        if (ownerText) { sets.push('description = ?'); vals.push(String(ownerText).slice(0, 600)); }
        else {
          const descParts = [];
          if (digest.diferencial) descParts.push(digest.diferencial);
          const items = [...(digest.productos || []), ...(digest.servicios || [])].map((x) => (x && (x.nombre || x)) || '').filter(Boolean);
          if (items.length) descParts.push('Ofrece: ' + items.slice(0, 6).join(', ') + '.');
          if (descParts.length) { sets.push('description = ?'); vals.push(descParts.join(' ').slice(0, 600)); }
        }
      }
      const handle = digest.fuentes && digest.fuentes.feed && digest.fuentes.feed.handle;
      if (handle && !prof.ig_username) { sets.push('ig_username = ?'); vals.push(String(handle).slice(0, 40)); }
      // (v235) Subrubro confirmado: viaja del digest (rubro_id/digest.subcat)
      // a profiles.subrubro si el perfil todavía no tiene uno.
      const profSub = String(digest.subcat || (digest.rubro_id && digest.rubro_id.subrubro) || '').slice(0, 40);
      if (profSub && !prof.subrubro) { sets.push('subrubro = ?'); vals.push(profSub); }
      if (sets.length) { sets.push("updated_at = datetime('now')"); vals.push(userId); db.prepare(`UPDATE profiles SET ${sets.join(', ')} WHERE user_id = ?`).run(...vals); }
    } catch (e) { console.error('[digest] seed perfil:', e.message); }
    // Colores de marca desde la paleta del digest (si Ajustes no tiene).
    try {
      if ((digest.paleta || []).length >= 2) {
        getSettings(userId);
        const st = db.prepare('SELECT brand_colors FROM settings WHERE user_id = ?').get(userId);
        let has = false;
        try { const bc = JSON.parse((st && st.brand_colors) || 'null'); has = Array.isArray(bc) && bc.length >= 2; } catch (e) {}
        if (!has) {
          const hexes = digest.paleta.map((c) => c.hex).filter((h) => /^#[0-9a-fA-F]{6}$/.test(h || '')).slice(0, 3);
          if (hexes.length >= 2) db.prepare('UPDATE settings SET brand_colors = ? WHERE user_id = ?').run(JSON.stringify(hexes), userId);
        }
      }
    } catch (e) { console.error('[digest] seed colores:', e.message); }
    console.log(`[digest] fundamento sembrado desde la prueba → usuario ${userId} (hash ${digest.hash}, ${(digest.productos || []).length} productos, ${(digest.servicios || []).length} servicios, ${(digest.temas_feed || []).length} temas de feed)`);
    return true;
  } catch (e) { console.error('[digest] seedFromTrialDigest:', e.message); return false; }
}
// Learnings de contenido ("Conocer al cliente a fondo", Track B): qué rinde en el IG del cliente.
// Lee la tabla content_learnings (la crea otro track); si no existe o no hay datos → null, sin romper.
function getContentLearnings(userId) {
  try {
    const r = db.prepare('SELECT learnings_json FROM content_learnings WHERE user_id = ?').get(userId);
    if (r && r.learnings_json) { const o = JSON.parse(r.learnings_json); return (o && typeof o === 'object') ? o : null; }
  } catch (e) {}
  return null;
}
// ===== Track A — ADN extendido: endpoints /api/dna =====
// Whitelist de campos editables del ADN (todo lo demás —series, paused_tipos, etc.— nunca se toca).
const DNA_WHITELIST = ['producto_estrella', 'cliente_ideal', 'diferencial', 'tono',
  'productos', 'servicios', 'promos_activas', 'horarios', 'ubicacion', 'tono_ejemplos', 'preguntas_frecuentes'];
const DNA_SCALARS = ['producto_estrella', 'cliente_ideal', 'diferencial', 'tono', 'horarios', 'ubicacion'];
const DNA_LEGACY = ['producto_estrella', 'cliente_ideal', 'diferencial', 'tono'];
// array -> campo clave para dedupe (null = array de strings).
const DNA_ARRAYS = { productos: 'nombre', servicios: 'nombre', promos_activas: 'titulo', tono_ejemplos: null, preguntas_frecuentes: 'pregunta' };
const DNA_SCHEMA_DOC = `{
  "producto_estrella": "string",
  "cliente_ideal": "string",
  "diferencial": "string",
  "tono": "string",
  "productos": [{"nombre": "string", "precio": "string", "descripcion": "string", "es_estrella": false}],
  "servicios": [{"nombre": "string", "precio": "string", "descripcion": "string"}],
  "promos_activas": [{"titulo": "string", "detalle": "string", "vigencia": "string"}],
  "horarios": "string",
  "ubicacion": "string",
  "tono_ejemplos": ["frase real del dueno"],
  "preguntas_frecuentes": [{"pregunta": "string", "respuesta": "string"}]
}`;
const DNA_EXTRACTION_PROMPT = `Sos un extractor de datos de negocios para una app de marketing. Te paso un texto dictado por el dueno de un negocio. Devolvé SOLO un objeto JSON válido (sin markdown, sin explicaciones) siguiendo este esquema, incluyendo UNICAMENTE los campos que el texto mencione de forma explícita:\n${DNA_SCHEMA_DOC}\nReglas: los arrays van vacíos si no hay nada; NUNCA inventes ni deduzcas datos que no estén en el texto; usá las palabras del dueno cuando sea posible; es_estrella es true solo si el texto dice que ese producto es el principal, estrella o más vendido.`;

function dnaIsEmpty(v) {
  if (v === undefined || v === null) return true;
  if (typeof v === 'string') return !v.trim();
  if (Array.isArray(v)) return !v.length;
  return false;
}
// Campos esenciales del ADN: sin ellos no se genera a ciegas (Track A — gate de ADN).
// Devuelve la lista de los que faltan; [] = ADN completo.
const DNA_ESSENTIAL = ['producto_estrella', 'cliente_ideal', 'diferencial', 'tono'];
function dnaMissingFields(dna) {
  const d = (dna && typeof dna === 'object') ? dna : {};
  return DNA_ESSENTIAL.filter(k => dnaIsEmpty(d[k]));
}
// Merge del ADN extraído sobre el existente. Escalares: se pisan solo si el valor no está vacío;
// los 4 campos legacy no se pisan si ya tienen valor (protectLegacy). Arrays: dedupe por clave,
// existentes primero, tope 20 items.
function mergeExtractedDna(cur, extracted, opts) {
  const protectLegacy = !!(opts && opts.protectLegacy);
  const dna = { ...(cur || {}) };
  for (const k of DNA_SCALARS) {
    const v = extracted ? extracted[k] : undefined;
    if (dnaIsEmpty(v)) continue;
    if (protectLegacy && DNA_LEGACY.includes(k) && !dnaIsEmpty(cur && cur[k])) continue;
    dna[k] = typeof v === 'string' ? v.trim() : v;
  }
  for (const k of Object.keys(DNA_ARRAYS)) {
    const incoming = (extracted && Array.isArray(extracted[k])) ? extracted[k] : [];
    if (!incoming.length) continue;
    const key = DNA_ARRAYS[k];
    const idOf = (it) => (key ? String(((it || {})[key]) || '') : String(it || '')).toLowerCase().trim();
    const existing = (cur && Array.isArray(cur[k])) ? cur[k] : [];
    const seen = new Set();
    for (const it of existing) { const id = idOf(it); if (id) seen.add(id); }
    const merged = [...existing];
    for (const it of incoming) {
      const id = idOf(it);
      if (!id || seen.has(id)) continue;
      seen.add(id);
      merged.push(it);
      if (merged.length >= 20) break;
    }
    dna[k] = merged;
  }
  return dna;
}
// Intenta parsear JSON; si falla, recorta al substring entre el primer { y el último }.
function parseLooseJson(raw) {
  const s = String(raw || '').trim();
  if (!s) return null;
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}
// Extrae ADN estructurado de un texto con una sola llamada a gpt-4o-mini. Devuelve solo claves de la whitelist.
async function extractDnaFromText(text, apiKey) {
  const r = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${apiKey}` },
    body: JSON.stringify({
      model: 'gpt-4o-mini',
      temperature: 0.2,
      messages: [
        { role: 'system', content: DNA_EXTRACTION_PROMPT },
        { role: 'user', content: 'Extraé los datos del negocio de este texto:\n\n' + String(text || '').slice(0, 6000) },
      ],
    }),
  });
  if (!r.ok) throw new Error('openai ' + r.status);
  const j = await r.json();
  costs.trackUsage({ feature: 'dna', model: 'gpt-4o-mini', json: j });
  const content = (j && j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '';
  const parsed = parseLooseJson(content);
  if (!parsed || typeof parsed !== 'object') throw new Error('json inválido');
  const out = {};
  for (const k of DNA_WHITELIST) if (parsed[k] !== undefined) out[k] = parsed[k];
  return out;
}

