app.post('/api/ideas/:id/make', requireAuth, requireTrialValid, async (req, res) => {
  const uid = req.session.userId;
  const idea = db.prepare(`SELECT * FROM posty_ideas WHERE id = ? AND user_id = ? AND status = 'pending'`).get(req.params.id, uid);
  if (!idea) return res.status(404).json({ error: 'Esa idea ya no está 😅 Actualizá y probá de nuevo' });
  try {
    const r = await makeIdeaDraft(uid, idea);
    if (!r.ok) {
      // (v236) Vencida: mensaje honesto y definitivo, no un "probá en
      // un rato" que promete lo que nunca va a pasar.
      if (r.reason === 'stale') return res.status(410).json({ error: 'Esa idea ya pasó de fecha 😅 No la armo para que no publiques algo vencido — el lunes te traigo ideas frescas.' });
      if (r.reason === 'ai_cap') return res.status(429).json({ error: costs.MSG_CAP || 'Llegamos al tope de trabajo de IA por hoy 😅' });
      if (r.reason === 'no_carousel') return res.status(502).json({ error: 'No pude armar el carrusel ahora 😅 Probá en un rato' });
      return res.status(502).json({ error: 'No pude armar el posteo ahora 😅 Probá en un rato' });
    }
    res.json({ ok: true, post_id: r.post_id, media_type: r.media_type || 'image' });
  } catch (e) {
    console.error('[ideas-loop] make:', e.message);
    res.status(500).json({ error: 'No pude armar el posteo ahora 😅 Probá en un rato' });
  }
});

// ---------- 🤔 POSTY PREGUNTA (2026-10-19, v238) ----------
// Máximo 1 pregunta por semana, sobre lo que el fundamento no pudo leer
// solo: confirmar el rubro dudoso (prioridad máxima: de él cuelgan
// posteos y prompts), confirmar el estrella inferido, resolver una
// contradicción de precios, o un hueco del ADN (estrella, más vendido,
// promos, cliente ideal, qué NO publicar jamás). Selección y redacción
// determinísticas en posty-questions.js (cero IA). La pregunta se
// asegura AL LEER (mismo patrón que el barrido de ideas): la tarjeta
// vive en Schedule — donde aterriza el ritual de fotos del lunes — y
// el reporte semanal la lleva como dato. Sin popups, sin push nuevo.
// La respuesta cae al digest y al ADN como fuente más fuerte.
function weeklyQuestionFor(uid) {
  try {
    const wk = mondayKeyOf(tzToday(userTz(uid)));
    // (v306) El radar y el banco clave salen en el idioma de la cuenta.
    let lang = 'es';
    try { const u = db.prepare('SELECT lang FROM users WHERE id = ?').get(uid); if (u && u.lang === 'en') lang = 'en'; } catch (e) {}
    return postyQuestions.ensureWeeklyQuestion(db, uid, wk, undefined, { lang });
  } catch (e) { return null; }
}

app.get('/api/questions/current', requireAuth, (req, res) => {
  const uid = req.session.userId;
  res.json({ ok: true, question: weeklyQuestionFor(uid) });
});

app.post('/api/questions/:id/answer', requireAuth, (req, res) => {
  const uid = req.session.userId;
  try {
    const body = req.body || {};
    const r = postyQuestions.applyAnswer(db, uid, req.params.id, {
      value: typeof body.value === 'string' ? body.value : '',
      text: typeof body.text === 'string' ? body.text : '',
    });
    if (!r.ok) {
      if (r.reason === 'gone') return res.status(404).json({ error: 'esa pregunta ya no está 😅' });
      if (r.reason === 'empty') return res.status(400).json({ error: 'contame con tus palabras y lo guardo 😊' });
      if (r.reason === 'needs_detail') return res.status(400).json({ error: 'contame el descuento y hasta cuándo 😊' });
      if (r.reason === 'bad_option') return res.status(400).json({ error: 'esa opción no es válida 😅' });
      return res.status(400).json({ error: 'no pude guardarla 😅' });
    }
    try { track(uid, 'question_answered', r.applied || ''); } catch (e) {}
    res.json({ ok: true, applied: r.applied });
  } catch (e) {
    console.error('[posty-pregunta] answer:', e.message);
    res.status(500).json({ error: 'no pude guardarla 😅 probá de nuevo' });
  }
});

app.post('/api/questions/:id/dismiss', requireAuth, (req, res) => {
  const uid = req.session.userId;
  try {
    const r = postyQuestions.dismissQuestion(db, uid, req.params.id);
    try { track(uid, 'question_dismissed', String(req.params.id)); } catch (e) {}
    res.json({ ok: true, changed: r.changed });
  } catch (e) { res.status(500).json({ error: 'no pude guardarla 😅' }); }
});

// Los endpoints admin del loop viven tras requireAdminToken (definido más
// abajo, junto al resto de rutas /api/admin/*): buscar "admin/ideas/run".

// ---------- Magic link (entrar sin contraseña) ----------
// Aplica el perfil de la prueba a un usuario NUEVO, espejando lo que hoy hace
// el cliente de prueba.html tras /api/auth/register (mismo catMap, mismos
// topes, mismos defaults). La data viaja dentro del token (15 min de vida),
// así que siempre es fresca: no necesita el chequeo de 24h del localStorage.
function applyTrialProfile(userId, tp) {
  if (!tp || typeof tp !== 'object') return;
  try {
    const catMap = TRIAL_CAT_MAP; // (v235) copia única, junto a buildTrialDigest
    const businessName = String(tp.business_name || '').slice(0, 80);
    if (businessName) {
      getProfile(userId);
      db.prepare(
        `UPDATE profiles SET business_name=?, category=?, tone=?, description=?, ig_username=?, competitors=?, goal=?, updated_at=datetime('now') WHERE user_id=?`
      ).run(
        businessName,
        catMap[tp.category] || 'otro',
        tp.tone === 'tu' ? 'profesional' : 'canchero',
        String(tp.description || '').slice(0, 600),
        String(tp.ig_username || '').slice(0, 40),
        String(tp.competitors || '').slice(0, 200),
        'vender',
        userId
      );
      // (v235) El subrubro confirmado en la prueba también se aplica
      // (solo si el perfil no tiene uno cargado).
      const tpSub = String(tp.subcat || '').slice(0, 40);
      if (tpSub) {
        try { db.prepare(`UPDATE profiles SET subrubro=? WHERE user_id=? AND (subrubro IS NULL OR subrubro='')`).run(tpSub, userId); } catch (e) {}
      }
    }
    // brand_colors: mismo formato que /api/settings (JSON de hex válidos, >= 2)
    const bc = (tp.brand_colors || []).filter((c) => /^#[0-9a-fA-F]{6}$/.test(c));
    if (bc.length >= 2) {
      getSettings(userId);
      db.prepare(`UPDATE settings SET brand_colors=?, updated_at=datetime('now') WHERE user_id=?`)
        .run(JSON.stringify(bc.slice(0, 3)), userId);
    }
  } catch (e) { console.error('[magic] trial_profile:', e.message); }
}

// ---------- Auth: rate-limit en memoria + página de error con salida ----------
// Ventanas cortas anti abuso y anti doble-click (login/reset/forgot): el
// proceso es único; alcanza para frenar fuerza bruta sin infraestructura.
const AUTH_HITS = new Map();
function authHitCount(key, windowMs) {
  const now = Date.now();
  const arr = (AUTH_HITS.get(key) || []).filter((t) => now - t < windowMs);
  AUTH_HITS.set(key, arr);
  return arr.length;
}
function authHitRecord(key) {
  const arr = AUTH_HITS.get(key) || [];
  arr.push(Date.now());
  AUTH_HITS.set(key, arr);
}
function authHitClear(key) { AUTH_HITS.delete(key); }
// Página mínima de marca para callbacks/links abiertos desde un email o una
// app externa: nada de texto plano sin salida (auditoría 2026-10-21).
function htmlLinkPage(title, msg) {
  return '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Posty</title></head>'
    + '<body style="margin:0;font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;background:#F2F9FD;color:#0A1E33;display:flex;min-height:100vh;align-items:center;justify-content:center;padding:24px;box-sizing:border-box">'
    + '<div style="max-width:420px;width:100%;background:#fff;border-radius:18px;padding:32px 28px;text-align:center;box-shadow:0 10px 40px rgba(10,30,51,.10)">'
    + '<img src="/ai-avatar.png" alt="Posty" width="72" height="72" style="border-radius:50%">'
    + '<h1 style="font-size:21px;margin:16px 0 8px">' + title + '</h1>'
    + '<p style="font-size:15px;line-height:1.55;color:#47617A;margin:0 0 22px">' + msg + '</p>'
    + '<a href="/#/login" style="display:inline-block;background:#FEC14D;color:#0A1E33;font-weight:800;font-size:15px;padding:13px 30px;border-radius:999px;text-decoration:none">Volver a Posty</a>'
    + '</div></body></html>';
}

// Siempre responde {ok:true} para no revelar si el email existe.
app.post('/api/auth/magic-request', async (req, res) => {
  const { email, trial_ig, ref, utm, trial_profile } = req.body || {};
  const em = String(email || '').trim().toLowerCase();
  let sessionNow = false;
  try {
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(em)) return res.json({ ok: true });
    // Rate limit: máx 5 tokens por hora por email
    const hourAgo = Date.now() - 3600 * 1000;
    const n = db.prepare('SELECT COUNT(*) AS c FROM magic_tokens WHERE email = ? AND created_at >= ?').get(em, hourAgo).c;
    if (n >= 5) return res.json({ ok: true });
    const token = crypto.randomBytes(32).toString('hex');
    const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
    const payload = JSON.stringify({
      trial_ig: trial_ig || null,
      ref: ref || null,
      utm: utm || null,
      trial_profile: trial_profile || null,
    });
    db.prepare('INSERT INTO magic_tokens (token_hash, email, payload, created_at, expires_at, used) VALUES (?,?,?,?,?,0)')
      .run(tokenHash, em, payload, Date.now(), Date.now() + 15 * 60 * 1000);
    let emailSent = false;
    if (process.env.RESEND_API_KEY) {
      const base = (process.env.BASE_URL || 'https://postycommunitymanager.com').replace(/\/$/, '');
      const link = `${base}/api/auth/magic?token=${token}`;
      try { const mr = await magicLinkEmail(em, link); if (mr && mr.ok) emailSent = true; }
      catch (e) { console.error('[magic] email:', e.message); }
    }
    // Sesión inmediata (2026-10-16, auditoría #3): si el email NO tiene
    // cuenta y el pedido trae la prueba recién hecha en ESTE navegador, la
    // cuenta se crea acá mismo (espejo exacto del canje) y la sesión queda
    // abierta — el pico de emoción ya no depende de que el email llegue en
    // 15 minutos. El link sigue viajando como respaldo (otros dispositivos).
    // Un email CON cuenta jamás recibe sesión sin canjear el link.
    try {
      const existing = db.prepare('SELECT id FROM users WHERE email = ?').get(em);
      if (!existing && (trial_ig || trial_profile)) {
        const code = newReferralCode();
        let referredBy = null;
        const refCode = String(ref || '').trim().toLowerCase().slice(0, 16);
        if (/^[a-z0-9]{4,16}$/.test(refCode)) {
          const referrer = db.prepare('SELECT id FROM users WHERE referral_code = ?').get(refCode);
          if (referrer && referrer.id) referredBy = referrer.id;
        }
        const trialEnds = Date.now() + TRIAL_DAYS * 24 * 3600 * 1000;
        const utmO = (utm && typeof utm === 'object') ? utm : {};
        const r2 = db.prepare("INSERT INTO users (email, password_hash, referral_code, referred_by, trial_ends_at, utm_source, utm_campaign, trust_level, autopilot_enabled) VALUES (?, '', ?, ?, ?, ?, ?, 1, 1)")
          .run(em, code, referredBy, trialEnds, String(utmO.source || '').slice(0, 40), String(utmO.campaign || '').slice(0, 80));
        const userId = r2.lastInsertRowid;
        try {
          const expBiz = (trial_profile && trial_profile.business_name) || null;
          const nImp = importTrialWeek(userId, trial_ig, expBiz);
          applyTrialLang(userId, trial_ig); // (v274) cuenta EN si la prueba fue EN
          if (nImp) console.log(`[posta] semana de prueba importada (sesión inmediata): ${nImp} borradores → usuario ${userId}`);
          recordTrialImport(userId, trial_ig, nImp, false);
          streakFromTrialImport(userId, nImp);
        } catch (e) { console.error('[posta] importTrialWeek (inmediata):', e.message); }
        applyTrialProfile(userId, trial_profile);
        seedFromTrialDigest(userId, trial_ig); // (v229) FUNDAMENTO: transferencia total también por magic-link
        track(userId, 'registered');
        evTrack(userId, 'account_created', {});
        await new Promise((resolve) => req.session.regenerate(() => { req.session.userId = userId; resolve(); }));
        sessionNow = true;
      }
    } catch (e) { console.error('[magic] sesión inmediata:', e.message); }
  } catch (e) { console.error('[magic] request:', e.message); }
  if (!sessionNow && !emailSent) {
    // El acceso de este email DEPENDE del correo (cuenta existente, o alta
    // sin prueba en curso) y el correo no salió: éxito falso jamás.
    console.error('[magic] request sin salida: el email no se envió (¿RESEND_API_KEY?) para', em);
    return res.status(503).json({ ok: false, error: 'No pudimos enviar el email de acceso 😅 Probá de nuevo en un rato.' });
  }
  res.json({ ok: true, session: sessionNow });
});

// Canjea el magic link: token de un solo uso, 15 min de vida.
// Usuario nuevo → se crea espejando /api/auth/register (sin contraseña:
// password_hash queda vacío y el login con contraseña da 401, nunca 500).
// Usuario existente → solo entra (+ importa la semana de /prueba si hay).
app.get('/api/auth/magic', (req, res) => {
  const token = String((req.query && req.query.token) || '');
  try {
    const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
    const row = db.prepare('SELECT * FROM magic_tokens WHERE token_hash = ? AND used = 0').get(tokenHash);
    if (!row || row.expires_at < Date.now())
      return res.status(400).send(htmlLinkPage('Ese link venció o ya se usó 😅', 'Pedí uno nuevo desde la app: dura 15 minutos y entrás directo.'));
    db.prepare('UPDATE magic_tokens SET used = 1 WHERE token_hash = ?').run(tokenHash);
    let payload = {};
    try { payload = JSON.parse(row.payload || '{}'); } catch (e) {}
    const email = row.email;
    const user = db.prepare('SELECT * FROM users WHERE email = ?').get(email);
    let sessUserId = null;
    if (!user) {
      const code = newReferralCode();
      let referredBy = null;
      const refCode = String(payload.ref || '').trim().toLowerCase().slice(0, 16);
      if (/^[a-z0-9]{4,16}$/.test(refCode)) {
        const referrer = db.prepare('SELECT id FROM users WHERE referral_code = ?').get(refCode);
        if (referrer && referrer.id) referredBy = referrer.id;
      }
      const trialEnds = Date.now() + TRIAL_DAYS * 24 * 3600 * 1000;
      const utm = (payload.utm && typeof payload.utm === 'object') ? payload.utm : {};
      const utmS = String(utm.source || '').slice(0, 40);
      const utmC = String(utm.campaign || '').slice(0, 80);
      const r = db.prepare("INSERT INTO users (email, password_hash, referral_code, referred_by, trial_ends_at, utm_source, utm_campaign, trust_level, autopilot_enabled) VALUES (?, '', ?, ?, ?, ?, ?, 1, 1)")
        .run(email, code, referredBy, trialEnds, utmS, utmC);
      const userId = r.lastInsertRowid;
      try {
        // El negocio esperado sale del perfil de la prueba (lo que el usuario
        // escribió en SU navegador): si la semana cacheada es de otro negocio,
        // no se importa (bug 2026-10-03).
        const expBiz = (payload.trial_profile && payload.trial_profile.business_name) || null;
        const nImp = importTrialWeek(userId, payload.trial_ig, expBiz);
        if (nImp) console.log(`[posta] semana de prueba importada (magic): ${nImp} borradores → usuario ${userId}`);
        recordTrialImport(userId, payload.trial_ig, nImp, false); // fix #2: usuario nuevo, sin posteos previos
        streakFromTrialImport(userId, nImp);
      } catch (e) { console.error('[posta] importTrialWeek:', e.message); }
      applyTrialProfile(userId, payload.trial_profile);
      seedFromTrialDigest(userId, payload.trial_ig); // (v229) FUNDAMENTO: transferencia total también en el canje magic
      track(userId, 'registered');
      evTrack(userId, 'account_created', {});
      sessUserId = userId;
    } else {
      sessUserId = user.id;
      try {
        const hadPosts = (db.prepare('SELECT COUNT(*) AS c FROM posts WHERE user_id = ?').get(user.id).c || 0) > 0;
        const expBiz = (payload.trial_profile && payload.trial_profile.business_name) || null;
        const nImp = importTrialWeek(user.id, payload.trial_ig, expBiz);
        if (nImp) console.log(`[posta] semana de prueba importada (magic, login): ${nImp} borradores → usuario ${user.id}`);
        recordTrialImport(user.id, payload.trial_ig, nImp, hadPosts); // fix #2: no pisar con un 0 si el import no se intentó
        streakFromTrialImport(user.id, nImp);
      } catch (e) { console.error('[posta] importTrialWeek:', e.message); }
    }
    return req.session.regenerate(() => { req.session.userId = sessUserId; res.redirect('/#/'); });
  } catch (e) {
    console.error('[magic] redeem:', e.message);
    return res.status(400).send(htmlLinkPage('Ese link no me cierra 😅', 'Pedí uno nuevo desde la app y probá de nuevo.'));
  }
});

// ---------- Recuperar contraseña ----------
try { db.exec(`CREATE TABLE IF NOT EXISTS password_resets (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at INTEGER NOT NULL,
  used INTEGER DEFAULT 0
)`); } catch (e) {}

// Siempre responde OK para no revelar si el email existe.
app.post('/api/auth/forgot', async (req, res) => {
  const email = String((req.body && req.body.email) || '').trim().toLowerCase();
  // Sin proveedor de email configurado el link JAMÁS sale: responder ok era
  // el éxito falso del incidente 2026-10-21. Error honesto y visible.
  if (!process.env.RESEND_API_KEY) {
    console.error('[posta] forgot: RESEND_API_KEY ausente — el email de reset no puede salir');
    return res.status(503).json({ error: 'El envío de emails está en mantenimiento 😅 Probá de nuevo en un rato.' });
  }
  // Rate-limit: máx 5 pedidos por hora por email+IP (espejo del magic-request).
  const rlKey = 'forgot|' + email + '|' + (req.ip || '');
  if (authHitCount(rlKey, 3600 * 1000) >= 5)
    return res.status(429).json({ error: 'Ya pediste varios links 😅 Esperá una hora y probá de nuevo.' });
  authHitRecord(rlKey);
  try {
    const user = db.prepare('SELECT id, email FROM users WHERE email = ?').get(email);
    if (user) {
      const token = crypto.randomBytes(32).toString('hex');
      const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
      db.prepare('DELETE FROM password_resets WHERE user_id = ?').run(user.id);
      db.prepare('INSERT INTO password_resets (user_id, token_hash, expires_at) VALUES (?,?,?)')
        .run(user.id, tokenHash, Date.now() + 3600 * 1000);
      // BASE_URL canónica (antes: header Host — un proxy o un request armado
      // podía mandar el link a otro dominio; magic ya usaba BASE_URL).
      const base = (process.env.BASE_URL || 'https://postycommunitymanager.com').replace(/\/$/, '');
      const link = `${base}/#/reset?token=${token}`;
      const r = await sendEmail({
        to: user.email,
        subject: 'Recuperá tu contraseña 🔑',
        html: `<div style="font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;max-width:560px;margin:0 auto;color:#0A1E33">
          <div style="background:#2793C8;padding:24px 28px;border-radius:14px 14px 0 0">
            <div style="font-size:22px;font-weight:800;color:#fff">posty<span style="color:#FEC14D">.</span></div>
          </div>
          <div style="background:#F2F9FD;padding:28px;border-radius:0 0 14px 14px">
            <p style="font-size:16px;line-height:1.6">¡Hola! Soy Posty 🤖 Me pediste cambiar tu contraseña. Tocá el botón y elegí una nueva:</p>
            <p style="text-align:center;margin:26px 0"><a href="${link}" style="display:inline-block;background:#FEC14D;color:#0A1E33;font-weight:800;font-size:16px;padding:14px 34px;border-radius:999px;text-decoration:none">Cambiar mi contraseña</a></p>
            <p style="font-size:13px;line-height:1.6;color:#47617A">El link vence en 1 hora. Si no fuiste vos, ignorá este mail 😊</p>
          </div></div>`,
      });
      if (!r || !r.ok) {
        console.error('[posta] forgot: sendEmail no entregó:', r && (r.error || r.skipped ? 'omitido' : 'sin detalle'));
        return res.status(502).json({ error: 'No pude enviar el email 😅 Probá de nuevo en un rato.' });
      }
    }
  } catch (e) {
    console.error('[posta] forgot:', e.message);
    return res.status(500).json({ error: 'Algo falló de nuestro lado 😅 Probá de nuevo' });
  }
  res.json({ ok: true });
});

app.post('/api/auth/reset', (req, res) => {
  const token = String((req.body && req.body.token) || '');
  const password = String((req.body && req.body.password) || '');
  const rlKey = 'reset|' + (req.ip || '');
  if (authHitCount(rlKey, 15 * 60 * 1000) >= 10)
    return res.status(429).json({ error: 'Demasiados intentos 😅 Esperá 15 minutos y pedí un link nuevo.' });
  if (!token || password.length < 6) {
    authHitRecord(rlKey);
    return res.status(400).json({ error: 'Necesito el link válido y una contraseña de 6 caracteres como mínimo 🔑' });
  }
  try {
    const tokenHash = crypto.createHash('sha256').update(token).digest('hex');
    const row = db.prepare('SELECT * FROM password_resets WHERE token_hash = ? AND used = 0').get(tokenHash);
    if (!row || row.expires_at < Date.now()) {
      authHitRecord(rlKey);
      return res.status(400).json({ error: 'Ese link venció o ya se usó 😅 Pedí uno nuevo' });
    }
    const hash = bcrypt.hashSync(password, 10);
    db.prepare('UPDATE users SET password_hash = ? WHERE id = ?').run(hash, row.user_id);
    db.prepare('UPDATE password_resets SET used = 1 WHERE id = ?').run(row.id);
    // Un reset exitoso cierra TODAS las demás sesiones de la cuenta: si el
    // cambio fue por una cuenta comprometida, nadie queda adentro con la
    // clave vieja (las sesiones duran hasta 365 días).
    try {
      const rows = db.prepare('SELECT sid, sess FROM sessions').all();
      for (const r2 of rows) {
        try {
          const sd = JSON.parse(r2.sess);
          if (sd && sd.userId === row.user_id && r2.sid !== req.sessionID)
            db.prepare('DELETE FROM sessions WHERE sid = ?').run(r2.sid);
        } catch (e) {}
      }
    } catch (e) { console.error('[posta] reset: no pude revocar sesiones:', e.message); }
    authHitClear(rlKey);
    // Sesión regenerada tras autenticar (anti fijación de sesión).
    req.session.regenerate(() => { req.session.userId = row.user_id; res.json({ ok: true }); });
  } catch (e) {
    res.status(400).json({ error: 'No pude cambiarla 😅 Probá de nuevo' });
  }
});

// ---------- Nudges proactivos de Posty (pide por chat, ~1/semana) ----------
// Posty pregunta en el chat lo que le falta: foto del producto, nota de voz, referencia de estilo.
try { db.exec(`CREATE TABLE IF NOT EXISTS posty_nudges (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  kind TEXT NOT NULL,
  created_at INTEGER DEFAULT (strftime('%s','now')*1000),
  shown_at INTEGER DEFAULT 0,
  done_at INTEGER DEFAULT 0
)`); } catch (e) {}

function nudgeMissing(uid) {
  // Kind más prioritario que le falta al usuario (foto > voz > estilo), o null.
  try {
    const done = new Set(db.prepare(`SELECT kind FROM posty_nudges WHERE user_id = ? AND done_at > 0`).all(uid).map(r => r.kind));
    const photo = db.prepare(`SELECT id FROM assets WHERE user_id = ? AND kind = 'photo' LIMIT 1`).get(uid);
    if (!photo && !done.has('photo')) return 'photo';
    let j = {};
    try { const r = db.prepare('SELECT dna_json FROM business_dna WHERE user_id = ?').get(uid); j = JSON.parse((r && r.dna_json) || '{}'); } catch (e) {}
    const hasDesc = String(j.descripcion || j.description || j.negocio || j.business_description || '').trim().length > 20;
    if (!hasDesc && !done.has('voice')) return 'voice';
    if (!String(j.inspo || '').trim() && !done.has('inspo')) return 'inspo';
  } catch (e) {}
  return null;
}

app.get('/api/nudges/pending', requireAuth, (req, res) => {
  try {
    const uid = req.session.userId;
    const n = db.prepare(`SELECT * FROM posty_nudges WHERE user_id = ? AND shown_at = 0 AND done_at = 0 ORDER BY id ASC LIMIT 1`).get(uid);
    if (!n) return res.json({ nudge: null });
    // Re-validar: si ya lo resolvió por otro lado, marcar hecho y no mostrar.
    const stillMissing = nudgeMissing(uid);
    if (stillMissing !== n.kind) {
      db.prepare(`UPDATE posty_nudges SET done_at = ? WHERE id = ?`).run(Date.now(), n.id);
      return res.json({ nudge: null });
    }
    db.prepare(`UPDATE posty_nudges SET shown_at = ? WHERE id = ?`).run(Date.now(), n.id);
    res.json({ nudge: { id: n.id, kind: n.kind } });
  } catch (e) { res.json({ nudge: null }); }
});

app.post('/api/nudges/done', requireAuth, (req, res) => {
  try {
    const kind = String((req.body && req.body.kind) || '');
    if (kind) db.prepare(`UPDATE posty_nudges SET done_at = ? WHERE user_id = ? AND kind = ? AND done_at = 0`).run(Date.now(), req.session.userId, kind);
  } catch (e) {}
  res.json({ ok: true });
});
// VOZ DE CHAT (2026-10-21, mandato de Valentino): el chat de Posty escribe
// como un amigo por WhatsApp — todo en minúscula y SIN signos de apertura
// (nada de ¡ ni ¿; los de cierre van normal). La minúscula sale del prompt y
// de las frases escritas a mano; esta es la ÚNICA red programática permitida:
// si una salida de chat ARRANCA con ¡ o ¿, se lo saca. Jamás lowercasear a
// ciegas una salida del modelo (rompería nombres propios del negocio).
function chatStripOpen(text) {
  return String(text == null ? '' : text).replace(/^\s*[¡¿]+\s*/, '');
}

// La IA entrevista al dueño por chat y extrae el perfil del negocio.
// El frontend manda el historial; el backend devuelve la próxima intervención.
const OB_STEPS = [
  { key: 'nombre', pregunta: 'cómo se llama tu negocio? 🏪' },
  { key: 'vende', pregunta: 'qué vendés? contame con tus palabras, sin vueltas.' },
  { key: 'cliente', pregunta: 'a quién le vendés? quién es tu cliente ideal?' },
  { key: 'distinto', pregunta: 'qué te hace distinto de otros que venden lo mismo?' },
  { key: 'instagram', pregunta: 'cuál es tu instagram? o pasame el de un competidor que te guste para chusmear el estilo. si no tenés, decime "saltear".' },
  { key: 'logo', pregunta: 'subí tu logo y saco tus colores de ahí 🎨. si no lo tenés a mano, decime "saltear".' },
  { key: 'objetivo', pregunta: 'cuál es tu objetivo principal con instagram?' },
  { key: 'fotos', pregunta: '📸 última: subí hasta 5 fotos de tu negocio — tu local, tus productos, vos laburando. con esas fotos la IA aprende cómo se ve lo que hacés y te genera contenido nuevo cada semana, sin que tengas que pensar en fotos. sacalas con luz de día si podés ☀️ si preferís, escribí "saltear".' },
];
const OB_GOAL_CHIPS = ['Vender más', 'Conseguir seguidores', 'Llenar mi local', 'Contar novedades'];
const OB_GREETING = 'hola! soy posty, tu community manager 🙌 te hago unas preguntas rápidas para conocer tu negocio a fondo y armarte todo. son 8, dale que va:';

app.post('/api/onboarding/chat', requireAuth, async (req, res) => {
  try {
    const history = Array.isArray(req.body.history)
      ? req.body.history.filter(m => m && (m.role === 'user' || m.role === 'assistant') && typeof m.text === 'string').slice(-20)
      : [];
    const userCount = history.filter(m => m.role === 'user').length;
    if (userCount >= OB_STEPS.length) return res.json({ ok: true, done: true, answered: userCount });
    const step = OB_STEPS[userCount];
    let reply;
    if (!history.length) {
      reply = `${OB_GREETING} ${step.pregunta}`;
    } else {
      const lastUser = [...history].reverse().find(m => m.role === 'user') || { text: '' };
      const apiKey = (getSettings(req.session.userId).openai_key) || process.env.OPENAI_API_KEY || '';
      if (!apiKey) {
        reply = `buenísimo! ${step.pregunta}`;
      } else {
        try {
          const r = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${apiKey}` },
            body: JSON.stringify({
              model: 'gpt-4o-mini',
              messages: [
                { role: 'system', content: `Sos Posty, el community manager personal de este negocio, entrevistando a su dueño para conocerlo a fondo. Tu nombre es Posty, siempre: nunca digas "Posta". Ya van ${userCount} de ${OB_STEPS.length} preguntas. El dueño acaba de responder: "${(lastUser.text || '').slice(0, 300)}". Escribí 1-2 líneas en español rioplatense con voseo: primero un acuse cálido y ESPECÍFICO de lo que dijo (nada genérico), y después hacé la siguiente pregunta: "${step.pregunta}". Si su respuesta fue evasiva ("no sé", "saltear", vacía o de una palabra), no insistas: pasá a la siguiente con buena onda. Nunca hagas más de una pregunta. Escribí todo en minúscula, como un amigo por WhatsApp: sin signos de apertura (nada de ¡ ni ¿; los de cierre van normal) y frases cortas.` },
              ],
              max_tokens: 220, temperature: 0.8,
            }),
            signal: AbortSignal.timeout(20000),
          });
          const j = await r.json();
          costs.trackUsage({ feature: 'onboarding', userId: req.session.userId, model: 'gpt-4o-mini', json: j });
          const txt = String((j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '').trim();
          reply = cortar(txt, 500) || `buenísimo! ${step.pregunta}`;
        } catch (e) { reply = `buenísimo! ${step.pregunta}`; }
      }
    }
    reply = chatStripOpen(reply);
    res.json({
      ok: true, done: false, reply, answered: userCount,
      chips: step.key === 'objetivo' ? OB_GOAL_CHIPS : null,
      awaitLogo: step.key === 'logo',
      awaitPhotos: step.key === 'fotos',
    });
  } catch (e) {
    console.error('[onboarding/chat]', e.message);
    res.json({ ok: false, error: 'No pudimos continuar' });
  }
});

app.post('/api/onboarding/finish', requireAuth, async (req, res) => {
  try {
    const history = Array.isArray(req.body.history) ? req.body.history.filter(m => m && m.role === 'user' && m.text) : [];
    const apiKey = (getSettings(req.session.userId).openai_key) || process.env.OPENAI_API_KEY || '';
    const qa = history.map((m, i) => `P${i + 1}: ${m.q || ''}\nR: ${m.text}`).join('\n');
    let profile = { business_name: '', category: 'otro', description: '', audience: '', differentiator: '', instagram: '', goal: '' };
    let summary = '';
    if (apiKey && qa) {
      try {
        const r = await fetch('https://api.openai.com/v1/chat/completions', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${apiKey}` },
          body: JSON.stringify({
            model: 'gpt-4o-mini',
            response_format: { type: 'json_object' },
            messages: [
              { role: 'system', content: 'Analizás la entrevista a un dueño de negocio y devolvés SOLO JSON: {"business_name":"...","category":"...","description":"...","audience":"...","differentiator":"...","instagram":"...","goal":"...","summary":"..."}. Reglas: category = la más cercana de [ropa, gastronomia, cafeteria, belleza, barberia, fitness, salud, mascotas, servicios, educacion, tecnologia, hogar, inmobiliaria, eventos, viajes, arte, otro]. description = 1-2 frases que resuman qué vende y para quién, con sus palabras. goal = una de [vender, seguidores, local, novedades] según lo que dijo (o vacío). summary = 2-3 líneas cálidas en español rioplatense con voseo, todo en minúscula y sin signos de apertura (nada de ¡ ni ¿), como un chat de WhatsApp, contándole lo que entendiste de su negocio, como un community manager que lo escuchó de verdad. Si un dato no está, dejalo vacío. Nada de texto fuera del JSON.' },
              { role: 'user', content: qa.slice(0, 3000) },
            ],
            max_tokens: 600, temperature: 0.5,
          }),
          signal: AbortSignal.timeout(25000),
        });
        const j = await r.json();
        costs.trackUsage({ feature: 'onboarding', userId: req.session.userId, model: 'gpt-4o-mini', json: j });
        const txt = String((j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '');
        const mm = txt.match(/\{[\s\S]*\}/);
        if (mm) {
          const p = JSON.parse(mm[0]);
          for (const k of Object.keys(profile)) if (typeof p[k] === 'string') profile[k] = p[k].slice(0, 600);
          if (typeof p.summary === 'string') summary = p.summary.slice(0, 600);
        }
      } catch (e) { console.error('[onboarding/extract]', e.message); }
    }
    if (!profile.business_name && history[0] && history[0].text) profile.business_name = cortar(history[0].text, 80);
    if (!summary) summary = profile.business_name ? `listo! ya conozco a ${profile.business_name} 🙌` : 'listo! ya te conozco un poco más 🙌';
    summary = chatStripOpen(summary);
    res.json({ ok: true, profile, summary });
  } catch (e) {
    console.error('[onboarding/finish]', e.message);
    res.json({ ok: false, error: 'No pudimos cerrar la entrevista' });
  }
});

