// Resuelve una ruta /media/xxx a archivo local dentro de MEDIA_DIR (anti path traversal)
function mediaFile(localPath) {
  if (!localPath || typeof localPath !== 'string' || !localPath.startsWith('/media/')) return null;
  const file = path.join(MEDIA_DIR, path.basename(localPath));
  if (!file.startsWith(path.resolve(MEDIA_DIR) + path.sep)) return null;
  return fs.existsSync(file) ? file : null;
}

// ---------- Generador de video ----------
app.post('/api/videos', requireAuth, async (req, res) => {
  if (!ffmpegAvailable()) {
    return res.status(503).json({ error: 'Video no disponible en el servidor todavía — probá en un rato 🙏' });
  }
  const { scenes, music_path } = req.body || {};
  if (!Array.isArray(scenes) || !scenes.length || scenes.length > 5) {
    return res.status(400).json({ error: 'El video lleva de 1 a 5 escenas' });
  }
  try {
    const prepared = scenes.map((s, i) => {
      const file = mediaFile(s.image_path);
      if (!file) throw new Error(`Escena ${i + 1}: imagen inválida`);
      const duration = Math.min(30, Math.max(1, Math.round(Number(s.duration) || 3)));
      return { file, text: String(s.text || '').slice(0, 140), duration };
    });
    const total = prepared.reduce((a, s) => a + s.duration, 0);
    if (total > 60) return res.status(400).json({ error: 'El video no puede durar más de 60 segundos' });
    let musicFile = null;
    if (music_path) {
      musicFile = mediaFile(music_path);
      if (!musicFile) return res.status(400).json({ error: 'Música inválida' });
    }
    const out = await renderVideo({ scenes: prepared, musicFile, mediaDir: MEDIA_DIR });
    res.json({ ok: true, url: out.url, duration: out.duration });
  } catch (e) {
    console.error('[posta] Error generando video:', e.message);
    res.status(500).json({ error: e.message || 'No se pudo generar el video' });
  }
});

// ---------- Posts ----------
// ---------- 🧠 Análisis (2026-10-19): el cerebro con casa propia ----------
// La radiografía de SU cuenta es de todos los planes; el mercado completo
// (competencia + posición + decisiones) es la capa Growth — el gateo vive en
// analysis-engine.gateForPlan y se aplica SIEMPRE acá, en la salida.
function peerHandlesFromText(text, max = 3) {
  const out = [];
  const raw = String(text || '');
  const re = /@?([a-zA-Z0-9._]{3,40})/g;
  let m;
  while ((m = re.exec(raw)) && out.length < max) {
    const h = feedAudit.sanitizeHandle(m[1]);
    if (!h || h.length < 3) continue;
    if (/^(www|com|ar|http|https)$/i.test(h)) continue;
    if (!out.includes(h)) out.push(h);
  }
  return out;
}
async function fetchPeersForAnalysis(handles) {
  const one = async (h) => {
    try {
      const data = await Promise.race([
        feedAudit.fetchAuditData(h),
        new Promise((r) => setTimeout(() => r(null), 3500)),
      ]);
      if (data && data.ok) return { handle: h, followers: data.profile ? data.profile.followers : null, posts: data.posts || [] };
    } catch (e) { /* un par sin datos no frena el análisis */ }
    return null;
  };
  const all = await Promise.all((handles || []).slice(0, 3).map(one));
  return all.filter(Boolean);
}
async function coldReviewsFor(businessName, city) {
  try {
    const gp = require('./google-places');
    const q = [businessName, city].filter(Boolean).join(' ');
    if (!q) return null;
    const place = await Promise.race([gp.findPlace(q), new Promise((r) => setTimeout(() => r(null), 3000))]);
    if (!place || !place.place_id) return null;
    const rv = await Promise.race([gp.getPlaceReviews(place.place_id), new Promise((r) => setTimeout(() => r(null), 3000))]);
    if (!rv || !rv.rating) return null;
    return { rating: rv.rating, total: rv.total_ratings || 0 };
  } catch (e) { return null; }
}
/* Construye (y persiste) el análisis de una cuenta. Reusa TODO lo auditado:
 * feed-audit para los datos públicos, client-digest para el fundamento,
 * google-places para las reseñas del plan de nacimiento. Nunca lanza. */
async function buildAccountAnalysis(uid, opts = {}) {
  const prof = db.prepare('SELECT business_name, category, description, ig_username, competitors FROM profiles WHERE user_id = ?').get(uid) || {};
  const digest = clientDigest.getDigest(db, uid);
  const plan = planForUid(uid);
  const prior = analysisEngine.priorAnalysis(db, uid);
  const peers = await fetchPeersForAnalysis(peerHandlesFromText(prof.competitors));
  // (Carta dominical) El nombre del negocio y el @ alimentan el saludo y la
  // narración de la carta (buildLetter, analysis-engine): sin nombre no se
  // inventa — la carta saluda genérico.
  const ctx = { postsPerWeek: plan.postsPerWeek || 7, plan: plan.id, prior, peers, source: 'instagram', businessName: prof.business_name || '', handle: (prof.ig_username || '').replace(/^@/, ''), hasIg: !!(prof.ig_username || '').trim() };
  // (v251) ctx.insights.bestHour: el motor ya lo acepta; se puebla desde
  // users.best_hour (la columna que carga insights.fetchBestHour), con el
  // mismo rango válido 9–21 que usan los demás lectores de la columna.
  try {
    const bh = db.prepare('SELECT best_hour FROM users WHERE id = ?').get(uid);
    if (bh && bh.best_hour >= 9 && bh.best_hour <= 21) ctx.insights = { bestHour: bh.best_hour };
  } catch (e) { /* sin dato: el análisis sigue con los datos públicos */ }
  // (v281) La ESTRATEGIA del negocio para la carta (queda en el análisis):
  // su estrella efectiva (dueño > ventas reales de Tiendanube > inferida
  // del feed, vía effectiveStarOf) y su objetivo comercial (reserva si
  // toma turnos; venta si tiene estrella o productos; consulta si vive de
  // servicios). Sin fundamento utilizable no se proyecta nada y la carta
  // cae a su selección de siempre — jamás una estrategia inventada.
  try {
    const star = (digest && clientDigest.effectiveStarOf) ? clientDigest.effectiveStarOf(digest) : null;
    if (star && star.item) ctx.star = { item: String(star.item), source: star.source || null };
    const nProds = (digest && Array.isArray(digest.productos)) ? digest.productos.length : 0;
    const nServs = (digest && Array.isArray(digest.servicios)) ? digest.servicios.length : 0;
    ctx.goal = (digest && digest.has_booking) ? 'reserva' : ((ctx.star || nProds > 0) ? 'venta' : (nServs > 0 ? 'consulta' : null));
  } catch (e) { /* sin estrategia: la carta usa su selección de siempre */ }
  let analysis = null;
  const ig = feedAudit.sanitizeHandle(prof.ig_username || '');
  if (ig) {
    let data = null;
    try {
      data = await Promise.race([feedAudit.fetchAuditData(ig), new Promise((r) => setTimeout(() => r(null), 4500))]);
    } catch (e) { data = null; }
    if (data && data.ok && !analysisEngine.isColdStart({ hasIg: true, profile: data.profile, posts: data.posts })) {
      let paletteHues = null;
      try {
        paletteHues = await Promise.race([feedAudit.analyzePalette(data.posts || []), new Promise((r) => setTimeout(() => r(null), 1500))]);
      } catch (e) { /* sin paleta: el hallazgo no se afirma */ }
      // (Carta mínima v280, agregado A) La foto del mejor posteo de la
      // semana para la carta dominical: se elige con pickBestPost (el de
      // más likes entre los que traen foto) y se LOCALIZA a MEDIA_DIR con
      // localizeTrialPhotos — la miniatura cruda de IG expira y no se
      // hotlinkea; la carta solo acepta un src propio /media/.... Todo
      // fail-closed con timeout corto: sin foto localizada, la carta sale
      // SIN foto — jamás una genérica ni una de otro.
      let bestPhoto = null;
      try {
        const best = analysisEngine.pickBestPost(data.posts || []);
        if (best && best.thumb) {
          const loc = await Promise.race([
            feedAudit.localizeTrialPhotos({ handle: ig, photos: [best.thumb] }, MEDIA_DIR),
            new Promise((r) => setTimeout(() => r(null), 3000)),
          ]);
          const src = loc && Array.isArray(loc.photos) ? loc.photos[0] : null;
          if (src && /^\/media\/[A-Za-z0-9_.-]+\.(?:jpe?g|png|webp)$/.test(src)) bestPhoto = { src, likes: best.likes };
        }
      } catch (e) { /* sin foto: la carta sale sin foto */ }
      analysis = analysisEngine.analyzeExisting({ profile: data.profile, posts: data.posts, ctx: Object.assign({}, ctx, { paletteHues, bestPhoto }) });
    }
  }
  if (!analysis) {
    const reviews = await coldReviewsFor(prof.business_name, digest.ciudad || '');
    analysis = analysisEngine.analyzeColdStart({
      business: { name: prof.business_name || '', category: prof.category || '', city: digest.ciudad || '', ig_username: ig },
      digest, peers, reviews, ctx,
    });
  }
  if (opts.save !== false) {
    const saved = analysisEngine.saveAnalysis(db, uid, analysis);
    if (saved && saved.analysis) analysis = saved.analysis;
  }
  return analysis;
}
function analysisPayload(uid, analysis) {
  const plan = planForUid(uid);
  const view = analysisEngine.gateForPlan(analysis, plan.id);
  return {
    ok: true,
    plan: plan.id,
    analysis: view,
    week_summary: analysisEngine.weekSummary(analysis),
    history: analysisEngine.analysisHistory(db, uid, 6),
  };
}
app.get('/api/analysis', requireAuth, async (req, res) => {
  try {
    const uid = req.session.userId;
    let latest = analysisEngine.latestAnalysis(db, uid);
    if (!latest) {
      // peek=1: solo lectura (Schedule no dispara construcciones pesadas).
      if (String(req.query.peek || '') === '1') return res.json({ ok: true, plan: planForUid(uid).id, analysis: null, week_summary: null, history: [] });
      latest = await buildAccountAnalysis(uid);
    }
    res.json(analysisPayload(uid, latest));
  } catch (e) {
    res.status(500).json({ ok: false, error: 'analysis_failed' });
  }
});
app.post('/api/analysis/refresh', requireAuth, async (req, res) => {
  try {
    const uid = req.session.userId;
    const fresh = await buildAccountAnalysis(uid);
    res.json(analysisPayload(uid, fresh));
  } catch (e) {
    res.status(500).json({ ok: false, error: 'analysis_failed' });
  }
});
// (Cartas anteriores) Carta anterior ENTERA: el payload completo ya vive guardado en
// account_analysis (saveAnalysis); este endpoint lo sirve SOLO al dueño de
// la carta (id de otro usuario ⇒ 404, sin filtrar existencia). La vista de
// Análisis lo usa para abrir las cartas viejas completas, no solo el
// resumen del historial. Payload corrupto ⇒ error amable, nunca un 500.
app.get('/api/analysis/:id', requireAuth, (req, res) => {
  const uid = req.session.userId;
  const id = Number(req.params.id) || 0;
  if (!id) return res.status(404).json({ ok: false, error: 'not_found' });
  let row = null;
  try {
    row = db.prepare('SELECT id, payload FROM account_analysis WHERE id = ? AND user_id = ?').get(id, uid);
  } catch (e) { row = null; }
  if (!row) return res.status(404).json({ ok: false, error: 'not_found' });
  let analysis = null;
  try { analysis = JSON.parse(row.payload); } catch (e) { analysis = null; }
  if (!analysis || typeof analysis !== 'object') {
    return res.json({ ok: false, error: 'carta_ilegible', message: 'Esta carta quedó guardada con un problema y no se puede leer 😅 La de esta semana está completa, acá arriba.' });
  }
  analysis.id = row.id;
  const plan = planForUid(uid);
  res.json({ ok: true, plan: plan.id, past: true, analysis: analysisEngine.gateForPlan(analysis, plan.id) });
});

app.get('/api/posts', requireAuth, (req, res) => {
  const { status } = req.query;
  const join = 'LEFT JOIN post_signals s ON s.user_id = p.user_id AND s.post_id = p.id';
  const vis = `AND COALESCE(p.needs_review, 0) = 0`; // "rueditas": en revisión no se muestra
  let rows;
  if (status) {
    rows = db.prepare(`SELECT p.*, s.client_signal AS signal FROM posts p ${join} WHERE p.user_id = ? AND p.status = ? ${vis} ORDER BY p.scheduled_at ASC, p.created_at DESC`).all(req.session.userId, status);
  } else {
    rows = db.prepare(`SELECT p.*, s.client_signal AS signal FROM posts p ${join} WHERE p.user_id = ? ${vis} ORDER BY p.created_at DESC LIMIT 100`).all(req.session.userId);
  }
  // 🧠 Porqué (2026-10-19): todo posteo visible lleva su porqué. Los caminos
  // de creación que no cargan strategy_why lo reciben acá, una sola vez,
  // desde el análisis persistido + el fundamento (analysis-engine.whyForPost).
  try {
    const missing = rows.filter((r) => r && !String(r.strategy_why || '').trim() && (r.status === 'draft' || r.status === 'scheduled'));
    if (missing.length) {
      const uid = req.session.userId;
      const analysis = analysisEngine.latestAnalysis(db, uid);
      const digest = clientDigest.getDigest(db, uid);
      const upd = db.prepare('UPDATE posts SET strategy_why = ? WHERE id = ? AND user_id = ?');
      for (const r of missing.slice(0, 30)) {
        const why = analysisEngine.whyForPost({
          tipo: r.tipo || '', formato: r.media_type || '',
          salesIntent: r.sales_intent || '', intent: r.intent || '',
          porque: '', topic: r.source_topic || '',
        }, analysis, digest);
        if (why) { upd.run(why, r.id, uid); r.strategy_why = why; }
      }
    }
  } catch (e) { /* el porqué nunca frena la agenda */ }
  res.json(rows);
});

// Si el usuario nunca configuró image_base_url, la deducimos del host actual (https en
// producción). Sin esto Instagram no puede descargar la imagen y la publicación real falla.
function ensureImageBaseUrl(db, userId, req) {
  try {
    if (process.env.IMAGE_BASE_URL) return;
    const rawHost = req.get('host') || '';
    if (!rawHost) return;
    const proto = /localhost|127\.0\.0\.1/.test(rawHost.split(':')[0]) ? 'http' : 'https';
    const cur = `${proto}://${rawHost}`;
    const s = db.prepare('SELECT image_base_url FROM settings WHERE user_id = ?').get(userId);
    // Migración de dominio: si la base guardada apunta al dominio viejo, actualizarla.
    if (s && s.image_base_url && /(postahacetodo|postyhacetodo)\.com/i.test(s.image_base_url) && s.image_base_url !== cur) {
      db.prepare(`UPDATE settings SET image_base_url = ?, updated_at = datetime('now') WHERE user_id = ?`).run(cur, userId);
      return;
    }
    if (s && s.image_base_url) return;
    db.prepare(`UPDATE settings SET image_base_url = ?, updated_at = datetime('now') WHERE user_id = ?`).run(cur, userId);
  } catch (e) { /* no bloquea la creación del post */ }
}

app.post('/api/posts', requireAuth, requireTrialValid, (req, res) => {
  const { image_path, caption, hashtags, scheduled_at, media_type, source_topic, source_angle, carousel_paths, tipo, strategy_why, script } = req.body || {};
  if (!image_path) return res.status(400).json({ error: 'Falta la imagen' });
  // Anti-duplicados: mismo texto en las últimas 24h (no cancelado) = avisar en vez de crear otro
  const cap = (caption || '').trim();
  if (cap) {
    const dup = db.prepare(`SELECT id FROM posts WHERE user_id = ? AND status != 'cancelled' AND LOWER(TRIM(caption)) = LOWER(?) AND created_at > datetime('now', '-1 day')`).get(req.session.userId, cap);
    if (dup) return res.status(409).json({ error: 'Ya creaste este posteo hoy. Lo ves en tu historial.', post_id: dup.id });
  }
  const status = scheduled_at ? 'scheduled' : 'draft';
  const mt = media_type === 'video' ? 'video' : media_type === 'story' ? 'story' : media_type === 'carousel' ? 'carousel' : 'image';
  // Cupo del plan: solo las publicaciones consumen cupo (los borradores son gratis).
  // Cada formato consume SU cupo (posteos, reels, historias). El carrusel cuenta como 1 posteo.
  if (status === 'scheduled') {
    // Cupo contra la semana DEL POSTEO (fix 2026-10-18), no la actual.
    const q = quotaForWeek(req.session.userId, mt, mondayKeyOf(String(scheduled_at).slice(0, 10)));
    if (q.left <= 0) {
      return res.status(403).json({ error: 'plan_limit', plan_limit: true, limit: q.limit, plan_name: q.plan_name, week_key: q.week_key,
        message: `Llegaste al límite de tu plan ${q.plan_name} (${q.limit} ${quotaUnitName(mt)} por semana). Mejorá tu paquete para seguir posteando esa semana.` });
    }
  }
  let cpaths = '';
  if (mt === 'carousel' && Array.isArray(carousel_paths)) {
    cpaths = JSON.stringify(carousel_paths.filter(Boolean).slice(0, 10));
  }
  // Guion del reel (segundo a segundo): viaja con el borrador para no perderse
  let scriptJson = '';
  if (Array.isArray(script)) {
    const scenes = script.slice(0, 6).map(sc => {
      if (!sc || typeof sc !== 'object') return null;
      const seg = String(sc.seg || '').slice(0, 12), visual = String(sc.visual || '').slice(0, 200), texto = String(sc.texto || '').slice(0, 200);
      return (seg || visual || texto) ? { seg, visual, texto } : null;
    }).filter(Boolean);
    if (scenes.length) scriptJson = JSON.stringify(scenes);
  }
  const r = db.prepare(
    'INSERT INTO posts (user_id, image_path, caption, hashtags, scheduled_at, status, media_type, source_topic, source_angle, carousel_paths, tipo, strategy_why, needs_review, script) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)'
  ).run(req.session.userId, image_path, caption || '', hashtags || '', scheduled_at || null, status, mt, source_topic || '', source_angle || '', cpaths, ['promo','tip','social','detras','novedad'].includes(tipo) ? tipo : '', String(strategy_why || '').slice(0, 500), status === 'draft' && trainingWheelsActive(req.session.userId) ? 1 : 0, scriptJson);
  const newId = r.lastInsertRowid;

  // 🚀 Autopiloto (2026-10-02): si está activado y el borrador pasa el filtro
  // de calidad, se programa solo para mañana 10am. Si no pasa, queda en
  // revisión manual.
  let autopiloted = false;
  if (status === 'draft') {
    try {
      const ap = autopilot.shouldAutopublish(req.session.userId, newId, db, MEDIA_DIR);
      if (ap.ok) {
        // Horario óptimo (2026-10-03): usa la mejor hora del usuario según
        // engagement histórico. Si no hay datos, 10am por defecto.
        let bestHour = 10;
        try {
          const bh = db.prepare('SELECT best_hour FROM users WHERE id = ?').get(req.session.userId);
          if (bh && bh.best_hour >= 0 && bh.best_hour <= 23) bestHour = bh.best_hour;
        } catch (e) {}
        const tomorrow = new Date(Date.now() + 24 * 3600 * 1000);
        tomorrow.setHours(bestHour, 0, 0, 0);
        const schedAt = tomorrow.toISOString().slice(0, 16).replace('T', ' ');
        db.prepare(`UPDATE posts SET status = 'scheduled', scheduled_at = ?, auto_published = 1 WHERE id = ?`)
          .run(schedAt, newId);
        autopiloted = true;
        console.log(`[autopilot] post ${newId} programado solo para ${schedAt} (score ${ap.score})`);
      }
    } catch (e) {
      console.error('[autopilot] no pude auto-programar:', e.message);
    }
  }
  // (v198-A) Lint al programar: nació 'scheduled' (directo o por autopiloto).
  if (status === 'scheduled' || autopiloted) scheduleLintForPost(req.session.userId, newId);

  ensureImageBaseUrl(db, req.session.userId, req);
  res.json({ ok: true, id: newId, autopiloted });
});

// ---------- (v198-A) LINT AL PROGRAMAR ----------
// El gate de captions (captionPasses: frases quemadas, empalmes en cualquier
// bloque, cuerpo, claims sin dato, topes de largo/bloques/emojis) y el lint
// de tono corrían SOLO al generar. El stock ya programado y los captions
// editados a mano podían quedar 'scheduled' con defectos que la generación
// nueva ya no deja pasar (la brecha M82: el post 112 salió con empalme).
// Desde v198-A, toda transición a 'scheduled' pasa por acá: si el caption
// no pasa, el posteo queda programado PERO marcado needs_review=1 (la marca
// del sistema: invisible para el cliente, primero en la cola de revisión) y
// el tick de publicación lo retiene hasta que la marca se libera. Evento
// schedule_lint_failed con el motivo real. Fundador: exento, como en el
// resto del sistema (week/ensure libera sus marcas). Nunca rompe el flujo
// que lo llama: ante cualquier error interno, el posteo sigue como estaba.
function scheduleLintForPost(uid, postId) {
  try {
    if (!uid || !postId || typeof captionPasses !== 'function') return null;
    const post = db.prepare('SELECT id, caption, week_key FROM posts WHERE id = ? AND user_id = ?').get(postId, uid);
    if (!post) return null;
    const caption = String(post.caption || '');
    if (!caption.trim()) return { ok: true }; // sin caption no hay copy que lintear
    let founder = false;
    try { founder = !!(costs.isFounderEmail && costs.isFounderEmail(uid)); } catch (e) {}
    if (founder) return { ok: true, founder: true };
    const prof = getProfile(uid) || {};
    const dna = digestForUser(uid);
    let prevCaptions = [];
    try {
      prevCaptions = db.prepare(`SELECT caption FROM posts WHERE user_id = ? AND id != ? AND COALESCE(caption, '') != ''
        AND status IN ('draft', 'scheduled') AND COALESCE(week_key, '') = COALESCE(?, '')
        ORDER BY id DESC LIMIT 12`).all(uid, postId, post.week_key || '').map((r) => r.caption);
    } catch (e) {}
    let failReason = '';
    const chk = captionPasses(caption, { business: prof.business_name || '', dna, ig_username: prof.ig_username || '', prevCaptions });
    if (chk && !chk.ok) failReason = String(chk.reason || 'caption no pasa el gate');
    if (!failReason) {
      try {
        const lt = analysisEngine.lintTone(caption);
        if (lt && !lt.ok) failReason = 'tono: contiene vocabulario de reto (' + (lt.hits || []).join(', ') + ')';
      } catch (e) {}
    }
    if (failReason) {
      db.prepare('UPDATE posts SET needs_review = 1 WHERE id = ?').run(postId);
      evTrack(uid, 'schedule_lint_failed', { post_id: postId, reason: failReason.slice(0, 300) });
      console.log(`[schedule-lint] post ${postId} (user ${uid}): NO pasa el lint al programar — queda marcado para revisión. Motivo: ${failReason}`);
      return { ok: false, reason: failReason };
    }
    return { ok: true };
  } catch (e) { console.error('[schedule-lint]', e.message); return null; }
}
function scheduleLintForPosts(uid, ids) {
  for (const id of ids || []) scheduleLintForPost(uid, id);
}

app.patch('/api/posts/:id', requireAuth, (req, res) => {
  const { scheduled_at, caption, hashtags, image_path, action } = req.body || {};
  const post = db.prepare('SELECT * FROM posts WHERE id = ? AND user_id = ?').get(req.params.id, req.session.userId);
  if (!post) return res.status(404).json({ error: 'Post no encontrado' });
  if (post.needs_review) return res.status(403).json({ error: 'in_review', message: 'Este posteo está en revisión ✨ Te aviso cuando esté listo.' });
  let scheduledInfo = null; // la rama de programar lo completa: el cliente confirma la fecha al aceptar
  if (action === 'cancel') {
    db.prepare(`UPDATE posts SET status='cancelled' WHERE id=?`).run(post.id);
    recordSignal(req.session.userId, post, 'rejected'); // lo canceló = no le gustó
  } else if (action === 'unschedule') {
    // Frenar el autopiloto (2026-10-02): vuelve a borrador, no se publica.
    db.prepare(`UPDATE posts SET status='draft', scheduled_at=NULL, auto_published=0, approval='pending', user_stopped=1 WHERE id=?`).run(post.id);
    console.log(`[autopilot] usuario ${req.session.userId} frenó el post ${post.id}`);
  } else if (action === 'save-draft') {
    // Guarda cambios en un borrador SIN programarlo (flujo de revisión del autopilot).
    // También acepta image_path para la regeneración de un borrador (↻).
    const edited = (caption !== undefined && caption !== post.caption) || (hashtags !== undefined && hashtags !== post.hashtags) || (image_path && image_path !== post.image_path);
    // Style-learn: si editó el caption a mano, aprendemos QUÉ cambió (sin emojis, más corto, con precios...)
    if (caption !== undefined && caption !== post.caption) {
      try { require('./style-learn').learnFromCaptionEdit(db, req.session.userId, post.caption, caption); } catch (e) {}
    }
    db.prepare(`UPDATE posts SET caption=?, hashtags=?, image_path=?, prev_image_path=? WHERE id=?`).run(caption ?? post.caption, hashtags ?? post.hashtags, image_path || post.image_path, (image_path && image_path !== post.image_path) ? (post.image_path || '') : (post.prev_image_path || ''), post.id);
    if (edited) recordSignal(req.session.userId, post, 'edited'); // tocó el texto en revisión
    return res.json({ ok: true });
  } else {
    const edited = (caption !== undefined && caption !== post.caption) || (hashtags !== undefined && hashtags !== post.hashtags);
    // Integridad de agenda (2026-10-16): jamás un posteo 'scheduled' sin
    // fecha (quedaba fantasma, no publicaba nunca) ni dos del feed el mismo
    // día. Sin fecha o con el día ocupado → próximo día libre del asignador.
    // La fecha se resuelve PRIMERO: el cupo se evalúa contra SU semana.
    let finalWhen = scheduled_at || post.scheduled_at;
    if (!finalWhen || scheduleDayTaken(req.session.userId, post, finalWhen)) {
      try { const slots = assignScheduleSlots(req.session.userId, [post]); if (slots.get(post.id)) finalWhen = slots.get(post.id); } catch (e) {}
    }
    if (!finalWhen) {
      db.prepare(`UPDATE posts SET caption=?, hashtags=? WHERE id=?`).run(caption ?? post.caption, hashtags ?? post.hashtags, post.id);
      return res.json({ ok: true, warning: 'sin_dia_libre' });
    }
    // Programar SÍ consume cupo (las publicaciones son el límite del plan) —
    // contra la semana DEL POSTEO (fix 2026-10-18): con la semana actual
    // llena, aceptar un borrador de la semana que viene funcionaba mal
    // (saltaba el modal de tope) porque quotaFor miraba la semana de hoy.
    // Si el posteo ya estaba programado/publicado, no se descuenta de nuevo.
    const whenMonday = mondayKeyOf(String(finalWhen).slice(0, 10));
    if (!['scheduled', 'publishing', 'published'].includes(post.status)) {
      const q = quotaForWeek(req.session.userId, post.media_type, whenMonday);
      if (q.left <= 0) {
        return res.status(403).json({ error: 'plan_limit', plan_limit: true, limit: q.limit, used: q.used, plan_name: q.plan_name, week_key: whenMonday,
          message: `Llegaste al límite de tu plan ${q.plan_name} (${q.limit} ${quotaUnitName(post.media_type)} por semana). Mejorá tu paquete para seguir posteando esa semana.` });
      }
    }
    scheduledInfo = { scheduled_at: finalWhen, week_key: whenMonday };
    db.prepare(`UPDATE posts SET scheduled_at=?, caption=?, hashtags=?, status='scheduled', error='', notified=?, approval=?, user_stopped=0 WHERE id=?`).run(
      finalWhen, caption ?? post.caption, hashtags ?? post.hashtags,
      // "Posty te avisa": si cambió la hora programada, se re-arma el aviso de
      // aprobación (3h antes). Si el posteo estaba rechazado y el usuario lo
      // vuelve a programar a mano, es una intención nueva: vuelve a 'pending'.
      finalWhen !== post.scheduled_at ? 0 : (post.notified || 0),
      post.approval === 'rejected' ? 'pending' : (post.approval || 'pending'),
      post.id
    );
    clearPublishingStopped(req.session.userId); // (v275) programar a mano es reanudar la cuenta
    scheduleLintForPost(req.session.userId, post.id); // (v198-A) lint al programar
    // 🎓 Autopiloto graduado (2026-10-02): si programó SIN editar, es un voto
    // de confianza. A los 10, Posty ofrece el autopiloto.
    if (!edited && post.status === 'draft') {
      try {
        db.prepare(`UPDATE users SET clean_approvals = COALESCE(clean_approvals, 0) + 1 WHERE id = ?`)
          .run(req.session.userId);
        const u = db.prepare(`SELECT clean_approvals, autopilot_offered, autopilot_enabled FROM users WHERE id = ?`)
          .get(req.session.userId);
        if (u && (u.clean_approvals || 0) >= 10 && !u.autopilot_offered && !u.autopilot_enabled) {
          db.prepare(`UPDATE users SET autopilot_offered = 1 WHERE id = ?`).run(req.session.userId);
          // Posty le ofrece el autopiloto en el chat.
          try {
            db.prepare(`INSERT INTO chat_messages (user_id, role, text) VALUES (?, 'assistant', ?)`)
              .run(req.session.userId,
                `🚀 ya aprobaste 10 posteos sin cambiarles nada — parece que nos entendemos!\n\n` +
                `querés que de ahora en más los publique solo? te aviso 30 min antes de cada uno por si querés frenarlo.\n\n` +
                `activá el autopiloto en Ajustes cuando quieras ✨`);
          } catch (e) {}
          console.log(`[autopilot] usuario ${req.session.userId} desbloqueó la oferta (${u.clean_approvals} aprobaciones limpias)`);
        }
      } catch (e) {
        console.error('[autopilot] no pude contar aprobación limpia:', e.message);
      }
    }
    if (edited) recordSignal(req.session.userId, post, 'edited'); // tocó el texto antes de que salga
  }
  // Al programar, la respuesta confirma la fecha real (el cliente la anuncia al aceptar).
  res.json(scheduledInfo ? { ok: true, scheduled_at: scheduledInfo.scheduled_at, week_key: scheduledInfo.week_key } : { ok: true });
});

// POST /api/posts/:id/reject-reason  body {reason}
// El cliente cuenta QUÉ no le gustó de un borrador: se guarda la señal +
// una regla NEGATIVA en style_rules (entra al prompt sola vía Track D).
const REJECT_REASONS = {
  generico: 'NUNCA: diseños genéricos de stock — siempre escena concreta y específica del negocio, nunca banco de imágenes',
  estilo: 'NUNCA: desviarse de la línea visual del cliente definida en LÍNEA VISUAL DEL CLIENTE',
  avatar: 'NUNCA: deformar, redibujar ni reinterpretar el logo de tu marca — debe salir idéntico a la referencia',
  representa: 'NUNCA: contenido que no parezca del negocio real del cliente (su local, sus productos, su gente)',
};
app.post('/api/posts/:id/reject-reason', requireAuth, express.json(), (req, res) => {
  try {
    const reason = String(((req.body || {}).reason) || '').trim();
    if (!REJECT_REASONS[reason]) return res.status(400).json({ ok: false, error: 'Motivo inválido' });
    const uid = req.session.userId;
    const post = db.prepare('SELECT * FROM posts WHERE id = ? AND user_id = ?').get(req.params.id, uid);
    if (!post) return res.status(404).json({ ok: false, error: 'No encontrado' });
    const rule = REJECT_REASONS[reason];
    try { recordSignal(uid, post, 'rejected'); } catch (e) {}
    try {
      db.prepare(`INSERT INTO style_rules (user_id, rule_key, rule_text, hits, active) VALUES (?, ?, ?, 1, 1)
        ON CONFLICT(user_id, rule_key) DO UPDATE SET rule_text=excluded.rule_text, active=1, hits=hits+1`)
        .run(uid, 'neg:' + reason, rule);
    } catch (e) { return res.status(500).json({ ok: false, error: 'db' }); }
    res.json({ ok: true, rule });
  } catch (e) {
    console.error('[reject-reason]:', e.message);
    res.status(500).json({ ok: false, error: 'No pude guardar tu motivo 😅' });
  }
});

app.delete('/api/posts/:id', requireAuth, (req, res) => {
  const post = db.prepare('SELECT * FROM posts WHERE id = ? AND user_id = ?').get(req.params.id, req.session.userId);
  if (post) recordSignal(req.session.userId, post, 'rejected'); // lo eliminó = no le gustó
  const wasDraft = post && post.status === 'draft';
  db.prepare('DELETE FROM posts WHERE id = ? AND user_id = ?').run(req.params.id, req.session.userId);
  // Track 4 (agregado): si borrando uno por uno llegó a cero borradores de esa
  // semana, se dispara la reconstrucción con otro enfoque (igual que Vaciar).
  // Vale para la semana corriente y para la N+1 si la estaba revisando.
  let rebuild = null;
  if (wasDraft) {
    try {
      const tz = userTz(req.session.userId);
      const curWk = mondayKeyOf(tzToday(tz));
      const dwk = post.week_key || curWk; // semana del borrador borrado
      let left;
      if (dwk === curWk) {
        left = db.prepare(`SELECT COUNT(*) AS n FROM posts WHERE user_id = ? AND status = 'draft' AND COALESCE(needs_review,0)=0 AND (week_key = '' OR week_key = ?)`).get(req.session.userId, curWk).n || 0;
      } else {
        left = db.prepare(`SELECT COUNT(*) AS n FROM posts WHERE user_id = ? AND status = 'draft' AND COALESCE(needs_review,0)=0 AND week_key = ?`).get(req.session.userId, dwk).n || 0;
      }
      if (left === 0) rebuild = maybeStartRebuild(req.session.userId, dwk);
    } catch (e) { /* no bloquea el borrado */ }
  }
  res.json({ ok: true, rebuild });
});

// Track 4 (agregado): "🗑️ Vaciar" reconstruye la semana con OTRO enfoque.
// Borra todos los borradores de la semana marcándolos como rejected en bulk
// (la exclusión de 60 días del Track D hace que la nueva tanda use otros
// ángulos/tipos) y dispara la generación en segundo plano. Tope: 2 por semana;
// a la 3ª frena y deriva al chat (modo frustración).
app.post('/api/posts/rebuild-week', requireAuth, requireTrialValid, async (req, res) => {
  const uid = req.session.userId;
  const tz = userTz(uid);
  const curWk = mondayKeyOf(tzToday(tz));
  // Semana a reconstruir: la corriente, o la que el frontend esté mostrando
  // (teaser de la N+1). Formato validado: no se acepta cualquier string.
  let wk = curWk;
  const qwk = String(((req.body || {}).week_key) || '');
  if (/^\d{4}-\d{2}-\d{2}$/.test(qwk)) wk = qwk;
  const drafts = wk === curWk
    ? db.prepare(`SELECT * FROM posts WHERE user_id = ? AND status = 'draft' AND COALESCE(needs_review,0)=0 AND COALESCE(image_path,'') != '' AND (week_key = '' OR week_key = ?) ORDER BY id ASC`).all(uid, curWk)
    : db.prepare(`SELECT * FROM posts WHERE user_id = ? AND status = 'draft' AND COALESCE(needs_review,0)=0 AND COALESCE(image_path,'') != '' AND week_key = ? ORDER BY id ASC`).all(uid, wk);
  if (!drafts.length) return res.status(400).json({ error: 'No hay borradores para reconstruir' });
  try {
    vaciarYMarcar(uid, drafts, wk);
  } catch (e) {
    console.error('[rebuild-week] vaciar:', e.message);
    return res.status(500).json({ error: 'No se pudieron borrar los borradores. Probá de nuevo.' });
  }
  const r = maybeStartRebuild(uid, wk);
  console.log(`[rebuild-week] usuario ${uid} semana ${wk}: ${drafts.length} borradores vaciados → rebuilding=${r.rebuilding} (${r.reason || 'ok'})`);
  res.json({ ok: true, emptied: drafts.length, week_key: wk, ...r });
});

// POST /api/week/ensure — garantiza que la semana actual tenga sus posteos.
// Idempotente por usuario: si la semana ya alcanzó el objetivo del plan, no
// hace nada. Si falta alguno (semana vacía O parcial), dispara
// generateWeekDrafts en segundo plano — que crea SOLO el déficit — y
// devuelve { generating: true }. El frontend lo llama al abrir el home
// (sin bloquear la UI) y refresca hasta que aparecen las tarjetas.
// (2026-10-05: pedido de Valentino — los 5 posteos tienen que estar listos
// al entrar a la app, sin comandos ni recargas.)
app.post('/api/week/ensure', requireAuth, requireTrialValid, async (req, res) => {
  const uid = req.session.userId;
  try {
    const tz = userTz(uid);
    const wk = mondayKeyOf(tzToday(tz));
    // 2026-10-07: el fundador nunca debería tener needs_review=1 (sus posteos
    // se ocultaban y el /api/posts los filtraba — causa raíz del "armando tu
    // semana" eterno). Liberar PRIMERO, antes de contar.
    try {
      let isFounder = false;
      try { isFounder = !!(costs.isFounderEmail && costs.isFounderEmail(uid)); } catch (e) {}
      if (isFounder) {
        const r = db.prepare(`UPDATE posts SET needs_review = 0 WHERE user_id = ? AND COALESCE(needs_review, 0) = 1 AND status IN ('draft','scheduled')`).run(uid);
        if (r.changes > 0) console.log(`[week-ensure] fundador ${uid}: ${r.changes} posteos liberados de revisión`);
      }
    } catch (e) { console.error('[week-ensure] liberar revisión:', e.message); }
    // ¿Ya hay trabajo de esta semana? (borradores o programados, no cancelados)
    // Solo contar los VISIBLES (needs_review=0), que son los que ve el frontend.
    let n = 0;
    try {
      // Ocupación unificada (mismo criterio que el pipeline y el cupo):
      // incluye publicados y programados por fecha, no solo week_key.
      n = weekOccupancyRows(uid, wk).filter(p => !p.needs_review).length;
    } catch (e) { /* DB sin week_key: seguir */ }
    // Fallback: borradores sin week_key (pipeline viejo) también cuentan.
    if (!n) {
      try {
        n = db.prepare(`SELECT COUNT(*) AS n FROM posts WHERE user_id = ? AND status = 'draft' AND (week_key = '' OR week_key IS NULL) AND COALESCE(needs_review,0)=0`).get(uid).n || 0;
      } catch (e) {}
    }
    // 2026-10-14: la semana se completa SOLA hasta el objetivo del plan
    // (pedido de Valentino). Antes, con n>0 no se hacía nada y la semana
    // parcial quedaba incompleta para siempre.
    let target = 3;
    try {
      const u = db.prepare('SELECT plan, plan_status FROM users WHERE id = ?').get(uid) || {};
      target = (getPlan(u.plan_status === 'active' ? u.plan : TRIAL_PLAN).postsPerWeek) || 3;
    } catch (e) {}
    if (n >= target) return res.json({ ok: true, generating: false, count: n, complete: true, week_key: wk });
    // ¿Ya hay una generación en curso? No duplicar.
    if (nextweekRunningFresh(uid)) return res.json({ ok: true, generating: true, count: n, missing: target - n, week_key: wk });
    if (!planOrTrialOk(uid)) return res.json({ ok: false, generating: false, reason: 'no_plan', week_key: wk });
    // Gate de ADN "no generar a ciegas" (MISMA lógica que generateWeekDrafts):
    // si la cuenta no tiene descripción del negocio ni producto_estrella, no
    // disparar nada y avisar al frontend con reason:'no_dna' para que muestre
    // la tarjeta honesta en vez del spinner de "armando tu semana" (que nunca
    // terminaría porque el pipeline descarta la generación en silencio).
    try {
      const profile = getProfile(uid);
      const dna = readDna(uid);
      const descOk = (profile.description || '').trim().length >= 20;
      const dnaOk = (dna.producto_estrella || '').trim().length >= 3;
      if (!descOk && !dnaOk) {
        console.log(`[week-ensure] usuario ${uid}: sin ADN mínimo, no se genera a ciegas`);
        return res.json({ ok: true, generating: false, reason: 'no_dna', week_key: wk });
      }
    } catch (e) { /* si falla el chequeo, dejar que el pipeline decida */ }
    // Cooldown anti-loop (2026-10-14): si la última corrida de ESTA semana
    // falló hace menos de 10 minutos, no re-disparar en cada apertura de la
    // app. La red de reintentos (sweep cada 3h + backfill diario) sigue.
    try {
      const last = LAST_WEEK_RESULT.get(uid);
      if (last && last.weekKey === wk && !last.ok && last.reason !== 'running' && Date.now() - (last.at || 0) < 10 * 60 * 1000) {
        return res.json({ ok: true, generating: false, reason: last.reason || 'retry_cooldown', count: n, week_key: wk });
      }
    } catch (e) {}
    // Disparar en segundo plano: la respuesta vuelve al toque.
    // 2026-10-08: guardar el resultado para que el frontend lo pueda mostrar
    // (antes el error se perdía en los logs del servidor).
    generateWeekDrafts(uid, { weekKey: wk, tag: 'ensure', quiet: false })
      .then(r => {
        console.log(`[week-ensure] usuario ${uid} semana ${wk}:`, r.ok ? `${r.created} creados` : `falló (${r.reason})`);
        try { LAST_WEEK_RESULT.set(uid, { ...r, at: Date.now(), weekKey: wk }); } catch (e) {}
      })
      .catch(e => {
        console.error('[week-ensure] pipeline:', e.message);
        try { LAST_WEEK_RESULT.set(uid, { ok: false, reason: 'exception', error: String(e.message || e).slice(0, 300), at: Date.now(), weekKey: wk }); } catch (e2) {}
      });
    return res.json({ ok: true, generating: true, count: n, missing: target - n, week_key: wk });
  } catch (e) {
    console.error('[week-ensure]:', e.message);
    return res.status(500).json({ ok: false, error: 'No se pudo verificar la semana.' });
  }
});

// 2026-10-08: devuelve el último resultado de generateWeekDrafts para el
// usuario (éxito o error exacto). El frontend lo consulta para mostrar el
// error en pantalla en vez del spinner eterno.
app.get('/api/week/last-result', requireAuth, (req, res) => {
  const uid = req.session.userId;
  const r = LAST_WEEK_RESULT.get(uid);
  if (!r) return res.json({ ok: true, has: false });
  return res.json({ ok: true, has: true, result: r });
});

// Fix auditoría #2 (2026-09-30): "⚡ Rearmar mi semana" del welcome honesto.
// La importación de /prueba trajo 0 (cache vencido / payload roto, marcado en
// users.trial_import_n): se genera la semana de nuevo en segundo plano con el
// perfil que ya quedó aplicado al registrarse. Responde al toque; el push
// "Tu semana está lista ✨" avisa cuando los borradores aparecen.
app.post('/api/trial/rebuild-import', requireAuth, requireTrialValid, (req, res) => {
  const uid = req.session.userId;
  try {
    const u = db.prepare('SELECT trial_import_n FROM users WHERE id = ?').get(uid) || {};
    if (u.trial_import_n !== 0) return res.json({ ok: true, rebuilding: false, reason: 'not_needed' });
    const drafts = db.prepare(`SELECT COUNT(*) AS n FROM posts WHERE user_id = ? AND status = 'draft'`).get(uid).n || 0;
    if (drafts > 0) return res.json({ ok: true, rebuilding: false, reason: 'has_drafts' });
    const r = maybeStartRebuild(uid);
    console.log(`[trial-rebuild] usuario ${uid}: rebuilding=${r.rebuilding} (${r.reason || 'ok'})`);
    return res.json({ ok: true, rebuilding: !!r.rebuilding, reason: r.reason || null });
  } catch (e) {
    console.error('[trial-rebuild]:', e.message);
    return res.status(500).json({ error: 'No pude arrancar la regeneración 😅 Probá de nuevo.' });
  }
});

// Estado de un posteo (para el seguimiento en vivo de "Publicar ahora")
app.get('/api/posts/:id', requireAuth, (req, res) => {
  const post = db.prepare(
    "SELECT * FROM posts WHERE id = ? AND user_id = ? AND COALESCE(needs_review,0)=0"
  ).get(req.params.id, req.session.userId);
  if (!post) return res.status(404).json({ error: 'Post no encontrado' });
  res.json({ ok: true, post });
});

// Descartar un posteo fallido: lo saca de la tarjeta de fallidos sin publicarlo.
// Idempotente: si ya está cancelado/descartado, no hace nada.
app.post('/api/posts/:id/dismiss-failed', requireAuth, (req, res) => {
  const post = db.prepare('SELECT * FROM posts WHERE id = ? AND user_id = ?').get(req.params.id, req.session.userId);
  if (!post) return res.status(404).json({ error: 'Post no encontrado' });
  if (post.status === 'cancelled') return res.json({ ok: true, status: 'cancelled' });
  if (post.status !== 'failed') {
    return res.status(409).json({ error: 'not_failed', message: 'Este posteo no está fallido.' });
  }
  db.prepare(`UPDATE posts SET status = 'cancelled', error = '' WHERE id = ?`).run(post.id);
  console.log(`[posta] Post #${post.id} fallido descartado por el cliente`);
  res.json({ ok: true, status: 'cancelled' });
});

// Publicar AHORA de forma inmediata: no espera al scheduler.
// Idempotente: si ya se está publicando o ya salió, no lo duplica.
app.post('/api/posts/:id/publish-now', requireAuth, requireTrialValid, (req, res) => {
  const post = db.prepare('SELECT * FROM posts WHERE id = ? AND user_id = ?').get(req.params.id, req.session.userId);
  if (!post) return res.status(404).json({ error: 'Post no encontrado' });
  if (post.status === 'publishing') return res.json({ ok: true, status: 'publishing' });
  if (post.status === 'published') return res.json({ ok: true, status: 'published', permalink: post.ig_permalink });
  if (!['draft', 'scheduled', 'failed'].includes(post.status)) {
    return res.status(400).json({ error: 'Este posteo no se puede publicar ahora' });
  }
  if (post.needs_review) return res.status(403).json({ error: 'in_review', message: 'Este posteo está en revisión ✨ Te aviso cuando esté listo.' });
  // Publicar ahora SÍ consume cupo (salvo que ya estuviera programado: ya se descontó).
  if (!['scheduled', 'publishing', 'published'].includes(post.status)) {
    const q = quotaFor(req.session.userId, post.media_type);
    if (q.left <= 0) {
      return res.status(403).json({ error: 'plan_limit', plan_limit: true, limit: q.limit, plan_name: q.plan_name,
        message: `Llegaste al límite de tu plan ${q.plan_name} (${q.limit} ${quotaUnitName(post.media_type)} por semana). Mejorá tu paquete para seguir posteando esta semana.` });
    }
  }
  db.prepare(`UPDATE posts SET status='publishing', scheduled_at=datetime('now'), error='' WHERE id=?`).run(post.id);
  ensureImageBaseUrl(db, req.session.userId, req);
  // La publicación corre en segundo plano; el frontend consulta GET /api/posts/:id
  publishSinglePost(db, { ...post, status: 'publishing' }).catch((e) => console.error('[posta] publish-now:', e.message));
  res.json({ ok: true, status: 'publishing' });
});

// ---------- "Posty te avisa": aprobación de posteos por notificación ----------
// Mini-página HTML para los enlaces de aprobar/rechazar (se abren desde la
// notificación o el email, sin necesidad de sesión).
function approvalPage(title, message) {
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  return '<!DOCTYPE html><html lang="es"><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1">' +
    `<title>${esc(title)} · Posty</title></head>` +
    '<body style="font-family:system-ui,sans-serif;display:flex;min-height:100vh;align-items:center;justify-content:center;margin:0;background:#fff;color:#111">' +
    '<main style="text-align:center;padding:24px;max-width:420px">' +
    `<h1 style="font-size:24px;margin:0 0 12px">${esc(title)}</h1>` +
    `<p style="font-size:17px;color:#444;margin:0">${esc(message)}</p>` +
    '</main></body></html>';
}

// Auth de aprobación: sesión (el post debe pertenecer al usuario de la sesión)
// O firma válida (?sig=&exp=, verifyAction). Con firma válida, el user_id del
// post manda y no hace falta sesión. Sin ninguna de las dos → 403.
function approvalAuth(action) {
  return (req, res, next) => {
    const post = db.prepare('SELECT * FROM posts WHERE id = ?').get(req.params.id);
    const deny = (title, msg) => req.method === 'GET'
      ? res.status(403).send(approvalPage(title, msg))
      : res.status(403).json({ error: 'forbidden', message: msg });
    if (!post) {
      return req.method === 'GET'
        ? res.status(404).send(approvalPage('Posteo no encontrado', 'Este enlace no corresponde a ningún posteo.'))
        : res.status(404).json({ error: 'Post no encontrado' });
    }
    const sessionUid = req.session && req.session.userId;
    if (sessionUid) {
      if (post.user_id !== sessionUid) return deny('Sin permiso', 'Este posteo no es de tu cuenta.');
      req.approvalPost = post;
      return next();
    }
    const { sig, exp } = req.query || {};
    if (sig && exp && approval.verifyAction(post.id, action, sig, exp)) {
      req.approvalPost = post;
      return next();
    }
    return deny('Enlace vencido', 'Este enlace de aprobación venció o no es válido. Entrá a Posty para ver tu posteo.');
  };
}

app.post('/api/posts/:id/approve', approvalAuth('approve'), (req, res) => {
  const post = req.approvalPost;
  if (post.approval === 'rejected') {
    return res.status(409).json({ error: 'rejected', message: 'Este posteo fue rechazado: ya no se puede aprobar.' });
  }
  if (post.approval === 'approved' || post.approval === 'auto') {
    return res.json({ ok: true, approval: post.approval }); // idempotente
  }
  db.prepare(`UPDATE posts SET approval = 'approved', approved_at = datetime('now') WHERE id = ?`).run(post.id);
  res.json({ ok: true, approval: 'approved' });
});

app.get('/api/posts/:id/approve', approvalAuth('approve'), (req, res) => {
  const post = req.approvalPost;
  if (post.approval === 'rejected') {
    return res.status(409).send(approvalPage('Ya fue rechazado', 'Este posteo fue cancelado: ya no se puede aprobar.'));
  }
  if (post.approval !== 'approved' && post.approval !== 'auto') {
    db.prepare(`UPDATE posts SET approval = 'approved', approved_at = datetime('now') WHERE id = ?`).run(post.id);
  }
  const label = approval.userHourLabel(db, post.user_id, post.scheduled_at);
  res.send(approvalPage('✅ ¡Aprobado!', `Tu posteo sale a las ${label || 'la hora programada'}.`));
});

// FASE 2 — lógica compartida de "aceptar borradores": los marca approved +
// scheduled en su horario. items = [{ id, scheduled_at? }].
// opts.includeNeedsReview=true incluye borradores con needs_review=1: el
// preview del email de semana YA fue la revisión humana, y el tap firmado ES
// la aprobación (default false = solo borradores ya revisados, comportamiento
// histórico del accept-all in-app).
// Con quota checks: todos de una o nada (mismo criterio que schedule-all).
// El tap cuenta como aprobación del usuario (recordSignal), NO como
// auto_published del sistema: suma a la escalera de confianza de Fase 1.
function acceptAllDrafts(uid, items, opts) {
  const list = Array.isArray(items) ? items : [];
  const ids = [...new Set(list.map((it) => Number(it && it.id)).filter((n) => n > 0))];
  if (!ids.length) return { ok: false, reason: 'empty' };
  const whenById = {};
  for (const it of list) {
    const n = Number(it && it.id);
    if (n > 0 && it.scheduled_at) {
      const d = new Date(String(it.scheduled_at));
      if (!isNaN(d)) whenById[n] = d.toISOString().slice(0, 19).replace('T', ' ');
    }
  }
  const ph = ids.map(() => '?').join(',');
  const drafts = db.prepare(
    `SELECT * FROM posts WHERE id IN (${ph}) AND user_id = ? AND status = 'draft' AND COALESCE(image_path,'') != ''`
  ).all(...ids, uid);
  const pool = (opts && opts.includeNeedsReview)
    ? drafts
    : drafts.filter((d) => (d.needs_review || 0) === 0);
  // Solo pendientes: respeta rechazados (no se tocan) y omite los ya aprobados.
  const pending = pool.filter((d) => (d.approval || 'pending') === 'pending');
  if (!pending.length) return { ok: false, reason: 'no_pending' };
  // Cupo POR SEMANA DEL POSTEO (fix 2026-10-18): cada borrador se evalúa
  // contra la semana lun–dom de su fecha destino, no contra la semana
  // actual. Antes el contador era el de ESTA semana: con la semana llena,
  // aceptar borradores de la semana que viene (cupo fresco) saltaba con
  // plan_limit. Se acepta hasta el límite de CADA semana (2026-10-11:
  // "si el máximo es 5, aceptame 5" — por semana, no global).
  const poolLimit = {
    image: quotaFor(uid, 'image').limit,
    video: quotaFor(uid, 'video').limit,
    story: quotaFor(uid, 'story').limit,
  };
  const weekLeftCache = new Map();
  const leftFor = (monday, poolKey) => {
    const k = monday + '|' + poolKey;
    if (!weekLeftCache.has(k)) {
      const c = quotaCounts(uid, monday);
      const used = poolKey === 'video' ? (c.video || 0)
        : poolKey === 'story' ? (c.story || 0)
        : (c.image || 0) + (c.carousel || 0);
      weekLeftCache.set(k, Math.max(0, (poolLimit[poolKey] || 0) - used));
    }
    return weekLeftCache.get(k);
  };
  const upd = db.prepare(`UPDATE posts SET approval='approved', approved_at=datetime('now'), status='scheduled', scheduled_at=?, needs_review=0, error='', user_stopped=0 WHERE id=?`);
  const acceptedItems = [];
  let blockedQuota = null; // primer bloqueo por cupo: { monday, poolKey }
  let n = 0;
  for (const d of pending) {
    let when = whenById[d.id] || (d.scheduled_at ? String(d.scheduled_at).slice(0, 19).replace('T', ' ') : null);
    // Integridad de agenda (2026-10-16): sin fecha o con el día ocupado
    // (por otro posteo o por uno aceptado recién en este mismo lote — el
    // UPDATE es inmediato, el chequeo ve el lote en curso), el asignador
    // da el próximo día libre. Nunca dos el mismo día.
    if (!when || scheduleDayTaken(uid, d, when)) {
      try { const s = assignScheduleSlots(uid, [d]); if (s.get(d.id)) when = s.get(d.id); } catch (e) {}
    }
    if (!when) continue; // sin hora no se puede programar: se saltea
    const poolKey = d.media_type === 'video' ? 'video' : d.media_type === 'story' ? 'story' : 'image';
    const monday = mondayKeyOf(String(when).slice(0, 10));
    if (leftFor(monday, poolKey) <= 0) {
      if (!blockedQuota) blockedQuota = { monday, poolKey };
      continue; // su semana está llena: queda borrador (el modal es para ESTE caso)
    }
    weekLeftCache.set(monday + '|' + poolKey, leftFor(monday, poolKey) - 1);
    upd.run(when, d.id);
    try { recordSignal(uid, d, 'approved'); } catch (e) {}
    acceptedItems.push({ id: d.id, scheduled_at: when });
    n++;
  }
  if (!n) {
    if (blockedQuota) {
      return { ok: false, reason: 'plan_limit', quota: quotaForWeek(uid, blockedQuota.poolKey, blockedQuota.monday) };
    }
    return { ok: false, reason: 'no_pending' };
  }
  clearPublishingStopped(uid); // (v275) aceptar la semana es reanudar la cuenta
  try { track(uid, 'accept_all', String(n)); } catch (e) {}
  let nextWeek = 0;
  try {
    const curMonday = mondayKeyOf(tzToday(userTz(uid)));
    nextWeek = acceptedItems.filter((it) => mondayKeyOf(String(it.scheduled_at).slice(0, 10)) > curMonday).length;
  } catch (e) {}
  return { ok: true, accepted: n, partial: n < pending.length, total: pending.length, items: acceptedItems, next_week: nextWeek };
}

// POST /api/posts/accept-all — "✅ Aceptar todos" (tarjeta "Revisá tu semana").
// Todos los borradores pendientes del usuario pasan a aprobados + programados en
// la hora indicada (la que muestra la tarjeta de revisión). Respeta rechazados:
// no los toca. El tap ES la confirmación (sin diálogo redundante).
app.post('/api/posts/accept-all', requireAuth, (req, res) => {
  const uid = req.session.userId;
  const items = Array.isArray((req.body || {}).items) ? req.body.items : [];
  const r = acceptAllDrafts(uid, items);
  if (r.reason === 'empty') return res.status(400).json({ error: 'Sin posteos para aceptar' });
  if (r.reason === 'no_pending') return res.status(400).json({ error: 'No hay borradores pendientes' });
  if (r.reason === 'plan_limit') {
    const qf = r.quota;
    return res.status(403).json({ error: 'plan_limit', plan_limit: true, limit: qf.limit, used: qf.used, plan_name: qf.plan_name, week_key: qf.week_key || null,
      message: `Llegaste al límite de tu plan ${qf.plan_name}. Mejorá tu paquete para seguir posteando esa semana.` });
  }
  res.json({ ok: true, accepted: r.accepted, partial: !!r.partial, total: r.total || 0, items: r.items || [], next_week: r.next_week || 0 });
});

// FASE 2 — GET /api/week/:weekKey/publish — "Publicar semana" de un tap, SIN
// login. Es el botón del email de preview (sendWeekPreview): la firma HMAC ata
// (userId, weekKey, exp) y el tap ES la revisión humana (includeNeedsReview).
// Idempotente: si ya no hay borradores, confirma igual.
app.get('/api/week/:weekKey/publish', (req, res) => {
  const weekKey = String(req.params.weekKey || '');
  const uid = Number(req.query.uid);
  const { sig, exp } = req.query || {};
  const bad = (code, title, msg) => res.status(code).send(approvalPage(title, msg));
  if (!/^\d{4}-\d{2}-\d{2}$/.test(weekKey)) return bad(404, 'Enlace inválido', 'Este enlace no corresponde a ninguna semana.');
  if (!uid || !(sig && exp)) return bad(403, 'Enlace inválido', 'A este enlace le faltan datos. Pedí uno nuevo desde tu email de Posty.');
  if (!approval.verifyWeekAction(uid, weekKey, sig, exp)) return bad(403, 'Enlace vencido', 'Este enlace venció o no es válido. Entrá a Posty para publicar tu semana.');
  const u = db.prepare('SELECT id FROM users WHERE id = ?').get(uid);
  if (!u) return bad(404, 'Cuenta no encontrada', 'Este enlace no corresponde a una cuenta válida.');
  const drafts = db.prepare(`SELECT id, scheduled_at FROM posts
    WHERE user_id = ? AND week_key = ? AND status = 'draft'
      AND media_type IN ('image','carousel','video')
    ORDER BY created_at ASC`).all(uid, weekKey);
  if (!drafts.length) return res.send(approvalPage('✅ Semana publicada', 'Tu semana ya está publicada o programada. ¡A seguir vendiendo! 🚀'));
  // Horarios propuestos: el preview los deja puestos; si faltan (email viejo),
  // se asignan acá con la misma política del autopilot.
  let slots = new Map();
  try {
    const missing = drafts.filter((d) => !d.scheduled_at);
    if (missing.length) slots = assignScheduleSlots(uid, missing);
  } catch (e) { console.error('[week publish] slots:', e.message); }
  const items = drafts.map((d) => ({ id: d.id, scheduled_at: d.scheduled_at || slots.get(d.id) || null }));
  const r = acceptAllDrafts(uid, items, { includeNeedsReview: true });
  if (r.reason === 'plan_limit') {
    const qf = r.quota || {};
    return bad(403, 'Límite del plan', `Tu plan ${qf.plan_name || ''} no alcanza para publicar toda la semana de una. Mejorá tu paquete y volvé a tocar el botón.`);
  }
  if (!r.ok || !r.accepted) return res.send(approvalPage('Nada para publicar', 'No había borradores pendientes en esta semana.'));
  return res.send(approvalPage('✅ ¡Semana publicada!', `${r.accepted} ${r.accepted === 1 ? 'posteo programado' : 'posteos programados'}. Posty se encarga del resto 🚀`));
});

app.post('/api/posts/:id/reject', approvalAuth('reject'), (req, res) => {
  const post = req.approvalPost;
  if (post.approval === 'rejected' || post.status === 'cancelled') {
    return res.json({ ok: true, approval: 'rejected' }); // idempotente
  }
  if (post.status === 'published') {
    return res.status(409).json({ error: 'already_published', message: 'Este posteo ya salió: no se puede cancelar.' });
  }
  if (!['pending', 'approved'].includes(post.approval || 'pending') || post.status !== 'scheduled') {
    return res.status(409).json({ error: 'not_rejectable', message: 'Este posteo ya no se puede cancelar.' });
  }
  db.prepare(`UPDATE posts SET approval = 'rejected', status = 'cancelled', error = '' WHERE id = ?`).run(post.id);
  try { recordSignal(post.user_id, post, 'rejected'); } catch (e) {} // FASE 5: el veto en el pre-aviso es señal fuerte
  console.log(`[posta] Post #${post.id} rechazado por el cliente → cancelado`);
  res.json({ ok: true, approval: 'rejected' });
});

app.get('/api/posts/:id/reject', approvalAuth('reject'), (req, res) => {
  const post = req.approvalPost;
  if (post.approval === 'rejected' || post.status === 'cancelled') {
    return res.send(approvalPage('Ya estaba cancelado', 'Este posteo ya estaba cancelado: no se va a publicar.'));
  }
  if (post.status === 'published') {
    return res.status(409).send(approvalPage('Ya salió', 'Este posteo ya se publicó: no se puede cancelar.'));
  }
  if (!['pending', 'approved'].includes(post.approval || 'pending') || post.status !== 'scheduled') {
    return res.status(409).send(approvalPage('No se puede cancelar', 'Este posteo ya no está programado.'));
  }
  db.prepare(`UPDATE posts SET approval = 'rejected', status = 'cancelled', error = '' WHERE id = ?`).run(post.id);
  try { recordSignal(post.user_id, post, 'rejected'); } catch (e) {} // FASE 5: el veto en el pre-aviso es señal fuerte
  console.log(`[posta] Post #${post.id} rechazado por el cliente → cancelado`);
  res.send(approvalPage('Posteo cancelado', 'Listo: este posteo no se va a publicar.'));
});

// Duplicar un posteo como borrador (para re-publicarlo sin armarlo de cero)
app.post('/api/posts/:id/duplicate', requireAuth, requireTrialValid, (req, res) => {
  const post = db.prepare('SELECT * FROM posts WHERE id = ? AND user_id = ?').get(req.params.id, req.session.userId);
  if (!post) return res.status(404).json({ error: 'Post no encontrado' });
  // Duplicar crea un borrador: los borradores no consumen cupo (se descuenta al programar/publicar).
  const r = db.prepare(
    'INSERT INTO posts (user_id, image_path, caption, hashtags, scheduled_at, status, media_type, needs_review) VALUES (?,?,?,?,?,?,?,?)'
  ).run(req.session.userId, post.image_path, post.caption, post.hashtags, null, 'draft', post.media_type || 'image', trainingWheelsActive(req.session.userId) ? 1 : 0);
  res.json({ ok: true, id: r.lastInsertRowid });
});

// "🔄 Otras 3": 3 variantes frescas (imagen con IA + texto) del MISMO borrador,
// cada una con otro ángulo de ejecución. No crea posteos ni consume cupo: solo
// genera imágenes temporales que el usuario puede elegir (PATCH) o ignorar.
// El borrador original queda intacto si la generación falla.
app.post('/api/posts/:id/variants', requireAuth, requireTrialValid, express.json(), async (req, res) => {
  const uid = req.session.userId;
  const post = db.prepare('SELECT * FROM posts WHERE id = ? AND user_id = ?').get(req.params.id, uid);
  if (!post) return res.status(404).json({ error: 'Post no encontrado' });
  if (post.media_type === 'video' || post.media_type === 'carousel')
    return res.status(400).json({ error: 'Las variantes van solo en posteos con imagen 🖼️' });
  try {
    const settings = getSettings(uid);
    const key = settings.openai_key || process.env.OPENAI_API_KEY || '';
    if (!key) return res.status(400).json({ error: 'Sin clave de OpenAI' });
    const profile = getProfile(uid);
    const topic = (post.source_topic || '').trim()
      || String(post.caption || '').split('\n')[0].trim().slice(0, 80)
      || 'novedad';
    const tipo = post.tipo || '';
    const dna = readDna(uid);
    let styleRules = [];
    try { styleRules = db.prepare('SELECT rule_text FROM style_rules WHERE user_id = ? AND active = 1').all(uid).map(r => r.rule_text); } catch (e) {}
    let voice = '';
    try { if (typeof voiceExamples === 'function') voice = voiceExamples(db, uid) || ''; } catch (e) {}
    // (v237) Refs del álbum POR PIEZA (mapeada/tag/calidad), no las 2
    // más recientes a ciegas.
    const refs = albumRefsForPiece(uid, { tipo, texts: topic }).refs;
    const baseInput = {
      business: profile.business_name,
      category: profile.category,
      description: profile.description,
      dna,
      tone: profile.tone,
      topic,
      tipo,
      competitors: profile.competitors,
      goal: profile.goal,
      taste: tasteProfile(uid),
      performance: [performanceBrief(db, uid), bestHoursLine(db, uid)].filter(Boolean).join('\n'),
      styleRules,
      voice,
      golden: goldenExamples(uid), // "rueditas": posteos aprobados como few-shot
    };
    // 3 ángulos distintos para que las variantes no se parezcan entre sí.
    const angles = [
      'Enfocá el ángulo del BENEFICIO directo: qué gana el cliente con esto.',
      'Enfocá el ángulo de la NOVEDAD y la curiosidad: algo que la gente no espera.',
      'Enfocá el ángulo de la CONFIANZA: cercanía, equipo, clientes que ya lo eligen.',
    ];
    const results = await Promise.allSettled([0, 1, 2].map(async (i) => {
      const out = await generateCaptions({ ...baseInput, feedback: angles[i], seedBase: i * 7 + 1 }, 1, key);
      const caption = (out.captions && out.captions[0]) || '';
      if (!caption.trim()) throw new Error('La IA no devolvió texto');
      // Titular corto y COMPLETO para la imagen (makeHeadline: jamás cortado a mitad de oración).
      const headline = makeHeadline(String(caption).split('\n')[0], 6, 70, (profile && profile.category) || null);
      const imagePath = await conceptShotGenerateQueued({
        uid, idea: { titulo: topic, porque: angles[i] }, tipo, headline, refs, apiKey: key,
      });
      return { image_path: imagePath, caption, hashtags: out.hashtags || '' };
    }));
    const variants = results.filter(r => r.status === 'fulfilled').map(r => r.value);
    results.filter(r => r.status === 'rejected').forEach(r => console.error('[variants] variante falló:', r.reason && r.reason.message));
    if (!variants.length)
      return res.status(502).json({ error: 'Las variantes no me salieron 😅 Probá de nuevo en un minuto' });
    console.log(`[variants] borrador ${post.id}: ${variants.length}/3 variantes para usuario ${uid}`);
    res.json({ ok: true, variants });
  } catch (e) {
    console.error('[variants]', e.message);
    res.status(500).json({ error: 'No se pudieron generar las variantes: ' + e.message.slice(0, 200) });
  }
});
// Semana con inicio lunes (zona horaria del negocio). week_key = 'YYYY-MM-DD' del lunes.
function tzToday(tz) {
  try { return new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date()); }
  catch { return new Date().toISOString().slice(0, 10); }
}
function mondayKeyOf(ymd) {
  const [y, m, d] = String(ymd).split('-').map(Number);
  const dt = new Date(Date.UTC(y || 1970, (m || 1) - 1, d || 1, 12));
  dt.setUTCDate(dt.getUTCDate() - ((dt.getUTCDay() + 6) % 7));
  return dt.toISOString().slice(0, 10);
}
function ymdInTz(iso, tz) {
  if (!iso) return null;
  try {
    const d = new Date(String(iso).length === 16 ? iso : String(iso).replace(' ', 'T'));
    if (isNaN(d)) return null;
    return new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
  } catch { return null; }
}
function shiftDays(ymd, n) {
  const [y, m, d] = String(ymd).split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d, 12));
  dt.setUTCDate(dt.getUTCDate() + n);
  return dt.toISOString().slice(0, 10);
}
function userTz(userId) {
  try { return getSettings(userId).timezone || 'America/Argentina/Buenos_Aires'; }
  catch { return 'America/Argentina/Buenos_Aires'; }
}
// UTC ISO → "AAAA-MM-DD HH:MM" en la zona del cliente (para la agenda que ve el chat).
function wallInTz(iso, tz) {
  if (!iso) return '';
  try {
    const s = String(iso);
    const d = new Date(s.length === 16 ? s : s.replace(' ', 'T'));
    if (isNaN(d)) return '';
    const fmt = new Intl.DateTimeFormat('en-CA', { timeZone: tz || 'America/Argentina/Buenos_Aires', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false });
    const p = Object.fromEntries(fmt.formatToParts(d).map(x => [x.type, x.value]));
    const hh = p.hour === '24' ? '00' : p.hour;
    return `${p.year}-${p.month}-${p.day} ${hh}:${p.minute}`;
  } catch { return ''; }
}
// "2026-09-30 18:00" como hora local en tz → ISO UTC. null si es inválido.
function zonedWallToUtc(s, tz) {
  try {
    const m = String(s).match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2})$/);
    if (!m) return null;
    const Y = +m[1], Mo = +m[2], D = +m[3], h = +m[4], mi = +m[5];
    if (Y < 2026 || Y > 2030 || Mo < 1 || Mo > 12 || D < 1 || D > 31 || h > 23 || mi > 59) return null;
    const zone = tz || DEFAULT_TZ;
    const guess = Date.UTC(Y, Mo - 1, D, h, mi);
    const fmt = new Intl.DateTimeFormat('en-US', { timeZone: zone, hour12: false, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
    const parts = {};
    for (const p of fmt.formatToParts(new Date(guess))) parts[p.type] = p.value;
    const asUtc = Date.UTC(+parts.year, +parts.month - 1, +parts.day, (+parts.hour % 24), +parts.minute, +parts.second);
    return new Date(guess - (asUtc - guess)).toISOString();
  } catch (e) { return null; }
}
function postWeekKey(p, tz) {
  // Track 4: si el posteo trae week_key explícita (pipeline perpetuo), manda ella.
  if (p.week_key) return p.week_key;
  return mondayKeyOf(ymdInTz(p.scheduled_at || p.published_at || p.created_at, tz) || tzToday(tz));
}
// Guarda (o actualiza) la señal del cliente para un posteo. La última señal vale.
// Perfil de gusto del cliente a partir de sus 👍/👎: se inyecta en el prompt para que la IA aprenda de verdad.
function tasteProfile(userId) {
  try {
    // FASE 5: las señales manuales pesan primero; las auto-marcadas por el
    // scheduler (auto_signal=1) van después para no diluir el taste.
    const rows = db.prepare(`
      SELECT s.caption AS caption, s.client_signal AS sig FROM post_signals s
      WHERE s.user_id = ? AND s.client_signal IN ('approved','rejected')
      ORDER BY COALESCE(s.auto_signal, 0) ASC, s.updated_at DESC LIMIT 12
    `).all(userId);
    const liked = [], disliked = [];
    for (const r of rows) {
      const cap = (r.caption || '').split('\n')[0].slice(0, 120).trim();
      if (!cap) continue;
      if (r.sig === 'approved' && liked.length < 3 && !liked.includes(cap)) liked.push(cap);
      else if (r.sig === 'rejected' && disliked.length < 3 && !disliked.includes(cap)) disliked.push(cap);
    }
    if (!liked.length && !disliked.length) return '';
    let t = '';
    if (liked.length) t += `\nAl cliente le GUSTARON estos posteos (escribí más en esta línea):\n- ${liked.join('\n- ')}`;
    if (disliked.length) t += `\nAl cliente NO le gustaron estos (evitá este estilo y estos temas):\n- ${disliked.join('\n- ')}`;
    return t;
  } catch (e) { return ''; }
}
// ===== Track D — Auditoría del loop de aprendizaje =====
// Antes de este fix: los temas rechazados NO se excluían (la IA los repetía),
// los aprobados NO se priorizaban explícitamente, y brought_clients/no_clients
// se guardaban pero NADIE los leía (señal MUERTA). Estas 3 funciones las reviven.
// Temas RECHAZADOS por el cliente (últimos 60 días) → se excluyen de la próxima tanda.
function excludedTopicsLine(userId) {
  try {
    const rows = db.prepare(`
      SELECT s.caption AS caption FROM post_signals s
      WHERE s.user_id = ? AND s.client_signal IN ('rejected', 'rating_1', 'rating_2')
        AND s.updated_at >= datetime('now', '-60 days')
      ORDER BY s.updated_at DESC LIMIT 12
    `).all(userId);
    const temas = rows.map(r => String(r.caption || '').split('\n')[0].slice(0, 80).trim())
      .filter(Boolean).filter((v, i, a) => a.indexOf(v) === i);
    return temas.length ? temas.join(' | ') : '';
  } catch (e) { return ''; }
}
// Temas y tipos APROBADOS/EDITADOS (últimos 60 días) → se priorizan con variación.
function approvedTopicsLine(userId) {
  try {
    const rows = db.prepare(`
      SELECT s.caption AS caption, p.tipo AS tipo FROM post_signals s
      LEFT JOIN posts p ON p.id = s.post_id
      WHERE s.user_id = ? AND s.client_signal IN ('approved', 'edited', 'rating_4', 'rating_5')
        AND s.updated_at >= datetime('now', '-60 days')
      ORDER BY COALESCE(s.auto_signal, 0) ASC, s.updated_at DESC LIMIT 12
    `).all(userId);
    const temas = rows.map(r => String(r.caption || '').split('\n')[0].slice(0, 80).trim())
      .filter(Boolean).filter((v, i, a) => a.indexOf(v) === i).slice(0, 5);
    const tipos = [...new Set(rows.map(r => String(r.tipo || '').trim()).filter(t => TIPOS_VALIDOS.includes(t)))].slice(0, 3);
    let t = '';
    if (temas.length) t += temas.join(' | ');
    if (tipos.length) t += (t ? '; ' : '') + `tipos que le gustaron: ${tipos.join(', ')}`;
    return t;
  } catch (e) { return ''; }
}
// Brief de outcome: temas que trajeron CLIENTES de verdad (repetir con variación)
// vs los que no trajeron (evitar). Entran al prompt de ideas y al chat.
function outcomeBrief(userId) {
  try {
    const rows = db.prepare(`
      SELECT s.caption AS caption, s.client_signal AS sig FROM post_signals s
      WHERE s.user_id = ? AND s.client_signal IN ('brought_clients', 'no_clients')
      ORDER BY s.updated_at DESC LIMIT 12
    `).all(userId);
    const si = [], no = [];
    for (const r of rows) {
      const cap = String(r.caption || '').split('\n')[0].slice(0, 80).trim();
      if (!cap) continue;
      if (r.sig === 'brought_clients' && si.length < 4 && !si.includes(cap)) si.push(cap);
      else if (r.sig === 'no_clients' && no.length < 4 && !no.includes(cap)) no.push(cap);
    }
    let t = '';
    if (si.length) t += `\nTemas que le trajeron CLIENTES de verdad (repetilos con una variación o un ángulo nuevo, no copies el posteo):\n- ${si.join('\n- ')}`;
    if (no.length) t += `\nTemas que NO le trajeron clientes (evitalos o cambialos de raíz):\n- ${no.join('\n- ')}`;
    return t;
  } catch (e) { return ''; }
}
// ===== FASE 5 (2026-10-05) — aprendizaje AUTOMÁTICO de contenido =====
// Bajo autopilot el taste manual (👍/👎) se seca: este bloque lo reemplaza con
// ER medido por tipo de contenido, y se inyecta en generateIdeas igual que
// tasteProfile. Lee post_metrics (ingesta de insights) con fallback a las
// columnas ig_* de posts; sin datos reales devuelve '' (fail-safe: sin App
// Review no hay métricas y el prompt queda intacto).
// Suavizado bayesiano con la fórmula documentada de learning.js, pero con
// prior = el promedio del PROPIO cliente (no el global): 1 posteo viral no
// domina. Solo habla con evidencia (>=2 posteos medidos por tipo, >=4 total)
// y cuando algún tipo se desvía de forma significativa de su promedio.
function contentPerformanceLine(userId) {
  try {
    const { engagementRate, C_PRIOR, PRIOR_ER } = require('./learning');
    const C = (typeof C_PRIOR === 'number' && C_PRIOR > 0) ? C_PRIOR : 5;
    const rows = db.prepare(`
      SELECT p.tipo AS tipo,
             SUM(COALESCE(m.reach, p.ig_reach, 0)) AS reach,
             SUM(COALESCE(m.likes, p.ig_likes, 0)) AS likes,
             SUM(COALESCE(m.comments, p.ig_comments, 0)) AS comments,
             SUM(COALESCE(m.saved, 0)) AS saved,
             COUNT(*) AS n
      FROM posts p
      LEFT JOIN post_metrics m ON m.post_id = p.id
      WHERE p.user_id = ?
        AND p.status = 'published'
        AND COALESCE(p.published_at, p.created_at) > datetime('now', '-90 days')
        AND p.tipo IN ('promo','tip','social','detras','novedad')
      GROUP BY p.tipo
    `).all(userId);
    const measured = rows.filter(r => (r.reach + r.likes + r.comments + r.saved) > 0 && r.n >= 2);
    const totalN = measured.reduce((a, r) => a + r.n, 0);
    if (!measured.length || totalN < 4) return '';
    const tot = measured.reduce((a, r) => ({
      reach: a.reach + r.reach, likes: a.likes + r.likes,
      comments: a.comments + r.comments, saved: a.saved + r.saved,
    }), { reach: 0, likes: 0, comments: 0, saved: 0 });
    const mean = engagementRate(tot) || PRIOR_ER;
    const scored = measured.map(r => {
      const er = engagementRate(r);
      const score = (C * mean + r.n * er) / (C + r.n);
      return { tipo: r.tipo, n: r.n, ratio: mean > 0 ? score / mean : 1 };
    }).filter(s => s.ratio >= 1.25 || s.ratio <= 0.75)
      .sort((a, b) => Math.abs(Math.log(b.ratio)) - Math.abs(Math.log(a.ratio)))
      .slice(0, 4);
    if (!scored.length) return '';
    const lines = scored.map(s => {
      const x = (Math.round(s.ratio * 10) / 10).toFixed(1).replace(/\.0$/, '');
      return s.ratio >= 1.25
        ? `- Tus posteos tipo "${s.tipo}" rinden ${x}x tu promedio (${s.n} posteos): PRIORIZALOS con variación.`
        : `- Tus posteos tipo "${s.tipo}" rinden ${x}x tu promedio (${s.n} posteos): usalos menos o cambiales el ángulo.`;
    });
    return `\nRENDIMIENTO MEDIDO de tu cuenta (últimos 90 días, datos reales de Instagram):\n${lines.join('\n')}`;
  } catch (e) { return ''; }
}
/* 🧠 (v232) CEREBRO COMERCIAL — realimentación por ÁNGULO: el espejo de
 * contentPerformanceLine pero agrupando por posts.sales_angle. Devuelve
 * { line, scores }: la línea alimenta el brief de ideas y los scores
 * (ratio vs el promedio de la cuenta, mismo encogimiento bayesiano)
 * alimentan al planificador semanal, que prefiere los ángulos
 * ganadores de ESTE negocio sin bloquear la rotación. */
function anglePerformanceFor(userId) {
  try {
    const rows = db.prepare(`
      SELECT p.sales_angle AS angle,
             COALESCE(m.reach, p.ig_reach, 0) AS reach,
             COALESCE(m.likes, p.ig_likes, 0) AS likes,
             COALESCE(m.comments, p.ig_comments, 0) AS comments,
             COALESCE(m.saved, 0) AS saved
      FROM posts p
      LEFT JOIN post_metrics m ON m.post_id = p.id
      WHERE p.user_id = ?
        AND p.status = 'published'
        AND COALESCE(p.published_at, p.created_at) > datetime('now', '-90 days')
        AND COALESCE(p.sales_angle, '') != ''
    `).all(userId);
    const scores = salesBrain.scoreAngles(rows);
    const keys = Object.keys(scores);
    if (!keys.length) return { line: '', scores };
    const lines = keys
      .filter((a) => scores[a] >= 1.25 || scores[a] <= 0.75)
      .sort((a, b) => Math.abs(Math.log(scores[b])) - Math.abs(Math.log(scores[a])))
      .slice(0, 3)
      .map((a) => {
        const x = (Math.round(scores[a] * 10) / 10).toFixed(1).replace(/\.0$/, '');
        return scores[a] >= 1.25
          ? `- Tus posteos con ángulo "${a}" rinden ${x}x tu promedio: PREFERILO con variación.`
          : `- Tus posteos con ángulo "${a}" rinden ${x}x tu promedio: usalo menos o reformulalo.`;
      });
    if (!lines.length) return { line: '', scores };
    return { line: `\nRENDIMIENTO POR ÁNGULO de tu cuenta (últimos 90 días):\n${lines.join('\n')}`, scores };
  } catch (e) { return { line: '', scores: {} }; }
}
/* 🧠 (v232) Objeciones REALES del público del cliente: se minan de sus
 * comentarios y DMs (las colas que ya junta el sistema community-pro)
 * buscando las señales de fricción — precio, demora, garantía, stock,
 * talle, envío. Alimentan el ángulo objeción→respuesta del cerebro
 * comercial: la respuesta nace de lo que SU gente pregunta de verdad. */
const OBJECTION_RE = /(cu[aá]nto|precio|caro|sale\b|demora|tarda|garant|env[ií]o|queda[n]?|stock|dura\b|obra social|talle|cambio|devol)/i;
function mineObjectionsFor(uid) {
  try {
    const rows = [
      ...db.prepare(`SELECT text FROM comment_queue WHERE user_id = ? AND COALESCE(text, '') != '' ORDER BY created_at DESC LIMIT 40`).all(uid),
      ...db.prepare(`SELECT text FROM dm_queue WHERE user_id = ? AND COALESCE(text, '') != '' ORDER BY created_at DESC LIMIT 40`).all(uid),
    ];
    const seen = new Set();
    const out = [];
    for (const r of rows) {
      const t = String((r && r.text) || '').replace(/\s+/g, ' ').trim().slice(0, 120);
      if (t.length < 8 || !OBJECTION_RE.test(t)) continue;
      const k = t.toLowerCase();
      if (seen.has(k)) continue;
      seen.add(k);
      out.push(t);
      if (out.length >= 5) break;
    }
    return out;
  } catch (e) { return []; }
}
function recordSignal(userId, post, signal) {
  try {
    const tz = userTz(userId);
    const prof = getProfile(userId) || {};
    const wk = postWeekKey(post, tz);
    db.prepare(`
      INSERT INTO post_signals (user_id, post_id, caption, hashtags, scheduled_for, rubro, client_signal, week_key, updated_at, style_code, tipo)
      VALUES (?,?,?,?,?,?,?,?,datetime('now'),?,?)
      ON CONFLICT(user_id, post_id) DO UPDATE SET
        client_signal=excluded.client_signal, caption=excluded.caption, hashtags=excluded.hashtags,
        scheduled_for=excluded.scheduled_for, rubro=excluded.rubro,
        week_key=excluded.week_key, updated_at=datetime('now'),
        style_code=excluded.style_code, tipo=excluded.tipo,
        auto_signal=0 -- FASE 5: la señal manual pisa la auto-marcada
    `).run(userId, post.id, post.caption || '', post.hashtags || '', post.scheduled_at || '', prof.category || '', signal, wk, post.style_code || '', post.tipo || '');
  } catch (e) { console.error('[posta] recordSignal:', e.message); }
}

// Señal manual sobre un posteo (👍/👎 en borradores, estrellitas 1-5 en "Ya salió")
app.post('/api/posts/:id/signal', requireAuth, (req, res) => {
  const { signal } = req.body || {};
  if (!['approved', 'edited', 'rejected', 'brought_clients', 'no_clients', 'rating_1', 'rating_2', 'rating_3', 'rating_4', 'rating_5'].includes(signal)) return res.status(400).json({ error: 'Señal inválida' });
  const post = db.prepare('SELECT * FROM posts WHERE id = ? AND user_id = ?').get(req.params.id, req.session.userId);
  if (!post) return res.status(404).json({ error: 'Post no encontrado' });
  recordSignal(req.session.userId, post, signal);
  res.json({ ok: true });
});

// ===== Track 4 "Pipeline perpetuo" =====
// Cuando el usuario programa su semana N (un tap), la semana N+1 se empieza a
// armar SOLA en segundo plano. Al llegar la semana siguiente, los borradores ya
// están listos para revisar y programar. NUNCA se auto-programa N+1: quedan como
// borradores. Sin el tap del usuario, nada se programa ni publica.
// El pipeline es 100% server-side (el autopilot del browser no sirve en
// background): ideas (generateIdeas) + texto (generateContent) + imagen
// (conceptShotGenerate, motor nivel agencia) + INSERT como borrador.
// Límites honestos del MVP server-side: sin canvas (no hay fallback de diseño
// si concept-shot falla: ese borrador se saltea y se sigue) y sin reels
// (autopilotReel vive en el browser; el último borrador sale como imagen y el
// usuario lo puede convertir).
// Guard en memoria (mismo proceso que el cron): una sola corrida por usuario.
const NEXTWEEK_RUNNING = new Map(); // uid -> timestamp de inicio
// 2026-10-08: último resultado de generateWeekDrafts por usuario, para que el
// frontend muestre el error exacto sin adivinar.
const LAST_WEEK_RESULT = new Map(); // uid -> {ok, reason, error, created, at, weekKey}
// Limpia corridas trabadas: si una generación lleva más de 15 min, se asume
// colgada y se libera para reintentar (2026-10-06: fix del "armando tu semana"
// eterno — la corrida anterior de Valentino quedó marcada y nunca se liberó).
function nextweekRunningFresh(uid) {
  const ts = NEXTWEEK_RUNNING.get(uid);
  if (!ts) return false;
  if (Date.now() - ts > 15 * 60 * 1000) {
    NEXTWEEK_RUNNING.delete(uid);
    console.log(`[pipeline] usuario ${uid}: corrida trabada (>15min), liberada para reintentar`);
    return false;
  }
  return true;
}
// Gate 1: solo con plan activo O trial vigente. Cada semana cuesta plata real.
function planOrTrialOk(uid) {
  try {
    const u = db.prepare('SELECT plan_status, trial_ends_at, trial_extended_until, created_at FROM users WHERE id = ?').get(uid);
    return !!(u && (u.plan_status === 'active' || trialEffectiveEnd(u) > Date.now()));
  } catch (e) { return false; }
}
// Gate 2: el usuario estuvo activo en los últimos 7 días.
// Señales (mejor disponible primero): posteos creados (el autopilot crea),
// mensajes de chat, señales del cliente (👍/👎, programados, outcome).
function activeRecently(uid, days) {
  try {
    const r = db.prepare(`
      SELECT 1 FROM posts WHERE user_id = ? AND created_at >= datetime('now', ?)
      UNION ALL SELECT 1 FROM chat_messages WHERE user_id = ? AND created_at >= datetime('now', ?)
      UNION ALL SELECT 1 FROM post_signals WHERE user_id = ? AND updated_at >= datetime('now', ?)
      LIMIT 1`).get(uid, `-${days} days`, uid, `-${days} days`, uid, `-${days} days`);
    return !!r;
  } catch (e) { return false; }
}
// Gate 4: pausa por inactividad — si en 14 días no hubo ni programados nuevos
// ni corridas del autopilot, no se dispara (ni trigger ni cron).
function pipelineAliveRecently(uid) {
  try {
    const r = db.prepare(`
      SELECT 1 FROM posts WHERE user_id = ? AND status IN ('scheduled','publishing','published') AND created_at >= datetime('now', '-14 days')
      UNION ALL SELECT 1 FROM posts WHERE user_id = ? AND status = 'draft' AND created_at >= datetime('now', '-14 days')
      UNION ALL SELECT 1 FROM post_signals WHERE user_id = ? AND client_signal = 'approved' AND updated_at >= datetime('now', '-14 days')
      LIMIT 1`).get(uid, uid, uid);
    return !!r;
  } catch (e) { return false; }
}
// Los 4 gates juntos. Devuelve { ok, reason }.
function nextWeekEligible(uid, weekKey) {
  if (!planOrTrialOk(uid)) return { ok: false, reason: 'no_plan' };
  if (!activeRecently(uid, 7)) return { ok: false, reason: 'inactive_7d' };
  // Gate 3: una sola semana de adelanto — si ya hay posteos (borradores o no)
  // marcados con esa week_key, no regenerar.
  try {
    const n = db.prepare(`SELECT COUNT(*) AS n FROM posts WHERE user_id = ? AND week_key = ? AND status != 'cancelled'`).get(uid, weekKey).n || 0;
    if (n > 0) return { ok: false, reason: 'already_exists' };
  } catch (e) { /* sin week_key en DB vieja: seguir */ }
  if (!pipelineAliveRecently(uid)) return { ok: false, reason: 'paused_14d' };
  return { ok: true };
}
// Helpers de marca para portadas de stories/reels (image-fallback.js).
// Logo del cliente como archivo absoluto (o null si no hay).
function logoAbsPath(uid) {
  try {
    const row = db.prepare(`SELECT file_path FROM assets WHERE user_id = ? AND kind = 'logo' ORDER BY id ASC LIMIT 1`).get(uid);
    const p = row && path.join(MEDIA_DIR, path.basename(String(row.file_path || '')));
    return (p && fs.existsSync(p)) ? p : null;
  } catch (e) { return null; }
}
// Primer color de marca del cliente (o default Posty).
function primaryBrandHex(uid) {
  try {
    const hexes = parseBrandHexes((getSettings(uid) || {}).brand_colors);
    return (hexes && hexes[0]) || '#0A1E33';
  } catch (e) { return '#0A1E33'; }
}
// Genera los borradores de una semana (week_key = lunes 'YYYY-MM-DD').
// Idempotente por (usuario, semana): si ya existen, no hace nada.
// ---------- 🧩 Equilibrio de grilla (2026-10-18, v224, pedido de Valentino) ----------
// "Que mantenga el equilibrio de colores que ya tienen los clientes en su
// feed. Si todas las publicaciones de la fila de la izquierda son de una
// manera, respetar eso." Lectura del patrón de la grilla que el cliente YA
// tiene (grid-pattern.js, lógica pura) desde estadísticas determinísticas
// de sus posteos publicados (grid-stats.py: luminancia, saturación y
// familia de tono por imagen — USD 0, todo local), cacheada por semana en
// grid_pattern_snapshots como los snapshots de competencia del loop de
// ideas. Sin patrón FUERTE no se toca nada: el pipeline sigue como siempre.
function readGridSnapshot(uid) {
  try {
    const row = db.prepare('SELECT data_json, computed_at FROM grid_pattern_snapshots WHERE user_id = ?').get(uid);
    if (!row) return null;
    const d = JSON.parse(row.data_json || 'null');
    if (d) d._computedAt = row.computed_at;
    return d;
  } catch (e) { return null; }
}

function runGridStats(files) {
  return new Promise((resolve) => {
    const { execFile } = require('child_process');
    execFile('python3', [path.join(__dirname, 'grid-stats.py'), ...files], { timeout: 30000, maxBuffer: 1024 * 1024 }, (err, stdout) => {
      if (err || !stdout) return resolve([]);
      const out = [];
      for (const line of String(stdout).split('\n')) {
        const s = line.trim();
        if (!s) continue;
        try { out.push(JSON.parse(s)); } catch (e) { out.push(null); }
      }
      resolve(out);
    });
  });
}

// Mide la grilla publicada que la app conoce (la más nueva primero: la
// posición 0 es arriba a la izquierda) y detecta su patrón. Una foto que
// no está en disco conserva su posición pero no vota (lum null).
async function computeGridPattern(uid) {
  let rows = [];
  try {
    rows = db.prepare(`SELECT id, image_path, cover_path, media_type, tipo, intent FROM posts
      WHERE user_id = ? AND status = 'published' AND media_type IN ('image','carousel','video')
      AND COALESCE(image_path, '') != ''
      ORDER BY published_at DESC, id DESC LIMIT 18`).all(uid);
  } catch (e) {}
  const files = [];
  const fileRowIdx = [];
  rows.forEach((r, i) => {
    // (v332) un video se mide por su PORTADA (cover_path si el director de
    // feed ya la eligió/graduó): es la superficie que toca la grilla; el
    // mp4 no es medible por grid-stats y antes quedaba fuera del patrón.
    const base = (r.media_type === 'video' && r.cover_path)
      ? path.basename(String(r.cover_path)) : path.basename(String(r.image_path || ''));
    if (!base) return;
    const f = path.join(MEDIA_DIR, base);
    if (fs.existsSync(f)) { files.push(f); fileRowIdx.push(i); }
  });
  const stats = files.length ? await runGridStats(files) : [];
  const statByRow = new Map();
  fileRowIdx.forEach((rowIdx, k) => statByRow.set(rowIdx, stats[k] || null));
  const tiles = rows.map((r, i) => {
    const s = statByRow.get(i);
    return {
      lum: s && s.ok ? s.lum : null,
      sat: s && s.ok ? s.sat : null,
      hueFam: s && s.ok ? s.hueFam : null,
      hueShare: s && s.ok ? s.hueShare : null,
      media_type: r.media_type || 'image', tipo: r.tipo || '', intent: r.intent || '',
    };
  });
  const pattern = gridPattern.detectPattern(tiles);
  return {
    pattern,
    tiles: tiles.length,
    usable: pattern.usable,
    tilesDetail: tiles.map((t) => ({ lum: t.lum, hueFam: t.hueFam, type: gridPattern.typeKeyOf(t) })),
    // (v332) medición COMPLETA de la cabeza real del feed, del más nuevo al
    // más viejo: la materia prima del director de feed (familias + roles).
    tilesFull: tiles.map((t, i) => ({
      id: rows[i].id, lum: t.lum, sat: t.sat, hueFam: t.hueFam, hueShare: t.hueShare,
      media_type: t.media_type, tipo: t.tipo, intent: t.intent,
    })),
    at: new Date().toISOString(),
  };
}

// (v332) snapshots viejos no traen tilesFull: se deriva de tilesDetail
// (sin hueShare/sat — la familia cálida queda conservadora, nunca inventada).
function withTilesFull(snap) {
  if (!snap || Array.isArray(snap.tilesFull) || !Array.isArray(snap.tilesDetail)) return snap;
  snap.tilesFull = snap.tilesDetail.map((t) => ({
    id: null, lum: t.lum, sat: null, hueFam: t.hueFam, hueShare: null,
    media_type: t.type === 'video' ? 'video' : (t.type === 'carrusel' ? 'carousel' : 'image'),
    tipo: '', intent: '',
  }));
  return snap;
}

// Patrón vigente de la cuenta: caché de 6 días; si venció, se remide.
async function gridPatternFor(uid) {
  const snap = readGridSnapshot(uid);
  if (snap && snap._computedAt) {
    const t = new Date(String(snap._computedAt).replace(' ', 'T') + 'Z').getTime();
    if (Number.isFinite(t) && t > Date.now() - 6 * 86400000 && snap.pattern) return withTilesFull(snap);
  }
  const fresh = await computeGridPattern(uid);
  if (snap && snap.applied) fresh.applied = snap.applied; // la marca de aplicado sobrevive a la remedición
  try {
    db.prepare(`INSERT INTO grid_pattern_snapshots (user_id, data_json, computed_at) VALUES (?,?,datetime('now'))
      ON CONFLICT(user_id) DO UPDATE SET data_json = excluded.data_json, computed_at = excluded.computed_at`)
      .run(uid, JSON.stringify(fresh));
  } catch (e) {}
  return fresh;
}

// Marca que la tanda de `weekKey` se armó respetando el patrón, con la
// línea que el reporte semanal puede mostrar. Sin línea no hay marca.
function markGridApplied(uid, weekKey, line) {
  if (!line) return;
  try {
    const row = db.prepare('SELECT data_json FROM grid_pattern_snapshots WHERE user_id = ?').get(uid);
    if (!row) return;
    const d = JSON.parse(row.data_json || 'null');
    if (!d) return;
    d.applied = { week_key: weekKey, line, at: new Date().toISOString() };
    db.prepare('UPDATE grid_pattern_snapshots SET data_json = ? WHERE user_id = ?').run(JSON.stringify(d), uid);
  } catch (e) {}
}

// Posteos que van a salir ANTES que la tanda nueva y quedan por encima de
// la grilla vieja en el marco final: los ya programados (comprometidos) y
// los borradores feed de esta semana o anteriores (salen primero porque se
// programan por orden de creación). Solo desplaza el marco de lectura del
// patrón; no mueve ninguna fecha.
function gridAheadCount(uid, weekKey) {
  let n = 0;
  try {
    const s = db.prepare(`SELECT COUNT(*) AS n FROM posts WHERE user_id = ? AND status = 'scheduled'
      AND media_type IN ('image','carousel','video')`).get(uid);
    n += (s && s.n) || 0;
  } catch (e) {}
  try {
    const d = db.prepare(`SELECT COUNT(*) AS n FROM posts WHERE user_id = ? AND status = 'draft'
      AND media_type IN ('image','carousel') AND COALESCE(image_path, '') != ''
      AND (COALESCE(week_key, '') = '' OR week_key <= ?)`).get(uid, weekKey);
    n += (d && d.n) || 0;
  } catch (e) {}
  return n;
}

// Ocupación REAL de una semana (2026-10-15): posteos feed con imagen que ya
// ocupan la semana, por etiqueta (week_key) O por fecha de publicación
// dentro del rango lun–dom, INCLUYENDO los ya publicados. Es el mismo
// criterio que el cupo (que cuenta por scheduled_at): antes el pipeline
// contaba solo week_key + draft/scheduled, así una semana con 2 publicados
// y 1 programado (creado otra semana) le figuraba VACÍA y generaba los 5
// de más — lo vio Valentino ("quedaban 2 e hizo 5"). Un solo helper para
// que el armador, el chequeo de completitud y el cupo nunca se contradigan.
function weekOccupancyRows(uid, weekKey) {
  try {
    return db.prepare(`SELECT * FROM posts WHERE user_id = ? AND media_type IN ('image','carousel')
      AND COALESCE(image_path,'') != '' AND status IN ('draft','scheduled','published')
      AND (week_key = ? OR (scheduled_at IS NOT NULL AND date(scheduled_at) >= date(?) AND date(scheduled_at) < date(?, '+7 days')))`).all(uid, weekKey, weekKey, weekKey);
  } catch (e) { return []; }
}
// ================= DIRECCIÓN DE FEED (v332, 2026-10-22) =================
// Mandato de Valentino: "todo lo que estás aprendiendo con el feed de
// Posty, utilizalo para los feeds de nuestros clientes; tenemos que ser
// expertos en que el feed quede excelente y que combine". La semana de
// cada cliente se compone como UNA pieza contra su grilla real: medición
// (grid-stats.py, números), composición por orden (feed-director.js,
// lógica pura), compuerta de portadas para reels/video firma y registro
// por semana (tabla feed_compositions). La paleta es la del feed DEL
// CLIENTE: sus posteos recientes medidos definen el registro.
// composeWeekFeed NUNCA lanza ni bloquea: si algo falla, la semana sigue
// con el orden de siempre y el pipeline no se entera.
const { execFile: execFileFd } = require('child_process');

function videoDurationSec(file) {
  return new Promise((resolve) => {
    execFileFd('ffprobe', ['-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', file],
      { timeout: 15000 }, (err, stdout) => {
        const d = parseFloat(String(stdout || '').trim());
        resolve(Number.isFinite(d) && d > 0 ? d : 0);
      });
  });
}

// Frames candidatos de un video (el primero ≈ la portada natural de hoy:
// el pipeline saca la portada al inicio del video). Temporales: viven en
// MEDIA_DIR/.fd-frames-* y el llamador los borra al terminar.
async function extractVideoFrames(file, count) {
  const dur = await videoDurationSec(file);
  const dir = path.join(MEDIA_DIR, `.fd-frames-${process.pid}-${Date.now()}`);
  try { fs.mkdirSync(dir, { recursive: true }); } catch (e) { return null; }
  const fracs = [0.04, 0.32, 0.58, 0.84].slice(0, count || 4);
  const files = [];
  for (let i = 0; i < fracs.length; i++) {
    const t = dur > 0 ? Math.max(0.1, dur * fracs[i]) : 0.5 * (i + 1);
    const out = path.join(dir, `f${i}.jpg`);
    const ok = await new Promise((resolve) => {
      execFileFd('ffmpeg', ['-y', '-ss', String(t), '-i', file, '-frames:v', '1', '-q:v', '3', out],
        { timeout: 30000 }, (err) => resolve(!err && fs.existsSync(out)));
    });
    files.push(ok ? out : null);
  }
  if (!files.some(Boolean)) {
    try { fs.rmSync(dir, { recursive: true, force: true }); } catch (e) {}
    return null;
  }
  return { dir, files };
}

function runCoverGrade(srcAbs, outAbs, targetLum, tint) {
  return new Promise((resolve) => {
    execFileFd('python3', [path.join(__dirname, 'cover-grade.py'), srcAbs, outAbs, String(targetLum), tint || 'none'],
      { timeout: 30000 }, (err, stdout) => {
        if (err) return resolve({ ok: false });
        try {
          const j = JSON.parse(String(stdout || '').trim().split('\n').pop());
          resolve(j && j.ok ? j : { ok: false });
        } catch (e) { resolve({ ok: false }); }
      });
  });
}

async function composeWeekFeed(uid, weekKey, tag) {
  const frameTempDirs = [];
  try {
    const rows = db.prepare(`SELECT id, image_path, cover_path, media_type, tipo, intent, status, scheduled_at, created_at
      FROM posts WHERE user_id = ? AND week_key = ? AND media_type IN ('image','carousel','video')
      AND COALESCE(image_path, '') != '' AND status IN ('draft','scheduled')
      ORDER BY (status = 'scheduled') DESC, scheduled_at ASC, created_at ASC, id ASC`).all(uid, weekKey);
    if (!rows.length) return { ok: true, pieces: 0, reason: 'sin piezas' };

    // El protagonista lo marca la v330 en image_meta (el avatar/la persona
    // ES la pieza): señal de rol para la alternancia.
    const avatarIds = new Set();
    try {
      const metas = db.prepare('SELECT post_id, meta FROM image_meta WHERE user_id = ?').all(uid);
      for (const m of metas) {
        try { const j = JSON.parse(m.meta || '{}'); if (j && j.avatarProtagonist === true) avatarIds.add(m.post_id); } catch (e) {}
      }
    } catch (e) {}

    // 1) MEDICIÓN de cada pieza candidata (números, nunca a ojo).
    const pieces = [];
    for (const r of rows) {
      const piece = {
        id: r.id, media_type: r.media_type || 'image', tipo: r.tipo || '', intent: r.intent || '',
        fixed: r.status === 'scheduled', avatarProtagonist: avatarIds.has(r.id),
        lum: null, sat: null, hueFam: null, hueShare: null, _frames: null, _prevCover: r.cover_path || '',
      };
      const imgAbs = path.join(MEDIA_DIR, path.basename(String(r.image_path || '')));
      const coverAbs = r.cover_path ? path.join(MEDIA_DIR, path.basename(String(r.cover_path))) : null;
      const isVidFile = /\.(mp4|mov|webm)$/i.test(String(r.image_path || ''));
      if (piece.media_type === 'video' && isVidFile && fs.existsSync(imgAbs)) {
        const fr = await extractVideoFrames(imgAbs, 4);
        if (fr) {
          frameTempDirs.push(fr.dir);
          const realFiles = fr.files.filter(Boolean);
          const stats = realFiles.length ? await runGridStats(realFiles) : [];
          const statByFile = new Map();
          realFiles.forEach((f, k) => statByFile.set(f, stats[k]));
          piece._frames = fr.files.map((f) => {
            const st = f ? statByFile.get(f) : null;
            return {
              file: f,
              lum: st && st.ok ? st.lum : null, sat: st && st.ok ? st.sat : null,
              hueFam: st && st.ok ? st.hueFam : null, hueShare: st && st.ok ? st.hueShare : null,
            };
          });
          const nat = piece._frames[0];
          if (nat && nat.lum != null) {
            piece.lum = nat.lum; piece.sat = nat.sat; piece.hueFam = nat.hueFam; piece.hueShare = nat.hueShare;
          }
        }
      }
      if (piece.lum == null) {
        const cand = (coverAbs && fs.existsSync(coverAbs)) ? coverAbs : (fs.existsSync(imgAbs) ? imgAbs : null);
        if (cand) {
          const st = (await runGridStats([cand]))[0];
          if (st && st.ok) { piece.lum = st.lum; piece.sat = st.sat; piece.hueFam = st.hueFam; piece.hueShare = st.hueShare; }
        }
      }
      pieces.push(piece);
    }

    // La grilla real del cliente: cabeza medida + patrón vigente (v224).
    const g = await gridPatternFor(uid);
    const existing = (g && Array.isArray(g.tilesFull)) ? g.tilesFull : [];
    const pattern = g && g.pattern ? g.pattern : null;
    let ahead = 0;
    try { ahead = Math.max(0, gridAheadCount(uid, weekKey) - rows.length); } catch (e) {}

    // 2) COMPOSICIÓN POR ORDEN (lógica pura del director).
    const res = feedDirector.composeOrder({ pieces, existing, pattern, ahead });
    const asgByIx = new Map(res.assignments.map((a) => [a.idx, a]));

    // 3) COMPUERTA DE PORTADAS: la portada es la superficie que toca la
    // grilla. Frame natural si ya combina; otro frame del mismo video si
    // combina; si no, el GRADO va solo sobre el archivo de portada
    // (posts.cover_path) — el video jamás se toca.
    for (let ix = 0; ix < pieces.length; ix++) {
      const piece = pieces[ix];
      if (!piece._frames) continue;
      const asg = asgByIx.get(ix);
      const want = asg ? asg.family : feedDirector.familyOf(piece);
      const gate = feedDirector.coverGate({ frames: piece._frames, wantFamily: want });
      let coverPath = '';
      let graded = null;
      if ((gate.action === 'alt-frame' || gate.action === 'grade') && piece._frames[gate.frameIx] && piece._frames[gate.frameIx].file) {
        const srcF = piece._frames[gate.frameIx].file;
        const destName = `feedcover-${piece.id}.jpg`;
        const destAbs = path.join(MEDIA_DIR, destName);
        if (gate.action === 'grade') {
          const gr = await runCoverGrade(srcF, destAbs, gate.targetLum, want === feedDirector.FAMILY.DARK ? 'navy' : 'none');
          if (gr.ok) { coverPath = '/media/' + destName; graded = { lumBefore: gr.lumBefore, lumAfter: gr.lumAfter }; }
        } else {
          try { fs.copyFileSync(srcF, destAbs); coverPath = '/media/' + destName; } catch (e) {}
        }
      }
      const decision = {
        action: gate.action, frameIx: gate.frameIx, wantFamily: want,
        targetLum: gate.targetLum || null, graded, reason: gate.reason, coverPath,
      };
      try { db.prepare('UPDATE posts SET cover_path = ? WHERE id = ?').run(coverPath, piece.id); } catch (e) {}
      if (piece._prevCover && piece._prevCover !== coverPath && piece._prevCover.indexOf('/media/feedcover-') === 0) {
        try { fs.unlinkSync(path.join(MEDIA_DIR, path.basename(piece._prevCover))); } catch (e) {}
      }
      piece._coverDecision = decision;
    }

    // 4) REGISTRO de la composición de la semana (familia asignada y por
    // qué cada pieza va en su lugar; las que pelean quedan marcadas).
    const record = {
      v: 1, uid, weekKey, at: new Date().toISOString(),
      pattern: pattern ? {
        has: !!pattern.has, checker: !!pattern.checker,
        columns: pattern.columns ? [0, 1, 2].map((c) => (pattern.columns[c] && pattern.columns[c].tone) || null) : null,
      } : null,
      ahead,
      existingHead: existing.slice(0, 6).map((t) => ({
        id: t.id != null ? t.id : null, lum: t.lum, sat: t.sat, hueFam: t.hueFam,
        family: feedDirector.familyOf(t), media_type: t.media_type,
      })),
      beforeOrder: rows.map((r) => r.id),
      order: res.order.map((ix) => pieces[ix].id),
      assignments: res.assignments.map((a) => ({
        postId: pieces[a.idx].id, pubRank: a.pubRank, family: a.family, role: a.role,
        fixed: !!pieces[a.idx].fixed, why: a.why,
        cover: pieces[a.idx]._coverDecision || null,
      })),
      flags: res.flags.map((f) => ({ postId: pieces[f.idx].id, reasons: f.reasons })),
      remainingViolations: res.remainingViolations,
      moves: res.moves,
    };
    try {
      db.prepare(`INSERT INTO feed_compositions (user_id, week_key, data_json) VALUES (?,?,?)
        ON CONFLICT(user_id, week_key) DO UPDATE SET data_json = excluded.data_json, created_at = datetime('now')`)
        .run(uid, weekKey, JSON.stringify(record));
    } catch (e) {}
    console.log(`[feed-dir:${tag || 'auto'}] usuario ${uid} semana ${weekKey}: ${pieces.length} piezas compuestas contra su grilla (${res.moves} movimientos, ${record.flags.length} marcadas)`);
    return { ok: true, pieces: pieces.length, moves: res.moves, flags: record.flags.length, record };
  } catch (e) {
    console.error(`[feed-dir] usuario ${uid} semana ${weekKey}:`, e && e.message);
    return { ok: false, error: e && e.message };
  } finally {
    for (const d of frameTempDirs) { try { fs.rmSync(d, { recursive: true, force: true }); } catch (e) {} }
  }
}

async function generateWeekDrafts(uid, { weekKey, tag, quiet }) {
  // Kill-switch diario también para el pipeline en segundo plano: se aborta en
  // silencio (el usuario lo reintenta mañana; nada se rompe).
  try { costs.assertAiOk(uid); }
  catch (e) { console.error(`[pipeline:${tag}] kill-switch, skip usuario ${uid}`); return { ok: false, reason: 'ai_cap' }; }
  // Gate de plan REAL (2026-10-16, paywall sincero): el cartel "necesitás
  // un plan activo" no tenía bloqueo propio detrás — dependía de que cada
  // llamador filtrara. Defensa en profundidad en la entrada del pipeline:
  // genera el fundador, un plan activo o un trial vigente; nadie más. La
  // misma regla que comunica el cartel, ahora también en el servidor.
  try {
    let founderGate = false;
    try { founderGate = !!(costs.isFounderEmail && costs.isFounderEmail(uid)); } catch (e) {}
    if (!founderGate && !planOrTrialOk(uid)) {
      console.log(`[pipeline:${tag}] usuario ${uid}: sin plan ni trial vigente — no se genera`);
      return { ok: false, reason: 'no_plan', created: 0 };
    }
  } catch (e) { /* el gate es defensa en profundidad: si la lectura falla, no bloquea */ }
  if (nextweekRunningFresh(uid)) { console.log(`[pipeline:${tag}] usuario ${uid}: ya hay una corrida en curso, skip`); return { ok: false, reason: 'running' }; }
  NEXTWEEK_RUNNING.set(uid, Date.now());
  // 2026-10-14: SEMANA PARCIAL (pedido de Valentino) — la semana se completa
  // sola hasta el objetivo del plan. Antes, con que existiera 1 posteo el
  // guard devolvía 'already_exists' y la semana quedaba incompleta para
  // siempre. Ahora: existing >= objetivo → completa; 0 < existing <
  // objetivo → se genera SOLO el déficit; existing = 0 → como siempre.
  let ppw = 3, existing = 0, deficit = 0;
  try {
    try {
      const u0 = db.prepare('SELECT plan, plan_status FROM users WHERE id = ?').get(uid) || {};
      ppw = (getPlan(u0.plan_status === 'active' ? u0.plan : TRIAL_PLAN).postsPerWeek) || 3;
    } catch (e) {}
    try {
      // Solo feed (image/carousel): historias y reels tienen su propio cupo
      // y no cuentan para el objetivo de posteos de la semana. Criterio de
      // ocupación unificado (weekOccupancyRows): incluye publicados y los
      // programados para esta semana aunque se hayan creado en otra.
      existing = weekOccupancyRows(uid, weekKey).length;
    } catch (e) { /* sin datos: existing=0, generación completa */ }
    if (existing >= ppw) return { ok: true, reason: 'already_complete', created: 0, existing };
    deficit = ppw - existing;
    if (existing === 0) {
      // Limpiar posteos fallidos de esta semana para empezar de cero. (Solo
      // desde cero: en modo completar, los fallidos quedan visibles para que
      // el usuario los reintente.)
      try {
        const del = db.prepare(`DELETE FROM posts WHERE user_id = ? AND week_key = ? AND status = 'failed'`).run(uid, weekKey);
        if (del.changes > 0) console.log(`[pipeline:${tag}] usuario ${uid}: ${del.changes} posteos fallidos limpiados`);
      } catch (e) {}
    } else {
      console.log(`[pipeline:${tag}] usuario ${uid}: semana parcial ${existing}/${ppw} — completando ${deficit}`);
    }
    // Gate de ADN "no generar a ciegas" (mismo umbral que /api/ideas).
    const profile = getProfile(uid);
    const dna = readDna(uid);
    const descOk = (profile.description || '').trim().length >= 20;
    const dnaOk = (dna.producto_estrella || '').trim().length >= 3;
    if (!descOk && !dnaOk) { console.log(`[pipeline:${tag}] usuario ${uid}: sin ADN mínimo, no se genera a ciegas`); return { ok: false, reason: 'no_dna' }; }
    const key = openaiKeyFor(uid);
    // Resiliencia (2026-10-05): si la generación de ideas tira (IA caída,
    // saldo 0, input inesperado), NO propagar la excepción al sweep: devolver
    // fallo estructurado para que se registre y se reintente con backoff.
    let ideas;
    try { ideas = await generateIdeas(ideasInputFor(uid), key, { strict: true }); }
    catch (e) { console.error(`[pipeline:${tag}] ideas falló:`, e.message); return { ok: false, reason: 'ai_error', error: e.message }; }
    // 2026-10-14: en modo completar, no repetir temas que la semana ya
    // tiene y traer 2 ideas extra de buffer por si alguna imagen falla
    // (el cupo exacto lo garantiza el claim de slots del worker).
    let pool = ideas;
    if (existing > 0) {
      try {
        const rows = weekOccupancyRows(uid, weekKey);
        const seen = new Set(rows.map(r => String(r.source_topic || '').trim().toLowerCase()).filter(Boolean));
        pool = ideas.filter(id => !seen.has(String(id.titulo || '').trim().toLowerCase()));
      } catch (e) {}
    }
    // Pool corto (2026-10-15): si las ideas no alcanzan para el déficit
    // (+buffer), UNA regeneración y fusión sin repetir títulos. Sin esto,
    // una respuesta corta de la IA dejaba la semana incompleta en silencio.
    if (pool.length < deficit + 2) {
      try {
        const more = await generateIdeas(ideasInputFor(uid), key, { strict: true });
        const have = new Set(pool.map(i => String(i.titulo || '').trim().toLowerCase()));
        for (const m of more) { const t = String(m.titulo || '').trim().toLowerCase(); if (t && !have.has(t)) { pool.push(m); have.add(t); } }
        console.log(`[pipeline:${tag}] usuario ${uid}: pool de ideas reforzado → ${pool.length}`);
      } catch (e) { console.error(`[pipeline:${tag}] refuerzo de ideas falló:`, e.message); }
    }
    const picks = pool.slice(0, deficit + 2);
    if (!picks.length) return { ok: false, reason: 'no_ideas' };
    // 🎯 CUOTAS DE INTENCIÓN (v231, adopción Predis): si la ventana sale
    // degenerada (toda venta, o toda una sola intención), se canjean
    // picks de la ventana por picks del buffer YA generado — cero IA
    // extra. Antes del equilibrio de grilla y del plan de texto.
    try {
      const rb = cleanPieces.rebalanceIntentPicks(picks, deficit);
      if (rb.swapped) {
        picks.splice(0, picks.length, ...rb.picks);
        const mix = cleanPieces.intentMixOf(picks.slice(0, deficit));
        console.log(`[pipeline:${tag}] usuario ${uid}: intención reequilibrada (${rb.swapped} canjes) — valor ${mix.valor} / comunidad ${mix.comunidad} / venta ${mix.venta}`);
      }
    } catch (e) { console.error(`[pipeline:${tag}] rebalance de intención falló:`, e.message); }
    // 🧠 CEREBRO COMERCIAL (v232): sobre el mix ya saneado, cada pick
    // recibe su intención de VENTA + ángulo + prueba desde el digest
    // (las cuotas salen del negocio: reservas si toma turnos, venta
    // anclada a su estrella, escasez solo con dato; sin prueba, la
    // pieza se degrada a autoridad en vez de vender humo). Mismo canje
    // ventana/buffer de v231, cero IA extra. Viaja en idea._sales y se
    // persiste en posts.sales_intent / posts.sales_angle.
    let salesStats = null;
    try {
      const digest = digestForUser(uid);
      if (digest) {
        const ang = anglePerformanceFor(uid);
        const sp = salesBrain.planSalesWeek(picks, deficit, digest, {
          angleScores: ang.scores,
          objections: mineObjectionsFor(uid),
        });
        picks.splice(0, picks.length, ...sp.picks);
        salesStats = sp.stats;
        const m = sp.stats.mix;
        console.log(`[pipeline:${tag}] usuario ${uid}: cerebro comercial — venta ${m.venta} / reserva ${m.reserva} / consulta ${m.consulta} / prueba ${m.prueba} / autoridad ${m.autoridad}${sp.stats.degraded ? ` (${sp.stats.degraded} degradadas sin prueba)` : ''}${sp.swapped ? ` (${sp.swapped} canjes)` : ''}`);
      }
    } catch (e) { console.error(`[pipeline:${tag}] cerebro comercial falló:`, e.message); }
    // (v234) SELECCIÓN QUE SABE: el perfil de feed de la semana (línea
    // de feed desde el digest — registro + paleta con roles — más el
    // patrón de grilla cuando el bloque de abajo lo computa) viaja a
    // cada pre-pick de estilo: un preset que rompe la línea del feed
    // queda fuera ANTES del score.
    let weekFeedProfile = null;
    // 🧩 EQUILIBRIO DE GRILLA (v224): si la grilla del cliente tiene un
    // patrón fuerte, la tanda se ORDENA por posición (el tipo de cada idea
    // calza con la columna donde va a caer) y cada idea lleva su consigna
    // tonal de posición (_gridNote), que viaja a la dirección de arte como
    // registro — subordinada al tema, al rol de escena y a la paleta.
    // Sin patrón: picks intactos, comportamiento de siempre.
    let gridAppliedLine = '';
    try {
      const gSnap = await gridPatternFor(uid);
      const gPat = gSnap && gSnap.pattern;
      if (gPat && gPat.has) {
        const ahead = gridAheadCount(uid, weekKey);
        const shift = deficit + ahead;
        const typeKeyOfPick = (p) => {
          try {
            const ri = resolveExplicitIntent({ tipo: p.tipo || '', theme: p.titulo || '', angle: p.angulo || p.porque || '' });
            if (ri.intent === 'tips' || ri.intent === 'educativo') return 'carrusel';
            return ri.intent || p.tipo || 'foto';
          } catch (e) { return p.tipo || 'foto'; }
        };
        const plan = gridPattern.planBatch(gPat, picks, deficit, shift, typeKeyOfPick);
        if (plan.moved > 0) {
          const ordered = plan.order.map((ix) => picks[ix]);
          picks.splice(0, picks.length, ...ordered);
          console.log(`[pipeline:${tag}] usuario ${uid}: equilibrio de grilla — tanda reordenada por posición (${plan.moved} ideas movidas)`);
        }
        plan.targets.forEach((t, i) => {
          const note = gridPattern.noteForTarget(t);
          if (note && picks[i]) picks[i]._gridNote = note;
        });
        gridAppliedLine = gridPattern.reportLine(gPat, shift);
        // (v234) El patrón de grilla también alimenta el perfil de
        // feed del dataset de selección (columnas con tono consistente
        // = línea de feed consolidada).
        try {
          const fp = require('./image-styles').feedProfileFromDigest(digestForUser(uid), { gridPattern: gPat });
          if (fp) weekFeedProfile = fp;
        } catch (e) {}
      }
    } catch (e) { console.error(`[pipeline:${tag}] equilibrio de grilla:`, e.message); }
    // 🧹 LIMPIEZA (2026-10-18): dosificación 2-de-5 TAMBIÉN en clientes —
    // hasta hoy el 100% de las piezas salía con titular y la regla vivía
    // solo en el demo. Con los picks ya ordenados (equilibrio incluido),
    // cada pick lleva su modo: 'text' (titular compuesto como siempre) o
    // 'clean' (sin titular hacia la generación; el caption cierra con
    // CTA). El pick del carousel queda exento de la cuenta (planWeekTextModes).
    try {
      const tm = planWeekTextModes(picks, deficit);
      picks.forEach((p, ix) => { p._textMode = tm.modes[ix] || 'text'; });
      const nText = picks.slice(0, deficit).filter((p) => p._textMode === 'text').length;
      console.log(`[pipeline:${tag}] usuario ${uid}: limpieza — ${nText} con texto / ${Math.max(0, deficit - nText)} limpias en la tanda${tm.carouselIdx >= 0 ? ` (carousel exento: pick ${tm.carouselIdx})` : ''}`);
    } catch (e) { console.error(`[pipeline:${tag}] limpieza (dosificación):`, e.message); }
    const dupStmt = db.prepare(`SELECT id FROM posts WHERE user_id = ? AND status != 'cancelled' AND LOWER(TRIM(caption)) = LOWER(?) AND created_at > datetime('now', '-1 day')`);
    const insStmt = db.prepare(`INSERT INTO posts (user_id, image_path, caption, hashtags, status, media_type, source_topic, source_angle, tipo, strategy_why, week_key, needs_review, style_code, style_reason, intent, product_ref, hook_id, image_prompt, sales_intent, sales_angle) VALUES (?,?,?,?, 'draft','image',?,?,?,?,?,?,?,?,?,?,?,?,?,?)`);
    // FASE 1: la escalera de confianza decide la revisión — nivel 0 pasa por
    // revisión humana; nivel ≥1 sale directo (el qualityGate de Fase 0 en
    // scheduleAllDrafts ya filtra lo que no está a la altura).
    // 2026-10-07: el fundador nunca pasa por revisión (sus posteos se
    // ocultaban por needs_review=1 y el /api/posts los filtraba — causa raíz
    // del "armando tu semana" eterno de Valentino).
    let isFounder = false;
    try { isFounder = !!(costs.isFounderEmail && costs.isFounderEmail(uid)); } catch (e) {}
    const needRev = (!isFounder && autopilot.trustLevel(db, uid) === 0) ? 1 : 0;
    let created = 0;
    // 🧹 Vigilancia de limpieza: modos y largos de caption de ESTA corrida,
    // medibles contra la línea de base del 2026-10-18 (100% de piezas con
    // texto; captions de 293-490 caracteres).
    const runCleanStats = { text: 0, clean: 0, carousel: 0, capLens: [] };
    // (v229) Vigilancia de pertenencia: piezas de ESTA corrida con ancla
    // del digest vs sin ancla (la exención de marca/comunidad admite 1).
    const belongStats = { anchored: 0, unanchored: 0 };
    let imgFailCount = 0; // ideas saltadas por fallo de imagen IA (nunca se crea un bloque plano)
    let firstImgError = ''; // 2026-10-14: primer error de imagen, para diagnóstico visible (last-result)
    // Contabilidad por slot (2026-10-15): cada slot que no produce posteo
    // registra su motivo. La prueba de rubros mostró semanas de 3/5 con
    // ok:true y ninguna explicación: eso no vuelve a pasar — el resultado
    // de la corrida lleva slotFails y el primer error de cada clase.
    const slotFails = { img: 0, dup: 0, content: 0, other: 0 };
    const slotErrs = {};
    function noteSlotFail(cls, err) {
      slotFails[cls] = (slotFails[cls] || 0) + 1;
      if (err && !slotErrs[cls]) slotErrs[cls] = String((err && err.message) || err).slice(0, 200);
    }
    // Estilos de imagen: un solo tracker por semana para no repetir estilo
    // entre borradores (lo comparten los 5 workers del pool).
    // (v233) + tracker de FAMILIAS de dirección (la variedad semanal es
    // de gramática visual, no solo de preset) y los insumos del pick
    // consciente: digest del cliente, favoritos y boosts de aprendizaje
    // se resuelven UNA vez por corrida, no por posteo.
    const usedFamilies = [];
    const weekDigest = (() => { try { return digestForUser(uid); } catch (e) { return null; } })();
    const weekFavorites = (() => { try { return getStyleFavorites(uid); } catch (e) { return []; } })();
    const weekBoosts = (() => { try { return require('./learning').getClientBoosts(db, uid) || {}; } catch (e) { return {}; } })();
    const usedStyles = [];
    // (v234) Sin patrón de grilla, el perfil de feed sale del digest solo.
    if (!weekFeedProfile) { try { weekFeedProfile = require('./image-styles').feedProfileFromDigest(weekDigest); } catch (e) { weekFeedProfile = null; } }
    // Director de semana: cada posteo cumple un ROL DE ESCENA distinto para
    // que la semana se vea diseñada (variada), no generada en serie. La
    // rotación arranca en un punto distinto cada semana (hash de weekKey).
    const SCENE_ROLES = [
      'la PERSONA en acción — el momento humano: manos trabajando, el oficio en vivo, alguien usando el producto',
      'el PRODUCTO protagonista — el héroe del negocio en primer plano, irresistible',
      'el LUGAR — el local con su ambiente y su vida, como invitando a entrar',
      'el DETALLE en primer plano — textura, material, cercanía que da ganas de tocar',
      'DETRÁS DE ESCENA — el equipo trabajando, el proceso, lo que el cliente nunca ve',
    ];
    let sceneRoleIdx = 0;
    for (const ch of String(weekKey || '')) sceneRoleIdx += ch.charCodeAt(0);
    sceneRoleIdx = sceneRoleIdx % SCENE_ROLES.length;
    const nextSceneRole = () => SCENE_ROLES[(sceneRoleIdx++) % SCENE_ROLES.length];
    // Pool de 3 en paralelo (igual que el autopilot del browser).
    let nextIdx = 0;
    // Cupo exacto de slots: en modo completar NUNCA crear más que el déficit
    // (claim sincrónico entre workers; se libera si ese slot falla, así otra
    // idea del buffer puede ocuparlo en la misma corrida).
    const cap = deficit;
    let claimed = 0;
    // Guarda final anti-sobrecreación (2026-10-15, pedido de Valentino:
    // "si quedan 2, que se generen 2 nomás"): además del claim exacto de
    // slots, antes de guardar cada posteo se RECUENTA la ocupación real de
    // la semana (weekOccupancyRows + los creados por esta corrida). Si el
    // cupo se completó mientras tanto (el usuario aceptó/programó a mano u
    // otra corrida), el slot no se guarda y los workers se detienen. Como
    // entre el insert y created++ no hay awaits (JS single-thread), la suma
    // ocupación+created es siempre consistente: crear más que el déficit
    // es imposible.
    let weekFullStop = false;
    // IDs de los posteos creados por ESTA corrida: la guarda los excluye
    // de la ocupación en vivo (si no, cada posteo cuenta doble —ocupación
    // + created— y la semana se frenaba en 3 de 5; bug v123 detectado por
    // la prueba de rubros del 2026-10-15).
    const runCreatedIds = new Set();
    function weekFullNow() {
      try {
        const external = weekOccupancyRows(uid, weekKey).filter(r => !runCreatedIds.has(r.id)).length;
        return external + created >= ppw;
      } catch (e) { return false; }
    }
    // Carousel automático: como máximo 1 por semana, para la idea más
    // carousel-friendly (tips/educativo). El claim es sincrónico: sin race
    // entre los 3 workers.
    let carouselClaimed = false;
    // Reference lock: la primera foto de producto de la semana (si ya existe)
    // viaja como referencia para que el producto se vea idéntico en todos
    // los posteos. Se resuelve por worker justo antes de generar.
    function weekProductRef() {
      try {
        const r = db.prepare(`SELECT image_path FROM posts WHERE user_id = ? AND week_key = ?
          AND intent = 'producto' AND image_path LIKE '/media/%' AND status != 'cancelled'
          ORDER BY id ASC LIMIT 1`).get(uid, weekKey);
        const p = r && String(r.image_path || '');
        if (p) { try { return fs.existsSync(path.join(MEDIA_DIR, path.basename(p))) ? p : null; } catch (e) { return null; } }
      } catch (e) {}
      return null;
    }
    async function worker() {
      while (true) {
        if (weekFullStop) return;
        const i = nextIdx++;
        if (i >= picks.length) return;
        if (claimed >= cap) return;
        if (weekFullNow()) { weekFullStop = true; return; }
        claimed++;
        const idea = picks[i];
        // 🧠 (v232) La decisión comercial de la pieza (si el cerebro la
        // planificó): viaja al prompt de captions y queda persistida.
        const salesIntent = (idea._sales && idea._sales.intent) || '';
        const salesAngle = (idea._sales && idea._sales.angle) || '';
        let isCarousel = false;
        let pendingId = null; // tarjeta inmediata (se crea más abajo, tras el texto)
        try {
          const ri = resolveExplicitIntent({ tipo: idea.tipo || '', theme: idea.titulo || '', angle: idea.angulo || idea.porque || '' });
          if (!carouselClaimed && (ri.intent === 'tips' || ri.intent === 'educativo')) { carouselClaimed = true; isCarousel = true; }
        } catch (e) {}
        try {
          const content = await generateContent(contentInputFor(uid, idea.titulo, idea.tipo, i, idea._sales), key);
          let caption = String((content && content.caption) || '').trim();
          const hashtags = String((content && content.hashtags) || '');
          if (!caption) throw new Error('caption vacío');
          recordHookUse(uid, content && content.hookId); // hook engine: rotación 8 semanas
          // 🧹 Pieza LIMPIA (dosificación 2-de-5): sin titular en la
          // imagen — la idea y el CTA viven en el caption, que CIERRA
          // con el CTA (ensureCaptionCtaClose, el mismo del demo).
          const cleanPiece = !isCarousel && idea._textMode === 'clean';
          if (cleanPiece) {
            // 🧠 (v232) Pieza con intención declarada: cierra según la
            // intención de venta, no solo según el kind.
            try {
              if (salesIntent && demo.ensureCaptionCloseForIntent) caption = demo.ensureCaptionCloseForIntent(caption, salesIntent, (profile && profile.tone) || '');
              else caption = demo.ensureCaptionCtaClose(caption, kindOfTipo(idea.tipo), (profile && profile.tone) || '');
            } catch (e) {}
          }
          // Anti-duplicados 24h (mismo criterio que POST /api/posts).
          if (dupStmt.get(uid, caption)) { console.log(`[pipeline:${tag}] duplicado 24h, skip: ${idea.titulo}`); noteSlotFail('dup', 'caption duplicado en 24h'); claimed--; continue; }
          // Titular COMPLETO para la imagen (makeHeadline: jamás cortado a mitad de oración).
          // Pieza limpia: headline vacío — la generación no reserva zona
          // de titular, no se compone titular y el salvavidas stock
          // tampoco lo pinta (ambos miran este mismo valor).
          const headline = cleanPiece ? ''
            : (makeHeadline(caption.split('\n')[0], 6, 70, (profile && profile.category) || null)
              || makeHeadline(idea.titulo, 5, 70, (profile && profile.category) || null));
          let refs = [];
          // (v237) Selección de fotos del álbum POR PIEZA (albumRefsForPiece):
          // la foto mapeada al ítem de la pieza (rol 'product') manda,
          // después el tag que la pieza pide, y la recencia solo
          // desempata. (Reemplaza el "las 2 más recientes" + merge
          // manual de v230/v231, que quedan dentro del selector.)
          let refRolesForRefs = null;
          try {
            const picked = albumRefsForPiece(uid, { tipo: idea.tipo, texts: [idea.titulo, caption.split('\n')[0]].filter(Boolean).join(' ') });
            refs = picked.refs;
            refRolesForRefs = picked.roles.length ? picked.roles : null;
          } catch (e) {}
          // 2026-10-14: TARJETA INMEDIATA (pedido de Valentino) — el borrador
          // nace AHORA con su texto y sin imagen: la tarjeta aparece en la
          // app en segundos ("creando imagen…") y la imagen se completa en
          // la MISMA fila cuando llega. Si la imagen falla tras los
          // reintentos, la fila se borra: nunca persiste un posteo sin
          // imagen real (la invariante de siempre).
          if (!isCarousel) {
            try {
              const info = insStmt.run(uid, '', caption, hashtags, idea.titulo || '', idea.angulo || '', idea.tipo || '', String(idea.porque || '').slice(0, 500), weekKey, needRev, '', '', '', '', String((content && content.hookId) || ''), '', salesIntent, salesAngle);
              pendingId = info && info.lastInsertRowid;
              if (pendingId) { runCreatedIds.add(pendingId); stampPostDigest(pendingId, uid, content && content._anchored === false); }
            } catch (e) { console.error(`[pipeline:${tag}] tarjeta inmediata falló:`, e.message); }
          }
          // INVARIANTE: todo borrador sale con imagen real de IA, nunca solo
          // palabras y nunca un bloque plano. Si la IA falla tras los
          // reintentos, la idea se salta (no se crea el borrador).
          const styleOut = {};
          const genOut = {}; // (v239) veredictos de QA (personaje/fidelidad) de ESTA pieza
          let imagePath = null;
          let carouselGen = null;
          // Reference lock: la primera foto de producto de la semana viaja como
          // referencia para que el producto se vea idéntico en todos los posteos.
          const productRef = weekProductRef();
          if (isCarousel) {
            // Carousel automático: portada scroll-stop + 3 placas IA.
            try {
              carouselGen = await generateCarouselSet({
                uid, idea: { titulo: idea.titulo, porque: idea.porque || idea.angulo },
                tipo: idea.tipo, caption, key, usedStyles, usedFamilies,
              });
              console.log(`[pipeline:${tag}] carousel para "${idea.titulo || i}": ${carouselGen.slidePaths.length} placas`);
            } catch (e) {
              console.error(`[pipeline:${tag}] carousel falló, caigo a imagen simple:`, e.message);
              carouselGen = null; isCarousel = false;
            }
          }
          if (!isCarousel) {
          // (v233) EL PRESET NACE CON LA IDEA: el estilo se pre-elige
          // ACÁ — con el digest del cliente (match léxico contra sus
          // productos reales), la memoria de la semana (sin repetir
          // código ni familia) y los favoritos/boosts — y viaja como
          // `style` fijo de la idea: adentro, el brief de arte se
          // escribe sabiendo qué dirección se aplicará y los 3
          // reintentos usan el MISMO preset. La reserva en
          // usedStyles/usedFamilies es inmediata (sincrónica): los
          // workers vecinos ya ven el estilo como tomado.
          let preStyleCode = null;
          try {
            const pk = pickStyle({
              intent: resolveExplicitIntent({ tipo: idea.tipo || '', theme: idea.titulo || '', angle: idea.angulo || idea.porque || '' }).intent, tipo: idea.tipo || '', theme: idea.titulo || '', angle: idea.angulo || idea.porque || '',
              rubro: (profile && profile.category) || '', subrubro: (weekDigest && weekDigest.subcat) || (profile && profile.subrubro) || '', businessName: (profile && profile.business_name) || '',
              usedThisWeek: usedStyles, boosts: weekBoosts, favorites: weekFavorites,
              digest: weekDigest, avoidFamilies: usedFamilies,
              // (v234) La intención de VENTA de la pieza (cerebro
              // comercial, idea._sales) y el perfil de feed de la
              // semana entran al pick: el preset tiene que servir a
              // lo que la pieza vende y no romper la línea del feed.
              salesIntent: (idea._sales && idea._sales.intent) || '',
              feedProfile: weekFeedProfile,
            });
            if (pk && pk.style) {
              preStyleCode = pk.style.code;
              if (!usedStyles.includes(preStyleCode)) usedStyles.push(preStyleCode);
              const fam = pk.family || (() => { try { return require('./image-styles').styleFamilyOf(pk.style); } catch (e) { return ''; } })();
              if (fam && !usedFamilies.includes(fam)) usedFamilies.push(fam);
              console.log(`[pipeline:${tag}] preset de "${idea.titulo || i}": ${preStyleCode} — ${pk.reason}`);
            }
          } catch (e) { console.error(`[pipeline:${tag}] pre-pick de estilo falló:`, e.message); }
          // Reintentos de imagen IA (2026-10-06, Valentino): un bloque plano
          // NUNCA se muestra como posteo terminado. Hasta 3 intentos con
          // backoff corto antes de saltar la idea.
          for (let attempt = 0; attempt < 3 && !imagePath; attempt++) {
          try {
            imagePath = await conceptShotGenerateQueued({
              uid, idea: { titulo: idea.titulo, porque: idea.porque || idea.angulo }, tipo: idea.tipo, headline, refs, refRoles: refRolesForRefs, apiKey: key,
              style: preStyleCode, usedStyles, usedFamilies, styleOut, resultOut: genOut, productRef, sceneRole: nextSceneRole(), gridNote: idea._gridNote || '',
            });
          } catch (e) {
            if (!firstImgError) firstImgError = String((e && e.message) || e).slice(0, 300);
            console.error(`[pipeline:${tag}] IA imagen falló (intento ${attempt + 1}/3):`, e.message);
            if (attempt < 2) await new Promise(r => setTimeout(r, 4000 * (attempt + 1)));
          }
          }
          }
          let finalCode = String(styleOut.code || ''), finalReason = String(styleOut.reason || ''), finalIntent = String(styleOut.intent || '');
          const finalProductRef = String(productRef || '');
          const finalHookId = String((content && content.hookId) || '');
          if (!isCarousel) {
          // Sin fallback plano (2026-10-06, Valentino): si la IA no generó
          // imagen tras los reintentos, NO se crea el borrador. La semana
          // queda con menos posteos reales antes que mostrar un bloque de
          // color como terminado. El retry del sweep (cada 3h) + backfill
          // (8:00) + ensure al abrir reintentan la semana.
          if (!imagePath) {
            // SALVAVIDAS STOCK (2026-10-17, pedido de Valentino): antes de
            // perder el posteo, una foto real curada del rubro con el
            // titular compuesto — foto real, jamás un bloque plano. Pasa
            // por la misma QA de siempre: si no pega con el tema, la
            // auditoría lo marca como cualquier otra imagen.
            try {
              const { pickStockPhoto } = require('./stock');
              const stockAbs = pickStockPhoto(profile && profile.category, `${uid}:${weekKey}:${idea.titulo || i}`);
              if (stockAbs) {
                const sName = `stock-${Date.now()}-${Math.random().toString(36).slice(2, 8)}.jpg`;
                const sPath = path.join(MEDIA_DIR, sName);
                fs.copyFileSync(stockAbs, sPath);
                // Normalizar a 4:5 (1080x1350) como las imágenes IA: el
                // stock viene en otros aspectos y IG recorta el feed a 4:5.
                try {
                  const { execFileSync } = require('child_process');
                  const tmpP = sPath + '.tmp.jpg';
                  execFileSync('ffmpeg', ['-y', '-v', 'error', '-i', sPath, '-vf', "crop='min(iw,ih*0.8)':'min(ih,iw/0.8)',scale=1080:1350", tmpP], { timeout: 20000 });
                  fs.renameSync(tmpP, sPath);
                } catch (e) { /* sin ffmpeg sigue la foto original */ }
                if (headline) {
                  try {
                    const { execFileSync } = require('child_process');
                    const cArgs = [path.join(__dirname, 'composite-headline.py'), '--in', sPath, '--headline', headline, '--out', sPath];
                    try {
                      const bc = JSON.parse((db.prepare('SELECT brand_colors FROM settings WHERE user_id = ?').get(uid) || {}).brand_colors || '[]');
                      if (Array.isArray(bc) && /^#[0-9a-fA-F]{6}$/.test(bc[0] || '')) cArgs.push('--grade', String(bc[0]));
                    } catch (e) {}
                    execFileSync('python3', cArgs, { timeout: 30000 });
                  } catch (e) { console.error(`[pipeline:${tag}] composite stock falló:`, e.message); }
                }
                makeVariantsAsync(sPath);
                imagePath = `/media/${sName}`;
                if (pendingId) { try { db.prepare("UPDATE posts SET source = 'stock' WHERE id = ?").run(pendingId); } catch (e) {} }
                console.log(`[pipeline:${tag}] posteo rescatado con foto stock del rubro (${(profile && profile.category) || '?'})`);
              }
            } catch (e) { console.error(`[pipeline:${tag}] salvavidas stock falló:`, e.message); }
          }
          if (!imagePath) {
            console.error(`[pipeline:${tag}] "${idea.titulo || i}": sin imagen IA tras 3 intentos, se salta (no se crea borrador plano)`);
            // Tarjeta inmediata: sin imagen no hay posteo — borrar la fila.
            if (pendingId) { try { db.prepare('DELETE FROM posts WHERE id = ?').run(pendingId); } catch (e) {} }
            imgFailCount++;
            noteSlotFail('img', firstImgError);
            claimed--;
            continue;
          }
          if (weekFullNow()) {
            // La semana se completó mientras se creaba la imagen (otro
            // actor): no guardar este posteo ni su imagen.
            console.log(`[pipeline:${tag}] semana completa al guardar — slot descartado`);
            if (pendingId) { try { db.prepare('DELETE FROM posts WHERE id = ?').run(pendingId); } catch (e) {} }
            try { fs.unlinkSync(path.join(MEDIA_DIR, path.basename(imagePath))); } catch (e) {}
            weekFullStop = true;
            return;
          }
          if (pendingId) {
            // Completar la tarjeta inmediata con la imagen y el estilo.
            const upd = db.prepare(`UPDATE posts SET image_path = ?, style_code = ?, style_reason = ?, intent = ?, product_ref = ? WHERE id = ?`)
              .run(imagePath, finalCode, finalReason, finalIntent, finalProductRef, pendingId);
            if (!upd.changes) {
              // El usuario borró la tarjeta mientras se creaba: no resucita.
              try { fs.unlinkSync(path.join(MEDIA_DIR, path.basename(imagePath))); } catch (e) {}
              claimed--;
              continue;
            }
            // (v239) QA de personaje: identidad no garantizada ⇒ revisión.
            if (genOut.character === 'failed') { try { db.prepare('UPDATE posts SET needs_review = 1 WHERE id = ?').run(pendingId); console.log(`[pipeline:${tag}] post ${pendingId}: protagonista no garantizado — needs_review`); } catch (e) {} }
          } else {
            const insInfo = insStmt.run(uid, imagePath, caption, hashtags, idea.titulo || '', idea.angulo || '', idea.tipo || '', String(idea.porque || '').slice(0, 500), weekKey, (genOut.character === 'failed' ? 1 : needRev), finalCode, finalReason, finalIntent, finalProductRef, finalHookId, promptForMedia(imagePath), salesIntent, salesAngle);
            if (insInfo && insInfo.lastInsertRowid) { runCreatedIds.add(insInfo.lastInsertRowid); stampPostDigest(insInfo.lastInsertRowid, uid, content && content._anchored === false); }
          }
          } else {
            // El carousel se guarda como UN post con media_type='carousel'.
            if (weekFullNow()) { console.log(`[pipeline:${tag}] semana completa al guardar — carousel descartado`); weekFullStop = true; return; }
            const paths = [carouselGen.coverPath, ...carouselGen.slidePaths].slice(0, 5);
            const carInfo = db.prepare(`INSERT INTO posts (user_id, image_path, caption, hashtags, status, media_type,
              carousel_paths, source_topic, source_angle, tipo, strategy_why, week_key, needs_review,
              style_code, style_reason, intent, product_ref, hook_id, sales_intent, sales_angle)
              VALUES (?,?,?,?,'draft','carousel',?,?,?,?,?,?,?,?,?,?,?,?,?,?)`)
              .run(uid, carouselGen.coverPath, carouselGen.caption, hashtags, JSON.stringify(paths),
                idea.titulo || '', idea.angulo || '', idea.tipo || '', String(idea.porque || '').slice(0, 500),
                weekKey, (needRev || carouselGen.needsReview) ? 1 : 0,
                'carousel', `carousel automático (${carouselGen.slidePaths.length} placas)`,
                finalIntent || 'tips', finalProductRef, finalHookId, salesIntent, salesAngle);
            if (carInfo && carInfo.lastInsertRowid) { runCreatedIds.add(carInfo.lastInsertRowid); stampPostDigest(carInfo.lastInsertRowid, uid, content && content._anchored === false); }
          }
          // 🧹 Vigilancia de limpieza: modo y largo final de la pieza creada.
          if (isCarousel) runCleanStats.carousel++;
          else if (cleanPiece) runCleanStats.clean++;
          else runCleanStats.text++;
          // (v229) Vigilancia de pertenencia: ancla del digest en la pieza.
          if (content && content._anchored === false) belongStats.unanchored++;
          else belongStats.anchored++;
          try { runCleanStats.capLens.push(String(isCarousel ? (carouselGen && carouselGen.caption) : caption || '').length); } catch (e) {}
          created++;
        } catch (e) {
          claimed--;
          noteSlotFail(/caption/i.test(String(e.message || '')) ? 'content' : 'other', e);
          // Si la tarjeta inmediata quedó creada y algo explotó antes de
          // completarla, borrarla: nunca una tarjeta fantasma sin imagen.
          try { if (pendingId) db.prepare('DELETE FROM posts WHERE id = ? AND COALESCE(image_path, \'\') = \'\'').run(pendingId); } catch (e2) {}
          console.error(`[pipeline:${tag}] borrador "${idea.titulo || i}" falló:`, e.message);
        }
      }
    }
    // 5 workers: la semana entera (5 posteos) sale en una sola oleada.
    await Promise.all([worker(), worker(), worker(), worker(), worker()]);
    console.log(`[pipeline:${tag}] usuario ${uid} semana ${weekKey}: ${created}/${picks.length} borradores`);
    // (v229) Pertenencia de la corrida: la vara es todas con ancla salvo
    // a lo sumo 1 de marca/comunidad. Queda en el log por corrida.
    if (created > 0) console.log(`[pipeline:${tag}] usuario ${uid} pertenencia: ${belongStats.anchored} con ancla / ${belongStats.unanchored} sin ancla (digest ${(digestForUser(uid) || {}).hash || '—'})`);
    // 🧹 Vigilancia de limpieza: las dos medianas de la corrida quedan en
    // el resultado (visible vía /api/week/last-result) y en el log, para
    // comparar contra la línea de base del 2026-10-18 (100% con texto;
    // captions de 293-490 caracteres). Señal durable por posteo: el
    // image_prompt de una pieza CON texto lleva la línea "HEADLINE ZONE"
    // y el de una limpia no — la proporción se puede auditar sobre los
    // posteos guardados sin columnas nuevas.
    const cleanStats = (() => {
      const imgTotal = runCleanStats.text + runCleanStats.clean;
      const lens = [...runCleanStats.capLens].sort((a, b) => a - b);
      return {
        withText: runCleanStats.text, clean: runCleanStats.clean, carousel: runCleanStats.carousel,
        pctText: imgTotal ? Math.round((runCleanStats.text / imgTotal) * 100) : 0,
        captionMedianChars: lens.length ? lens[Math.floor((lens.length - 1) / 2)] : 0,
      };
    })();
    if (created > 0) console.log(`[pipeline:${tag}] usuario ${uid} limpieza: ${cleanStats.withText}/${cleanStats.withText + cleanStats.clean} posteos imagen con texto (${cleanStats.pctText}%), mediana de caption ${cleanStats.captionMedianChars} caracteres`);
    // 🧩 Si la tanda se armó respetando el patrón de la grilla, queda la
    // marca para la línea del reporte semanal (solo si salió algún posteo).
    if (created > 0 && gridAppliedLine) {
      try { markGridApplied(uid, weekKey, gridAppliedLine); console.log(`[pipeline:${tag}] usuario ${uid}: equilibrio de grilla aplicado — "${gridAppliedLine}"`); } catch (e) {}
    }
    // Si la semana quedó incompleta por fallos de imagen IA, alimentar el
    // loop de reintentos (v72): el cron cada 3h la regenera con reason 'img_fail'.
    if (imgFailCount > 0 && created < picks.length) {
      try { recordSweepFailure(uid, weekKey, 'img_fail'); } catch (e) {}
    }
    // Push "tu semana está lista": avisar en el celu para que la revise.
    // quiet (FASE 2): el sweep de nivel 0 manda el email con preview + botón
    // "Publicar semana" en su lugar — el push exigiría entrar a la app.
    if (created > 0 && !quiet) {
      try { push.sendPush(uid, { title: 'Tu semana está lista ✨', body: 'Posty armó tus posteos: revisalos y aprobá 👇', url: '/#/app/semana' }).catch(() => {}); }
      catch (e) { /* el push nunca bloquea */ }
    }
    // Historias + reels del plan: reusan las imágenes recién generadas.
    // Va en try/catch propio: si falla, el autopilot de feed queda intacto.
    // 2026-10-16: generateWeekExtras es idempotente (genera solo el
    // déficit) → corre también en modo completar: una semana completada
    // en dos tandas recibe las historias/reels que le faltan.
    try {
      const { generateWeekExtras } = require('./story-reel');
      const feedDrafts = db.prepare(`SELECT * FROM posts WHERE user_id = ? AND week_key = ? AND status = 'draft' AND media_type = 'image' ORDER BY created_at ASC`).all(uid, weekKey);
      const xr = await generateWeekExtras({ db, uid, weekKey, tag, mediaDir: MEDIA_DIR, feedDrafts, needsReview: needRev === 1 });
      // Semana "ok" sin el reel/historias del plan = fallo de barrido: se
      // registra para que el sistema de reintentos la complete (antes el
      // resultado se ignoraba y el faltante era invisible).
      if (xr && xr.need && xr.have && (xr.have.stories < xr.need.stories || xr.have.reels < xr.need.reels)) {
        console.error(`[pipeline:${tag}] extras incompletos usuario ${uid}: ${xr.have.stories}/${xr.need.stories} historias, ${xr.have.reels}/${xr.need.reels} reels`);
        try { recordSweepFailure(uid, weekKey, 'extras_missing'); } catch (e) {}
      }
    } catch (e) {
      console.error(`[pipeline:${tag}] extras historias/reels:`, e.message);
      try { recordSweepFailure(uid, weekKey, 'extras_error'); } catch (e2) {}
    }
    // DIRECCIÓN DE FEED (v332): con la semana completa (posteos + extras
    // historias/reels ya creados arriba), se compone el orden de
    // publicación contra la grilla real del cliente y queda registrado.
    // Nunca bloquea ni rompe la generación: adentro captura todo.
    if (created > 0) {
      try { await composeWeekFeed(uid, weekKey, tag); } catch (e) {}
    }
    // 2026-10-08: si no se creó NADA, es un fallo (no un éxito vacío).
    // Antes retornaba ok:true con created:0 y el retry lo borraba como si
    // hubiera funcionado — por eso la semana de Valentino nunca se reintentó.
    if (created === 0) {
      const failReason = imgFailCount > 0 ? 'img_fail' : 'no_ideas';
      console.error(`[pipeline:${tag}] usuario ${uid}: 0 posteos creados (${imgFailCount} fallos de imagen)`);
      return { ok: false, reason: failReason, created: 0, imgFailCount, error: firstImgError || undefined };
    }
    // PILOTO AUTOMÁTICO TOTAL (2026-10-16): el eslabón que faltaba del
    // sistema de autopilot que ya existía (users.autopilot_enabled +
    // trust levels + quality gate): cuando se genera una semana nueva,
    // al cliente que YA activó el autopiloto se le programa sola y solo
    // le llega el aviso — la tesis autopilot hasta el final.
    // scheduleAllDrafts aplica su gate de calidad fail-closed, el cupo
    // del plan y solo toca borradores que no necesitan revisión. Sin
    // autopilot o con rueditas: como siempre, espera su aprobación.
    try {
      const uA = db.prepare('SELECT autopilot_enabled FROM users WHERE id = ?').get(uid);
      if (uA && uA.autopilot_enabled && !trainingWheelsActive(uid)) {
        const rA = scheduleAllDrafts(uid);
        if (rA && rA.ok && rA.scheduled && rA.scheduled.length) {
          console.log(`[pipeline:${tag}] piloto automático total: usuario ${uid}: ${rA.scheduled.length} posteos programados solos`);
          try { push.sendPush(uid, { title: 'Tu semana se publica sola ✨', body: `${rA.scheduled.length} posteos quedaron programados en sus mejores horarios.`, url: '/#/app/semana' }).catch(() => {}); } catch (e) {}
        }
      }
    } catch (e) { console.error(`[pipeline:${tag}] piloto automático:`, e.message); }
    // 2026-10-15: semana PARCIAL (created < déficit) ya no es un éxito
    // silencioso: queda registrada para el loop de reintentos (el sweep la
    // completa) y el resultado lo dice con sus motivos por slot.
    if (created < deficit) {
      try { recordSweepFailure(uid, weekKey, 'partial_week'); } catch (e) {}
      console.error(`[pipeline:${tag}] usuario ${uid}: semana parcial ${created}/${deficit} — slotFails: ${JSON.stringify(slotFails)} errs: ${JSON.stringify(slotErrs)}`);
      return { ok: true, created, existing, deficit, incomplete: true, slotFails, slotErrs, cleanStats };
    }
    return { ok: true, created, existing, deficit, slotFails, cleanStats };
  } finally {
    NEXTWEEK_RUNNING.delete(uid);
  }
}
// ----- Resiliencia del generador semanal (2026-10-05): "la semana nunca queda
// vacía en silencio". Los fallos transitorios del sweep se registran en
// sweep_failures para reintentarse con backoff (retrySweepFailures, cada 3h)
// y con el backfill diario de las 8:00 (backfillThisWeek).
function sweepNowStr() { return new Date().toISOString().slice(0, 19).replace('T', ' '); }
function recordSweepFailure(uid, weekKey, reason) {
  try {
    const nextRetry = new Date(Date.now() + 3 * 3600 * 1000).toISOString().slice(0, 19).replace('T', ' ');
    db.prepare(`INSERT INTO sweep_failures (user_id, week_key, reason, attempts, next_retry_at, created_at)
      VALUES (?,?,?,?,?,?)
      ON CONFLICT(user_id, week_key) DO UPDATE SET reason = excluded.reason, attempts = 0, next_retry_at = excluded.next_retry_at, created_at = excluded.created_at`)
      .run(uid, weekKey, String(reason || '').slice(0, 200), 0, nextRetry, sweepNowStr());
  } catch (e) { console.error('[sweep-retry] no se pudo registrar el fallo:', e.message); }
}
// Barrido semanal (lo llama el cron de scheduler.js): para cada usuario que
// cumple los gates y no tiene borradores de la próxima semana, generarlos.
// Respaldo por si el trigger inline de schedule-all falló.
async function nextWeekSweep() {
  let users = [];
  try { users = db.prepare('SELECT id FROM users').all(); } catch (e) { return { ok: false, error: e.message }; }
  let ok = 0, skip = 0;
  for (const u of users) {
    let nextWk = null;
    try {
      // FASE 1: evaluación semanal de la escalera de confianza (barata: sale
      // enseguida si el usuario no está en nivel 1).
      try { autopilot.maybeGraduateLevel2(db, u.id); } catch (e) {}
      const tz = userTz(u.id);
      nextWk = shiftDays(mondayKeyOf(tzToday(tz)), 7);
      const elig = nextWeekEligible(u.id, nextWk);
      if (!elig.ok) { skip++; continue; }
      const r = await generateWeekDrafts(u.id, { weekKey: nextWk, tag: 'sweep', quiet: autopilot.trustLevel(db, u.id) === 0 });
      if (r.ok) {
        ok++;
        // FASE 2: nivel 0 → preview por email con "Publicar semana" de un tap
        // (sin login), en vez del push que exige entrar a la app. Nivel ≥1
        // mantiene el aviso de siempre (ya está programada).
        if (autopilot.trustLevel(db, u.id) === 0) {
          let emailed = false;
          try {
            const em = require('./notify-email');
            const er = (em && em.sendWeekPreview) ? await em.sendWeekPreview(db, u.id, nextWk) : null;
            emailed = !!(er && er.ok);
          } catch (e) { console.error('[next-week sweep] week preview:', e.message); }
          if (!emailed) {
            // Fallback: el push de siempre (mejor que silencio si no hay email).
            try { push.sendPush(u.id, { title: 'Tu semana está lista ✨', body: 'Posty armó tus posteos: revisalos y aprobá 👇', url: '/#/app/semana' }).catch(() => {}); }
            catch (e) { /* el push nunca bloquea */ }
          }
        }
        // 🚀 Abrir y listo: la semana semanal también se programa sola.
        // generateWeekDrafts ya generó historias/reels y mandó el push.
        if (autoWeekEnabled(u.id)) {
          try {
            const sa = scheduleAllDrafts(u.id);
            if (sa.ok) console.log(`[next-week sweep] usuario ${u.id}: ${sa.scheduled.length} programados solos 🚀`);
          } catch (e) { console.error('[next-week sweep] auto-schedule:', e.message); }
        }
      } else {
        // Fallo transitorio de IA ('ai_error' / 'no_ideas'): se registra para
        // reintentar con backoff — nunca queda la semana vacía en silencio.
        // Las demás reasons (no_dna, no_plan, ai_cap, already_exists, running)
        // son finales o requieren acción del usuario: no van a retry.
        if (r.reason === 'ai_error' || r.reason === 'no_ideas') recordSweepFailure(u.id, nextWk, r.reason);
        skip++;
      }
    } catch (e) {
      console.error('[next-week sweep] usuario', u.id, e.message);
      if (nextWk) recordSweepFailure(u.id, nextWk, 'exception: ' + String((e && e.message) || e || '').slice(0, 120));
      skip++;
    }
  }
  console.log(`[next-week sweep] generadas: ${ok}, salteadas: ${skip}`);
  return { ok: true, generated: ok, skipped: skip };
}
// Reintenta los fallos registrados del sweep con backoff exponencial
// (3h, 6h, 12h, 12h, 12h; a los 5 intentos se rinde y lo reporta).
// Lo llama el cron de scheduler.js cada 3 horas. Cada usuario está aislado:
// un fallo no mata el loop de los demás.
async function retrySweepFailures() {
  let rows = [];
  try { rows = db.prepare(`SELECT * FROM sweep_failures WHERE next_retry_at <= datetime('now') AND attempts < 5`).all(); }
  catch (e) { console.error('[sweep-retry] query:', e.message); return { ok: false, error: e.message }; }
  let resolved = 0, retried = 0;
  for (const f of rows) {
    try {
      const r = await generateWeekDrafts(f.user_id, { weekKey: f.week_key, tag: 'sweep-retry' });
      const del = () => { try { db.prepare(`DELETE FROM sweep_failures WHERE user_id = ? AND week_key = ?`).run(f.user_id, f.week_key); } catch (e) {} };
      if (r && r.ok) { del(); resolved++; }
      else if (r && (r.reason === 'ai_error' || r.reason === 'no_ideas' || r.reason === 'img_fail')) {
        const attempts = (f.attempts || 0) + 1;
        if (attempts >= 5) {
          del();
          logGenError('sweep', new Error(`semana ${f.week_key} sin generar tras 5 reintentos (uid ${f.user_id})`));
        } else {
          const hours = Math.min(3 * Math.pow(2, attempts), 12);
          const nextRetry = new Date(Date.now() + hours * 3600 * 1000).toISOString().slice(0, 19).replace('T', ' ');
          try { db.prepare(`UPDATE sweep_failures SET attempts = ?, reason = ?, next_retry_at = ? WHERE user_id = ? AND week_key = ?`).run(attempts, r.reason, nextRetry, f.user_id, f.week_key); }
          catch (e) { console.error('[sweep-retry] update:', e.message); }
        }
        retried++;
      } else {
        // Reason final (no_dna, no_plan, ai_cap, already_exists, running,
        // inactive_7d, paused_14d): ya no aplica → no tiene sentido seguir
        // reintentando, se limpia la fila.
        del();
      }
    } catch (e) {
      // Excepción inesperada (ej. el usuario fue borrado y getProfile choca
      // con la FK): cuenta como intento para no dejar la fila colgada.
      console.error('[sweep-retry] usuario', f.user_id, e.message);
      const attempts = (f.attempts || 0) + 1;
      if (attempts >= 5) {
        try { db.prepare(`DELETE FROM sweep_failures WHERE user_id = ? AND week_key = ?`).run(f.user_id, f.week_key); } catch (e2) {}
        logGenError('sweep', new Error(`semana ${f.week_key} sin generar tras 5 reintentos (uid ${f.user_id}, excepción)`));
      } else {
        try { db.prepare(`UPDATE sweep_failures SET attempts = ?, next_retry_at = datetime('now', '+3 hours') WHERE user_id = ? AND week_key = ?`).run(attempts, f.user_id, f.week_key); }
        catch (e2) {}
      }
    }
  }
  if (rows.length) console.log(`[sweep-retry] filas: ${rows.length}, resueltas: ${resolved}, reintentadas: ${retried}`);
  return { ok: true, rows: rows.length, resolved, retried };
}
// Backfill diario (cron 8:00 ART en scheduler.js): genera la semana EN CURSO
// para los usuarios que el barrido del domingo no cubrió — aunque el domingo
// falle TODO, el lunes a la mañana la semana existe (tarde, pero existe).
// Idempotente por el guard already_exists (de nextWeekEligible y del pipeline).
async function backfillThisWeek() {
  let users = [];
  try { users = db.prepare('SELECT id FROM users').all(); } catch (e) { return { ok: false, error: e.message }; }
  let ok = 0, skip = 0;
  for (const u of users) {
    let wk = null;
    try {
      wk = mondayKeyOf(tzToday(userTz(u.id)));
      const elig = nextWeekEligible(u.id, wk);
      if (!elig.ok) { skip++; continue; }
      const r = await generateWeekDrafts(u.id, { weekKey: wk, tag: 'backfill' });
      if (r && r.ok) ok++;
      else {
        // El backfill también alimenta el loop de reintentos: si a las 8:00 la
        // IA sigue caída, el cron de cada 3h lo vuelve a intentar.
        if (r && (r.reason === 'ai_error' || r.reason === 'no_ideas')) recordSweepFailure(u.id, wk, r.reason);
        skip++;
      }
    } catch (e) {
      console.error('[backfill] usuario', u.id, e.message);
      if (wk) recordSweepFailure(u.id, wk, 'exception: ' + String((e && e.message) || e || '').slice(0, 120));
      skip++;
    }
  }
  console.log(`[backfill] semanas generadas: ${ok}, salteadas: ${skip}`);
  return { ok: true, generated: ok, skipped: skip };
}
// ----- Agregado Track 4: "si vacía los borradores, se reconstruye con otro enfoque" -----
function rebuildCountFor(uid, wk) {
  try {
    const r = db.prepare('SELECT count FROM rebuild_counts WHERE user_id = ? AND week_key = ?').get(uid, wk);
    return (r && r.count) || 0;
  } catch (e) { return 0; }
}
function bumpRebuildCount(uid, wk) {
  try {
    db.prepare(`INSERT INTO rebuild_counts (user_id, week_key, count) VALUES (?,?,1)
      ON CONFLICT(user_id, week_key) DO UPDATE SET count = count + 1`).run(uid, wk);
  } catch (e) { /* no bloquea */ }
}
// Dispara la reconstrucción de una semana en segundo plano. Asume que los
// borradores ya fueron marcados como rejected y eliminados. Aplica gates + tope
// de 2 reconstrucciones/semana. Devuelve { rebuilding, reason?, count? }.
function maybeStartRebuild(uid, wk) {
  const tz = userTz(uid);
  const week = wk || mondayKeyOf(tzToday(tz));
  if (!planOrTrialOk(uid)) return { rebuilding: false, reason: 'no_plan' };
  // Gates 2 y 4 de actividad: el usuario está tocando la app AHORA MISMO
  // (acaba de vaciar) — trivialmente activo. No se chequean.
  const c = rebuildCountFor(uid, week);
  if (c >= 2) return { rebuilding: false, reason: 'frustrated', count: c };
  bumpRebuildCount(uid, week);
  generateWeekDrafts(uid, { weekKey: week, tag: 'rebuild' })
    .catch((e) => console.error('[rebuild] pipeline:', e.message));
  return { rebuilding: true, count: c + 1 };
}
// Marca borradores como rejected EN BULK (una transacción) y los elimina.
// Los rejected alimentan excludedTopicsLine() (Track D): la próxima tanda sale
// con otros ángulos y tipos automáticamente. Nota: PRAGMA foreign_keys NO está
// activado en db.js, así que las señales sobreviven al DELETE (no hay cascade).
function vaciarYMarcar(uid, drafts, wk) {
  const prof = getProfile(uid) || {};
  const mark = db.prepare(`INSERT INTO post_signals (user_id, post_id, caption, hashtags, scheduled_for, rubro, client_signal, week_key, updated_at)
    VALUES (?,?,?,?,?,?,'rejected',?,datetime('now'))
    ON CONFLICT(user_id, post_id) DO UPDATE SET client_signal='rejected', caption=excluded.caption, hashtags=excluded.hashtags, week_key=excluded.week_key, updated_at=datetime('now')`);
  const del = db.prepare('DELETE FROM posts WHERE id = ?');
  // node:sqlite no tiene db.transaction(): transacción manual.
  db.exec('BEGIN IMMEDIATE');
  try {
    for (const d of drafts) {
      mark.run(uid, d.id, d.caption || '', d.hashtags || '', d.scheduled_at || '', prof.category || '', wk);
      del.run(d.id);
    }
    db.exec('COMMIT');
  } catch (e) {
    try { db.exec('ROLLBACK'); } catch (_) {}
    throw e;
  }
}

// "📅 Programar mi semana →": TODOS los borradores del usuario se programan
// de una, cada uno en su mejor horario. El tap ES la aprobación (sin él,
// nada se programa ni publica). Registra la señal 'approved' por posteo para
// que el aprendizaje no se rompa. Programar SÍ consume cupo (los borradores son gratis).
// ---------- 🚀 ABRIR Y LISTO (2026-10-03) ----------
// Programa todos los borradores listos del usuario en sus horarios óptimos.
// Es la versión interna de POST /api/posts/schedule-all (sin req/res):
// acepta (approval='approved') y programa feed en best_hour, stories 13:00,
// reels en best_hour, sin pisar días ya ocupados. Devuelve { ok, scheduled }.
// Asigna horarios de publicación a borradores: un feed por día desde mañana en
// best_hour (9-21, respaldo 19:00), historias en STORY_HOUR, salteando días ya
// ocupados. No toca la DB: devuelve Map id → 'YYYY-MM-DD HH:MM:SS' (UTC).
// Extraído de scheduleAllDrafts (FASE 2) para reutilizar la misma política en
// el publish firmado de la semana y en el email de preview.
// ¿El día (hora del cliente) de `whenIso` ya tiene un posteo de la misma
// clase (feed vs historia) programado o publicado? Regla de agenda de
// Posty: un posteo de feed por día por cliente (2026-10-16).
function scheduleDayTaken(uid, post, whenIso) {
  try {
    const tz = userTz(uid);
    const k = ymdInTz(whenIso, tz);
    if (!k) return false;
    const isStory = post && post.media_type === 'story';
    const rows = db.prepare(`SELECT scheduled_at, media_type FROM posts
      WHERE user_id = ? AND status IN ('scheduled','published') AND scheduled_at IS NOT NULL AND id != ?`).all(uid, (post && post.id) || 0);
    for (const r of rows) {
      if ((r.media_type === 'story') !== isStory) continue;
      if (ymdInTz(r.scheduled_at, tz) === k) return true;
    }
  } catch (e) {}
  return false;
}

// 🚪 Días de cierre (v283): profiles.closed_days es un JSON de días ISO
// (1=Lun..7=Dom) en los que el negocio NO abre. Los dos motores de slots lo
// respetan: ningún posteo automático cae en un día cerrado. (La fecha que el
// dueño elige a mano en el PATCH queda fuera: es su decisión explícita,
// como su programación manual ya limpia el freno de cuenta.)
function weekdayOfYmd(ymd) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(ymd || ''));
  if (!m) return 0;
  const wd = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]))).getUTCDay();
  return wd === 0 ? 7 : wd;
}
function closedDaysOf(uid) {
  try {
    const p = db.prepare('SELECT closed_days FROM profiles WHERE user_id = ?').get(uid);
    if (!p || !p.closed_days) return new Set();
    const arr = JSON.parse(p.closed_days);
    if (!Array.isArray(arr)) return new Set();
    return new Set(arr.map((d) => Number(d)).filter((d) => Number.isInteger(d) && d >= 1 && d <= 7));
  } catch (e) { return new Set(); }
}

function assignScheduleSlots(uid, drafts) {
  const tz = userTz(uid);
  let bestHour = 19;
  try {
    const u = db.prepare('SELECT best_hour FROM users WHERE id = ?').get(uid);
    if (u && u.best_hour >= 9 && u.best_hour <= 21) bestHour = u.best_hour;
  } catch (e) { /* respaldo 19:00 */ }
  const { STORY_HOUR } = require('./story-reel');
  const taken = new Set();
  const takenStory = new Set();
  try {
    const sched = db.prepare(`SELECT scheduled_at, media_type FROM posts WHERE user_id = ? AND status = 'scheduled' AND scheduled_at IS NOT NULL`).all(uid);
    for (const s of sched) {
      const k = ymdInTz(s.scheduled_at, tz); if (!k) continue;
      if (s.media_type === 'story') takenStory.add(k); else taken.add(k);
    }
  } catch (e) { /* no bloquea */ }
  const slotAt = (i, hour) => {
    const ymd = shiftDays(tzToday(tz), i + 1);
    return zonedWallToUtc(`${ymd} ${String(hour).padStart(2, '0')}:00`, tz);
  };
  const out = new Map();
  const closedSet = closedDaysOf(uid);
  let off = 0, offStory = 0, guard = 0;
  for (const d of drafts) {
    const isStory = d.media_type === 'story';
    const hour = isStory ? STORY_HOUR : bestHour;
    const tset = isStory ? takenStory : taken;
    let o = isStory ? offStory : off;
    let iso = null;
    while (guard++ < 400) {
      const cand = slotAt(o++, hour);
      if (!cand) break;
      const k = ymdInTz(cand, tz);
      if (k && closedSet.has(weekdayOfYmd(k))) continue; // 🚪 día de cierre: no se programa
      if (k && !tset.has(k)) { tset.add(k); iso = cand; break; }
    }
    if (isStory) offStory = o; else off = o;
    // Sin slot: si cierra TODOS los días no hay fallback posible (el de
    // siempre podría caer en un día cerrado); queda sin asignar.
    if (!iso && closedSet.size < 7) iso = slotAt(o++, hour);
    if (iso) out.set(d.id, iso);
    // (Si no hay slot —tz inválida—, se saltea: nunca scheduled_at=NULL.)
  }
  return out;
}

// ---------- schedule-all POR SEMANA DEL POSTEO (fix 2026-10-18, v216) ----------
// Espejo de la semántica de acceptAllDrafts (v215): nada de "todos de una o
// nada" contra la semana actual. Cada borrador se evalúa contra SU semana:
// la de su week_key (sin week_key o vencida → la actual). Si el cupo de ESA
// semana (por formato, desde quotaCounts) lo admite y hay un día libre en
// ella (nunca hoy ni el pasado), se programa; si no, queda borrador y se
// reporta en `waiting` ({ id, week_key, reason }) sin bloquear al resto.
function quotaPoolKey(d) {
  return d.media_type === 'video' ? 'video' : d.media_type === 'story' ? 'story' : 'image';
}
// Saldos de cupo por semana|formato, con descuento en memoria a medida que
// ESTA corrida programa (mismo patrón que acceptAllDrafts v215).
function weekQuotaPools(uid) {
  const poolLimit = {
    image: quotaFor(uid, 'image').limit,
    video: quotaFor(uid, 'video').limit,
    story: quotaFor(uid, 'story').limit,
  };
  const cache = new Map();
  const leftFor = (monday, poolKey) => {
    const k = monday + '|' + poolKey;
    if (!cache.has(k)) {
      const c = quotaCounts(uid, monday);
      const used = poolKey === 'video' ? (c.video || 0)
        : poolKey === 'story' ? (c.story || 0)
        : (c.image || 0) + (c.carousel || 0);
      cache.set(k, Math.max(0, (poolLimit[poolKey] || 0) - used));
    }
    return cache.get(k);
  };
  return {
    leftFor,
    consume(monday, poolKey) { cache.set(monday + '|' + poolKey, Math.max(0, leftFor(monday, poolKey) - 1)); },
  };
}
// Núcleo compartido del schedule-all ("Programar mi semana" y el
// scheduleAllDrafts del autopilot): programa `drafts` semana a semana.
// `apply(iso, d)` ejecuta el UPDATE propio de cada flujo. Horarios: feed y
// reels a la best_hour del negocio, historias a STORY_HOUR; un posteo de
// feed por día (las historias tienen su propio carril de días).
function scheduleDraftsPerWeek(uid, drafts, apply) {
  const tz = userTz(uid);
  let bestHour = 19;
  try {
    const u = db.prepare('SELECT best_hour FROM users WHERE id = ?').get(uid);
    if (u && u.best_hour >= 9 && u.best_hour <= 21) bestHour = u.best_hour;
  } catch (e) { /* respaldo 19:00 */ }
  const { STORY_HOUR } = require('./story-reel');
  const curMonday = mondayKeyOf(tzToday(tz));
  const tomorrow = shiftDays(tzToday(tz), 1);
  const taken = new Set();
  const takenStory = new Set();
  try {
    const sched = db.prepare(`SELECT scheduled_at, media_type FROM posts WHERE user_id = ? AND status = 'scheduled' AND scheduled_at IS NOT NULL`).all(uid);
    for (const s of sched) {
      const k = ymdInTz(s.scheduled_at, tz); if (!k) continue;
      if (s.media_type === 'story') takenStory.add(k); else taken.add(k);
    }
  } catch (e) { /* no bloquea */ }
  const pools = weekQuotaPools(uid);
  const closedSet = closedDaysOf(uid);
  // DIRECCIÓN DE FEED (v332): si el director compuso alguna de estas
  // semanas, el orden de salida de las piezas FEED es el compuesto (las
  // historias conservan el suyo). El mapa de slots no cambia — días y
  // horas salen de las mismas reglas de siempre —: solo se permuta QUÉ
  // pieza cae en cada slot, que es exactamente "el orden entre piezas de
  // la misma semana". Sin registro compuesto, orden de creación, como
  // siempre. El orden se agrupa por la semana de cada borrador: ninguna
  // pieza salta de semana.
  try {
    const rankByPost = new Map();
    const compRows = db.prepare('SELECT data_json FROM feed_compositions WHERE user_id = ?').all(uid);
    for (const cr of compRows) {
      try {
        const rec = JSON.parse(cr.data_json || '{}');
        if (rec && Array.isArray(rec.order)) {
          rec.order.forEach((pid, ix) => { if (!rankByPost.has(pid)) rankByPost.set(pid, ix); });
        }
      } catch (e) {}
    }
    if (rankByPost.size) {
      const feedPos = [];
      drafts.forEach((d, i) => { if (d.media_type !== 'story') feedPos.push(i); });
      const subset = feedPos.map((i) => drafts[i]);
      const grpOf = (d) => (d.week_key ? mondayKeyOf(d.week_key) : curMonday);
      subset.sort((a, b) => {
        const ga = grpOf(a), gb = grpOf(b);
        if (ga !== gb) return ga < gb ? -1 : 1;
        const ra = rankByPost.has(a.id) ? rankByPost.get(a.id) : Number.MAX_SAFE_INTEGER;
        const rb = rankByPost.has(b.id) ? rankByPost.get(b.id) : Number.MAX_SAFE_INTEGER;
        return ra - rb;
      });
      feedPos.forEach((pos, k) => { drafts[pos] = subset[k]; });
    }
  } catch (e) { /* sin composición, orden de siempre */ }
  const scheduled = [];
  const waiting = [];
  for (const d of drafts) {
    const isStory = d.media_type === 'story';
    const tset = isStory ? takenStory : taken;
    const hour = isStory ? STORY_HOUR : bestHour;
    let monday = curMonday;
    if (typeof d.week_key === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d.week_key)) monday = mondayKeyOf(d.week_key);
    if (monday < curMonday) monday = curMonday;
    const poolKey = quotaPoolKey(d);
    if (pools.leftFor(monday, poolKey) <= 0) {
      waiting.push({ id: d.id, week_key: monday, reason: 'plan_limit' });
      continue;
    }
    // Primer día libre dentro de SU semana (desde mañana si es la actual).
    // 🚪 Los días de cierre se saltan siempre: si los abiertos no alcanzan,
    // la semana sale con menos posteos — jamás se viola un cierre.
    let iso = null;
    const firstDay = monday < tomorrow ? tomorrow : monday;
    for (let i = 0; i < 7; i++) {
      const ymd = shiftDays(monday, i);
      if (ymd < firstDay || tset.has(ymd)) continue;
      if (closedSet.has(weekdayOfYmd(ymd))) continue;
      const cand = zonedWallToUtc(`${ymd} ${String(hour).padStart(2, '0')}:00`, tz);
      if (cand && ymdInTz(cand, tz) === ymd) { tset.add(ymd); iso = cand; break; }
    }
    if (!iso) { waiting.push({ id: d.id, week_key: monday, reason: closedSet.size >= 7 ? 'closed_days' : 'no_slot' }); continue; }
    pools.consume(monday, poolKey);
    apply(iso, d);
    try { recordSignal(uid, d, 'approved'); } catch (e) { /* no bloquea */ }
    scheduled.push({ id: d.id, scheduled_at: iso, week_key: monday });
  }
  return { scheduled, waiting };
}

// ⛔ Freno a nivel CUENTA (fix v275, 2026-10-20): users.publishing_stopped.
// Lo setea SOLO el stop administrativo (POST /api/admin/stop-publishing) y
// bloquea TODO lo automático de la cuenta, aunque un posteo puntual no
// tenga la marca user_stopped (borradores que ya eran borradores cuando se
// frenó — la v272 no los marcaba y la regla 24h resucitó 5 de la cuenta 12 —
// o borradores generados DESPUÉS del freno). Se limpia solo cuando el dueño
// mismo reanuda: programar (PATCH), aceptar (acceptAllDrafts), schedule-all
// o encender el autopiloto. No hay endpoint admin de reanudación: el freno
// administrativo lo levanta el dueño desde su propia cuenta.
function publishingStopped(uid) {
  try {
    const r = db.prepare('SELECT publishing_stopped FROM users WHERE id = ?').get(uid);
    return !!(r && r.publishing_stopped);
  } catch (e) { return false; }
}
function clearPublishingStopped(uid) {
  try { db.prepare('UPDATE users SET publishing_stopped = 0 WHERE id = ?').run(uid); } catch (e) {}
}

function scheduleAllDrafts(uid) {
  // ⛔ user_stopped (fix 2026-10-20): un posteo que el dueño FRENÓ (o que un
  // stop administrativo frenó) NUNCA se re-programa solo. Esta función es el
  // embudo de TODOS los flujos automáticos (pipeline, sweep semanal, regla
  // 24h, login/signup): la marca se respeta acá y en ningún otro lado hace
  // falta. Sin la marca, la regla 24h resucitaba posteos frenados a la hora
  // siguiente (visto 3 veces en producción el 2026-10-20, cuentas 12 y 3).
  // La marca se limpia SOLO cuando el usuario mismo lo programa/acepta.
  // ⛔ publishing_stopped (fix v275): capa a nivel CUENTA sobre la marca —
  // si la cuenta está frenada administrativamente, el embudo no programa
  // NADA (ni siquiera posteos sin marca o creados después del freno).
  if (publishingStopped(uid)) return { ok: false, reason: 'publishing_stopped', scheduled: [], waiting: [] };
  const drafts = db.prepare(`SELECT * FROM posts WHERE user_id = ? AND status = 'draft' AND COALESCE(needs_review,0)=0 AND COALESCE(user_stopped,0)=0 AND COALESCE(image_path,'') != '' ORDER BY created_at ASC`).all(uid);
  if (!drafts.length) return { ok: false, reason: 'no_drafts', scheduled: [], waiting: [] };
  // FASE 0 — qualityGate: solo lo bueno sale solo. El borrador que no pasa
  // el gate queda en 'draft' con needs_review=1 (cola de revisión humana) y
  // no consume cupo. Fail-closed: si el gate tira error, tampoco sale solo.
  const ready = [];
  let gateFailed = 0;
  for (const d of drafts) {
    let g = null;
    try {
      g = autopilot.qualityGate(d, db, MEDIA_DIR);
      autopilot.saveQualityResult(db, d.id, g);
    } catch (e) { console.error(`[autopilot] gate post ${d.id}:`, e.message); }
    if (g && g.pass) { ready.push(d); continue; }
    gateFailed++;
    try { db.prepare(`UPDATE posts SET needs_review=1 WHERE id=?`).run(d.id); } catch (e) {}
    const failed = g
      ? Object.entries(g.checks).filter(([, c]) => !c.ok).map(([k, c]) => `${k}(${c.detail})`).join(', ')
      : 'gate_error';
    console.log(`[autopilot] scheduleAllDrafts: post ${d.id} NO pasa gate (score ${g ? g.score : '?'}): ${failed} → revisión humana`);
  }
  if (!ready.length) return { ok: false, reason: gateFailed > 0 ? 'quality_failed' : 'no_drafts', scheduled: [], waiting: [], gateFailed };
  // Cupo POR SEMANA DEL POSTEO (fix v216): el criterio viejo ("todos de
  // una o nada" contra la semana ACTUAL) bloqueaba TODO cuando la semana
  // actual estaba llena, aunque los borradores fueran de la que viene.
  // Ahora cada borrador que pasó el gate se programa si el cupo de SU
  // semana lo admite (scheduleDraftsPerWeek); el resto queda en espera,
  // reportado en `waiting`, sin bloquear a los demás.
  // FASE 1: auto_published=1 marca lo programado POR EL SISTEMA (sin tap
  // del usuario): así el aviso pre-publicación de 30 min lo cubre como
  // freno de emergencia en nivel 1, y el conteo de semanas limpias lo ve.
  const upd = db.prepare(`UPDATE posts SET scheduled_at=?, status='scheduled', approval='approved', approved_at=datetime('now'), error='', notified=0, auto_published=1 WHERE id=?`);
  const { scheduled, waiting } = scheduleDraftsPerWeek(uid, ready, (iso, d) => upd.run(iso, d.id));
  scheduleLintForPosts(uid, scheduled.map((s) => s.id)); // (v198-A) lint al programar
  if (!scheduled.length) {
    const reason = waiting.some((w) => w.reason === 'plan_limit') ? 'plan_limit' : 'no_slots';
    return { ok: false, reason, scheduled: [], waiting, gateFailed };
  }
  return { ok: true, scheduled, waiting, gateFailed };
}

// Arma la semana sola: genera historias/reels del plan sobre los borradores,
// programa TODO y avisa "tu semana está lista 🎉" (push + email de respaldo).
// Fire-and-forget: nunca tira.
async function autoArmWeek(uid, tag) {
  try {
    tag = tag || 'auto-arm';
    // 1) Historias + reels del plan (si el plan los incluye).
    try {
      const { generateWeekExtras } = require('./story-reel');
      const tz = userTz(uid);
      const weekKey = mondayKeyOf(tzToday(tz));
      const feedDrafts = db.prepare(`SELECT * FROM posts WHERE user_id = ? AND media_type = 'image'
        AND status IN ('draft','scheduled') AND created_at > datetime('now', '-3 days')
        ORDER BY created_at ASC`).all(uid, weekKey);
      if (feedDrafts.length) {
        let needRev = 0;
        try { needRev = trainingWheelsActive(uid) ? 1 : 0; } catch (e) {}
        await generateWeekExtras({ db, uid, weekKey, tag, mediaDir: MEDIA_DIR, feedDrafts, needsReview: needRev === 1 });
      }
    } catch (e) { console.error(`[auto-arm:${tag}] extras:`, e.message); }
    // 1b) DIRECCIÓN DE FEED (v332): con posteos + extras ya creados, se
    // compone el orden de la semana contra la grilla real antes de
    // programar (scheduleDraftsPerWeek honra el registro compuesto).
    try {
      const wkArm = mondayKeyOf(tzToday(userTz(uid)));
      await composeWeekFeed(uid, wkArm, tag);
    } catch (e) {}
    // 2) Programar todo lo listo.
    const r = scheduleAllDrafts(uid);
    if (!r.ok) { console.log(`[auto-arm:${tag}] usuario ${uid}: ${r.reason}`); return r; }
    console.log(`[auto-arm:${tag}] usuario ${uid}: ${r.scheduled.length} programados 🚀`);
    // 3) Aviso "tu semana está lista".
    try {
      const n = r.scheduled.length;
      push.sendPush(uid, {
        title: 'Tu semana está lista 🎉',
        body: `${n} ${n === 1 ? 'posteo sale solo' : 'posteos salen solos'} en su horario. Tocá para verla 👀`,
        url: '/#/app/semana',
      }).catch(() => {});
    } catch (e) { /* el push nunca bloquea */ }
    try {
      const em = require('./notify-email');
      if (em && em.sendWeekReady) em.sendWeekReady(db, uid, r.scheduled.length);
    } catch (e) { /* el email nunca bloquea */ }
    return r;
  } catch (e) {
    console.error(`[auto-arm:${tag}] usuario ${uid}:`, e.message);
    return { ok: false, reason: 'error', scheduled: [] };
  }
}

function autoWeekEnabled(uid) {
  try {
    const r = db.prepare('SELECT auto_week FROM users WHERE id = ?').get(uid);
    return !r || r.auto_week !== 0; // default 1 (migración): opt-out
  } catch (e) { return true; }
}

app.post('/api/posts/schedule-all', requireAuth, async (req, res) => {
  const uid = req.session.userId;
  const drafts = db.prepare(`SELECT * FROM posts WHERE user_id = ? AND status = 'draft' AND COALESCE(needs_review,0)=0 AND COALESCE(image_path,'') != '' ORDER BY created_at ASC`).all(uid);
  if (!drafts.length) {
    let pending = 0;
    try { pending = db.prepare(`SELECT COUNT(*) AS n FROM posts WHERE user_id = ? AND status = 'draft' AND COALESCE(needs_review,0)=1`).get(uid).n || 0; } catch (e) {}
    if (pending > 0) return res.status(400).json({ error: 'in_review', message: 'Tus primeros posteos están en el horno ✨ Te aviso cuando estén listos para programar.' });
    return res.status(400).json({ error: 'No hay borradores para programar' });
  }
  // DIRECCIÓN DE FEED (v332): antes de programar, componer el orden de
  // cada semana presente en estos borradores contra la grilla real del
  // cliente (best-effort: si la composición falla, se programa en el
  // orden de siempre; scheduleDraftsPerWeek honra el registro compuesto).
  try {
    const wks = [...new Set(drafts.map((d) => d.week_key).filter(Boolean))];
    for (const wk of wks) {
      try { await composeWeekFeed(uid, wk, 'manual'); } catch (e) {}
    }
  } catch (e) {}
  // Cupo POR SEMANA DEL POSTEO (fix v216): cada borrador se programa si el
  // cupo de SU semana (la de su week_key) lo admite; los que exceden el cupo
  // de su propia semana quedan borradores y se reportan en `waiting`
  // (id + week_key + motivo), sin bloquear al resto. El 403 queda SOLO para
  // el tope verdadero —cuando NINGÚN borrador pudo programarse por cupo— y
  // trae los datos de la semana del posteo (mismo criterio que v215).
  const upd = db.prepare(`UPDATE posts SET scheduled_at=?, status='scheduled', error='', notified=0, user_stopped=0 WHERE id=?`);
  const { scheduled, waiting } = scheduleDraftsPerWeek(uid, drafts, (iso, d) => upd.run(iso, d.id));
  scheduleLintForPosts(uid, scheduled.map((s) => s.id)); // (v198-A) lint al programar
  if (!scheduled.length && waiting.length) {
    const w0 = waiting.find((w) => w.reason === 'plan_limit') || waiting[0];
    if (w0.reason === 'plan_limit') {
      const d0 = drafts.find((d) => d.id === w0.id) || {};
      const qx = quotaForWeek(uid, d0.media_type, w0.week_key);
      return res.status(403).json({ error: 'plan_limit', plan_limit: true, limit: qx.limit, used: qx.used, plan_name: qx.plan_name, week_key: w0.week_key, waiting,
        message: `Llegaste al límite de tu plan ${qx.plan_name} (${qx.limit} ${quotaUnitName(d0.media_type)} por semana). Mejorá tu paquete para seguir posteando esa semana.` });
    }
    return res.status(400).json({ error: 'no_slots', waiting, message: 'No encontramos días libres en la semana de tus posteos para programarlos.' });
  }
  if (scheduled.length) clearPublishingStopped(uid); // (v275) programar todo a mano es reanudar la cuenta
  res.json({ ok: true, scheduled, waiting });
  // ===== Track 4 "Pipeline perpetuo" =====
  // Al programar la semana N, la N+1 se empieza a armar SOLA en segundo plano.
  // Fire-and-forget: la respuesta ya salió, esto no la bloquea. Solo BORRADORES:
  // nada se programa ni publica sin el tap del usuario.
  try {
    const tz2 = userTz(uid);
    const nextWk = shiftDays(mondayKeyOf(tzToday(tz2)), 7);
    if (nextWeekEligible(uid, nextWk).ok) {
      generateWeekDrafts(uid, { weekKey: nextWk, tag: 'next-week' })
        .catch((e) => console.error('[next-week] pipeline:', e.message));
    }
  } catch (e) { console.error('[next-week] trigger:', e.message); }
});

// Historias + reels del plan para el autopilot manual del browser.
// Corre en segundo plano (los reels tardan ~1 min en ffmpeg): responde al toque
// y los borradores aparecen en "Revisá tu semana" al refrescar.
app.post('/api/posts/generate-extras', requireAuth, (req, res) => {
  const uid = req.session.userId;
  res.json({ ok: true, started: true });
  (async () => {
    try {
      const { generateWeekExtras } = require('./story-reel');
      const tz = userTz(uid);
      const weekKey = mondayKeyOf(tzToday(tz));
      // Borradores de feed recientes (el browser no setea week_key: van con '').
      const feedDrafts = db.prepare(`SELECT * FROM posts WHERE user_id = ? AND media_type = 'image'
        AND status IN ('draft','scheduled') AND (week_key = ? OR week_key = '')
        AND created_at > datetime('now', '-3 days') ORDER BY created_at ASC`).all(uid, weekKey);
      if (!feedDrafts.length) return;
      // Idempotencia: si ya hay historias/reels recientes, no duplicar.
      const existing = db.prepare(`SELECT COUNT(*) AS n FROM posts WHERE user_id = ? AND media_type IN ('story','video')
        AND status != 'cancelled' AND created_at > datetime('now', '-3 days')`).get(uid).n || 0;
      if (existing > 0) { console.log(`[extras:manual] usuario ${uid}: ya existen, skip`); return; }
      await generateWeekExtras({ db, uid, weekKey, tag: 'manual', mediaDir: MEDIA_DIR, feedDrafts, needsReview: trainingWheelsActive(uid) });
    } catch (e) { console.error('[extras:manual]:', e.message); }
  })();
});

