// Resumen para el dashboard "Mi semana": semana actual, aprobación, ritmo y mes.
// Métricas honestas de actividad propia (posteos), NUNCA métricas de Instagram.
app.get('/api/stats/summary', requireAuth, (req, res) => {
  const uid = req.session.userId;
  const tz = userTz(uid);
  const curWeek = mondayKeyOf(tzToday(tz));
  const posts = db.prepare('SELECT * FROM posts WHERE user_id = ?').all(uid);
  const withWk = posts.map((p) => ({ ...p, _wk: postWeekKey(p, tz) }));
  const sigRows = db.prepare('SELECT post_id, client_signal FROM post_signals WHERE user_id = ?').all(uid);
  const sigMap = Object.fromEntries(sigRows.map((r) => [r.post_id, r.client_signal]));

  const weekPosts = withWk
    .filter((p) => p._wk === curWeek && p.status !== 'cancelled')
    .sort((a, b) => String(a.scheduled_at || a.created_at).localeCompare(String(b.scheduled_at || b.created_at)));
  const byStatus = {};
  for (const p of weekPosts) byStatus[p.status] = (byStatus[p.status] || 0) + 1;
  const ready = weekPosts.filter((p) => ['scheduled', 'publishing', 'published'].includes(p.status)).length;

  const u = db.prepare('SELECT plan, plan_status FROM users WHERE id = ?').get(uid) || {};
  const ppw = (getPlan(u.plan_status === 'active' ? u.plan : TRIAL_PLAN).postsPerWeek) || 3;

  const weekly = [];
  for (let i = 7; i >= 0; i--) {
    const wk = shiftDays(curWeek, -i * 7);
    weekly.push({
      key: wk,
      label: wk.slice(8) + '/' + wk.slice(5, 7),
      total: withWk.filter((p) => p._wk === wk && p.status !== 'cancelled').length,
    });
  }

  let approved = 0, edited = 0, rejected = 0;
  for (const r of sigRows) {
    if (r.client_signal === 'approved') approved++;
    else if (r.client_signal === 'edited') edited++;
    else if (r.client_signal === 'rejected') rejected++;
  }
  const sigTotal = approved + edited + rejected;

  const mk = tzToday(tz).slice(0, 7);
  const monthPublished = db.prepare(`SELECT COUNT(*) AS c FROM posts WHERE user_id = ? AND status = 'published' AND substr(published_at, 1, 7) = ?`).get(uid, mk).c;
  const monthScheduled = db.prepare(`SELECT COUNT(*) AS c FROM posts WHERE user_id = ? AND status = 'scheduled'`).get(uid).c;
  const totalPublished = db.prepare(`SELECT COUNT(*) AS c FROM posts WHERE user_id = ? AND status = 'published'`).get(uid).c;
  const tasteLearned = db.prepare(`SELECT COUNT(*) AS c FROM post_signals WHERE user_id = ? AND client_signal IN ('approved','rejected','edited')`).get(uid).c;

  res.json({
    week: {
      key: curWeek,
      start: curWeek,
      end: shiftDays(curWeek, 6),
      planned: ppw,
      ready,
      missing: Math.max(0, ppw - ready),
      by_status: byStatus,
      posts: weekPosts.map((p) => ({
        id: p.id, image_path: p.image_path, caption: p.caption, hashtags: p.hashtags,
        scheduled_at: p.scheduled_at, published_at: p.published_at, status: p.status,
        media_type: p.media_type, ig_permalink: p.ig_permalink, signal: sigMap[p.id] || null,
      })),
    },
    approval: {
      approved, edited, rejected, total: sigTotal,
      approved_rate: sigTotal ? Math.round((approved / sigTotal) * 100) : null,
    },
    weekly,
    month: {
      key: mk,
      published: monthPublished,
      scheduled: monthScheduled,
      hours_saved: Math.round(monthPublished * 1.5 * 10) / 10, // estimado: ~1,5 h por posteo hecho a mano
      hours_saved_total: Math.round(totalPublished * 1.5 * 10) / 10,
    },
    taste_learned: tasteLearned,
  });
});

// Reinicio total: marca (logo, colores, nombre) + posteos pendientes (borradores,
// programados, en publicación). El historial publicado no se toca.
// Se usa al cambiar de cuenta de IG conectada y en el botón manual "Reiniciar todo".
function fullBrandReset(userId) {
  try {
    const logos = db.prepare(`SELECT * FROM assets WHERE user_id=? AND kind='logo'`).all(userId);
    for (const l of logos) { try { fs.unlinkSync(path.join(MEDIA_DIR, path.basename(l.file_path))); } catch (_) {} }
    db.prepare(`DELETE FROM assets WHERE user_id=? AND kind='logo'`).run(userId);
    db.prepare(`UPDATE settings SET brand_colors='', updated_at=datetime('now') WHERE user_id=?`).run(userId);
    db.prepare(`UPDATE profiles SET business_name='' WHERE user_id=?`).run(userId);
    db.prepare(`DELETE FROM posts WHERE user_id=? AND status IN ('draft','scheduled','publishing')`).run(userId);
  } catch (e) { console.error('[brand-reset]', e.message); }
}

// ---------- Instagram OAuth (Instagram Login / Business Login) ----------
// Avatar de un usuario de Instagram (og:image público, con caché de 30 días)
app.get('/api/ig/avatar', requireAuth, async (req, res) => {
  const u = String(req.query.u || '').trim().toLowerCase().replace(/^@+/, '');
  if (!/^[a-z0-9._]{1,30}$/.test(u)) return res.status(400).json({ error: 'Usuario inválido' });
  try {
    const cached = db.prepare("SELECT pic_url, name FROM ig_avatar_cache WHERE username=? AND fetched_at > datetime('now','-30 days')").get(u);
    if (cached && cached.pic_url) return res.json({ username: u, pic_url: cached.pic_url, name: cached.name });
    const ctl = new AbortController();
    const t = setTimeout(() => ctl.abort(), 10000);
    let html = '';
    try {
      const r = await fetch('https://www.instagram.com/' + encodeURIComponent(u) + '/', {
        signal: ctl.signal,
        headers: { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15' },
      });
      html = await r.text();
    } finally { clearTimeout(t); }
    const m = html.match(/<meta property="og:image" content="([^"]+)"/);
    const t2 = html.match(/<meta property="og:title" content="([^"]+)"/);
    let pic = m ? m[1].replace(/&amp;/g, '&') : null;
    // solo avatares reales (scontent); si IG sirvió el muro de login, no cachear
    if (pic && !/scontent[^/]*\.cdninstagram\.com\/v\//.test(pic)) pic = null;
    const nm = t2 ? t2[1].replace(/&amp;/g, '&').split(' on Instagram')[0].split(' • ')[0] : '';
    if (pic) db.prepare('INSERT OR REPLACE INTO ig_avatar_cache (username, pic_url, name, fetched_at) VALUES (?,?,?,datetime(\'now\'))').run(u, pic, nm);
    res.json({ username: u, pic_url: pic, name: nm });
  } catch (e) { res.json({ username: u, pic_url: null }); }
});

// ---------- 🏠 HOME (v331): el perfil literal del cliente ----------
// La home de la app es el perfil de Instagram del cliente TAL CUAL es:
// encabezado fiel (foto, @, nombre, bio, link, conteos) + sus posteos
// reales recientes; las piezas de la semana las compone el cliente
// sobre esta base. Fuente SIN conexión Meta: la lectura pública que
// Posty ya hace del perfil (la misma del fundamento/radiografía:
// feedAudit.fetchAuditData), guardada como snapshot por cuenta y
// refrescada con cadencia de 24 h (la home nunca espera a Instagram:
// snapshot vencido se sirve al instante y refresca en segundo plano).
// REGLA DE VERDAD: lo que la lectura no trae queda null/vacío y la
// home lo omite — jamás un conteo ni un posteo inventado. Las
// destacadas reales NO viajan en la lectura pública (la superficie
// conectada disponible tampoco las expone: getIgProfile solo trae
// username), así que el snapshot las trae vacías y la fila aparece
// solo si alguna fuente futura las puebla. Cuenta sin IG (o sin
// lectura posible todavía): la home cae al kit de nacimiento
// (analysisEngine.profileKit) — el perfil TAL COMO Posty lo propone,
// marcado source:'kit', nunca disfrazado de lectura real.
try {
  db.exec(`CREATE TABLE IF NOT EXISTS ig_home_snapshot (
    user_id INTEGER PRIMARY KEY,
    username TEXT DEFAULT '',
    payload TEXT DEFAULT '',
    fetched_at INTEGER DEFAULT 0
  )`);
} catch (e) {}
const HOME_SNAPSHOT_TTL_MS = 24 * 3600 * 1000;
const homeSnapInFlight = new Map(); // uid -> Promise (un solo refresco por cuenta)

function homeSnapshotGet(uid) {
  try {
    const r = db.prepare('SELECT username, payload, fetched_at FROM ig_home_snapshot WHERE user_id = ?').get(uid);
    if (!r || !r.payload) return null;
    const payload = JSON.parse(r.payload);
    if (!payload || typeof payload !== 'object') return null;
    // Contrato de la home: highlights/recents SIEMPRE arrays (la
    // lectura real nunca trae destacadas; el cliente no adivina).
    if (!Array.isArray(payload.highlights)) payload.highlights = [];
    if (!Array.isArray(payload.recents)) payload.recents = [];
    return { payload, fetched_at: Number(r.fetched_at) || 0 };
  } catch (e) { return null; }
}
function homeSnapshotPut(uid, username, payload) {
  try {
    db.prepare(`INSERT INTO ig_home_snapshot (user_id, username, payload, fetched_at) VALUES (?,?,?,?)
      ON CONFLICT(user_id) DO UPDATE SET username=excluded.username, payload=excluded.payload, fetched_at=excluded.fetched_at`)
      .run(uid, String(username || ''), JSON.stringify(payload || {}), Date.now());
  } catch (e) {}
}
// Proyección de la lectura cruda a la forma de la home: conteos TAL
// CUAL (null si no vinieron), posteos recientes con tipo y fecha
// reales, miniaturas y foto LOCALIZADAS en /media (las URLs de la CDN
// de IG expiran y no se dejan hotlinkear: mismo criterio que /prueba).
async function homeProfileFromRead(handle, data) {
  if (!data || !data.ok || !data.profile) return null;
  const prof = feedAudit.trialProfileFromAudit(data, null);
  if (!prof) return null;
  const posts = (data.posts || []).filter((x) => x && x.thumb);
  const loc = { handle: prof.handle, photos: posts.map((x) => x.thumb) };
  try { await feedAudit.localizeTrialPhotos(loc, MEDIA_DIR); } catch (e) { /* quedan las que haya */ }
  let pic = prof.pic || null;
  if (pic) {
    const lp = { handle: prof.handle, pic };
    try { await feedAudit.localizeTrialPic(lp, MEDIA_DIR); pic = lp.pic || pic; } catch (e) { /* foto como vino */ }
  }
  const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : null);
  return {
    source: 'read',
    username: prof.handle || String(handle || '').replace(/^@/, ''),
    name: prof.name || '',
    pic,
    bio: prof.bio || '',
    bio_unread: !!prof.bio_unread,
    link: prof.link || '',
    followers: num(data.profile.followers),
    posts_count: num(data.profile.posts_count),
    following: num(data.profile.following),
    highlights: [], // la lectura pública no las expone: jamás inventadas
    recents: posts.map((x, i) => ({
      img: (loc.photos && loc.photos[i]) || null,
      type: x.type === 'GraphVideo' ? 'video' : x.type === 'GraphSidecar' ? 'carousel' : 'image',
      taken_at: (typeof x.taken_at === 'number' && x.taken_at > 0) ? x.taken_at : null,
      shortcode: x.shortcode || null,
    })).filter((r) => r.img),
    captured_at: Date.now(),
  };
}
async function homeProfileReadAndStore(uid, handle) {
  const data = await feedAudit.fetchAuditData(handle).catch(() => null);
  const payload = await homeProfileFromRead(handle, data).catch(() => null);
  if (payload) homeSnapshotPut(uid, handle, payload);
  return payload;
}
function homeProfileRefreshOnce(uid, handle) {
  if (homeSnapInFlight.has(uid)) return homeSnapInFlight.get(uid);
  const pr = homeProfileReadAndStore(uid, handle)
    .catch(() => null)
    .finally(() => { homeSnapInFlight.delete(uid); });
  homeSnapInFlight.set(uid, pr);
  return pr;
}
function homeProfileKit(uid, prof) {
  let kit = null;
  try {
    const digest = clientDigest.getDigest(db, uid);
    kit = analysisEngine.profileKit({
      business: { name: (prof && prof.business_name) || '', category: (prof && prof.category) || '', ig_username: (prof && prof.ig_username) || '' },
      digest,
      reviews: null,
      lang: 'es',
    });
  } catch (e) { kit = null; }
  return {
    source: 'kit',
    username: (prof && prof.ig_username || '').replace(/^@/, ''),
    name: (kit && kit.display_name) || (prof && prof.business_name) || '',
    pic: null,
    bio: kit ? (kit.bio_lines || []).join('\n') : '',
    bio_unread: false,
    link: '',
    followers: null, posts_count: null, following: null,
    highlights: kit && Array.isArray(kit.highlights) ? kit.highlights.map((t) => ({ title: String(t), cover: null })) : [],
    recents: [],
    kit_note: kit ? (kit.note || '') : '',
    captured_at: null,
  };
}
app.get('/api/home/profile', requireAuth, async (req, res) => {
  const uid = req.session.userId;
  try {
    const prof = getProfile(uid) || {};
    const handle = String(prof.ig_username || '').replace(/^@+/, '').trim().toLowerCase();
    if (!handle) return res.json({ ok: true, ...homeProfileKit(uid, prof) });
    const snap = homeSnapshotGet(uid);
    if (snap && snap.payload && snap.payload.username === handle) {
      if (Date.now() - snap.fetched_at < HOME_SNAPSHOT_TTL_MS) return res.json({ ok: true, ...snap.payload });
      // Vencido: se sirve al instante y el refresco corre en segundo plano.
      homeProfileRefreshOnce(uid, handle);
      return res.json({ ok: true, ...snap.payload });
    }
    // Primera lectura de esta cuenta (o cambió el @): se intenta en
    // línea con presupuesto corto; si Instagram no responde a tiempo,
    // la home cae al kit (sin inventar nada) y la lectura sigue en
    // segundo plano para la próxima entrada.
    let payload = null;
    try {
      payload = await Promise.race([
        homeProfileRefreshOnce(uid, handle),
        new Promise((r) => setTimeout(() => r(null), 6000)),
      ]);
    } catch (e) { payload = null; }
    if (payload) return res.json({ ok: true, ...payload });
    return res.json({ ok: true, ...homeProfileKit(uid, prof), pending_read: true });
  } catch (e) {
    res.json({ ok: false, error: 'home_profile' });
  }
});
// Prepara el OAuth de Instagram: valida la Embed URL, guarda state en sesión
// y devuelve la URL de autorización de Meta.
// IMPORTANTE iOS: el frontend NO navega directo a instagram.com (iOS lo sacaría
// a la app de Instagram y el regreso a Posta se pierde). En su lugar va a
// /api/ig/go, que hace 302 al authorize: los universal links solo actúan en taps
// del usuario, no en redirects del servidor, así el ida y vuelta queda en Safari
// y vuelve solo a Posta. Vale también para desktop.
function buildIgAuth(req) {
  const s = getSettings(req.session.userId);
  // (v343) Precedencia GLOBAL primero: la Embed URL de entorno manda
  // sobre la guardada por usuario — una ig_embed_url vieja (o el env
  // con un dominio retirado) dejaba a TODOS sin poder conectar.
  const embedUrl = process.env.META_IG_EMBED_URL || process.env.IG_EMBED_URL || s.ig_embed_url;
  if (!embedUrl)
    return { error: 'Configurá tu Instagram Embed URL en Ajustes' };
  // (v343) El redirect_uri se FUERZA al host actual de Posty: de la
  // Embed URL solo se heredan client_id/scope/permisos. El valor en
  // fuerza apuntaba a www.postahacetodo.com (dominio retirado) y el
  // chequeo de host rechazaba el arranque para cada cliente; con el
  // override, cualquier Embed URL vieja queda neutralizada y el
  // callback vuelve siempre a ESTE host (ambos dominios vigentes
  // están en la whitelist de Meta). La sesión guarda el mismo URI
  // para el intercambio del code en /api/ig/callback.
  const host = req.get('host');
  const redirectUri = `${host.startsWith('localhost') ? 'http' : 'https'}://${host}/api/ig/callback`;
  let authUrl = embedUrl;
  try {
    const u = new URL(embedUrl);
    u.searchParams.set('redirect_uri', redirectUri);
    authUrl = u.toString();
  } catch (e) {
    return { error: 'La Embed URL no es válida. Revisala en Ajustes \u2192 Integraciones.' };
  }
  const state = crypto.randomBytes(16).toString('hex');
  req.session.igState = state;
  req.session.igRedirect = redirectUri;
  // Destino post-conexión (solo rutas internas de la app, anti open-redirect)
  const nx = String(req.query.next || '');
  if (/^\/#\/[^\s"'\\<>]*$/.test(nx)) req.session.igNext = nx;
  else delete req.session.igNext;
  return { url: getAuthUrl(authUrl, state) };
}
app.get('/api/ig/start', requireAuth, (req, res) => {
  const r = buildIgAuth(req);
  if (r.error) return res.status(400).json({ error: r.error });
  res.json({ url: r.url });
});
// Bounce del OAuth: el navegador llega a instagram.com vía 302 del servidor
// (no saca a la app de Instagram) y el callback vuelve solo a Posta.
app.get('/api/ig/go', requireAuth, (req, res) => {
  const r = buildIgAuth(req);
  if (r.error) {
    const safe = String(r.error).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    return res.status(400).send(`<!doctype html><html lang="es"><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="font-family:system-ui;padding:32px;text-align:center"><h2>No se pudo iniciar la conexión</h2><p>${safe}</p><p><a href="/#/app/ajustes">\u2190 Volver a Posta</a></p></body></html>`);
  }
  // Marca el intento: si Instagram deja al usuario varado en el feed (login +
  // verificación que pierde el contexto OAuth), al volver a Posta mostramos el
  // banner 'terminar de conectar' (ig_pending) por 15 minutos.
  req.session.igAttemptAt = Date.now();
  res.redirect(r.url);
});

app.get('/api/ig/callback', async (req, res) => {
  const { code, state, error, error_description } = req.query;
  // Destino post-OAuth: si el flujo empezó en una pantalla con ?next=, volvemos ahí
  const igDest = () => {
    const n = req.session.igNext;
    delete req.session.igNext;
    return (typeof n === 'string' && /^\/#\/[^\s"'\\<>]*$/.test(n)) ? n : '/#/app/ajustes';
  };
  const withQs = (base, qs) => base + (base.includes('?') ? '&' : '?') + qs;
  // Meta puede redirigir con error (permiso denegado, rol insuficiente, etc.)
  if (error) {
    const msg = /access_denied|user_denied/i.test(error)
      ? 'Denegaste el acceso a Instagram. Probá de nuevo y tocá "Permitir".'
      : (error_description || error);
    return res.redirect(withQs(igDest(), 'ig=error&msg=' + encodeURIComponent(msg)));
  }
  if (!req.session.userId || state !== req.session.igState) return res.status(400).send(htmlLinkPage('La conexión venció 😅', 'Volvé a Posty y conectá tu cuenta de nuevo desde Ajustes → Conexiones.'));
  try {
    const s = getSettings(req.session.userId);
    const appId = s.meta_app_id || process.env.IG_APP_ID || process.env.META_APP_ID;
    const appSecret = s.meta_app_secret || process.env.IG_APP_SECRET || process.env.META_APP_SECRET;
    const { accessToken, igUserId } = await exchangeCodeForTokens(
      appId,
      appSecret,
      req.session.igRedirect,
      code
    );
    let username = '', accountType = '', finalIgId = igUserId;
    try {
      const prof = await getIgProfile(igUserId, accessToken);
      username = prof.username; accountType = prof.accountType;
      if (prof.userId) finalIgId = prof.userId;
    } catch (e) { console.error('[ig/callback] getIgProfile:', e.message); }
    // Solo las cuentas profesionales (Business/Creator) pueden publicar vía API
    if (/personal/i.test(accountType || '')) {
      return res.redirect(withQs(igDest(), 'ig=personal'));
    }
    // Un Instagram = una sola cuenta ACTIVA a la vez en Posta
    const dupe = finalIgId ? db.prepare(`SELECT user_id FROM settings WHERE ig_user_id = ? AND user_id != ?`).get(finalIgId, req.session.userId) : null;
    if (dupe) {
      return res.redirect(withQs(igDest(), 'ig=error&msg=' + encodeURIComponent('Esta cuenta de Instagram ya está vinculada a otra cuenta de Posta.')));
    }
    // Si el IG se usó antes en otra cuenta pero ya no está conectado a nadie
    // (el dupe-check de arriba lo garantiza), se permite la transferencia y el
    // registro pasa al nuevo dueño. La prueba gratis sigue siendo por usuario.
    const usedBefore = finalIgId ? db.prepare(`SELECT first_user_id FROM ig_registry WHERE ig_user_id = ?`).get(finalIgId) : null;
    if (usedBefore && usedBefore.first_user_id !== req.session.userId) {
      db.prepare(`UPDATE ig_registry SET first_user_id = ?, first_seen_at = datetime('now') WHERE ig_user_id = ?`).run(req.session.userId, finalIgId);
    }
    const s0 = getSettings(req.session.userId);
    const wasDemo = !!s0.demo_mode;
    const prevIgId = String(s0.ig_user_id || s0.last_ig_user_id || '');
    db.prepare(
      `UPDATE settings SET ig_user_id=?, ig_page_id='', ig_access_token=?, ig_token_issued_at=datetime('now'), ig_token_warning=0, demo_mode=0, updated_at=datetime('now') WHERE user_id=?`
    ).run(finalIgId, accessToken, req.session.userId);
    // Si cambió la cuenta de IG: la marca y los posteos pendientes eran de otro negocio → reset total
    let brandReset = false;
    if (prevIgId && finalIgId && prevIgId !== String(finalIgId)) {
      fullBrandReset(req.session.userId);
      db.prepare(`UPDATE settings SET last_ig_user_id='' WHERE user_id=?`).run(req.session.userId);
      brandReset = true;
    }
    // Registro permanente del uso (sobrevive a desconexiones)
    try {
      db.prepare(`INSERT OR IGNORE INTO ig_registry (ig_user_id, first_user_id) VALUES (?, ?)`).run(finalIgId, req.session.userId);
    } catch (e) { /* no bloquea la conexión */ }
    db.prepare(`UPDATE profiles SET ig_username=?, ig_connected=1 WHERE user_id=?`).run(username, req.session.userId);
    // Análisis de su Instagram en background: la IA los conoce desde el día uno. Nunca bloquea la conexión.
    try {
      const { analyzeInstagram } = require('./instagram');
      analyzeInstagram(finalIgId, accessToken)
        .then(r => {
          if (r && r.summary) {
            try {
              db.prepare(`INSERT INTO ig_analysis (user_id, summary, updated_at) VALUES (?, ?, datetime('now'))
                ON CONFLICT(user_id) DO UPDATE SET summary=excluded.summary, updated_at=datetime('now')`)
                .run(req.session.userId, String(r.summary).slice(0, 4000));
            } catch (e) { console.error('[ig] analysis save:', e.message); }
          }
        })
        .catch(e => console.error('[ig] analyze:', e.message));
    } catch (e) { console.error('[ig] analyze:', e.message); }
    // Style Lock visual + Caption Style Lock + Brief unificado: analizan el IG en
    // background al conectar. El brief se reconstruye cuando terminan ambos
    // análisis (los resume en una sola fuente de verdad). Nunca bloquea la conexión.
    try {
      const uidCb = req.session.userId;
      const vP = analyzeVisualStyle(db, uidCb);
      vP.catch(e => console.error('[ig] style-visual:', e.message));
      const cP = analyzeCaptionStyle(db, uidCb);
      cP.catch(e => console.error('[ig] caption-style:', e.message));
      Promise.allSettled([vP, cP]).then(() => {
        try { refreshClientBrief(db, uidCb).catch(e => console.error('[ig] client-brief:', e.message)); }
        catch (e) { console.error('[ig] client-brief:', e.message); }
      });
    } catch (e) { console.error('[ig] client-brief:', e.message); }
    track(req.session.userId, 'ig_connected');
    evTrack(req.session.userId, 'ig_connect', {});
    delete req.session.igAttemptAt; // conectado: no más banner pendiente
    res.redirect(withQs(igDest(), 'ig=ok' + (wasDemo ? '&demo_off=1' : '') + (brandReset ? '&brand_reset=1' : '')));
  } catch (e) {
    res.redirect(withQs(igDest(), 'ig=error&msg=' + encodeURIComponent(e.message)));
  }
});

// Track B: análisis profundo de Instagram ("Conocer al cliente a fondo").
// Corre analyzeInstagramDeep con las credenciales guardadas y guarda los learnings
// en content_learnings. Nunca devuelve 500: errores → {ok:false, reason}.
app.post('/api/ig/analyze', requireAuth, async (req, res) => {
  try {
    const s = getSettings(req.session.userId);
    if (!s.ig_user_id || !s.ig_access_token) return res.json({ ok: false, reason: 'no_ig' });
    const { analyzeInstagramDeep } = require('./instagram');
    const r = await analyzeInstagramDeep(s.ig_user_id, s.ig_access_token);
    if (r && r.learnings) {
      try {
        db.prepare(`INSERT INTO content_learnings (user_id, learnings_json, updated_at) VALUES (?, ?, datetime('now'))
          ON CONFLICT(user_id) DO UPDATE SET learnings_json=excluded.learnings_json, updated_at=datetime('now')`)
          .run(req.session.userId, JSON.stringify(r.learnings));
      } catch (e) { console.error('[ig/analyze] save:', e.message); }
      return res.json({ ok: true, learnings: r.learnings });
    }
    return res.json({ ok: false, reason: 'no_data' });
  } catch (e) {
    console.error('[ig/analyze]:', e.message);
    return res.json({ ok: false, reason: 'error' });
  }
});

// Relee el perfil de IG con el token guardado (rellena el username si quedó vacío)
app.get('/api/ig/sync', requireAuth, async (req, res) => {
  try {
    const s = getSettings(req.session.userId);
    if (!s.ig_user_id || !s.ig_access_token) return res.status(400).json({ error: 'Sin cuenta conectada' });
    const prof = await getIgProfile(s.ig_user_id, s.ig_access_token);
    if (prof.userId && prof.userId !== s.ig_user_id) {
      db.prepare(`UPDATE settings SET ig_user_id=? WHERE user_id=?`).run(prof.userId, req.session.userId);
    }
    db.prepare(`UPDATE profiles SET ig_username=?, ig_connected=1 WHERE user_id=?`).run(prof.username, req.session.userId);
    res.json({ ok: true, username: prof.username, accountType: prof.accountType });
  } catch (e) {
    console.error('[ig/sync]:', e.message);
    res.status(400).json({ error: e.message });
  }
});

app.post('/api/ig/disconnect', requireAuth, (req, res) => {
  // Guardamos cuál IG estaba conectado: si después conecta otro distinto, se detecta
  // el cambio y se reinician marca + posteos pendientes (eran de otro negocio).
  db.prepare(`UPDATE settings SET last_ig_user_id=ig_user_id, ig_user_id='', ig_page_id='', ig_access_token='' WHERE user_id=?`).run(req.session.userId);
  db.prepare(`UPDATE profiles SET ig_connected=0 WHERE user_id=?`).run(req.session.userId);
  res.json({ ok: true });
});

// ---------- TikTok: conectar y compartir posteos (v1, siempre a pedido) ----------
// Sin TIKTOK_CLIENT_KEY/SECRET en el entorno, todo queda inerte y la UI lo
// muestra como "próximamente". Publicar es SIEMPRE a pedido del usuario desde
// un posteo existente; sin la auditoría de Direct Post de TikTok, lo que sale
// queda en privado (SELF_ONLY) — el módulo respeta lo que creator_info ofrece.
const tiktok = require('./tiktok');
const google = require('./google');
const tiendanube = require('./tiendanube');
const tnWebhooks = require('./tiendanube-webhooks');
const tnInstall = require('./tn-install');

app.get('/api/tiktok/status', requireAuth, (req, res) => {
  const acc = tiktok.getAccount(db, req.session.userId);
  res.json({
    configured: tiktok.configured(),
    connected: !!acc,
    username: acc ? (acc.username || '') : '',
  });
});

app.get('/api/tiktok/connect', requireAuth, (req, res) => {
  if (!tiktok.configured()) {
    return res.status(503).send(`<!doctype html><html lang="es"><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="font-family:system-ui;padding:32px;text-align:center"><h2>🎵 TikTok llega en poquito</h2><p>Estamos terminando la conexión con TikTok. Cuando esté lista, vas a poder compartir tus posteos ahí con un toque.</p><p><a href="/#/app/ajustes">← Volver a Posty</a></p></body></html>`);
  }
  const host = req.get('host');
  const redirectUri = `${host.startsWith('localhost') ? 'http' : 'https'}://${host}/api/tiktok/callback`;
  const state = crypto.randomBytes(16).toString('hex');
  req.session.ttState = state;
  req.session.ttRedirect = redirectUri;
  res.redirect(tiktok.buildAuthUrl(redirectUri, state));
});

app.get('/api/tiktok/callback', async (req, res) => {
  const dest = '/#/app/ajustes';
  const { code, state, error, error_description } = req.query;
  if (error) {
    const msg = /access_denied|user_denied/i.test(error)
      ? 'Denegaste el acceso a TikTok. Probá de nuevo y tocá "Autorizar".'
      : (error_description || 'TikTok no autorizó la conexión. Probá de nuevo.');
    return res.redirect(dest + '?tiktok=error&msg=' + encodeURIComponent(msg));
  }
  if (!req.session.userId || !state || state !== req.session.ttState) return res.status(400).send(htmlLinkPage('La conexión venció 😅', 'Volvé a Posty y conectá tu cuenta de nuevo desde Ajustes → Conexiones.'));
  try {
    const tok = await tiktok.exchangeCode(code, req.session.ttRedirect);
    let username = '';
    try {
      const u = await tiktok.fetchUserInfo(tok.access_token);
      username = u.username || u.display_name || '';
    } catch (e) { console.error('[tiktok/callback] user/info:', e.message); }
    // Una cuenta de TikTok = una sola cuenta de Posty activa a la vez.
    if (tok.open_id) {
      const dupe = db.prepare('SELECT user_id FROM tiktok_accounts WHERE tiktok_user_id = ? AND user_id != ?').get(tok.open_id, req.session.userId);
      if (dupe) return res.redirect(dest + '?tiktok=error&msg=' + encodeURIComponent('Esa cuenta de TikTok ya está conectada a otra cuenta de Posty.'));
    }
    tiktok.saveAccount(db, req.session.userId, tok, username);
    try { track(req.session.userId, 'tiktok_connected'); } catch (e) {}
    return res.redirect(dest + '?tiktok=ok');
  } catch (e) {
    console.error('[tiktok/callback]', e.message);
    return res.redirect(dest + '?tiktok=error&msg=' + encodeURIComponent('No pudimos conectar tu TikTok 😅 Probá de nuevo.'));
  }
});

app.post('/api/tiktok/disconnect', requireAuth, (req, res) => {
  tiktok.deleteAccount(db, req.session.userId);
  res.json({ ok: true });
});

app.post('/api/tiktok/publish/:postId', requireAuth, async (req, res) => {
  try {
    const post = db.prepare('SELECT * FROM posts WHERE id = ? AND user_id = ?').get(req.params.postId, req.session.userId);
    if (!post) return res.status(404).json({ error: 'Ese posteo no aparece 😅 Actualizá y probá de nuevo.' });
    if (!tiktok.configured()) return res.status(503).json({ error: 'TikTok todavía no está activo en Posty. ¡Falta poquito! 🎵' });
    if (!tiktok.getAccount(db, req.session.userId)) return res.status(400).json({ error: 'Conectá tu TikTok en Ajustes primero 🎵' });
    if (post.tiktok_publish_id) return res.status(409).json({ error: 'Ese posteo ya lo compartiste en TikTok 🎵' });
    if (!post.image_path) return res.status(400).json({ error: 'Ese posteo todavía no tiene imagen o video para compartir.' });
    const accessToken = await tiktok.getValidToken(db, req.session.userId);
    if (!accessToken) return res.status(400).json({ error: 'Tu conexión con TikTok venció. Reconectala en Ajustes 🎵' });
    const base = (process.env.BASE_URL || 'https://postycommunitymanager.com').replace(/\/$/, '');
    const abs = (p) => /^https?:\/\//i.test(p) ? p : base + (p.startsWith('/') ? p : '/' + p);
    const cap = String(post.caption || '').trim();
    const tags = String(post.hashtags || '').trim();
    const fullText = [cap, tags].filter(Boolean).join('\n');
    const mt = String(post.media_type || 'image');
    let out;
    if (mt === 'video' || /\.mp4($|\?)/i.test(post.image_path)) {
      out = await tiktok.publishVideo({ accessToken, videoUrl: abs(post.image_path), title: fullText || 'Posteo de mi negocio' });
    } else {
      let paths = [post.image_path];
      if (mt === 'carousel' && post.carousel_paths) {
        try { const arr = JSON.parse(post.carousel_paths); if (Array.isArray(arr) && arr.length) paths = arr.map(String); } catch (e) { /* queda la portada */ }
      }
      if (/\.png($|\?)/i.test(paths[0])) {
        return res.status(400).json({ error: 'TikTok no acepta imágenes PNG 😅 Este posteo tiene un formato viejo: regenerá la imagen y probá de nuevo.' });
      }
      const firstLine = (cap.split('\n')[0] || 'Mi negocio').slice(0, 90);
      out = await tiktok.publishPhoto({ accessToken, imageUrls: paths.map(abs), title: firstLine, description: fullText });
    }
    db.prepare('UPDATE posts SET tiktok_publish_id = ? WHERE id = ?').run(out.publishId, post.id);
    // Verificación diferida del estado real: TikTok procesa asincrónico y
    // publishStatus no tenía NINGÚN consumidor — un posteo rechazado del
    // lado de TikTok quedaba "compartido" para siempre y el reintento daba
    // 409. Si falló: se limpia el id (reintento posible) y se avisa al dueño.
    {
      const uidTk = req.session.userId, pidTk = post.id, pubTk = out.publishId;
      const checkTk = (delay, triesLeft) => {
        setTimeout(async () => {
          try {
            const tok = await tiktok.getValidToken(db, uidTk);
            if (!tok) return;
            const st = await tiktok.publishStatus(tok, pubTk);
            const status = String((st && st.status) || '');
            if (/FAIL|ERROR/i.test(status)) {
              try { db.prepare('UPDATE posts SET tiktok_publish_id = NULL WHERE id = ? AND tiktok_publish_id = ?').run(pidTk, pubTk); } catch (e) {}
              try { db.prepare(`INSERT INTO chat_messages (user_id, role, text) VALUES (?, 'assistant', ?)`).run(uidTk, `🎵 Uy — TikTok no pudo publicar ese posteo${st.failReason ? ' (' + String(st.failReason).slice(0, 120) + ')' : ''}. Ya lo destrabé: podés compartirlo de nuevo desde el posteo.`); } catch (e) {}
              console.error('[tiktok/publish] verificación: post', pidTk, 'falló en TikTok:', status, (st && st.failReason) || '');
            } else if (!/COMPLETE|PUBLISHED/i.test(status) && triesLeft > 0) {
              checkTk(120000, triesLeft - 1);
            }
          } catch (e) { console.error('[tiktok/publish] verificación:', e.message); }
        }, delay);
      };
      checkTk(60000, 3);
    }
    try { track(req.session.userId, 'tiktok_publish'); } catch (e) {}
    res.json({
      ok: true, publish_id: out.publishId, privacy_level: out.privacyLevel,
      message: out.privacyLevel === 'SELF_ONLY'
        ? '🎵 ¡Listo! Tu posteo se está publicando en TikTok. Por ahora sale en privado, hasta que TikTok apruebe nuestra app.'
        : '🎵 ¡Listo! Tu posteo se está publicando en TikTok.',
    });
  } catch (e) {
    console.error('[tiktok/publish]', e.message);
    res.status(502).json({ error: 'TikTok no pudo recibir el posteo 😅 ' + String(e.message || '').slice(0, 140) });
  }
});

// Enviar un REEL a la bandeja de TikTok del dueño (scope video.upload):
// le llega a su cuenta para terminar de publicarlo desde la app de
// TikTok, cuando quiera. No depende de la auditoría de Direct Post ni
// fija privacidad: decide el dueño en su TikTok. Siempre a pedido, sobre
// un posteo ya existente — nunca automático ni programado.
app.post('/api/tiktok/inbox/:postId', requireAuth, async (req, res) => {
  try {
    const post = db.prepare('SELECT * FROM posts WHERE id = ? AND user_id = ?').get(req.params.postId, req.session.userId);
    if (!post) return res.status(404).json({ error: 'Ese posteo no aparece 😅 Actualizá y probá de nuevo.' });
    if (!tiktok.configured()) return res.status(503).json({ error: 'TikTok todavía no está activo en Posty. ¡Falta poquito! 🎵' });
    if (!tiktok.getAccount(db, req.session.userId)) return res.status(400).json({ error: 'Conectá tu TikTok en Ajustes primero 🎵' });
    const mt = String(post.media_type || 'image');
    const isVideo = mt === 'video' || /\.mp4($|\?)/i.test(String(post.image_path || ''));
    if (!post.image_path || !isVideo) return res.status(400).json({ error: 'El borrador de TikTok es solo para reels 🎬 Ese posteo no es un video.' });
    const accessToken = await tiktok.getValidToken(db, req.session.userId);
    if (!accessToken) return res.status(400).json({ error: 'Tu conexión con TikTok venció. Reconectala en Ajustes 🎵' });
    const base = (process.env.BASE_URL || 'https://postycommunitymanager.com').replace(/\/$/, '');
    const abs = (p) => /^https?:\/\//i.test(p) ? p : base + (p.startsWith('/') ? p : '/' + p);
    const out = await tiktok.publishVideoInbox({ accessToken, videoUrl: abs(post.image_path) });
    try { track(req.session.userId, 'tiktok_inbox'); } catch (e) {}
    res.json({ ok: true, publish_id: out.publishId, message: '📥 ¡Listo! Te mandé el reel a tu TikTok: abrí la app y tocá la notificación en tu bandeja — el video ya está ahí para publicarlo cuando quieras.' });
  } catch (e) {
    console.error('[tiktok/inbox]', e.message);
    res.status(502).json({ error: 'TikTok no pudo recibir el reel 😅 ' + String(e.message || '').slice(0, 140) });
  }
});

