    const name = `${stamp}-u${uid || 0}-p${postId || 0}-${String(gate || 'qa').replace(/[^a-z0-9-]/gi, '')}.jpg`;
    fs.writeFileSync(path.join(QA_FAILED_DIR, name), buf);
