    dnaBits: dnaBitsLine(dna),
    learningsLine: learningsLineOf(getContentLearnings(uid)),
    memoryLine: [topStyleMemoryLine(uid), clientTasteLine(uid), monthlyGoalLine(uid)].filter(Boolean).join(' '),
