// Llave de prueba del dueño: con ?test_key=... se saltea el límite de 1 prueba
// por IP y no se registra el uso. La llave vive en Railway (variable
// TRIAL_TEST_KEY), nunca en el código ni en el repo.
function trialTestMode(req) {
  const k = process.env.TRIAL_TEST_KEY || '';
  return !!(k && req.query && req.query.test_key === k);
}

// (v274 · MODO EN) Días/meses de la semana según el idioma de la prueba:
// EN → Sunday…Saturday y formato "Oct 21"; ES → el histórico rioplatense.
function buildTrialWeek(n, lang) {
  const en = lang === 'en';
  const days = en
    ? ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
    : ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
  const months = en
    ? ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
    : ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
  const now = new Date();
  // (v323 · pieza 2) Horario PROPUESTO por posteo: la agenda mini de la
  // prueba muestra día, fecha y hora. Son los horarios fuertes habituales
  // de Instagram en rotación (propuesta de Posty, no un dato del visitante);
  // con la cuenta conectada manda su mejor hora real, como siempre.
  const hours = en
    ? ['12:30 PM', '7:00 PM', '8:30 PM', '11:00 AM', '7:30 PM', '1:00 PM']
    : ['12:30', '19:00', '20:30', '11:00', '19:30', '13:00'];
  return Array.from({ length: n }, (_, i) => {
    const d = new Date(now.getTime() + (i + 1) * 86400000);
    return {
      day: days[d.getDay()],
      date: en ? `${months[d.getMonth()]} ${d.getDate()}` : `${d.getDate()} ${months[d.getMonth()]}`,
      hour: hours[i % hours.length],
      post: i,
    };
  });
}

const TRIAL_IMG_MIME = { jpeg: 'image/jpeg', jpg: 'image/jpeg', png: 'image/png', webp: 'image/webp' };

// ---------- (v323 · piezas 8+13) CANDADO DE PRUEBA 90 DÍAS + ESCUDO ANTI-BOTS ----------
// Pieza 8: un mismo negocio (@ o dominio normalizados) no regenera una
// prueba por 90 días; la vuelta recibe su snapshot ("tu semana sigue acá")
// o el mensaje amable con la fecha exacta. Módulo: trial-lock.js (la
// allowlist interna/QA vive ahí + tabla trial_lock_allowlist).
let trialLock = null;
try { trialLock = require('./trial-lock'); } catch (e) { console.error('[init] trial-lock no disponible:', e.message); }

// Identidad del negocio para el candado, desde los campos crudos del form
// (la normalización robusta vive en el módulo: URL pegada, mayúsculas, @).
function trialLockGate(fields, webData, testMode) {
  try {
    if (!trialLock || testMode) return null;
    const igK = trialLock.normalizeIg((fields && fields.ig) || '');
    let domK = trialLock.normalizeDomain((fields && fields.web) || '');
    if (!domK && webData && webData.url) domK = trialLock.normalizeDomain(webData.url);
    if (!igK && !domK) return null;
    const lock = trialLock.findLock(db, igK, domK);
    if (!lock) return null;
    track(null, 'prueba_lock', (igK || domK) + '|' + (lock.payload ? 'snapshot' : 'mensaje'));
    return { lock, igK, domK };
  } catch (e) { return null; }
}

// Sirve el snapshot del candado decorado (banderas del candado + semana y
// lugares frescos) y rehidrata el trial_cache: chat, rediseño y lead-email
// vuelven a funcionar sobre la semana servida sin gastar IA.
function trialLockServePayload(lock) {
  if (!lock || !lock.payload) return null;
  let out = null;
  try { out = JSON.parse(lock.payload); } catch (e) { return null; }
  out = trialLock.decorateSnapshot(lock, out, { spotsLeft, buildWeek: buildTrialWeek });
  if (out && lock.ig) {
    try {
      db.prepare(`INSERT INTO trial_cache (ig, payload, created_at) VALUES (?, ?, ?)
        ON CONFLICT(ig) DO UPDATE SET payload=excluded.payload, created_at=excluded.created_at`)
        .run(lock.ig, JSON.stringify(out), Date.now());
    } catch (e) { /* la semana se sirve igual */ }
  }
  return out;
}

// Nace el candado de una generación recién producida (junto al trial_cache).
function trialLockRecordFor(fields, webData, business, lang, out) {
  try {
    if (!trialLock) return;
    trialLock.recordLock(db, {
      ig: trialLock.normalizeIg((fields && fields.ig) || ''),
      domain: trialLock.normalizeDomain((fields && fields.web) || '') || (webData ? trialLock.normalizeDomain(webData.url || '') : ''),
      business, lang, payloadStr: JSON.stringify(out),
    });
  } catch (e) { /* el candado nunca rompe la generación */ }
}

// Pieza 13 · ESCUDO INVISIBLE ANTI-BOTS (cero fricción visible, nada de
// captchas — regla cero trabas): (a) honeypot silencioso: el form trae un
// campo trampa que ningún humano ve ni completa; si viene lleno, es un bot
// → se corta con un error genérico y el bloqueo queda como evento;
// (b) tope por hora y por IP en el INICIO de generación (el de 5/día ya
// existe): una IP sana jamás llega a 20 arranques por hora.
try { db.exec('CREATE TABLE IF NOT EXISTS trial_gen_usage (ip TEXT, hour TEXT, count INTEGER DEFAULT 0, PRIMARY KEY (ip, hour))'); } catch (e) {}
const TRIAL_GEN_HOURLY = 20;
function trialGenHourlyAllowed(ip) {
  const hour = new Date().toISOString().slice(0, 13);
  try {
    if (Math.random() < 0.05) db.exec(`DELETE FROM trial_gen_usage WHERE hour < strftime('%Y-%m-%dT%H', 'now', '-48 hours')`);
    const row = db.prepare('SELECT count FROM trial_gen_usage WHERE ip = ? AND hour = ?').get(ip, hour);
    if (row && row.count >= TRIAL_GEN_HOURLY) return false;
    db.prepare('INSERT INTO trial_gen_usage (ip, hour, count) VALUES (?, ?, 1) ON CONFLICT(ip, hour) DO UPDATE SET count = count + 1').run(ip, hour);
    return true;
  } catch (e) { return true; }
}
function trialHoneypotHit(fields) {
  return !!(fields && String(fields.hp_empresa || '').trim());
}

// (v323 · pieza 19) SU COMPETENCIA EN UNA LÍNEA: datos para UNA línea de
// contraste REAL arriba de los resultados — cadencia propia vs la de los
// pares LEÍDOS de su zona/rubro (los que el análisis ya leyó). Sin pares
// con cadencia medida o sin cadencia propia, devuelve null y la línea NO
// sale (regla de verdad: jamás un número inventado). El tono lo pone el
// frontend: el hueco como oportunidad, nunca como reto.
function trialCompetitionLine(rawAnalysis) {
  try {
    const m = rawAnalysis && rawAnalysis.market;
    const own = rawAnalysis && rawAnalysis.signals ? rawAnalysis.signals.posts_per_week : null;
    if (!m || !m.available || own == null) return null;
    const peers = (m.peers || []).filter(p => p && p.posts_per_week != null && p.handle);
    if (!peers.length) return null;
    const rates = peers.map(p => p.posts_per_week).slice().sort((a, b) => a - b);
    const median = rates[Math.floor(rates.length / 2)];
    const top = peers.reduce((a, b) => (b.posts_per_week > a.posts_per_week ? b : a), peers[0]);
    return {
      own_rate: own,
      peer_median: median,
      peer_handle: top.handle,
      peer_rate: top.posts_per_week,
      peers_n: peers.length,
    };
  } catch (e) { return null; }
}

// La semana cacheada por @ solo vale si se generó para ESTE negocio y rubro.
// Sin este chequeo, una prueba vieja de otro negocio con el mismo @ se servía
// e importaba verbatim: marca, fotos y textos ajenos en la semana del cliente
// (bug 2026-10-03: posteos "FITSWAPP" en la cuenta de otro negocio).
function trialCacheMatches(out, business, category, lang) {
  try {
    // Motor de la prueba (v182): una semana generada por un motor viejo NO
    // se sirve desde el cache — se regenera con el motor actual.
    if (!out || Number(out.engine || 0) !== demo.DEMO_ENGINE_V) return false;
    // (v274) El idioma TAMBIÉN es parte de la identidad de la semana: una
    // semana ES cacheada jamás se sirve a un visitante EN (ni al revés).
    if (lang && String(out.lang || 'es') !== String(lang)) return false;
    const b = String((out && out.business) || '').trim().toLowerCase();
    const want = String(business || '').trim().toLowerCase();
    if (!b || !want || b !== want) return false;
    const c = String((out && out.category) || '').trim().toLowerCase();
    const wantC = String(category || '').trim().toLowerCase();
    if (wantC && c && c !== wantC) return false;
    return true;
  } catch (e) { return false; }
}

app.post('/api/trial/generate', express.raw({ type: 'multipart/form-data', limit: '6mb' }), async (req, res) => {
  let fields, file;
  try {
    ({ fields, file } = demo.parseMultipart(req, req.body));
  } catch (e) {
    return res.status(400).json({ error: e.message || 'Formulario inválido' });
  }
  // (v323 · pieza 13) Honeypot silencioso: si el campo trampa viene lleno,
  // es un bot — corte genérico + evento, sin gastar ni un fetch más.
  if (trialHoneypotHit(fields)) {
    track(null, 'prueba_bot_block', 'honeypot');
    return res.status(400).json({ error: 'No pudimos armar tu prueba ahora. Probá de nuevo en unos minutos.' });
  }
  let business = String(fields.business || '').trim().slice(0, 60);
  const ig = String(fields.ig || '').trim().replace(/^@/, '').replace(/[^a-zA-Z0-9._]/g, '').slice(0, 40);
  // (v212) La web del negocio (si pegó su link): la extracción determinística
  // arranca YA, en paralelo con el resto; se consume con carrera acotada.
  const webRaw = String(fields.web || '').trim().slice(0, 300);
  const webDescEdited = String(fields.web_desc || '').replace(/<[^>]*>/g, '').trim().slice(0, 400);
  const webCtxPromise = webRaw ? trialWebContext(webRaw) : Promise.resolve(null);
  const category = String(fields.category || '').trim();
  const country = String(fields.country || '').trim().toUpperCase();
  const tone = String(fields.tone || 'vos').trim().toLowerCase();
  // (v274 · MODO EN) Idioma de la prueba: 'en' solo si el funnel EN lo
  // declara; cualquier otro valor (o su ausencia) = 'es', el histórico.
  // Con lang 'en' el país efectivo es US (hashtags y calendario US).
  const lang = String(fields.lang || '').trim().toLowerCase() === 'en' ? 'en' : 'es';
  const effCountry = lang === 'en' ? 'US' : country;
  // (v323 · pieza 8) CANDADO 90 DÍAS — chequeo TEMPRANO, antes de leer el
  // IG/web y de validar el form: si este negocio ya produjo su prueba, la
  // vuelta es su snapshot (o el 409 amable con la fecha exacta), sin
  // gastar nada y sin depender de que el formulario venga completo.
  if (!trialTestMode(req)) {
    const gate = trialLockGate(fields, null, false);
    if (gate) {
      const snap = trialLockServePayload(gate.lock);
      if (snap) return res.json(snap);
      return res.status(409).json({
        error: trialLock.lockMessage(gate.lock, lang),
        trial_locked: true,
        generated_at: gate.lock.generated_at,
        unlock_at: gate.lock.unlock_at,
      });
    }
  }
  const goal = String(fields.goal || '').replace(/<[^>]*>/g, '').trim().slice(0, 400);
  const competitors = String(fields.competitors || '').replace(/<[^>]*>/g, '').trim().slice(0, 200);
  // Preguntas previas de /prueba (opcionales): objetivo + producto + diferencial.
  // Se suman a la descripción para que ideas y posteos salgan a medida.
  const goal_key = ['vender', 'seguidores', 'lanzamiento', 'fidelizar'].includes(String(fields.goal_key || '').trim())
    ? String(fields.goal_key).trim() : '';
  const producto = String(fields.producto || '').replace(/<[^>]*>/g, '').trim().slice(0, 120);
  const diferencial = String(fields.diferencial || '').replace(/<[^>]*>/g, '').trim().slice(0, 200);
  let richGoal = [goal, producto && ((lang === 'en' ? 'Main product: ' : 'Producto principal: ') + producto), diferencial && ((lang === 'en' ? 'What makes you different: ' : 'Diferencial: ') + diferencial)].filter(Boolean).join('\n');
  // Colores: si el visitante mandó (ya no se pide en el form), se usan; si no,
  // intentamos los colores REALES de su perfil de Instagram (best-effort) y
  // si no se puede, cae a la paleta curada de su rubro.
  const pal = demo.CATEGORY_COLORS[category] || demo.CATEGORY_COLORS.otro;
  const hexOk = (v) => /^#[0-9a-fA-F]{6}$/.test(String(v || '').trim());
  let accent = hexOk(fields.accent) ? String(fields.accent).trim().toUpperCase() : pal[0];
  let btn = hexOk(fields.btn) ? String(fields.btn).trim().toUpperCase() : pal[1];
  let colorSource = 'rubro';
  let igPic = null, igName = '';
  if (ig) {
    // Perfil real de Instagram (best-effort): foto + nombre + colores.
    // Si no se puede, todo cae a los fallbacks sin que se note.
    try {
      // Instagram lento no frena la prueba: a los 2,5s seguimos con los
      // datos del formulario (el fetch sigue de fondo, sin efecto).
      const prof = await Promise.race([demo.fetchIgProfile(ig), new Promise((r) => setTimeout(() => r(null), 2500))]);
      if (prof) {
        igPic = prof.pic; igName = prof.name;
        if (!hexOk(fields.accent) && prof.colors && prof.colors[0]) {
          accent = prof.colors[0];
          if (prof.colors[1]) btn = prof.colors[1];
          colorSource = 'instagram';
        }
      }
    } catch (e) { /* fallback silencioso */ }
  }
  // (v212) Web del negocio (1/2): nombre si el form no lo trajo y
  // descripción/servicios al goal. Carrera acotada: la web nunca frena.
  let webData = null;
  if (webRaw) {
    webData = await Promise.race([webCtxPromise, new Promise((r) => setTimeout(() => r(null), 9000))]).catch(() => null);
    if (webData) {
      if (!business && webData.name) business = webData.name;
      const wl = trialWebGoalLines(webData, webDescEdited);
      if (wl.length) richGoal = [richGoal, ...wl].filter(Boolean).join('\n');
    }
  }
  if (!business) return res.status(400).json({ error: 'Contanos el nombre de tu negocio' });
  if (!demo.CATEGORIES.includes(category)) return res.status(400).json({ error: 'Rubro inválido' });
  if (!demo.COUNTRIES.includes(country)) return res.status(400).json({ error: 'País inválido' });
  if (!['vos', 'tu'].includes(tone)) return res.status(400).json({ error: 'Tono inválido' });

  // (v196) Medallón de los pósters de marca: la foto de perfil localizada
  // en MEDIA_DIR (mismo archivo que usa el stream). Sin @ o sin foto, los
  // pósters salen tipográficos.
  let profilePicPath = null;
  if (ig && igPic) {
    try {
      const profObj = { handle: ig, pic: igPic };
      await feedAudit.localizeTrialPic(profObj, MEDIA_DIR);
      if (profObj.pic_media) {
        const abs = path.join(MEDIA_DIR, path.basename(profObj.pic_media));
        if (fs.statSync(abs).isFile()) profilePicPath = abs;
      }
    } catch (e) { /* póster tipográfico */ }
  }

  const ip = demo.clientIp(req);
  const testMode = trialTestMode(req);
  const igKey = ig.toLowerCase();
  // Cache por @: si este Instagram ya generó su semana hace menos de 72h,
  // se la mostramos al instante sin regenerar (no gasta IA ni espera).
  // PERO solo si esa semana es de ESTE negocio y rubro: si el @ se usó antes
  // para otro negocio, la semana vieja NO se sirve (se regenera).
  if (!testMode && igKey) {
    try {
      const hit = db.prepare('SELECT payload, created_at FROM trial_cache WHERE ig = ?').get(igKey);
      if (hit && Date.now() - hit.created_at < 72 * 3600 * 1000) {
        let cachedOut = null;
        try {
          const probe = JSON.parse(hit.payload);
          if (trialCacheMatches(probe, business, category, lang)) cachedOut = probe;
          else console.log(`[posta] trial_cache: la semana de @${igKey} es de otro negocio ("${probe && probe.business}") — regenerando`);
        } catch (e) { /* payload roto: se regenera */ }
        if (cachedOut) {
          cachedOut.cached = true;
          cachedOut.spots_left = spotsLeft();
          cachedOut.week = buildTrialWeek((cachedOut.posts || []).length, cachedOut.lang);
          track(null, 'prueba_done', igKey + '|cached');
          return res.json(cachedOut);
        }
      }
      if (hit) db.prepare('DELETE FROM trial_cache WHERE ig = ?').run(igKey);
      if (Math.random() < 0.05) db.exec(`DELETE FROM trial_cache WHERE created_at < ${Date.now() - 72 * 3600 * 1000}`);
    } catch (e) { /* si falla el cache, se genera igual */ }
  }
  // (El candado 90 días se chequea TEMPRANO, apenas parseado el form —
  // ver más arriba en este mismo endpoint.)
  // Anti-spam honesto: 5 pruebas por día por IP. El intento se RESERVA al
  // arrancar (atómico: 2 requests simultáneos no pueden pasar de 5) y se
  // REEMBOLSA si la generación falla — un error nunca quita un intento.
  let charged = false;
  if (!testMode) {
    // (v323 · pieza 13) Tope por hora en el inicio: 20 arranques/hora/IP.
    if (!trialGenHourlyAllowed(ip)) {
      track(null, 'prueba_bot_block', 'gen_hourly');
      return res.status(429).json({ error: 'Muchas pruebas desde esta conexión. Probá en un rato 🚀' });
    }
    const rl = demo.consumeTrialAttempt(ip);
    if (!rl.ok) {
      return res.status(429).json({ error: 'Llegaste al límite de 5 pruebas por día. Volvé mañana 🚀' });
    }
    charged = true;
  }

  let photoPath = null;
  let ok = false;
  try {
    if (file) {
      const kind = demo.validImageKind(file);
      if (!kind) return res.status(400).json({ error: 'La imagen tiene que ser JPG, PNG o WebP' });
      photoPath = path.join(os.tmpdir(), `posta-trial-up-${Date.now()}-${crypto.randomBytes(6).toString('hex')}.${kind}`);
      fs.writeFileSync(photoPath, file.buffer);
    }
    // 6 ideas pensadas para SU negocio + semana Pro: 5 posteos (4 imágenes + 1 video)
    // Las ideas (LLM) solo viajan en el payload final: NO alimentan ni el
    // spec ni los diseños ni los captions. Lanzarlas en paralelo con el
    // render en vez de esperarlas antes saca ~1-2s del camino crítico.
    // (v348 · D2) Etapa del negocio vía el detector exportado: si
    // todavía no lanzó, las ideas de plantilla salen en clave de
    // presentación/lista de espera (nada de promos ni testimonios).
    const etapaTrial = (() => { try { return clientDigest.detectEtapa({ description: richGoal, diferencial: (webData && webData.description) || '' }).etapa; } catch (e) { return ''; } })();
    const ideasPromise = Promise.resolve(generateIdeas({ business, category, tone, description: richGoal, competitors, lang, etapa: etapaTrial }, null)).catch(() => []);
    // (v212) Web del negocio (2/2): su paleta manda si no hay otra fuente de
    // color (con @, manda el feed) y sus fotos entran como material gateado.
    let webExtraPhotos = [];
    if (webData) {
      if (colorSource === 'rubro' && webData.palette && webData.palette[0]) {
        accent = webData.palette[0];
        if (webData.palette[1]) btn = webData.palette[1];
        colorSource = 'web';
      }
      webExtraPhotos = await trialWebPhotos(webData);
    }
    // (v230) LECTURA PROFUNDA: catálogo completo de su web (páginas de
    // catálogo + PDFs enlazados) y mapa foto→producto de las fotos del
    // sitio, cada uno con su carrera: la prueba nunca espera de más.
    let deep = null;
    if (webData) {
      const catalog = await raceMs(trialDeepCatalog(webData), 7000);
      const itemNames = [...(webData.services || []), ...((catalog && catalog.items) || []).map((x) => x.nombre)];
      const photoEntries = await raceMs(trialPhotoEntries(webExtraPhotos, itemNames), 7000);
      deep = { catalog, photoEntries };
    }
    // (v235) RUBRO ANTES DE GENERAR: confirmación del front (la pregunta
    // de /prueba viaja como fields) o voto multi-señal con las fuentes
    // de esta ruta. La categoría resuelta gobierna spec, digest e ideas.
    const rubroRes = resolveTrialRubro({ fields, webData, feed: null, formText: richGoal, catalogItems: ((deep && deep.catalog && deep.catalog.items) || []).map((x) => x.nombre), lang });
    const effCategory = rubroRes.category;
    // (v229) FUNDAMENTO: el digest se compila ANTES del spec — los temas
    // de la semana se derivan de ÉL (web + formulario en esta ruta).
    const trialDigest = buildTrialDigest({ business, category, webData, feed: null, formText: richGoal, deep, rubro: rubroRes });
    const { posts, spec } = await demo.generateDemo({ business, category: effCategory, country: effCountry, tone, photoPath, goal: richGoal, goal_key, accent, btn, count: 5, profilePicPath, bioText: webData ? (webData.description || '') : '', extraPhotos: webExtraPhotos, digest: trialDigest, lang });
    // 🧠 Análisis (2026-10-19): misma radiografía que la ruta stream. Si los
    // datos del @ no llegan, el análisis queda ausente — jamás se afirma un
    // nacimiento sobre una cuenta que no se pudo leer.
    let trialAnalysisJson = null;
    let trialCompetition = null;
    try {
      let dataJson = null;
      if (ig) {
        dataJson = await Promise.race([feedAudit.fetchAuditData(ig), new Promise((r) => setTimeout(() => r(null), 3000))]).catch(() => null);
      }
      if (dataJson && dataJson.ok) {
        const peersJ = await fetchPeersForAnalysis(peerHandlesFromText(competitors));
        const coldJ = analysisEngine.isColdStart({ hasIg: true, profile: dataJson.profile, posts: dataJson.posts || [] });
        const rawAJ = coldJ
          ? analysisEngine.analyzeColdStart({ business: { name: business, category: effCategory, city: (trialDigest && trialDigest.ciudad) || '', ig_username: ig }, digest: trialDigest, peers: peersJ, reviews: null, ctx: { postsPerWeek: 7, plan: 'trial', lang } })
          : analysisEngine.analyzeExisting({ profile: dataJson.profile, posts: dataJson.posts, ctx: { postsPerWeek: 7, plan: 'trial', peers: peersJ, source: 'instagram', lang } });
        trialCompetition = trialCompetitionLine(rawAJ);
        trialAnalysisJson = analysisEngine.gateForPlan(rawAJ, 'trial');
      } else if (!ig) {
        trialAnalysisJson = analysisEngine.gateForPlan(analysisEngine.analyzeColdStart({
          business: { name: business, category: effCategory, city: (trialDigest && trialDigest.ciudad) || '', ig_username: '' },
          digest: trialDigest, peers: [], reviews: null, ctx: { postsPerWeek: 7, plan: 'trial', lang },
        }), 'trial');
      }
      if (trialAnalysisJson && Array.isArray(posts)) {
        for (const p of posts) {
          if (!p || p.why) continue;
          const w = analysisEngine.whyForPost({ tipo: p.tipo || p.kind || '', formato: p.type || '', salesIntent: p.sales_intent || '', porque: p.porque || '' }, trialAnalysisJson, trialDigest);
          if (w) p.why = w;
        }
      }
    } catch (e) { /* el análisis nunca frena la prueba */ }
    const videoOk = posts.some((p) => p && p.type === 'video' && p.video);
    if (!videoOk) console.error('[posta] ⚠️ TRIAL sin video para', business, '— revisar render de video');

    let screenshot = null;
    if (photoPath) {
      const ext = photoPath.split('.').pop().toLowerCase();
      screenshot = `data:${TRIAL_IMG_MIME[ext] || 'image/jpeg'};base64,` + fs.readFileSync(photoPath).toString('base64');
    }
    const out = {
      ok: true,
      engine: demo.DEMO_ENGINE_V,
      lang, // (v274) el idioma de la semana viaja en el payload (caché, chat, registro)
      business, ig, category: effCategory,
      subcat: rubroRes.subcat || '', // (v235) subrubro confirmado/detectado (viaja al registro)
      rubro_check: rubroRes.rubroCheck, // (v235) la duda queda registrada en el payload
      accent, btn, color_source: colorSource,
      feed_register: spec.feedRegister || null,
      web_info: trialWebInfo(webData, trialWebPhotosUsed(spec.photos)),
      digest: trialDigest, // (v229) FUNDAMENTO: viaja al trial_cache y a la cuenta al registrarse
      ig_pic: igPic, ig_name: igName,
      analysis: trialAnalysisJson,
      competition_line: trialCompetition,
      ideas: (await ideasPromise).slice(0, 6),
      posts,
      design: spec, // spec de diseño guardado: permite recolor/cambio de fotos sin regenerar textos
      week: buildTrialWeek(posts.length, lang),
      screenshot,
      spots_left: spotsLeft(),
      video_ok: videoOk,
    };
    // Guardamos la semana por @ (72h): si vuelve, la ve al instante.
    if (!testMode && igKey) {
      try {
        const payload = JSON.stringify(out);
        if (payload.length < 12 * 1024 * 1024) {
          db.prepare(`INSERT INTO trial_cache (ig, payload, created_at) VALUES (?, ?, ?)
            ON CONFLICT(ig) DO UPDATE SET payload=excluded.payload, created_at=excluded.created_at`).run(igKey, payload, Date.now());
        }
      } catch (e) { console.error('[posta] no se pudo cachear la prueba:', e.message); }
    }
    // (v323 · pieza 8) Nace el candado de 90 días de este negocio (@ o
    // dominio): la próxima generación de esta identidad espera al día 91.
    if (!testMode) trialLockRecordFor(fields, webData, business, lang, out);
    track(null, 'prueba_done', igKey);
    ok = true;
    res.json(out);
  } catch (e) {
    console.error('[posta] Error en prueba completa:', e.message);
    res.status(500).json({ error: 'No pudimos armar tu prueba ahora. Probá de nuevo en unos minutos.' });
  } finally {
    if (charged && !ok) demo.refundTrialAttempt(ip); // falló: no se consume
    if (photoPath) {
      try { fs.unlinkSync(photoPath); } catch (_) {}
    }
  }
});

// ---------- Prueba en 1 campo: prefill por @ de Instagram ----------
// Con solo el @ completamos nombre + rubro (+ colores y foto si se puede).
// Rate limit liviano propio: 30 por hora por IP (NO el de 5/día, que es para generar).
try { db.exec('CREATE TABLE IF NOT EXISTS trial_prefill_usage (ip TEXT, hour TEXT, count INTEGER DEFAULT 0, PRIMARY KEY (ip, hour))'); } catch (e) {}
function trialPrefillAllowed(ip) {
  const hour = new Date().toISOString().slice(0, 13); // "2026-09-30T20"
  try {
    if (Math.random() < 0.05) db.exec(`DELETE FROM trial_prefill_usage WHERE hour < strftime('%Y-%m-%dT%H', 'now', '-48 hours')`);
    const row = db.prepare('SELECT count FROM trial_prefill_usage WHERE ip = ? AND hour = ?').get(ip, hour);
    if (row && row.count >= 30) return { ok: false, remaining: 0 };
    db.prepare('INSERT INTO trial_prefill_usage (ip, hour, count) VALUES (?, ?, 1) ON CONFLICT(ip, hour) DO UPDATE SET count = count + 1').run(ip, hour);
    return { ok: true, remaining: Math.max(0, 30 - (row ? row.count + 1 : 1)) };
  } catch (e) { return { ok: true, remaining: 30 }; }
}
app.post('/api/trial/prefill', express.json({ limit: '16kb' }), async (req, res) => {
  const ip = demo.clientIp(req);
  if (!trialPrefillAllowed(ip).ok) return res.status(429).json({ ok: false, error: 'Demasiados intentos, probá en un rato' });
  // Misma sanitización del handle que en /api/trial/generate
  const ig = String((req.body || {}).ig || '').trim().replace(/^@/, '').replace(/[^a-zA-Z0-9._]/g, '').slice(0, 40);
  if (!ig) return res.json({ ok: false, error: 'Pasame tu @ de Instagram' });
  let html = null;
  try { html = await demo.fetchIgEmbedHtml(ig); } catch (e) { html = null; }
  if (!html) return res.json({ ok: false, error: 'No encontramos ese Instagram (puede ser privado o no existir)' });
  const bio = demo.extractIgBiography(html);
  // Perfil real (best-effort): foto + nombre. Si falla, igual respondemos
  // con lo que sacamos de la bio.
  let prof = null;
  try { prof = await demo.fetchIgProfile(ig); } catch (e) { prof = null; }
  const name = (prof && prof.name) || '';
  // (v235) IDENTIFICACIÓN ESPECIALISTA: el estudio del @ ya parsea los
  // posteos del embed (mismo HTML, cero fetches nuevos) — sus captions
  // entran al voto multi-señal junto a bio + nombre + HANDLE. La
  // categoría legada (un solo regex sobre bio+nombre) queda como piso:
  // si el voto no tiene NINGUNA señal, manda ella.
  let embedPosts = [];
  try { embedPosts = feedAudit.parseEmbedPosts(html) || []; } catch (e) { embedPosts = []; }
  const captions = embedPosts.map((p) => p.caption).filter(Boolean).slice(0, 12);
  const signals = {
    bio: bio || '', fullName: name, handle: ig, captions,
    igCategory: (prof && prof.category) || '',
  };
  // (v274 · MODO EN) El prefill del funnel EN pide lang='en': las opciones
  // de la pregunta de rubro salen con rótulos en inglés.
  const prefillLang = String((req.body || {}).lang || '').trim().toLowerCase() === 'en' ? 'en' : 'es';
  const cls = await classifyWithVision(signals, embedPosts.map((p) => p.thumb).filter(Boolean), prefillLang);
  const resolved = rubroId.resolveRubro({ cls, lang: prefillLang });
  const legacyCat = demo.categoryFromText((bio ? bio + ' ' : '') + name);
  const hasVotes = (cls.candidatas || []).length > 0;
  res.json({
    ok: true,
    ig,
    name,
    category: hasVotes ? resolved.category : legacyCat,
    subcat: hasVotes ? (resolved.subcat || '') : '',
    // La pregunta de rubro viaja acá: el front la muestra ANTES de
    // generar (orden de Valentino) y reenvía la confirmación.
    rubro_check: hasVotes ? resolved.rubroCheck : { needed: false, options: [], detected: null },
    photo: (prof && prof.pic) || null, // dataURL de la foto de perfil
  });
});

// ---------- Prueba con la WEB del negocio (v212) ----------
// Orden de Valentino: "en el website deberíamos agregar para que peguen su
// link de su website". El visitante pega la URL de su sitio y Posty lo lee
// (determinístico, CERO IA): nombre, descripción, servicios, ciudad, paleta
// y fotos. Eso precarga el negocio y alimenta la generación igual que el @:
// la descripción y los servicios enriquecen los temas (vía goal), la paleta
// entra como paleta del negocio y las fotos del sitio son material válido
// (son SUYAS, como las del álbum — pasan el gate foto↔tema como todo).
// Si vienen @ Y web: el @ manda en lo visual/herencia (paleta del feed) y la
// web enriquece servicios/textos. Solo web: la semana se genera igual y la
// proyección/auditoría no aparecen (sin @ no hay feed que analizar).
// Si el sitio no responde, bloquea o no tiene nada útil: webData = null y la
// prueba sigue con lo que haya — la web NUNCA rompe ni frena la prueba.
const trialWebPromises = new Map(); // url normalizada -> Promise<data|null>
function trialWebContext(rawUrl) {
  const url = webExtract.normalizeSiteUrl(rawUrl);
  if (!url) return Promise.resolve(null);
  const hit = trialWebPromises.get(url);
  if (hit) return hit;
  const p = webExtract.fetchBusinessSite(url).catch(() => null);
  trialWebPromises.set(url, p);
  if (trialWebPromises.size > 300) trialWebPromises.clear();
  // La extracción se comparte entre el prefill y la generación (el segundo
  // no vuelve a bajar el sitio) y se olvida a los 30 min.
  p.then(() => {
    const t = setTimeout(() => trialWebPromises.delete(url), 30 * 60 * 1000);
    if (t.unref) t.unref();
  });
  return p;
}
async function trialWebPhotos(webData) {
  if (!webData || !Array.isArray(webData.photos) || !webData.photos.length) return [];
  try { return await webExtract.localizeSitePhotos(webData.photos, MEDIA_DIR, 6); }
  catch (e) { return []; }
}
function trialWebPhotosUsed(specPhotos) {
  return (specPhotos || []).filter((p) => typeof p === 'string' && path.basename(p).startsWith('web-')).length;
}
function trialWebInfo(webData, photosUsed) {
  if (!webData) return null;
  return {
    url: webData.url,
    name: webData.name || '',
    description: webData.description || '',
    services: webData.services || [],
    city: webData.city || '',
    palette: webData.palette || [],
    pic: (webData.photos && webData.photos[0] && webData.photos[0].url) || null,
    photos_total: (webData.photos || []).length,
    photos_used: photosUsed || 0,
  };
}
// Líneas de goal que aporta la web (descripción editada por el visitante si
// la mandó en web_desc; si no, la extraída) — se suman al richGoal para que
// temas, ideas y captions hablen de SU negocio y no solo de su rubro.
function trialWebGoalLines(webData, editedDesc) {
  if (!webData) return [];
  const desc = String(editedDesc || '').replace(/<[^>]*>/g, '').trim().slice(0, 400) || webData.description || '';
  const lines = [];
  if (desc) lines.push('Sobre el negocio (de su web): ' + desc);
  if (webData.services && webData.services.length) lines.push('Servicios: ' + webData.services.slice(0, 8).join(', '));
  if (webData.city) lines.push('Ciudad: ' + webData.city);
  return lines;
}
app.post('/api/trial/web-prefill', express.json({ limit: '16kb' }), async (req, res) => {
  const ip = demo.clientIp(req);
  if (!trialPrefillAllowed(ip).ok) return res.status(429).json({ ok: false, error: 'Demasiados intentos, probá en un rato' });
  const raw = String((req.body || {}).web || '').trim().slice(0, 300);
  const url = webExtract.normalizeSiteUrl(raw);
  if (!url) return res.json({ ok: false, error: 'Ese link no parece una web válida' });
  // Carrera acotada: un sitio lento no cuelga la pantalla; la extracción
  // sigue de fondo y la generación la reusa desde la misma promesa.
  const data = await Promise.race([
    trialWebContext(raw),
    new Promise((r) => setTimeout(() => r(null), 11000)),
  ]).catch(() => null);
  if (!data) return res.json({ ok: false, error: 'No pudimos leer esa web (puede estar caída o bloquear lecturas automáticas)' });
  // (v235) La web se clasifica con el voto multi-señal: su @type JSON-LD
  // (categoryHint, la auto-declaración del negocio) + nombre/descripción/
  // servicios. La categoría legada queda como piso si no hay señales.
  const webSignals = {
    jsonldType: data.categoryHint || '',
    catalogText: (data.services || []).join(' · '),
    webText: [data.name || '', data.description || ''].join(' '),
  };
  const webPrefillLang = String((req.body || {}).lang || '').trim().toLowerCase() === 'en' ? 'en' : 'es';
  const wcls = await classifyWithVision(webSignals, (data.photos || []).map((p) => p.url), webPrefillLang);
  const wresolved = rubroId.resolveRubro({ cls: wcls, lang: webPrefillLang });
  const wLegacy = demo.categoryFromText([data.name, data.description, ...(data.services || [])].join(' '));
  const wHasVotes = (wcls.candidatas || []).length > 0;
  res.json({
    ok: true,
    web: data.url,
    name: data.name || '',
    description: data.description || '',
    services: data.services || [],
    city: data.city || '',
    category: wHasVotes ? wresolved.category : wLegacy,
    subcat: wHasVotes ? (wresolved.subcat || '') : '',
    rubro_check: wHasVotes ? wresolved.rubroCheck : { needed: false, options: [], detected: null },
    palette: data.palette || [],
    photos: (data.photos || []).map((p) => p.url),
    photoCount: (data.photos || []).length,
  });
});

// ---------- Prueba en 1 campo: generación con streaming (SSE) ----------
// Acepta el MISMO multipart que /api/trial/generate y emite:
//   event: status → {step, text} (tracker en primera persona)
//   event: post   → {index, day, date, post} (uno por posteo, en orden; el
//                   videoIdx sale primero como imagen y de nuevo como video
//                   cuando está listo)
//   event: done   → {out} (payload IDÉNTICO al de /api/trial/generate)
//   event: error  → {error}
// Mismas reglas que /api/trial/generate: anti-spam 5/día por IP, cache 72h
// por @ (hit → done directo) y TRIAL_TEST_KEY. /api/trial/generate queda
// intacto como fallback.
app.post('/api/trial/generate-stream', express.raw({ type: 'multipart/form-data', limit: '6mb' }), async (req, res) => {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache, no-transform',
    'Connection': 'keep-alive',
    'X-Accel-Buffering': 'no',
  });
  if (res.flushHeaders) res.flushHeaders();
  let closed = false;
  // OJO: req 'close' se dispara cuando el body del POST termina de llegar
  // (al instante); el que indica desconexión del cliente es res 'close'.
  res.on('close', () => { closed = true; });
  const send = (event, data) => {
    if (closed) return;
    try { res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`); } catch (e) {}
  };
  const finish = () => { if (!closed) { try { res.end(); } catch (e) {} } };
  const fail = (msg) => { send('error', { error: msg }); finish(); };

  let fields, file;
  try {
    ({ fields, file } = demo.parseMultipart(req, req.body));
  } catch (e) {
    return fail(e.message || 'Formulario inválido');
  }
  // (v323 · pieza 13) Honeypot silencioso, igual que /api/trial/generate.
  if (trialHoneypotHit(fields)) {
    track(null, 'prueba_bot_block', 'honeypot');
    return fail('No pudimos armar tu prueba ahora. Probá de nuevo en unos minutos.');
  }
  // Mismo parseo y sanitización que /api/trial/generate
  let business = String(fields.business || '').trim().slice(0, 60);
  const ig = String(fields.ig || '').trim().replace(/^@/, '').replace(/[^a-zA-Z0-9._]/g, '').slice(0, 40);
  // (v212) La web del negocio (si pegó su link): la extracción determinística
  // arranca YA, en paralelo con el resto; se consume con carrera acotada.
  const webRaw = String(fields.web || '').trim().slice(0, 300);
  const webDescEdited = String(fields.web_desc || '').replace(/<[^>]*>/g, '').trim().slice(0, 400);
  const webCtxPromise = webRaw ? trialWebContext(webRaw) : Promise.resolve(null);
  const category = String(fields.category || '').trim();
  const country = String(fields.country || '').trim().toUpperCase();
  const tone = String(fields.tone || 'vos').trim().toLowerCase();
  // (v274 · MODO EN) Mismo parseo de idioma que /api/trial/generate.
  const lang = String(fields.lang || '').trim().toLowerCase() === 'en' ? 'en' : 'es';
  const effCountry = lang === 'en' ? 'US' : country;
  // (v323 · pieza 8) CANDADO 90 DÍAS — chequeo TEMPRANO, igual que en
  // /api/trial/generate: con snapshot se emite 'done' directo (la semana
  // de siempre, sin gastar); sin snapshot, el evento 'locked' con el
  // mensaje amable y las fechas exactas.
  if (!trialTestMode(req)) {
    const gate = trialLockGate(fields, null, false);
    if (gate) {
      const snap = trialLockServePayload(gate.lock);
      if (snap) { send('done', { out: snap }); return finish(); }
      send('locked', {
        trial_locked: true,
        generated_at: gate.lock.generated_at,
        unlock_at: gate.lock.unlock_at,
        message: trialLock.lockMessage(gate.lock, lang),
      });
      return finish();
    }
  }
  const goal = String(fields.goal || '').replace(/<[^>]*>/g, '').trim().slice(0, 400);
  const competitors = String(fields.competitors || '').replace(/<[^>]*>/g, '').trim().slice(0, 200);
  const goal_key = ['vender', 'seguidores', 'lanzamiento', 'fidelizar'].includes(String(fields.goal_key || '').trim())
    ? String(fields.goal_key).trim() : '';
  const producto = String(fields.producto || '').replace(/<[^>]*>/g, '').trim().slice(0, 120);
  const diferencial = String(fields.diferencial || '').replace(/<[^>]*>/g, '').trim().slice(0, 200);
  let richGoal = [goal, producto && ((lang === 'en' ? 'Main product: ' : 'Producto principal: ') + producto), diferencial && ((lang === 'en' ? 'What makes you different: ' : 'Diferencial: ') + diferencial)].filter(Boolean).join('\n');
  const pal = demo.CATEGORY_COLORS[category] || demo.CATEGORY_COLORS.otro;
  const hexOk = (v) => /^#[0-9a-fA-F]{6}$/.test(String(v || '').trim());
  let accent = hexOk(fields.accent) ? String(fields.accent).trim().toUpperCase() : pal[0];
  let btn = hexOk(fields.btn) ? String(fields.btn).trim().toUpperCase() : pal[1];
  let colorSource = 'rubro';
  let igPic = null, igName = '';
  let igProfPromise = null;
  if (ig) {
    // Una sola promesa de perfil, reutilizable: la carrera de 2,5s define
    // colores/foto para el diseño y la MISMA promesa alimenta la proyección
    // de perfil (v184) sin fetches duplicados.
    igProfPromise = demo.fetchIgProfile(ig).catch(() => null);
    try {
      // Instagram lento no frena la prueba: a los 2,5s seguimos con los
      // datos del formulario (el fetch sigue de fondo, sin efecto).
      const prof = await Promise.race([igProfPromise, new Promise((r) => setTimeout(() => r(null), 2500))]);
      if (prof) {
        igPic = prof.pic; igName = prof.name;
        if (!hexOk(fields.accent) && prof.colors && prof.colors[0]) {
          accent = prof.colors[0];
          if (prof.colors[1]) btn = prof.colors[1];
          colorSource = 'instagram';
        }
      }
    } catch (e) { /* fallback silencioso */ }
  }
  // ---------- Proyección de perfil (v184): su perfil HOY vs CON Posty ------
  // Fetch completo del perfil real (bio, conteos, grilla) EN PARALELO con la
  // generación: nunca la espera ni la frena. Carrera de ~3s: si el perfil
  // llega, se emite el evento 'profile' apenas está (la proyección se pinta
  // durante la generación) y viaja en el payload final para la tarjeta de
  // resultados y el cache. Si pierde la carrera o falla (IG privado, IG
  // caído), la proyección no existe y el flujo queda idéntico al de siempre.
  let trialProfile = null;
  let trialProfilePromise = null;
  // (v210) Auditoría en vivo del @: se computa de los MISMOS datos crudos
  // que alimentan la proyección (cero IA, cero fetches nuevos) y viaja en
  // el payload final y en el evento 'audit' del stream.
  let trialAudit = null;
  let trialAuditPalette = null;
  let trialData = null; // (2026-10-19) datos crudos del @: alimentan el análisis completo
  if (ig) {
    trialProfilePromise = (async () => {
      try {
        const known = await Promise.race([igProfPromise, new Promise((r) => setTimeout(() => r(null), 4500))]);
        const data = await feedAudit.fetchAuditData(ig, null, known || undefined);
        trialData = data;
        // (v210) Señales determinísticas desde los posteos públicos; la
        // paleta (única señal que descarga miniaturas) refina en segundo
        // plano y reemite el evento si suma el hallazgo de línea visual.
        try {
          const auditBase = feedAudit.trialAuditFromData(data, { lang });
          if (auditBase) trialAudit = auditBase;
        } catch (e) { /* la auditoría nunca frena la prueba */ }
        trialAuditPalette = feedAudit.analyzePalette((data && data.posts) || [])
          .then((hues) => {
            if (hues == null) return;
            try {
              const refined = feedAudit.trialAuditFromData(data, { paletteHues: hues, lang });
              if (refined) { trialAudit = refined; send('audit', { audit: refined }); }
            } catch (e) { /* best-effort */ }
          })
          .catch(() => {});
        const prof = feedAudit.trialProfileFromAudit(data, igPic);
        if (prof) {
          // v187: las miniaturas se sirven desde NUESTRO server — las URLs
          // de la CDN de IG no se dejan hotlinkear desde el navegador y la
          // grilla HOY salía gris en vivo. Descarga paralela (timeout 2 s
          // por foto) dentro de esta misma carrera de ~3 s: lo que no llega
          // queda null (celda neutra) y la semana nunca espera por esto.
          try { await feedAudit.localizeTrialPhotos(prof, MEDIA_DIR); } catch (e) { /* queda como vino */ }
          // (v196) La foto de perfil también local: es el medallón de los
          // pósters de marca (el render es del servidor, no del navegador).
          try { await feedAudit.localizeTrialPic(prof, MEDIA_DIR); } catch (e) { /* póster tipográfico */ }
        }
        return prof;
      } catch (e) { return null; }
    })();
    Promise.race([trialProfilePromise, new Promise((r) => setTimeout(() => r(null), 3000))])
      .then((p) => {
        if (p) { trialProfile = p; send('profile', { profile: p }); }
        if (trialAudit) send('audit', { audit: trialAudit });
      })
      .catch(() => {});
  }
  // (v212) Web del negocio (1/2): si el form no trajo nombre, lo completa la
  // web (con carrera corta: en el flujo normal el nombre ya viene del
  // formulario y esto no espera nada).
  let webData = null;
  if (!business && webRaw) {
    webData = await Promise.race([webCtxPromise, new Promise((r) => setTimeout(() => r(null), 4000))]).catch(() => null);
    if (webData && webData.name) business = webData.name;
  }
  if (!business) return fail('Contanos el nombre de tu negocio');
  if (!demo.CATEGORIES.includes(category)) return fail('Rubro inválido');
  if (!demo.COUNTRIES.includes(country)) return fail('País inválido');
  if (!['vos', 'tu'].includes(tone)) return fail('Tono inválido');

  const ip = demo.clientIp(req);
  const testMode = trialTestMode(req);
  const igKey = ig.toLowerCase();
  // Cache por @ 72h: hit → done directo, sin regenerar.
  // Igual que /api/trial/generate: solo vale si la semana es de ESTE negocio.
  if (!testMode && igKey) {
    try {
      const hit = db.prepare('SELECT payload, created_at FROM trial_cache WHERE ig = ?').get(igKey);
      if (hit && Date.now() - hit.created_at < 72 * 3600 * 1000) {
        let cachedOut = null;
        try {
          const probe = JSON.parse(hit.payload);
          if (trialCacheMatches(probe, business, category, lang)) cachedOut = probe;
          else console.log(`[posta] trial_cache: la semana de @${igKey} es de otro negocio ("${probe && probe.business}") — regenerando`);
        } catch (e) { /* payload roto: se regenera */ }
        if (cachedOut) {
          // (v210) Las semanas cacheadas anteriores a la auditoría no la
          // traen: si el análisis del @ llega rápido (la misma lectura que
          // alimenta la proyección, ya en vuelo), viaja en este payload.
          if (!cachedOut.audit && trialProfilePromise) {
            await Promise.race([trialProfilePromise, new Promise((r) => setTimeout(() => r(null), 2500))]).catch(() => null);
            if (trialAudit) cachedOut.audit = trialAudit;
            // (2026-10-19) Semanas cacheadas sin análisis: si los datos del @
            // llegaron en la ventana, el análisis viaja también en este payload.
            if (!cachedOut.analysis && trialData) {
              try {
                const coldC = !trialData.ok || analysisEngine.isColdStart({ hasIg: true, profile: trialData.profile, posts: trialData.posts || [] });
                cachedOut.analysis = analysisEngine.gateForPlan(coldC
                  ? analysisEngine.analyzeColdStart({ business: { name: business, category, ig_username: ig }, digest: cachedOut.digest || null, peers: [], reviews: null, ctx: { plan: 'trial', lang } })
                  : analysisEngine.analyzeExisting({ profile: trialData.profile, posts: trialData.posts, ctx: { plan: 'trial', lang } }), 'trial');
              } catch (e) { /* best-effort */ }
            }
            if (cachedOut.analysis && Array.isArray(cachedOut.posts)) {
              try {
                for (const p of cachedOut.posts) {
                  if (!p || p.why) continue;
                  const w = analysisEngine.whyForPost({ tipo: p.tipo || p.kind || '', formato: p.type || '', salesIntent: p.sales_intent || '', porque: p.porque || '' }, cachedOut.analysis, cachedOut.digest || null);
                  if (w) p.why = w;
                }
              } catch (e) { /* best-effort */ }
            }
          }
          cachedOut.cached = true;
          cachedOut.spots_left = spotsLeft();
          cachedOut.week = buildTrialWeek((cachedOut.posts || []).length, cachedOut.lang);
          track(null, 'prueba_done', igKey + '|cached');
          send('done', { out: cachedOut });
          return finish();
        }
      }
      if (hit) db.prepare('DELETE FROM trial_cache WHERE ig = ?').run(igKey);
      if (Math.random() < 0.05) db.exec(`DELETE FROM trial_cache WHERE created_at < ${Date.now() - 72 * 3600 * 1000}`);
    } catch (e) { /* si falla el cache, se genera igual */ }
  }
  // (El candado 90 días se chequea TEMPRANO, apenas parseado el form —
  // ver más arriba en este mismo endpoint.)
  // Anti-spam honesto: igual que /api/trial/generate (reserva atómica +
  // reembolso si falla). Si el cliente corta el stream antes de recibir
  // 'done', tampoco se consume (doneSent=false → reembolso en finally).
  let charged = false;
  if (!testMode) {
    // (v323 · pieza 13) Tope por hora en el inicio, igual que el clásico.
    if (!trialGenHourlyAllowed(ip)) {
      track(null, 'prueba_bot_block', 'gen_hourly');
      return fail('Muchas pruebas desde esta conexión. Probá en un rato 🚀');
    }
    const rl = demo.consumeTrialAttempt(ip);
    if (!rl.ok) {
      return fail('Llegaste al límite de 5 pruebas por día. Volvé mañana 🚀');
    }
    charged = true;
  }

  let photoPath = null;
  let runDir = null;
  let doneSent = false;
  let keepalive = null;
  try {
    if (file) {
      const kind = demo.validImageKind(file);
      if (!kind) return fail('La imagen tiene que ser JPG, PNG o WebP');
      photoPath = path.join(os.tmpdir(), `posta-trial-up-${Date.now()}-${crypto.randomBytes(6).toString('hex')}.${kind}`);
      fs.writeFileSync(photoPath, file.buffer);
    }
    // 1) Ideas (van en el payload final; el tracker muestra el progreso)
    send('status', { step: 'empezando', text: lang === 'en' ? "OK, I'm building your trial…" : 'Dale, estoy armando tu prueba…' });
    send('status', { step: 'ideas', text: lang === 'en' ? `I'm thinking up ideas for ${business}…` : `Estoy pensando ideas para ${business}…` });
    // (v348 · D2) Etapa vía el detector exportado (ver endpoint clásico).
    const etapaTrial = (() => { try { return clientDigest.detectEtapa({ description: richGoal, diferencial: (webData && webData.description) || '' }).etapa; } catch (e) { return ''; } })();
    const ideas = await generateIdeas({ business, category, tone, description: richGoal, competitors, lang, etapa: etapaTrial }, null);

    // (v192) HERENCIA VISUAL DEL PERFIL: la semana sale de SU línea, no de
    // una plantilla genérica del rubro. Con el perfil ya en vuelo (la misma
    // promesa de la proyección — cero fetches nuevos) y SOLO si el visitante
    // no fijó colores a mano: (a) la paleta sale de hasta 3 fotos de su feed
    // ya localizadas, y reemplaza a la del rubro y a la de la foto de
    // perfil; (b) su bio alimenta los temas (demoSubcat vía bioText).
    // Espera acotada: las ideas ya tomaron su tiempo y el perfil suele
    // estar; si no llega, se sigue con lo que haya — la prueba no se frena.
    let bioText = '';
    let profilePicPath = null;
    let feedRegister = null;
    let feedPhotoPaths = [];
    let feedPalette = null; // v203: paleta completa de los últimos posteos (roles + hexes)
    if (ig && trialProfilePromise) {
      const prof = trialProfile || await Promise.race([
        trialProfilePromise,
        new Promise((r) => setTimeout(() => r(null), 4000)),
      ]).catch(() => null);
      if (prof) {
        bioText = String(prof.bio || '');
        // (v196) Medallón de los pósters de marca: la foto de perfil ya
        // localizada por la cadena de la proyección (mismo archivo).
        if (prof.pic_media) {
          const abs = path.join(MEDIA_DIR, path.basename(prof.pic_media));
          try { if (fs.statSync(abs).isFile()) profilePicPath = abs; } catch (e) { /* sin medallón */ }
        }
        // (v198) Paths locales de las fotos del feed: alimentan la
        // clasificación ilustrado/foto y la referencia visual de la IA.
        if (Array.isArray(prof.photos)) {
          for (const p of prof.photos) {
            if (feedPhotoPaths.length >= 6) break;
            if (typeof p !== 'string' || !p.startsWith('/media/')) continue;
            const fp = path.join(MEDIA_DIR, path.basename(p));
            try { if (fs.statSync(fp).isFile()) feedPhotoPaths.push(fp); } catch (e) { /* podada: se sigue */ }
          }
        }
        if (!hexOk(fields.accent) && feedPhotoPaths.length) {
          const bufs = [];
          for (const fp of feedPhotoPaths) {
            if (bufs.length >= 6) break; // v203: los posteos MÁS RECIENTES (hasta 6, en orden de feed)
            try { bufs.push(fs.readFileSync(fp)); } catch (e) { /* foto podada por el janitor: se sigue con las demás */ }
          }
          if (bufs.length) {
            // (v203) PALETA COMPLETA de los últimos posteos: principal,
            // acento, oscuro, claro/crema y fondo dominante. Viaja en el
            // payload (feed_palette, origen 'latest-posts') y como
            // directiva dura en los prompts de las piezas IA. El par
            // accent/btn de siempre se deriva de la misma extracción.
            feedPalette = await demo.extractFeedPaletteFromBuffers(bufs).catch(() => null);
            const feedPal = feedPalette ? { accent: feedPalette.principal, btn: feedPalette.accent } : null;
            if (feedPal && feedPal.accent) {
              accent = feedPal.accent;
              if (feedPal.btn) btn = feedPal.btn;
              colorSource = 'instagram-feed';
            }
            // (v197) REGISTRO LUMÍNICO heredado: la luminancia media de
            // las mismas fotos decide si las piezas gráficas de la
            // semana salen claras u oscuras — la semana sigue la luz
            // del feed que el visitante ya tiene, no una plantilla.
            const feedLum = await demo.feedLuminanceFromBuffers(bufs).catch(() => null);
            if (feedLum != null) feedRegister = feedLum >= 0.55 ? 'light' : 'dark';
          }
        }
      }
    }

    // (v230) LECTURA PROFUNDA: el link de la bio empieza a seguirse YA
    // (en paralelo con la clasificación del feed y la web); el digest se
    // compila más abajo, cuando la web y sus fotos ya están, para que
    // catálogo/bio-link/mapa entren en la MISMA compilación.
    const bioLinkPromise = trialBioLink(trialProfile && trialProfile.link);

    // (v198) CLASIFICACIÓN DEL FEED (ilustrado vs foto real): corre en
    // paralelo con el spec y el render de plantillas — la semana de
    // plantillas NO espera a la IA. Una sola llamada de visión barata
    // sobre la hoja de contacto; el resultado viaja en el payload y en
    // la caché de la semana. Si clasificar falla o el tope diario del
    // demo ya se alcanzó, feedKind queda 'photo' (plantillas, $0 extra).
    const demoApiKey = process.env.OPENAI_API_KEY || '';
    // v205: clave de Gemini (Nano Banana Pro) — si está, es el motor
    // principal de las piezas IA del demo ilustrado; si falta o falla,
    // generateDemoPieceImage cae solo a gpt-image y de ahí a plantillas.
    const geminiKey = process.env.GEMINI_API_KEY || '';
    let feedKind = ig ? 'photo' : null;
    let feedFormula = null; // v202: fórmula de composición del feed (viaja en el payload/caché)
    let demoSpendBefore = null;
    let classifyPromise = null;
    if (ig && feedPhotoPaths.length && demoApiKey && costs.demoAiCapOk()) {
      demoSpendBefore = costs.demoAiSpendTodayUsd();
      classifyPromise = demoAi.classifyFeedKind({ photoPaths: feedPhotoPaths, apiKey: demoApiKey }).catch(() => null);
    }

    // (v212) Web del negocio (2/2): descripción/servicios al goal, la
    // descripción como bio para el subrubro, paleta SOLO si ni el feed ni
    // el perfil aportaron la suya (con @ manda lo visual del feed) y sus
    // fotos como material gateado (pasan el gate foto↔tema como todo).
    let webExtraPhotos = [];
    if (webRaw) {
      if (!webData) webData = await Promise.race([webCtxPromise, new Promise((r) => setTimeout(() => r(null), 9000))]).catch(() => null);
      if (webData) {
        const wl = trialWebGoalLines(webData, webDescEdited);
        if (wl.length) richGoal = [richGoal, ...wl].filter(Boolean).join('\n');
        if (!bioText && webData.description) bioText = webData.description;
        if (colorSource === 'rubro' && webData.palette && webData.palette[0]) {
          accent = webData.palette[0];
          if (webData.palette[1]) btn = webData.palette[1];
          colorSource = 'web';
        }
        webExtraPhotos = await trialWebPhotos(webData);
      }
    }
    // (v230) LECTURA PROFUNDA + (v229) FUNDAMENTO: el digest se compila
    // con TODO lo recolectado (feed real: bio + captions; web; formulario;
    // catálogo profundo, link de bio y mapa foto→producto con sus
    // carreras acotadas) justo ANTES del spec — los temas de la semana
    // se derivan de él, no del catálogo por rubro.
    let deep = null;
    {
      const catalog = webData ? await raceMs(trialDeepCatalog(webData), 6000) : null;
      const bioLink = await raceMs(bioLinkPromise, 4000);
      const itemNames = [...((webData && webData.services) || []),
        ...((catalog && catalog.items) || []).map((x) => x.nombre),
        ...((bioLink && bioLink.items) || []).map((x) => x.nombre)];
      const photoEntries = webExtraPhotos.length ? await raceMs(trialPhotoEntries(webExtraPhotos, itemNames), 6000) : null;
      deep = { catalog, bioLink, photoEntries };
    }
    // (v235) RUBRO ANTES DEL SPEC: la confirmación del front (pregunta o
    // select tocado a mano) manda; si no, el voto multi-señal con TODO lo
    // recolectado (feed real + web + formulario). Con duda: padre seguro
    // y subrubro vacío — ningún posteo nace de un subrubro inventado.
    const rubroRes = resolveTrialRubro({
      fields, webData,
      feed: trialProfile ? { bio: bioText, captions: trialProfile.captions || [], name: trialProfile.name || '', handle: trialProfile.handle || ig } : null,
      formText: richGoal,
      catalogItems: ((deep && deep.catalog && deep.catalog.items) || []).map((x) => x.nombre),
      lang,
    });
    const effCategory = rubroRes.category;
    const trialDigest = buildTrialDigest({
      business, category, webData,
      feed: trialProfile ? { bio: bioText, captions: trialProfile.captions || [], name: trialProfile.name || '', handle: trialProfile.handle || ig } : null,
      formText: richGoal, feedPalette, registro: feedRegister, deep, rubro: rubroRes,
    });
    // 2) Spec + textos: MISMO armado que generateDemo en demo.js (para que
    // el payload final sea idéntico al de /api/trial/generate)
    const spec = demo.buildDemoSpec({ business, category: effCategory, country: effCountry, tone, photoPath, goal: richGoal, goal_key, accent, btn, count: 5, bioText, profilePicPath, feedRegister, extraPhotos: webExtraPhotos, digest: trialDigest, lang });
    const { specPosts, videoIdx, count: n, goalLine, topics } = spec;
    const week = buildTrialWeek(n, lang); // día/fecha de cada posteo (igual que en out.week)
    const cat = demo.CATEGORIES.includes(effCategory) ? effCategory : 'otro';
    const withPhotos = specPosts.map((p) => (
      (p.photo && typeof p.photo === 'object' && p.photo.userPhoto && photoPath) ? { ...p, photo: photoPath } : p
    ));
    // Captions gateados igual que en demo.generateDemo (mismo armado).
    // (v348 · D1) prevCaptions acumulado, igual que en demo.generateDemo.
    const prevCaps = [];
    const made = topics.map((t, i) => {
      const r = demo.resolveTrialCaption(topics, cat, {
        business, tone, country: effCountry, idx: i, goalLine, lang, prevCaptions: prevCaps,
      });
      // (v209) Pieza LIMPIA (dosificación): el caption cierra con el CTA.
      // 🧠 (v232) Y el cierre es el de la INTENCIÓN DE VENTA del topic.
      const cleanPiece = specPosts[i].text_mode === 'clean';
      const finalCaption = cleanPiece
        ? demo.closeTrialCaption(r.caption, topics[r.topicIndex] || t, tone, lang)
        : r.caption;
      prevCaps.push(finalCaption);
      return {
        caption: finalCaption,
        hashtags: r.hashtags,
        headline: specPosts[i].headline,
      };
    });
    const posts = new Array(n).fill(null);
    // 3) Render con streaming: cada PNG que aparece se emite como post imagen
    send('status', { step: 'diseno', text: lang === 'en' ? "Got the ideas: now I'm designing your posts one by one…" : 'Ya tengo las ideas: ahora estoy diseñando tus posteos uno por uno…' });
    const streamed = await demo.renderSpecPngsStream(withPhotos, { accent, btn, register: spec.feedRegister }, async (i, buf) => {
      posts[i] = {
        type: 'image',
        image: 'data:image/jpeg;base64,' + buf.toString('base64'),
        caption: made[i].caption,
        hashtags: made[i].hashtags,
        headline: made[i].headline,
        style: specPosts[i].style,
        style_name: specPosts[i].style_name,
        text_mode: specPosts[i].text_mode || 'text',
      };
      send('post', { index: i, day: week[i].day, date: week[i].date, hour: week[i].hour, post: posts[i] });
    });
    runDir = streamed.runDir;
    const bufs = streamed.bufs;

    // (v198) PIEZAS CON IA — solo si el feed clasificó ILUSTRADO: las 5
    // piezas de la semana se regeneran con el pipeline real (brief del
    // director de arte + gpt-image con la foto de perfil y una foto del
    // feed como referencia del personaje + titular compuesto por
    // código) y van reemplazando a las de plantilla a medida que
    // completan (mismo evento 'post' por índice: la proyección CON
    // Posty y la semana las toman en vivo; el payload final y la caché
    // quedan con las piezas IA). Cada pieza que falla conserva su
    // plantilla — fallback silencioso total, sin error visible. Los
    // extras de la grilla NO usan IA (quedan de plantilla, como hoy).
    let demoAiInfo = { used: false, pieces: 0, cost_usd: 0, engines: [], qa: [] };
    // v205: motor (nano|gpt) y veredicto del QA visual por pieza IA —
    // viajan en el payload (demo_ai.engines / demo_ai.qa por índice y
    // post.engine / post.qa) para poder verificar qué produjo cada una.
    const pieceEngines = {};
    const pieceQa = {};
    let demoTreatments = null; // tratamientos de la tanda IA (para el posteo video)
    if (classifyPromise) {
      const cls = await Promise.race([
        classifyPromise,
        new Promise((r) => setTimeout(() => r(null), 20000)),
      ]).catch(() => null);
      if (cls && cls.kind === 'illustrated') {
        feedKind = 'illustrated';
        if (demoApiKey && costs.demoAiCapOk()) {
          send('status', { step: 'personaje', text: lang === 'en' ? "Your brand is illustrated: I'm creating your posts with your character, in your feed's line…" : 'Tu marca es ilustrada: estoy creando tus posteos con tu personaje, en la línea de tu feed…' });
          const aiKeepalive = setInterval(() => {
            send('status', { step: 'personaje', text: lang === 'en' ? "I'm creating your posts with your character…" : 'Estoy creando tus posteos con tu personaje…' });
          }, 20000);
          if (aiKeepalive.unref) aiKeepalive.unref();
          try {
            const visualStyle = demoAi.visualStyleForFeed(cls, feedRegister);
            // v202: la FÓRMULA de composición del feed manda sobre la
            // tanda: restricciones duras por pieza (personaje 60-70%,
            // fondo simple, UN objeto-concepto, tercio superior limpio)
            // y escala de titular del composite según la fórmula.
            const formula = demoAi.compositionFor(cls);
            feedFormula = formula;
            const headlineScale = formula.headline === 'large' ? 1.45 : 1;
            // v203 (ampliación): CAPA DE TRATAMIENTOS — cada pieza IA de
            // la semana recibe un tratamiento visual DISTINTO (FLAT
            // STUDIO / GRAPHIC POSTER / DUO / WORKSPACE / PROP SCENE)
            // derivado de su estilo nombrado + rotación sin repetir,
            // para que la semana no converja a un único look. Las
            // piezas planas/gráficas componen el titular en la tinta
            // oscura de su paleta (poster_dark, la misma del demo).
            const treatments = demoAi.assignTreatments(specPosts.map((sp) => ({ style: sp.style, headline: sp.headline })));
            demoTreatments = treatments;
            const inkHex = demo.demoColors(accent, btn, feedRegister).poster_dark;
            // Referencias: la foto de perfil (el personaje) + la foto del
            // feed más nítida (mayor peso = mejor proxy disponible).
            const sharpRef = demoAi.pickSharpestRef(feedPhotoPaths);
            const refs = [profilePicPath, sharpRef].filter(Boolean);
            const { getStyle: getStyleDemo } = require('./image-styles');
            const makePiece = async (i) => {
              const sp = specPosts[i];
              const topicText = `${sp.tema || ''} ${sp.headline || ''} ${sp.subline || ''}`;
              // (v233) UNA SOLA INYECCIÓN del preset: el estilo del
              // catálogo entra UNA vez, dentro del brief, en la
              // posición de DIRECCIÓN DE ESTILO de assembleImagePrompt
              // (vía stylePreset de expandArtBrief). Hasta v232 entraba
              // DOS veces: como fragmento pegado tras el brief y como
              // "style signature" dentro de la dirección de arte.
              let styleObj = null;
              try { styleObj = sp.style ? getStyleDemo(sp.style) : null; } catch (e) { styleObj = null; }
              let prompt = await expandArtBrief({
                // Pieza limpia (dosificación): sin titular hacia la
                // generación — assembleImagePrompt no reserva zona y la
                // foto usa el encuadre completo (igual que en clientes).
                headline: sp.text_mode === 'clean' ? '' : sp.headline,
                tipo: sp.kind || 'social',
                angle: sp.subline || '',
                theme: sp.tema || sp.headline,
                businessName: business,
                category,
                paletteHex: [accent, btn].filter(Boolean),
                visualStyle,
                sceneRole: demoAi.SCENE_ROLES[i % demoAi.SCENE_ROLES.length],
                stylePreset: styleObj,
              }, demoApiKey, 'demo-ai-brief');
              // v205: DIRECCIÓN DE ARTE completa del estilo nombrado —
              // manda sobre el brief y el fragmento; solo cede ante las
              // directivas duras que siguen (fórmula/tratamiento y
              // paleta). Es la capa anti-convergencia: dos estilos de
              // familias distintas no pueden salir con el mismo look.
              try {
                const artDir = demoAi.artDirectionFor(styleObj || sp.style);
                if (artDir) prompt += '\n\n' + artDir;
              } catch (e) { /* la dirección es opcional: sin ella manda el brief */ }
              prompt += '\n\n' + demoAi.compositionDirectives(cls, topicText, treatments[i], { palette: feedPalette, index: i });
              const palDir = demoAi.paletteDirectives(feedPalette);
              if (palDir) prompt += '\n\n' + palDir;
              // v205: cadena de motores — Nano Banana Pro (si hay clave
              // Gemini) → gpt-image → null (la pieza queda de plantilla).
              // v209: la ruta IA del demo genera en el tier de calidad
              // MÁS ALTO de gpt-image ('high') — la prueba es la vidriera
              // y la vara es calidad máxima; el tope diario fail-closed
              // del demo (DEMO_AI_DAILY_CAP_USD) sigue mandando. El
              // pipeline de clientes NO usa este override (su techo
              // mensual por usuario no lo admite: ver genConceptImage).
              // (v237) La nota para gpt-image nombra SOLO la referencia
              // que su transporte efectivamente manda (la primera: el
              // personaje) — la nota de 2 roles va solo a Nano, que
              // recibe todas (demoAi.REF_NOTE sigue siendo la de
              // Nano vía el parámetro refNote de abajo).
              const genGpt = (p) => genConceptImage(demoApiKey, p, refs, refRoles.buildRefNote(['character']), null, 'demo-ai-image', 'high');
              let gen = await demoAi.generateDemoPieceImage({ prompt, refs, geminiKey, genGpt, refNote: demoAi.REF_NOTE });
              if (!gen) return null;
              // v205: QA VISUAL con reintento — la pieza cruda se chequea
              // contra su brief (concepto correcto y sin prohibidos, SIN
              // texto renderizado por el modelo, tratamiento
              // materializado). Si falla y el tope diario lo permite, se
              // regenera UNA vez con la directiva reforzada y queda la
              // mejor de las dos (por puntaje del propio QA).
              const qaArgs = { topicText, treatment: treatments[i], apiKey: demoApiKey };
              const qaRes = await demoAi.qaDemoPiece({ b64: gen.b64, ...qaArgs });
              let qaInfo = { passed: qaRes ? qaRes.passed : true, retried: false };
              if (qaRes && !qaRes.passed && costs.demoAiCapOk()) {
                const gen2 = await demoAi.generateDemoPieceImage({
                  prompt: prompt + '\n\n' + demoAi.qaRetryDirective(qaRes),
                  refs, geminiKey, genGpt, refNote: demoAi.REF_NOTE,
                }).catch(() => null);
                if (gen2) {
                  const qa2 = await demoAi.qaDemoPiece({ b64: gen2.b64, ...qaArgs });
                  if (!qa2 || qa2.score >= qaRes.score) {
                    gen = gen2;
                    qaInfo = { passed: qa2 ? qa2.passed : qaRes.passed, retried: true };
                  } else {
                    qaInfo = { passed: qaRes.passed, retried: true };
                  }
                } else {
                  qaInfo = { passed: qaRes.passed, retried: true };
                }
                if (!qaInfo.passed) {
                  console.error(`[posta] demo-ai QA: la pieza ${i} (${sp.headline}) quedó sin pasar tras el reintento: ${(qaRes.failures || []).join(', ')} — ${qaRes.detalle || ''}`);
                }
              }
              pieceEngines[i] = gen.engine;
              // (v209) DOSIFICACIÓN también en la ruta IA: la pieza
              // limpia NO compone titular (su imagen cruda ya pasó el QA
              // de "sin texto"); la pieza con texto compone arriba y
              // pasa el 4º chequeo del QA sobre la pieza COMPUESTA: el
              // titular no puede tapar caras, ojos ni el producto o
              // personaje. Si tapa, se recompone en la zona opuesta —
              // ese es su reintento (sin regenerar la imagen).
              const inkFor = (treatments[i] === 'flat' || treatments[i] === 'poster') ? inkHex : null;
              if (specPosts[i].text_mode === 'clean') {
                pieceQa[i] = { ...qaInfo, text: null };
                return demoAi.compositeDemoPiece({
                  b64: gen.b64, headline: '', gradeHex: accent, workDir: runDir, index: i, headlineScale, inkHex: inkFor,
                });
              }
              let buf = await demoAi.compositeDemoPiece({
                b64: gen.b64, headline: made[i].headline, gradeHex: accent, workDir: runDir, index: i, headlineScale, inkHex: inkFor, zone: 'top',
              });
              let textInfo = { passed: true, zone: 'top', retried: false };
              const textQa = buf ? await demoAi.qaComposedText({ b64: buf.toString('base64'), zone: 'top', apiKey: demoApiKey }) : null;
              if (textQa) textInfo.passed = textQa.passed;
              if (buf && textQa && !textQa.passed && costs.demoAiCapOk()) {
                const buf2 = await demoAi.compositeDemoPiece({
                  b64: gen.b64, headline: made[i].headline, gradeHex: accent, workDir: runDir, index: i, headlineScale, inkHex: inkFor, zone: 'bottom',
                }).catch(() => null);
                let swapped = false;
                if (buf2) {
                  const textQa2 = await demoAi.qaComposedText({ b64: buf2.toString('base64'), zone: 'bottom', apiKey: demoApiKey });
                  if (textQa2 && textQa2.passed) { buf = buf2; swapped = true; }
                }
                textInfo = swapped
                  ? { passed: true, zone: 'bottom', retried: true }
                  : { passed: false, zone: 'top', retried: true };
                if (!swapped) {
                  console.error(`[posta] demo-ai QA texto: la pieza ${i} (${made[i].headline}) tapa el sujeto según visión y la otra zona no lo resolvió: ${textQa.detalle || ''}`);
                }
              }
              pieceQa[i] = { ...qaInfo, text: textInfo };
              return buf;
            };
            const { replaced } = await demoAi.replacePiecesWithAi({
              indexes: posts.map((_, i) => i),
              capOk: () => costs.demoAiCapOk(),
              makePiece,
              onPiece: async (i, buf) => {
                bufs[i] = buf;
                // El diseño IA pisa el JPG del runDir: el video-tour de
                // la semana recorre las piezas IA, no las plantillas.
                try { fs.writeFileSync(path.join(runDir, `post-${i}.jpg`), buf); } catch (e) {}
                posts[i] = {
                  type: 'image',
                  image: 'data:image/jpeg;base64,' + buf.toString('base64'),
                  caption: made[i].caption,
                  hashtags: made[i].hashtags,
                  headline: made[i].headline,
                  style: specPosts[i].style,
                  style_name: specPosts[i].style_name,
                  text_mode: specPosts[i].text_mode || 'text',
                  treatment: treatments[i],
                  ai: true,
                  engine: pieceEngines[i] || null,
                  qa: pieceQa[i] || null,
                };
                send('post', { index: i, day: week[i].day, date: week[i].date, hour: week[i].hour, post: posts[i] });
              },
            });
            demoAiInfo.used = replaced.size > 0;
            demoAiInfo.pieces = replaced.size;
            demoAiInfo.engines = posts.map((_, i) => pieceEngines[i] || null);
            demoAiInfo.qa = posts.map((_, i) => pieceQa[i] || null);
            demoAiInfo.text_modes = specPosts.map((sp) => sp.text_mode || 'text');
          } catch (e) {
            console.error('[posta] demo-ai: la tanda IA falló, quedan las plantillas:', e.message);
          } finally {
            clearInterval(aiKeepalive);
          }
        }
      }
      if (demoSpendBefore != null) {
        demoAiInfo.cost_usd = Math.round(Math.max(0, costs.demoAiSpendTodayUsd() - demoSpendBefore) * 100) / 100;
      }
    }

    // 4) El video (v182): recorre TODOS los diseños con cortes (tour por
    // las piezas), ya no anima una sola tarjeta estática. Necesita los 5
    // diseños listos, así que arranca acá; los JPG ya están en runDir.
    send('status', { step: 'video', text: lang === 'en' ? "I'm creating your week's video…" : 'Estoy creando el video de tu semana…' });
    // v188: el paso de video+extras es el tramo en silencio más largo del
    // stream (la corrida real de v187 se cortó a los ~127 s sin done: el
    // proxy corta la conexión por inactividad). Un status cada 20 s lo
    // mantiene vivo; el front ya sabe mostrarlo (es el mismo tracker).
    keepalive = setInterval(() => send('status', { step: 'video', text: lang === 'en' ? "I'm creating your week's video…" : 'Estoy creando el video de tu semana…' }), 20000);
    if (keepalive.unref) keepalive.unref();
    const designPaths = specPosts.map((_, i) => path.join(runDir, `post-${i}.jpg`));
    // v187: visuales extra para la grilla CON Posty de la proyección, SIN
    // repetir ningún diseño de la semana: (A) diseños de los temas del pool
    // que la semana no usó (cada rubro trae 6, la semana usa 5) y (B) fotos
    // del rubro sin titular con tratamientos de ESTA semana — todo con
    // fotos distintas a las de la semana (excludePhotos). Corren en
    // paralelo con el video; si fallan, la grilla muestra 6 celdas.
    const buildTrialGridExtras = async () => {
      const posts = [];
      const usedPhoto = new Set((spec.photos || []).map((p) => String(p)));
      const usedTema = new Set((spec.topics || []).map((t) => (t && (t.tema || t.headline)) || ''));
      // (v196) El tratamiento que hereda un extra NUNCA es el póster: un
      // extra es una foto/diseño de la semana, no un póster de marca.
      const weekTreat = (j) => {
        const arr = spec.specPosts;
        for (let m = 0; m < arr.length; m++) {
          const cand = arr[(j + m) % arr.length];
          if (cand && !(cand.treatment && cand.treatment.skeleton === 'poster')) return cand;
        }
        return arr[j % arr.length] || {};
      };
      const probe = (off) => {
        try {
          return demo.buildDemoSpec({ business, category, country: effCountry, tone, photoPath: null, goal: richGoal, goal_key, accent, btn, count: 1, topicOffset: off, excludePhotos: [...usedPhoto], bioText, lang });
        } catch (e) { return null; }
      };
      for (let off = n; off < n + 3 && posts.length < 3; off++) {
        const pr = probe(off);
        if (!pr || !pr.specPosts.length) continue;
        const sp = pr.specPosts[0];
        const tema = sp.tema || sp.headline || '';
        if (!tema || usedTema.has(tema)) continue;
        if (typeof sp.photo !== 'string' || usedPhoto.has(sp.photo)) continue;
        const w = weekTreat(posts.length + 2);
        posts.push({ ...sp, style: w.style, style_name: w.style_name, treatment: w.treatment });
        usedTema.add(tema); usedPhoto.add(sp.photo);
      }
      while (posts.length < 3) {
        const pr = probe(n);
        if (!pr || !pr.specPosts.length) break;
        const sp = pr.specPosts[0];
        if (typeof sp.photo !== 'string' || usedPhoto.has(sp.photo)) break;
        const w = weekTreat(posts.length + 3);
        posts.push({ ...sp, style: w.style, style_name: w.style_name, treatment: w.treatment, headline: '', subline: '', pill: '', cta: '', kind: 'foto', tema: null });
        usedPhoto.add(sp.photo);
      }
      if (!posts.length) return [];
      const r = await demo.renderSpecPngs(posts, { accent, btn });
      try { fs.rmSync(r.runDir, { recursive: true, force: true }); } catch (e) {}
      return r.bufs.map((b) => 'data:image/jpeg;base64,' + b.toString('base64'));
    };
    const extrasPromise = (async () => {
      try { return ig ? await buildTrialGridExtras() : []; } catch (e) { return []; }
    })();
    const videoB64 = await demo.renderVideoB64(designPaths, runDir, videoIdx);
    if (videoB64) {
      posts[videoIdx] = {
        type: 'video',
        video: 'data:video/mp4;base64,' + videoB64,
        // v187: la tapa del reel (el still de su diseño) — la grilla CON
        // Posty la usa como celda propia, como hace Instagram con los reels.
        cover: 'data:image/jpeg;base64,' + bufs[videoIdx].toString('base64'),
        caption: made[videoIdx].caption,
        hashtags: made[videoIdx].hashtags,
        headline: made[videoIdx].headline,
        style: specPosts[videoIdx].style,
        style_name: specPosts[videoIdx].style_name,
        text_mode: specPosts[videoIdx].text_mode || 'text',
        // v205: si la pieza del reel salió del motor IA, su motor y su
        // QA viajan también en el posteo video (antes se perdían acá).
        ...(pieceEngines[videoIdx] ? { ai: true, engine: pieceEngines[videoIdx], qa: pieceQa[videoIdx] || null, ...(demoTreatments ? { treatment: demoTreatments[videoIdx] } : {}) } : {}),
      };
    } else {
      posts[videoIdx] = {
        type: 'image',
        image: 'data:image/jpeg;base64,' + bufs[videoIdx].toString('base64'),
        caption: made[videoIdx].caption,
        hashtags: made[videoIdx].hashtags,
        headline: made[videoIdx].headline,
        style: specPosts[videoIdx].style,
        style_name: specPosts[videoIdx].style_name,
        text_mode: specPosts[videoIdx].text_mode || 'text',
        ...(pieceEngines[videoIdx] ? { ai: true, engine: pieceEngines[videoIdx], qa: pieceQa[videoIdx] || null, ...(demoTreatments ? { treatment: demoTreatments[videoIdx] } : {}) } : {}),
      };
    }
    send('post', { index: videoIdx, day: week[videoIdx].day, date: week[videoIdx].date, hour: week[videoIdx].hour, post: posts[videoIdx] });

    const videoOk = posts.some((p) => p && p.type === 'video' && p.video);
    if (!videoOk) console.error('[posta] ⚠️ TRIAL sin video para', business, '— revisar render de video');

    let screenshot = null;
    if (photoPath) {
      const ext = photoPath.split('.').pop().toLowerCase();
      screenshot = `data:${TRIAL_IMG_MIME[ext] || 'image/jpeg'};base64,` + fs.readFileSync(photoPath).toString('base64');
    }
    const gridExtra = await extrasPromise;
    // (v210) La generación tarda más que el análisis de paleta casi
    // siempre; esta espera corta es solo un seguro para que la auditoría
    // del payload final incluya la señal de línea visual si ya llegó.
    if (trialAuditPalette) {
      try { await Promise.race([trialAuditPalette, new Promise((r) => setTimeout(() => r(null), 1200))]); } catch (e) { /* sigue sin paleta */ }
    }
    // 🧠 Análisis completo (2026-10-19): radiografía de la cuenta + probada de
    // mercado, o plan de nacimiento si la cuenta recién arranca — y el porqué
    // de cada posteo de la prueba, atado a los hallazgos. Nunca frena la prueba.
    let trialAnalysis = null;
    let competitionLine = null;
    try {
      const peers = await fetchPeersForAnalysis(peerHandlesFromText(competitors));
      const ctxA = { postsPerWeek: 7, plan: 'trial', peers, source: 'instagram', lang };
      const cold = !ig || !trialData || !trialData.ok || analysisEngine.isColdStart({ hasIg: !!ig, profile: trialData && trialData.profile, posts: (trialData && trialData.posts) || [] });
      if (cold) {
        trialAnalysis = analysisEngine.analyzeColdStart({
          business: { name: business, category: effCategory, city: (trialDigest && trialDigest.ciudad) || '', ig_username: ig },
          digest: trialDigest, peers, reviews: null, ctx: ctxA,
        });
      } else {
        trialAnalysis = analysisEngine.analyzeExisting({ profile: trialData.profile, posts: trialData.posts, ctx: ctxA });
      }
      // (v323 · pieza 19) La línea de competencia se calcula del análisis
      // CRUDO (el gate de prueba vacía los pares): solo números leídos.
      competitionLine = trialCompetitionLine(trialAnalysis);
      trialAnalysis = analysisEngine.gateForPlan(trialAnalysis, 'trial');
      if (Array.isArray(posts)) {
        for (const p of posts) {
          if (!p || p.why) continue;
          const w = analysisEngine.whyForPost({ tipo: p.tipo || p.kind || '', formato: p.type || '', salesIntent: p.sales_intent || '', porque: p.porque || '' }, trialAnalysis, trialDigest);
          if (w) p.why = w;
        }
      }
    } catch (e) { /* el análisis nunca frena la prueba */ }
    // Payload IDÉNTICO al de /api/trial/generate (el frontend lo guarda en idb igual)
    const out = {
      ok: true,
      engine: demo.DEMO_ENGINE_V,
      lang, // (v274) idioma de la semana (caché, chat, registro)
      business, ig, category: effCategory,
      subcat: rubroRes.subcat || '', // (v235) subrubro confirmado/detectado
      rubro_check: rubroRes.rubroCheck, // (v235) la duda queda registrada
      accent, btn, color_source: colorSource,
      feed_register: spec.feedRegister || null,
      web_info: trialWebInfo(webData, trialWebPhotosUsed(spec.photos)),
      digest: trialDigest, // (v229) FUNDAMENTO: viaja al trial_cache y a la cuenta al registrarse
      feed_kind: feedKind,
      feed_formula: feedFormula,
      feed_palette: feedPalette,
      demo_ai: demoAiInfo,
      ig_pic: igPic, ig_name: igName,
      profile: trialProfile,
      audit: trialAudit,
      analysis: trialAnalysis,
      competition_line: competitionLine,
      grid_extra: gridExtra,
      ideas: ideas.slice(0, 6),
      posts,
      design: {
        posts: specPosts,
        styles: spec.styles,
        photos: spec.photos,
        videoIdx, count: n,
        engine: demo.DEMO_ENGINE_V,
        subcat: spec.subcat || null,
      },
      week, // día/fecha por posteo (el mismo que viaja en los eventos post)
      screenshot,
      spots_left: spotsLeft(),
      video_ok: videoOk,
    };
    // Cache 72h por @, igual que /api/trial/generate
    if (!testMode && igKey) {
      try {
        const payload = JSON.stringify(out);
        if (payload.length < 12 * 1024 * 1024) {
          db.prepare(`INSERT INTO trial_cache (ig, payload, created_at) VALUES (?, ?, ?)
            ON CONFLICT(ig) DO UPDATE SET payload=excluded.payload, created_at=excluded.created_at`).run(igKey, payload, Date.now());
        }
      } catch (e) { console.error('[posta] no se pudo cachear la prueba:', e.message); }
    }
    // (v323 · pieza 8) Nace el candado de 90 días de este negocio.
    if (!testMode) trialLockRecordFor(fields, webData, business, lang, out);
    track(null, 'prueba_done', igKey);
    if (!closed) { send('done', { out }); doneSent = true; }
    finish();
  } catch (e) {
    console.error('[posta] Error en prueba streaming:', e.message);
    fail('No pudimos armar tu prueba ahora. Probá de nuevo en unos minutos.');
  } finally {
    if (keepalive) clearInterval(keepalive);
    // Falló la generación o el stream se cortó a mitad (el cliente nunca
    // recibió 'done'): el intento se reembolsa, no se consume.
    if (charged && !doneSent) demo.refundTrialAttempt(ip);
    if (photoPath) {
      try { fs.unlinkSync(photoPath); } catch (_) {}
    }
    if (runDir) {
      try { fs.rmSync(runDir, { recursive: true, force: true }); } catch (_) {}
    }
  }
});

// ---------- Chat de la prueba: mejorar los posteos por chat ----------
// El visitante pide cambios ("hacelo más canchero") y la IA edita los TEXTOS
// (caption/hashtags) de sus posteos ya creados. Los cambios se guardan en el
// trial_cache, así viajan a su cuenta como borradores cuando se registra.
// Sin login: rate limit de 8 mensajes por día por IP.
const TRIAL_CHAT_LIMIT = 8;
try { db.exec('CREATE TABLE IF NOT EXISTS trial_chat_usage (ip TEXT, day TEXT, count INTEGER DEFAULT 0, PRIMARY KEY (ip, day))'); } catch (e) {}
function trialChatAllowed(ip) {
  const day = new Date().toISOString().slice(0, 10);
  try {
    if (Math.random() < 0.05) db.exec(`DELETE FROM trial_chat_usage WHERE day < date('now', '-7 days')`);
    const row = db.prepare('SELECT count FROM trial_chat_usage WHERE ip = ? AND day = ?').get(ip, day);
    if (row && row.count >= TRIAL_CHAT_LIMIT) return { ok: false, remaining: 0 };
    db.prepare('INSERT INTO trial_chat_usage (ip, day, count) VALUES (?, ?, 1) ON CONFLICT(ip, day) DO UPDATE SET count = count + 1').run(ip, day);
    const now = db.prepare('SELECT count FROM trial_chat_usage WHERE ip = ? AND day = ?').get(ip, day);
    return { ok: true, remaining: Math.max(0, TRIAL_CHAT_LIMIT - (now ? now.count : 1)) };
  } catch (e) { return { ok: true, remaining: TRIAL_CHAT_LIMIT }; }
}
app.post('/api/trial/chat', express.json({ limit: '64kb' }), async (req, res) => {
  const ip = demo.clientIp(req);
  const { ig, message, history, lang: langHint } = req.body || {};
  const msg = String(message || '').trim().slice(0, 300);
  const igKey = String(ig || '').trim().replace(/^@/, '').toLowerCase();
  const hintEn = String(langHint || '').trim().toLowerCase() === 'en';
  if (!msg) return res.status(400).json({ error: hintEn ? 'tell me what you want to change 🙂' : 'escribí qué querés cambiar 🙂' });
  if (!igKey || !/^[a-z0-9._]{1,30}$/.test(igKey)) return res.status(400).json({ error: hintEn ? 'your instagram is missing' : 'falta tu instagram' });
  const chatChk = trialChatAllowed(ip);
  if (!chatChk.ok) return res.status(429).json({ error: 'chat_limit' });
  const hit = db.prepare('SELECT payload FROM trial_cache WHERE ig = ?').get(igKey);
  if (!hit) return res.status(404).json({ error: hintEn ? 'we could not find your week. build it again 🙂' : 'no encontramos tu semana. generala de nuevo 🙂' });
  let out;
  try { out = JSON.parse(hit.payload); } catch (e) { return res.status(500).json({ error: hintEn ? 'we could not read your week' : 'no pudimos leer tu semana' }); }
  // (v274 · MODO EN) El idioma del chat sale del payload de la prueba: si
  // la semana nació EN, Posty edita y responde en inglés (precios USD).
  const en = out.lang === 'en' || hintEn;
  const posts = out.posts || [];
  if (!posts.length) return res.status(404).json({ error: en ? 'we could not find your posts' : 'no encontramos tus posteos' });
  const apiKey = process.env.OPENAI_API_KEY || '';
  if (!apiKey) return res.status(500).json({ error: en ? 'chat is not available right now. try again in a few minutes.' : 'el chat no está disponible ahora. probá en unos minutos.' });
  const week = out.week || [];
  const postList = posts.map((p, i) => {
    const w = week.find((x) => x.post === i);
    return { i, dia: w ? w.day : ((en ? 'post ' : 'posteo ') + (i + 1)), caption: String(p.caption || ''), hashtags: String(p.hashtags || '') };
  });
  const hist = Array.isArray(history) ? history.slice(-6).map((h) => `${h.role === 'user' ? (en ? 'Owner' : 'Dueño') : (en ? 'Posty' : 'Posta')}: ${String(h.text || '').slice(0, 200)}`).join('\n') : '';
  // (v274 · MODO EN) System prompt del chat EN: mismo rol y mismas reglas,
  // en inglés US y con los precios EN (USD 49/99/149 — ver config/plans.js,
  // bloque PLANS_US: el cobro US va por Stripe, todavía sin alta; el chat
  // solo informa precios, nunca cobra).
  const sysEn =
    'You are the content editor of Posty, a service that builds Instagram posts for local businesses. ' +
    'You are talking to the owner of "' + String(out.business || 'their business').slice(0, 60) + '" (category: ' + String(out.category || 'general').slice(0, 30) + ') who is on a free trial and ALREADY has their 5 posts created. ' +
    'They ask for changes. You can ONLY edit texts: the caption and hashtags of one or more posts. ' +
    'You cannot change designs, photos or headlines (they are part of the image). If they ask to change a post PHOTO, guide them: "tap the post and then the 📷 Change photo button". ' +
    'If they ask to change COLORS, guide them: "tap the 🎨 Colors button right below". ' +
    'If they ask to change the design HEADLINE, explain in one line that the headline is part of the design and offer to improve the caption instead. ' +
    'Write in clear US English, warm and confident, 1-2 lines. Your visible "reply" text is a WhatsApp-style chat: write it ALL in lowercase (even at the start of sentences), short and friendly — e.g. "done! i changed that caption for you ✅" or "sure — what would you tweak first?". The texts you edit (captions and hashtags) are the work product: they keep their normal published capitalization and punctuation.\n\n' +
    'Posts (index, day, current caption, current hashtags):\n' +
    postList.map((p) => `#${p.i} (${p.dia}): "${p.caption.slice(0, 220)}" [${p.hashtags.slice(0, 120)}]`).join('\n') +
    (hist ? '\n\nRecent history:\n' + hist : '') +
    '\n\nOwner request: "' + msg.replace(/"/g, "'") + '"\n\n' +
    'Reply ONLY with a JSON: {"edits": [{"post": <index>, "caption": "...", "hashtags": "..."}], "reply": "<short reply the user sees>"}. ' +
    'If the request applies to several posts, include all of them. If it is unclear, edits: [] and ask for clarification in reply. ' +
    'SALES (once per conversation): this visitor does NOT have an account yet. You know the service: Posty runs a business Instagram (ideas, designs, texts and scheduling for them; nothing goes out without their OK). ' +
    'Free 3-day trial, no card. Plans: Essential $99.99/month (community manager: 7 posts + 1 reel per week), Pro $189.99/month (adds Growth: 3 reels per week, stories 3x per week — the recommended one, $6.33 a day), Total $289.99/month (adds customer care: daily stories, comment and message replies). ' +
    'If they ask what Posty is, how much it costs, how to continue or how to save their posts: answer shortly with these facts in "reply" and offer ONCE to create their free account to save everything and build their first week. ' +
    'If they say no, do not insist. Objections: "too expensive" → the recommended Pro works out to $6.33 a day, and Essential starts at $99.99; "no time" → they need no time, we do everything; distrust → Try it free, no card.' +
    '\n\nCAPTION RULES: one idea per post; specific beats generic (name the real product/service); one concrete CTA per caption; at most 5 hashtags; no stock openers ("Welcome to our page", "We are excited to announce"); never invent prices, promos or results.';
  const sysEs =
    'Sos el editor de contenidos de Posta, un servicio argentino que arma los posteos de Instagram de los negocios. ' +
    'Hablás con el dueño de "' + String(out.business || 'su negocio').slice(0, 60) + '" (rubro: ' + String(out.category || 'general').slice(0, 30) + ') que está probando gratis y YA tiene sus 5 posteos creados. ' +
    'Te pide cambios. Podés editar ÚNICAMENTE los textos: caption y hashtags de uno o varios posteos. ' +
    'NO podés cambiar diseños, fotos ni titulares (vienen en la imagen). Si te pide cambiar la FOTO de un posteo, guialo: "tocá el posteo y después el botón 📷 Cambiar foto". ' +
    'Si te pide cambiar los COLORES, guialo: "tocá el botón 🎨 Colores que está acá abajo". ' +
    'Si te pide cambiar el TITULAR del diseño, explicale en una línea que el titular es parte del diseño y ofrecé mejorar el caption en su lugar. ' +
    'Escribís en español rioplatense con voseo, tono cercano y canchero, 1-2 líneas. Tu texto visible ("reply") es un chat de WhatsApp: escribilo TODO en minúscula (también al arrancar cada frase) y sin signos de apertura (nada de ¡ ni ¿; los de cierre van normal) — ej: "listo! te cambié ese caption ✅" o "dale — qué querés tocar primero?". Los textos que editás (captions y hashtags) son el trabajo que se publica: mantienen su escritura normal.\n\n' +
    'Posteos (índice, día, caption actual, hashtags actuales):\n' +
    postList.map((p) => `#${p.i} (${p.dia}): "${p.caption.slice(0, 220)}" [${p.hashtags.slice(0, 120)}]`).join('\n') +
    (hist ? '\n\nHistorial reciente:\n' + hist : '') +
    '\n\nPedido del dueño: "' + msg.replace(/"/g, "'") + '"\n\n' +
    'Respondé SOLO con un JSON: {"edits": [{"post": <índice>, "caption": "...", "hashtags": "..."}], "reply": "<respuesta corta que ve el usuario>"}. ' +
    'Si el pedido aplica a varios posteos, incluí todos los que correspondan. Si no se entiende, edits: [] y pedí aclaración en reply. ' +
    'VENTA (una sola vez por conversación): este visitante todavía NO tiene cuenta. Conocés el servicio: Posta maneja el Instagram de negocios (ideas, diseños, textos y publicación por él; nada sale sin su OK). ' +
    'Prueba gratis de 3 días, sin tarjeta. Planes: Esencial $99.999/mes (Community Manager), Pro $189.900/mes (CM + Growth, el recomendado — $6.330 por día), Total $289.900/mes (CM + Growth + Atención al cliente). ' +
    'Si pregunta qué es Posta, cuánto sale, cómo seguir o cómo guardar sus posteos: respondé corto con estos datos en "reply" y ofrecé UNA vez que cree su cuenta gratis para guardar todo y armar su primera semana. ' +
    'Si dice que no, no insistas. Objeciones: "es caro" → el recomendado sale $6.330 por día; "no tengo tiempo" → no necesita tiempo, lo hacemos todo nosotros; desconfianza → Probalo gratis, sin tarjeta.' +
    // El visitante no tiene cuenta (no hay perfil de estilo): el checklist anti-genérico sí aplica.
    (CAPTION_CHECKLIST ? '\n\n' + CAPTION_CHECKLIST : '');
  const sys = en ? sysEn : sysEs;
  try {
    const ai = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + apiKey },
      body: JSON.stringify({
        model: 'gpt-4o-mini',
        response_format: { type: 'json_object' },
        messages: [{ role: 'system', content: sys }, { role: 'user', content: msg }],
        max_tokens: 900,
        temperature: 0.8,
      }),
    });
    if (!ai.ok) throw new Error('OpenAI ' + ai.status);
    const data = await ai.json();
    costs.trackUsage({ feature: 'chat-trial', model: 'gpt-4o-mini', json: data });
    let parsed;
    try { parsed = JSON.parse(data.choices[0].message.content); } catch (e) { throw new Error('respuesta IA inválida'); }
    const edits = (parsed.edits || [])
      .filter((e) => e && Number.isInteger(e.post) && e.post >= 0 && e.post < posts.length)
      .slice(0, 5);
    for (const e of edits) {
      if (typeof e.caption === 'string' && e.caption.trim()) posts[e.post].caption = e.caption.trim().slice(0, 600);
      if (typeof e.hashtags === 'string' && e.hashtags.trim()) posts[e.post].hashtags = e.hashtags.trim().slice(0, 300);
    }
    if (edits.length) {
      try { db.prepare('UPDATE trial_cache SET payload = ? WHERE ig = ?').run(JSON.stringify(out), igKey); } catch (e) {}
    }
    res.json({
      reply: chatStripOpen(String(parsed.reply || (en ? 'done ✅ anything else?' : 'listo ✅ algo más?'))).slice(0, 300),
      edits: edits.map((e) => ({ post: e.post, caption: posts[e.post].caption, hashtags: posts[e.post].hashtags })),
      chat_remaining: chatChk.remaining,
    });
  } catch (e) {
    console.error('[posta] trial chat:', e.message);
    res.status(500).json({ error: en ? 'i could not process that. try again 🙂' : 'no pude procesar tu pedido. probá de nuevo 🙂' });
  }
});

// ---------- Chat público "Hablá con Posty" (landing + /prueba) ----------
// Canal de atención/venta atendido por Posty (la IA, el personaje), sin
// login. Cada conversación se guarda en posty_chats para revisión humana;
