// Track 4 "Pipeline perpetuo": el cron semanal de scheduler.js hace require
// perezoso de este módulo (ya cargado) para llamar al barrido. No requerir
// scheduler.js desde acá abajo: server.js ya lo requiere arriba.
// ---------- FUNDAMENTO (v229): refresco del digest con cadencia ----------
// Lo llama el scheduler los lunes 06:30 (Buenos Aires), ANTES del loop de
// ideas de las 07:00: el fundamento no queda congelado el día del alta.
//  · website_url con estudio de ≥30 días → re-estudio solo (mismo merge
//    que el endpoint manual) + bloque web reconstruido desde web-extract
//    (productos/servicios reales, USD 0).
//  · IG conectado → bio/temas del feed re-minados (≥7 días) y locks de
//    estilo re-analizados si tienen ≥30 días (con kill-switch de gasto).
// (v230) LECTURA PROFUNDA, en las mismas cadencias:
//  · con la web (30 días o primera vez): catálogo completo del sitio
//    (páginas de catálogo/tienda/menú + PDFs enlazados, USD 0).
//  · con el feed (7 días): link de la bio seguido hasta su tienda/
//    reserva; léxico re-minado de los captions frescos; mapa
//    foto→producto para las fotos nuevas (álbum + publicados, caché
//    por contenido, tope por corrida, guarda de gasto); estrella
//    inferido y contradicciones recalculados con el rendimiento.
// Merge: lo editado a mano en el ADN manda — las listas del digest se
// re-derivan del ADN vigente y solo se reemplazan los bloques cuya
// fuente se refrescó en esta corrida.
async function refreshDigestsSweep() {
  const summary = { users: 0, web: 0, feed: 0, locks: 0, saved: 0, errors: 0, catalog: 0, bioLink: 0, photoMap: 0 };
  const DAY = 24 * 3600 * 1000;
  const ageOf = (iso) => { const t = Date.parse(iso || ''); return Number.isFinite(t) ? Date.now() - t : Infinity; };
  try {
    const rows = db.prepare(`SELECT user_id FROM client_digest
      UNION SELECT user_id FROM profiles WHERE ig_connected = 1
      UNION SELECT user_id FROM business_dna WHERE dna_json LIKE '%"website_url"%'`).all().slice(0, 40);
    for (const row of rows) {
      const uid = row.user_id;
      try {
        summary.users++;
        const prof = getProfile(uid) || {};
        let dna = readDna(uid);
        const stored = clientDigest.getStoredDigest(db, uid);
        const webUrl = String(dna.website_url || '').trim();
        const webStale = !!webUrl && (ageOf(dna.website_analyzed_at) >= 30 * DAY
          || !stored || ageOf(stored.fuentes && stored.fuentes.web && stored.fuentes.web.at) >= 30 * DAY);
        const feedStale = !!(prof.ig_connected && prof.ig_username)
          && (!stored || ageOf(stored.fuentes && stored.fuentes.feed && stored.fuentes.feed.at) >= 7 * DAY);
        // (v230) El catálogo profundo se lee con la cadencia de la web
        // (30 días) y también la PRIMERA vez que falta el bloque.
        const catalogDue = !!webUrl && (!stored || !stored.catalog
          || ageOf(stored.fuentes && stored.fuentes.catalog && stored.fuentes.catalog.at) >= 30 * DAY);
        if (!webStale && !feedStale && !catalogDue && stored) continue;
        const parts = {
          business: prof.business_name || (stored && stored.business) || '',
          category: (stored && stored.category) || prof.category || '',
          dna, form: { description: prof.description || '' },
        };
        let webFresh = null;
        let feedFresh = null;
        if (webStale) {
          try {
            const wd = await webExtract.fetchBusinessSite(webUrl);
            if (wd && wd.ok) {
              webFresh = { name: wd.name, description: wd.description, services: wd.services || [], city: wd.city, palette: wd.palette || [], url: wd.url, categoryHint: wd.categoryHint };
              summary.web++;
            }
          } catch (e) { /* web caída: se sigue con el resto */ }
          try {
            const key = openaiKeyFor(uid);
            if (key) {
              costs.assertAiOk(uid);
              const r = await analyzeWebsite(webUrl, key);
              if (r && r.source !== 'mercadolibre') {
                const cur = readDna(uid);
                const patch = { website_url: r.website_url, website_analyzed_at: new Date().toISOString(), website_partial: !!r.partial };
                for (const f of WEBSITE_DNA_FIELDS) if (websiteFieldHas(r[f])) patch[f] = r[f];
                writeDna(uid, { ...cur, ...patch });
                dna = readDna(uid);
                parts.dna = dna;
              }
            }
          } catch (e) { /* sin presupuesto o estudio fallido: el bloque web-extract ya refrescó lo esencial */ }
        }
        // (v230) CATÁLOGO PROFUNDO con la cadencia de la web: páginas de
        // catálogo/tienda/menú del propio sitio + PDFs enlazados (USD 0).
        if ((webStale || catalogDue) && webUrl) {
          try {
            const cat = await deepRead.fetchDeepCatalog(webUrl);
            if (cat && cat.items && cat.items.length) { parts.catalog = cat; summary.catalog++; }
          } catch (e) { /* catálogo ilegible esta vuelta: se sigue */ }
        }
        if (feedStale) {
          let feedLink = '';
          try {
            const data = await feedAudit.fetchAuditData(prof.ig_username);
            if (data && data.ok && data.profile) {
              feedFresh = {
                bio: data.profile.bio || '',
                captions: (data.posts || []).map((x) => String((x && x.caption) || '').slice(0, 240)).filter(Boolean).slice(0, 12),
                name: data.profile.name || '', handle: data.profile.handle || prof.ig_username,
              };
              feedLink = data.profile.link || '';
              summary.feed++;
            }
          } catch (e) { /* feed no disponible: se sigue */ }
          // (v230) LINK DE LA BIO con la cadencia del feed: se sigue
          // hasta su tienda/reserva y los ítems legibles entran al digest.
          if (feedLink) {
            try {
              const bl = await deepRead.fetchBioLink(feedLink);
              if (bl) { parts.bioLink = bl; summary.bioLink++; }
            } catch (e) { /* link caído: se sigue */ }
          }
          // (v230) MAPA FOTO→PRODUCTO con la cadencia del feed: fotos de
          // su álbum + sus posteos publicados, SOLO las no clasificadas
          // (caché por hash de contenido en el propio mapa), tope duro
          // por corrida y guarda de gasto — si el guarda frena, el mapa
          // se completa en la próxima cadencia, en silencio.
          try {
            const key = openaiKeyFor(uid);
            if (key) {
              const candPaths = [];
              try {
                for (const r of db.prepare(`SELECT file_path FROM assets WHERE user_id = ? AND kind = 'photo' ORDER BY created_at DESC LIMIT 12`).all(uid)) candPaths.push(r.file_path);
                for (const r of db.prepare(`SELECT image_path FROM posts WHERE user_id = ? AND status = 'published' AND image_path LIKE '/media/%' ORDER BY id DESC LIMIT 8`).all(uid)) candPaths.push(r.image_path);
              } catch (e) {}
              const already = (stored && stored.photo_map && stored.photo_map.entries) || {};
              const photos = [];
              for (const fp of candPaths) {
                if (photos.length >= deepRead.VISION_MAX_PHOTOS) break;
                const abs = path.join(MEDIA_DIR, path.basename(String(fp || '')));
                const k = deepRead.photoContentKey(abs);
                if (!k || already[k] || photos.some((x) => x.key === k)) continue;
                photos.push({ key: k, path: abs });
              }
              if (photos.length) {
                costs.assertAiOk(uid);
                const itemNames = [...((stored && stored.productos) || []), ...((stored && stored.servicios) || [])]
                  .map((x) => (x && (x.nombre || x)) || '').filter(Boolean);
                const entries = await deepRead.classifyDigestPhotos({ photos, items: itemNames, apiKey: key, userId: uid });
                if (entries && Object.keys(entries).length) { parts.photoEntries = entries; summary.photoMap += Object.keys(entries).length; }
              }
            }
          } catch (e) { /* mapa best-effort: nunca frena el refresco */ }
          try {
            const cs = db.prepare('SELECT analyzed_at FROM ig_caption_style WHERE user_id = ?').get(uid);
            const vs = db.prepare('SELECT analyzed_at FROM ig_visual_style WHERE user_id = ?').get(uid);
            const csStale = !cs || ageOf(cs.analyzed_at) >= 30 * DAY;
            const vsStale = !vs || ageOf(vs.analyzed_at) >= 30 * DAY;
            if (csStale || vsStale) {
              costs.assertAiOk(uid);
              if (csStale && typeof analyzeCaptionStyle === 'function') { await analyzeCaptionStyle(db, uid); summary.locks++; }
              if (vsStale && typeof analyzeVisualStyle === 'function') { await analyzeVisualStyle(db, uid); summary.locks++; }
            }
          } catch (e) { /* locks: best-effort, nunca frenan el refresco */ }
        }
        // (v230) Señales del estrella inferido: su rendimiento medido
        // (los captions de sus posteos con más alcance, 90 días).
        if (feedStale || webStale || catalogDue) {
          try {
            const mrows = db.prepare(`SELECT p.caption AS caption, m.reach AS reach FROM post_metrics m JOIN posts p ON p.id = m.post_id
              WHERE p.user_id = ? AND p.status = 'published' AND p.published_at >= datetime('now', '-90 days') AND m.reach > 0
              ORDER BY m.reach DESC LIMIT 12`).all(uid);
            if (mrows.length) parts.starSignals = { metrics: mrows.map((r) => ({ text: String(r.caption || '').slice(0, 160), reach: r.reach })) };
          } catch (e) {}
        }
        if (!stored && !webFresh && !feedFresh && !parts.catalog && !parts.bioLink) {
          const seeded = clientDigest.buildFromParts(parts);
          if (clientDigest.hasFoundation(seeded)) { clientDigest.saveDigest(db, uid, seeded); summary.saved++; }
          continue;
        }
        const fresh = clientDigest.buildFromParts({ ...parts, web: webFresh, feed: feedFresh });
        const merged = { ...(stored || fresh) };
        if (feedFresh) {
          merged.temas_feed = fresh.temas_feed;
          if (fresh.protagonista) merged.protagonista = fresh.protagonista;
          merged.fuentes = { ...(merged.fuentes || {}), feed: fresh.fuentes.feed };
          merged.has_booking = !!(merged.has_booking || fresh.has_booking);
        }
        if (webFresh) {
          merged.productos = fresh.productos;
          merged.servicios = fresh.servicios;
          merged.promos = fresh.promos;
          if (fresh.ciudad) merged.ciudad = fresh.ciudad;
          merged.fuentes = { ...(merged.fuentes || {}), web: fresh.fuentes.web };
        }
        if (fresh.diferencial) merged.diferencial = fresh.diferencial;
        merged.built_at = new Date().toISOString();
        // (v230) Los bloques profundos se fusionan sobre el merge de
        // siempre (aditivo, por bloque; el mapa de fotos por clave).
        const finalDigest = clientDigest.applyDeepBlocks(merged, fresh);
        // (v235) RECLASIFICACIÓN DE RUBRO — NUNCA en silencio: lo que el
        // dueño confirmó (pregunta/formulario) no se toca jamás. Si la
        // lectura fresca difiere con CONFIANZA ALTA de lo guardado, se
        // adopta pero queda needs_question + log (Posty pregunta lo
        // confirma con el dueño). Si difiere sin certeza, se conserva lo
        // guardado y la duda fresca queda como candidatas.
        try {
          const oldR = (stored && stored.rubro_id) || null;
          const newR = (fresh && fresh.rubro_id) || null;
          const ownerSet = !!(oldR && (oldR.fuente === 'pregunta' || oldR.fuente === 'form'));
          if (newR && !ownerSet) {
            const differs = !oldR || oldR.rubro !== newR.rubro || (oldR.subrubro || '') !== (newR.subrubro || '');
            if (differs && newR.segura) {
              finalDigest.rubro_id = { ...newR, needs_question: true, pending_reason: 'reclasificacion' };
              finalDigest.category = newR.rubro;
              finalDigest.subcat = newR.subrubro || '';
              console.log(`[rubro-id] usuario ${uid}: ${oldR ? oldR.rubro + '/' + (oldR.subrubro || '-') : '(sin rubro)'} -> ${newR.rubro}/${newR.subrubro || '-'} (confianza ${newR.confianza}) — queda pregunta pendiente`);
              summary.rubroReclassified = (summary.rubroReclassified || 0) + 1;
            } else if (differs && oldR) {
              finalDigest.rubro_id = { ...oldR, needs_question: true, candidatas: newR.candidatas || oldR.candidatas || [] };
            } else if (!oldR) {
              finalDigest.rubro_id = newR;
              if (newR.segura) { finalDigest.category = newR.rubro; finalDigest.subcat = newR.subrubro || ''; }
            }
          }
        } catch (e) { /* la reclasificación nunca frena el refresco */ }
        clientDigest.saveDigest(db, uid, finalDigest);
        summary.saved++;
      } catch (e) { summary.errors++; console.error('[digest-refresh] usuario ' + uid + ':', e.message); }
    }
  } catch (e) { console.error('[digest-refresh] sweep:', e.message); }
  console.log(`[digest-refresh] ${JSON.stringify(summary)}`);
  return summary;
}

// 🧠 CARTA SEMANAL: la pantalla "Tu análisis" es una carta NUEVA por semana —
// el loop (diagnóstico → plan → medición → ajuste) necesita la serie. Este
// sweep reconstruye el análisis de las cuentas activas y lo persiste
// (buildAccountAnalysis guarda con saveAnalysis). Liviano: tope de cuentas
// por corrida, una falla no frena a las demás, y GET /api/analysis no cambia.
//
// 📮 ENTREGA (decisión de Valentino, 2026-10-20): la carta llega los DOMINGOS
// A LA NOCHE — cierra la semana que pasó y presenta la que viene. Antes era
// el lunes 06:45 BA; el sweep ahora corre en modo ventana dominical: lo
// dispara scheduler.js cada hora en la franja en que algún huso puede estar
// en su domingo a la noche, y acá cada cuenta se genera SOLO si en SU zona
// (userTz; default Buenos Aires) es domingo entre las 20:00 y las 22:59.
// La carta de las 21:00 del cliente, en la práctica. Sin opts (llamadas
// internas/manuales) el comportamiento es el histórico: genera para todas.
// Anti-duplicado en modo ventana: si la cuenta ya tiene una carta creada en
// los últimos 3 días, no se genera otra — el lunes a la mañana la carta del
// domingo ya está en "Tu análisis" y la serie no se duplica jamás.
function sundayLetterWindow(tzName, now) {
  try {
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: tzName || 'America/Argentina/Buenos_Aires',
      weekday: 'short', hour: '2-digit', hour12: false,
    }).formatToParts(now instanceof Date ? now : new Date(now || Date.now()));
    const wd = (parts.find((p) => p.type === 'weekday') || {}).value;
    let hh = Number((parts.find((p) => p.type === 'hour') || {}).value);
    if (hh === 24) hh = 0;
    return wd === 'Sun' && hh >= 20 && hh <= 22;
  } catch (e) {
    return sundayLetterWindow('America/Argentina/Buenos_Aires', now);
  }
}

let __analysisSweepRunning = false;
async function refreshAnalysesSweep(opts = {}) {
  if (__analysisSweepRunning) return { skipped: 'running' };
  __analysisSweepRunning = true;
  const sundayWindow = !!(opts && opts.sundayWindow);
  if (sundayWindow) { try { analysisEngine.ensureAnalysisTable(db); } catch (e) {} }
  const summary = { users: 0, built: 0, errors: 0, skippedWindow: 0, skippedDup: 0 };
  try {
    const rows = db.prepare(`SELECT user_id FROM client_digest
      UNION SELECT user_id FROM profiles WHERE ig_connected = 1
      UNION SELECT user_id FROM posts WHERE created_at >= datetime('now', '-14 days')`).all().slice(0, 40);
    for (const row of rows) {
      const uid = row.user_id;
      try {
        if (sundayWindow) {
          if (!sundayLetterWindow(userTz(uid), new Date())) { summary.skippedWindow++; continue; }
          const recent = db.prepare(`SELECT COUNT(*) AS c FROM account_analysis WHERE user_id = ? AND created_at >= datetime('now', '-3 days')`).get(uid);
          if (recent && recent.c > 0) { summary.skippedDup++; continue; }
        }
        summary.users++;
        const fresh = await buildAccountAnalysis(uid);
        if (fresh) summary.built++;
        // 📩 Aviso de la carta (v283, la "C" de la carta dominical): SOLO en
        // modo ventana y SOLO cuando se construyó una carta nueva — las
        // cuentas con carta reciente ya se saltaron arriba (skippedDup), así
        // que una carta nueva equivale a un único push, jamás dos.
        if (sundayWindow && fresh && fresh.letter) {
          try { await push.notifySundayLetter(uid); } catch (e) { /* el aviso nunca frena el barrido */ }
        }
      } catch (e) { summary.errors++; console.error('[analysis-sweep] usuario ' + uid + ':', e.message); }
    }
  } catch (e) { console.error('[analysis-sweep] sweep:', e.message); }
  __analysisSweepRunning = false;
  console.log(`[analysis-sweep] cartas semanales: ${summary.built}/${summary.users} cuentas, errores: ${summary.errors}` + (sundayWindow ? `, fuera de ventana: ${summary.skippedWindow}, ya con carta: ${summary.skippedDup}` : ''));
  return summary;
}

module.exports = { nextWeekSweep, generateWeekDrafts, nextWeekEligible, maybeStartRebuild, revalidateReferralDiscount, maybeReferralNudge, conceptShotGenerate: conceptShotGenerateQueued, autoArmWeek, scheduleAllDrafts, autoWeekEnabled, assignScheduleSlots, acceptAllDrafts, retrySweepFailures, backfillThisWeek, albumRitualSweep, runWeeklyIdeasLoop, runIdeasForUser, gridPatternFor, computeGridPattern, composeWeekFeed, planWeekTextModes, weekTextModeFor, kindOfTipo, runWeeklyDigestRefresh: refreshDigestsSweep, runWeeklyAnalysisRefresh: refreshAnalysesSweep };
